-- 由 magic_views.py 從 Oracle 定義轉換，請勿手動修改
-- 執行前先執行 postgresql.sql 和 oracle_compat.sql
-- 只包含已在 PostgreSQL 實際建立成功的 View，依相依順序排列

-- Home #73 ViewA01_19.PDF修改異動比較
CREATE OR REPLACE VIEW "viewa01_19_01" AS (SELECT "a"."serial_num", CONCAT(TRIM("a"."異動日期"), TRIM("a"."異動時間")) AS "主檔異動日時", CONCAT(COALESCE(TRIM("b"."pdf新增日期"), ' '), COALESCE(TRIM("b"."pdf新增時間"), ' ')) AS "pdf新增日時" FROM "a01" AS "a" LEFT JOIN "a01_19" AS "b" ON "a"."serial_num" = "b"."serial_num");

-- DOC #59 ViewDoc_KMTree
CREATE OR REPLACE VIEW "viewdoc_kmtree" AS (SELECT "doc_kmtree"."objid", "doc_kmtree"."category", "doc_kmtree"."nodeid", "doc_kmtree"."subject", "doc_kmcategory"."user_", "doc_kmtree"."open2tran" FROM "doc_kmtree", "doc_kmcategory" WHERE "doc_kmtree"."category" = "doc_kmcategory"."category");

-- DOC #60 ViewDoc_OwnerTotalSize
CREATE OR REPLACE VIEW "viewdoc_ownertotalsize" AS (SELECT "doc_allowedsize"."userid", ROUND(CAST(CAST(SUM(COALESCE("doc_docbytool"."blobsize", 0)) AS DOUBLE PRECISION) / 1000000 AS DECIMAL), 2) AS "totalsize", AVG(COALESCE("doc_allowedsize"."allowedsize", 0)) AS "allowsize", MAX(COALESCE("doc_allowedsize"."allowcategory", 0)) AS "allowcategory", MAX(COALESCE("doc_allowedsize"."allownode", 0)) AS "allownode", MAX(COALESCE("doc_allowedsize"."allowdoc", 0)) AS "allowdoc" FROM "doc_allowedsize" LEFT JOIN "doc_docbytool" ON "doc_docbytool"."createdby" = "doc_allowedsize"."userid" AND "doc_docbytool"."category" <> ' ' GROUP BY "doc_allowedsize"."userid");

-- DOC #55 ViewDoc_UserRights
CREATE OR REPLACE VIEW "viewdoc_userrights" AS (SELECT "a"."userid", "a"."objid", CASE WHEN SUM("a"."read_") = 0 THEN 0 ELSE 1 END AS "read_", CASE WHEN SUM("a"."modify_") = 0 THEN 0 ELSE 1 END AS "modify_", CASE WHEN SUM("a"."delete_") = 0 THEN 0 ELSE 1 END AS "delete_" FROM (SELECT "a"."userid", "b"."objid", CASE WHEN SUM("b"."read_") = 0 THEN 0 ELSE 1 END AS "read_", CASE WHEN SUM("b"."modify_") = 0 THEN 0 ELSE 1 END AS "modify_", CASE WHEN SUM("b"."delete_") = 0 THEN 0 ELSE 1 END AS "delete_" FROM "doc_groupusers" AS "a" INNER JOIN "doc_groupobj" AS "b" ON "a"."groupid" = "b"."groupid" INNER JOIN "doc_docbytool" AS "z" ON "b"."objid" = "z"."objid" GROUP BY "a"."userid", "b"."objid" UNION ALL /* 個人分享文件 */ SELECT "a"."userid", "a"."objid", "a"."read_", "a"."modify_", "a"."delete_" FROM "doc_userobj" AS "a" INNER JOIN "doc_docbytool" AS "z" ON "a"."objid" = "z"."objid" UNION ALL /* 群組分享頁籤 */ SELECT "a"."userid", "z"."objid", CASE WHEN SUM("b"."read_") = 0 THEN 0 ELSE 1 END AS "read_", CASE WHEN SUM("b"."modify_") = 0 THEN 0 ELSE 1 END AS "modify_", CASE WHEN SUM("b"."delete_") = 0 THEN 0 ELSE 1 END AS "delete_" FROM "doc_groupusers" AS "a" INNER JOIN "doc_groupobj" AS "b" ON "a"."groupid" = "b"."groupid" INNER JOIN "doc_kmcategory" AS "y" ON "b"."objid" = "y"."category" INNER JOIN "doc_docbytool" AS "z" ON "y"."category" = "z"."category" GROUP BY "a"."userid", "z"."objid" UNION ALL /* 個人分享頁籤 */ SELECT "a"."userid", "z"."objid", "a"."read_", "a"."modify_", "a"."delete_" FROM "doc_userobj" AS "a" INNER JOIN "doc_kmcategory" AS "y" ON "a"."objid" = "y"."category" INNER JOIN "doc_docbytool" AS "z" ON "y"."category" = "z"."category" UNION ALL /* 群組分享資料夾 */ SELECT "a"."userid", "z"."objid", CASE WHEN SUM("b"."read_") = 0 THEN 0 ELSE 1 END AS "read_", CASE WHEN SUM("b"."modify_") = 0 THEN 0 ELSE 1 END AS "modify_", CASE WHEN SUM("b"."delete_") = 0 THEN 0 ELSE 1 END AS "delete_" FROM "doc_groupusers" AS "a" INNER JOIN "doc_groupobj" AS "b" ON "a"."groupid" = "b"."groupid" INNER JOIN "doc_kmtree" AS "y" ON "b"."objid" = "y"."objid" INNER JOIN "doc_docbytool" AS "z" ON "y"."category" = "z"."category" AND "z"."nodeid" LIKE CONCAT(RTRIM("y"."nodeid"), '%') GROUP BY "a"."userid", "z"."objid" /* 群組分享文件 */ UNION ALL /* 個人分享資料夾 */ SELECT "a"."userid", "z"."objid", "a"."read_", "a"."modify_", "a"."delete_" FROM "doc_userobj" AS "a" INNER JOIN "doc_kmtree" AS "y" ON "a"."objid" = "y"."objid" INNER JOIN "doc_docbytool" AS "z" ON "y"."category" = "z"."category" AND "z"."nodeid" LIKE CONCAT(RTRIM("y"."nodeid"), '%')) AS "a" GROUP BY "a"."userid", "a"."objid");

-- Home #1662 ViewFIL0010.功能表選單
CREATE OR REPLACE VIEW "viewfil0010" AS (SELECT "a"."員工編號", "a"."員工姓名", "a"."序號", "a"."父階", "a"."子階", "a"."node", "a"."說明", "a"."cabinet", "a"."publicname", "a"."啟用", "a"."隱藏", "a"."不需授權", "a"."權限組合", "a"."單據類別", "a"."流程代碼", "a"."特殊管制", "a"."人事管制", COALESCE("b"."權限", ' ') AS "權限", COALESCE("b"."最後更新者", ' ') AS "最後更新者", "b"."最後更新日", COALESCE("b"."隱藏", 0) AS "使用者隱藏", COALESCE("b"."獨立執行", 0) AS "獨立執行", COALESCE("b"."密碼執行", 0) AS "密碼執行" FROM (SELECT * FROM "fil1000" AS "a", "fil0010" AS "b") AS "a" LEFT JOIN "fil1007" AS "b" ON "b"."員工編號" = "a"."員工編號" AND "b"."publicname" = "a"."publicname");

-- Home #1663 ViewFIL0011.公司代碼檔
CREATE OR REPLACE VIEW "viewfil0011" AS (SELECT "a"."系統代碼" AS "代碼", "a"."代碼名稱" AS "名稱", "a"."文字參數" AS "廠商編號", COALESCE("b"."全名", ' ') AS "全名", COALESCE("b"."簡稱", ' ') AS "簡稱", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil1014" AS "a" LEFT JOIN "fil0011" AS "b" ON "a"."文字參數" = "b"."編號" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."代碼類別" = '公司別');

-- Home #1665 ViewFIL0012014.部門廠商檔
CREATE OR REPLACE VIEW "viewfil0012014" AS (SELECT "a"."部門編號" AS "編號", CONCAT(COALESCE("b"."名稱", ' '), '.', "a"."部門名稱") AS "名稱", CAST(CONCAT(COALESCE("b"."名稱", ' '), '.', "a"."部門名稱") AS TEXT) AS "排序", '1' AS "類別" FROM "fil0020" AS "a" LEFT JOIN "viewfil0011" AS "b" ON "b"."代碼" = "a"."所屬公司" UNION ALL SELECT "a"."編號", "a"."全名" AS "名稱", CAST("a"."全名" AS TEXT) AS "排序", '2' AS "類別" FROM "fil0011" AS "a" WHERE "a"."廠客" = '1');

-- Home #1666 ViewFIL0013.通知記錄檔
CREATE OR REPLACE VIEW "viewfil0013" AS (SELECT "a"."寄件者", "a"."收件者", "a"."序號", "a"."主旨", "a"."本文", "a"."提醒日", "a"."寄件日", COALESCE("b"."員工姓名", ' ') AS "寄件者姓名", COALESCE("c"."員工姓名", ' ') AS "收件者姓名", "a"."發送", "a"."已讀", "a"."隱藏", "a"."通知", "a"."簽核系統" FROM "fil1017" AS "a" LEFT JOIN "fil0010" AS "b" ON "a"."寄件者" = "b"."員工編號" LEFT JOIN "fil0010" AS "c" ON "a"."收件者" = "c"."員工編號");

-- Home #1667 ViewFIL0014.修改記錄檔
CREATE OR REPLACE VIEW "viewfil0014" AS (SELECT "a"."單據類別", "a"."單據編號", "a"."序號", "a"."說明", "a"."狀態", "a"."修改人", COALESCE("b"."員工姓名", ' ') AS "修改人姓名", "a"."修改日" FROM "fil1018" AS "a" LEFT JOIN "fil0010" AS "b" ON "a"."修改人" = "b"."員工編號");

-- Home #1668 ViewFIL0015.使用記錄檔
CREATE OR REPLACE VIEW "viewfil0015" AS (SELECT "對應編號", "員工編號", MAX("西元日期") AS "西元日期", MAX("時間") AS "時間", MAX("記錄內容") AS "記錄內容", MAX("裝置位址") AS "裝置位址" FROM "fil1006" WHERE "類別" LIKE '附件%' AND "對應編號" LIKE 'C11B%' GROUP BY "對應編號", "員工編號");

-- Home #1669 ViewFIL0020.單據類別檔
CREATE OR REPLACE VIEW "viewfil0020" AS (SELECT "a"."系統代碼" AS "單據類別", "a"."代碼名稱" AS "單據名稱", "a"."文字參數" AS "排序", "a"."數字參數" AS "產品庫存參數", "a"."數字參數二" AS "材料庫存參數", "a"."數字參數三" AS "採購應付參數", "a"."數字參數四" AS "代工應付參數", "a"."數字參數五" AS "應收參數", "a"."數字參數六" AS "成本參數", "a"."英數參數" AS "iso", "a"."文字參數一" AS "單據管理員代號", COALESCE("c"."員工姓名", ' ') AS "單據管理員姓名", "a"."文字參數二" AS "單據管理員代號二", COALESCE("d"."員工姓名", ' ') AS "單據管理員姓名二", "a"."文字參數三" AS "單據管理員代號三", COALESCE("e"."員工姓名", ' ') AS "單據管理員姓名三", "a"."最後更新者", COALESCE("b"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil1014" AS "a" LEFT JOIN "fil0010" AS "b" ON "b"."員工編號" = "a"."最後更新者" LEFT JOIN "fil0010" AS "c" ON "c"."員工編號" = "a"."文字參數一" LEFT JOIN "fil0010" AS "d" ON "d"."員工編號" = "a"."文字參數二" LEFT JOIN "fil0010" AS "e" ON "e"."員工編號" = "a"."文字參數三" WHERE "a"."代碼類別" = '單據類別');

-- Home #1671 ViewFIL0030.簽核狀態檔
CREATE OR REPLACE VIEW "viewfil0030" AS (SELECT "a"."簽核編號", "a"."簽核系統", "a"."單號", "a"."發函人", COALESCE("c"."員工姓名", ' ') AS "發函人姓名", "a"."發函日期", "a"."發函時間", "a"."簽核群組", "a"."最後簽核流程順序", "a"."簽核狀態", "a"."刪除退回人", "a"."刪除退回日", "a"."發函代理人", COALESCE("b"."員工姓名", ' ') AS "代理人姓名" FROM "fil1009" AS "a" LEFT JOIN "fil0010" AS "b" ON "b"."員工編號" = "a"."發函代理人" LEFT JOIN "fil0010" AS "c" ON "c"."員工編號" = "a"."發函人" WHERE "a"."簽核編號" = (SELECT MAX("a1"."簽核編號") FROM "fil1009" AS "a1" WHERE "a1"."簽核系統" = "a"."簽核系統" AND "a1"."單號" = "a"."單號"));

-- Home #1672 ViewFIL0040.簽核發送檔
CREATE OR REPLACE VIEW "viewfil0040" AS (SELECT "a"."簽核編號", "a"."簽核系統", "b"."單據類別", "c"."單據名稱", "a"."單號" AS "單據編號", "d"."簽核狀態" AS "表單狀態", "a"."發函人", COALESCE("e"."員工姓名", ' ') AS "發函人姓名", "a"."發函日期", "a"."發函時間", "a"."簽核群組", "a"."最後簽核流程順序", "a"."簽核狀態", "a"."刪除退回人", COALESCE("f"."員工姓名", ' ') AS "撤回人姓名", "a"."刪除退回日", "a"."發函代理人", COALESCE("g"."員工姓名", ' ') AS "發函代理人姓名", "b"."單據日期", "b"."備註", "b"."填表人", COALESCE("h"."員工姓名", ' ') AS "填表人姓名" FROM "fil1009" AS "a" INNER JOIN "fil0030" AS "b" ON "b"."單據編號" = "a"."單號" AND ("b"."簽核系統" = "a"."簽核系統" OR "b"."簽核系統_結案" = "a"."簽核系統") LEFT JOIN "viewfil0020" AS "c" ON "c"."單據類別" = "b"."單據類別" LEFT JOIN "viewfil0030" AS "d" ON "d"."簽核系統" = "a"."簽核系統" AND "d"."單號" = "a"."單號" LEFT JOIN "fil0010" AS "e" ON "e"."員工編號" = "a"."發函人" LEFT JOIN "fil0010" AS "f" ON "f"."員工編號" = "a"."刪除退回人" LEFT JOIN "fil0010" AS "g" ON "g"."員工編號" = "a"."發函代理人" LEFT JOIN "fil0010" AS "h" ON "h"."員工編號" = "b"."填表人");

-- Home #1673 ViewFIL0050.簽核流程檔
CREATE OR REPLACE VIEW "viewfil0050" AS (SELECT "a"."簽核編號", "a"."序號", "a"."簽核人", COALESCE("b"."員工姓名", ' ') AS "簽核人姓名", "a"."簽核流程順序", "a"."執行碼", CASE WHEN "a"."執行碼" = 'K' THEN '核准' WHEN "a"."執行碼" = 'R' THEN '退件' ELSE CASE WHEN "e"."最後簽核流程順序" = "a"."簽核流程順序" THEN '待簽' ELSE ' ' END END AS "執行碼說明", "a"."執行日", "a"."執行時", "a"."意見", "a"."移轉簽核人", COALESCE("c"."員工姓名", ' ') AS "移轉簽核人姓名", "a"."代簽人", COALESCE("d"."員工姓名", ' ') AS "代簽人姓名", "a"."guid" FROM "fil1010" AS "a" INNER JOIN "fil1009" AS "e" ON "e"."簽核編號" = "a"."簽核編號" LEFT JOIN "fil0010" AS "b" ON "b"."員工編號" = "a"."簽核人" LEFT JOIN "fil0010" AS "c" ON "c"."員工編號" = "a"."移轉簽核人" LEFT JOIN "fil0010" AS "d" ON "d"."員工編號" = "a"."代簽人");

-- Home #1674 ViewFIL0051.簽核附件檔
CREATE OR REPLACE VIEW "viewfil0051" AS (SELECT "a"."簽核系統", "a"."單號", "a"."序號", "a"."附件", UPPER("a"."格式") AS "格式", "a"."說明", "a"."大小", "a"."關鍵字", "a"."客供類別", ' ' AS "客供名稱", "a"."附件類別", ' ' AS "附件類別名稱", "a"."更新者" AS "最後更新者", COALESCE("b"."員工姓名", ' ') AS "更新者姓名", "a"."更新日" AS "最後更新日", COALESCE("c"."員工姓名", ' ') AS "建檔人姓名", "a"."建檔日" AS "建檔日", "a"."建檔時" AS "建檔時" FROM "fil1011" AS "a" LEFT JOIN "fil0010" AS "b" ON "a"."更新者" = "b"."員工編號" LEFT JOIN "fil0010" AS "c" ON "a"."建檔人" = "c"."員工編號");

-- Home #1675 ViewFIL0052.附件查詢檔
CREATE OR REPLACE VIEW "viewfil0052" AS (SELECT "a"."簽核系統", "b"."單據類別", "a"."單號" AS "單據編號", "d"."單據名稱", "b"."訂單號碼", "b"."單據日期", "b"."廠客編號", COALESCE("e"."全名", ' ') AS "廠客全名", "a"."序號", "a"."附件", UPPER("a"."格式") AS "格式", "a"."說明", "a"."大小", "a"."關鍵字", "a"."更新者" AS "最後更新者", COALESCE("c"."員工姓名", ' ') AS "更新者姓名", "a"."更新日" AS "最後更新日" FROM "fil1011" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."簽核系統" = "b"."簽核系統" AND "a"."單號" = "b"."單據編號" INNER JOIN "viewfil0020" AS "d" ON "b"."單據類別" = "d"."單據類別" LEFT JOIN "fil0010" AS "c" ON "a"."更新者" = "c"."員工編號" LEFT JOIN "fil0011" AS "e" ON "b"."廠客編號" = "e"."編號");

-- Home #1676 ViewFIL0053.附件依年度
CREATE OR REPLACE VIEW "viewfil0053" AS (SELECT "a"."父階", "a"."子階", "a"."年度", "a"."廠商", "a"."單號", "a"."附件", "a"."說明" FROM (SELECT DISTINCT '0000' AS "父階", ORA_SUBSTR("a"."單據日期", 1, 4) AS "子階", 1 AS "年度", 0 AS "廠商", 0 AS "單號", 0 AS "附件", ORA_SUBSTR("a"."單據日期", 1, 4) AS "說明" FROM "viewfil0052" AS "a" UNION SELECT DISTINCT ORA_SUBSTR("a"."單據日期", 1, 4) AS "父階", "a"."廠客編號" AS "子階", 0 AS "年度", 1 AS "廠商", 0 AS "單號", 0 AS "附件", CAST("a"."廠客全名" AS TEXT) AS "說明" FROM "viewfil0052" AS "a" UNION SELECT DISTINCT "a"."廠客編號" AS "父階", CAST(CONCAT(TRIM("a"."訂單號碼"), '^', '^', TRIM("a"."單據編號"), '^', "a"."簽核系統") AS TEXT) AS "子階", 0 AS "年度", 0 AS "廠商", 1 AS "單號", 0 AS "附件", CAST(CONCAT(TRIM("a"."單據編號"), ' ', "a"."單據名稱") AS TEXT) AS "說明" FROM "viewfil0052" AS "a" UNION SELECT DISTINCT CAST(CONCAT(TRIM("a"."訂單號碼"), '^', TRIM("a"."單據編號"), '^', "a"."簽核系統") AS TEXT) AS "父階", TO_CHAR("a"."序號", '999') AS "子階", 0 AS "年度", 0 AS "廠商", 0 AS "單號", 1 AS "附件", CAST(CONCAT('【', TRIM(UPPER("a"."格式")), '】', "a"."說明") AS TEXT) AS "說明" FROM "viewfil0052" AS "a") AS "a");

-- Home #1677 ViewFIL0054.簽核附件大小
CREATE OR REPLACE VIEW "viewfil0054" AS (SELECT "a"."簽核系統", "a"."單號", SUM("a"."大小") AS "檔案大小", COUNT("a"."序號") AS "筆數" FROM "fil1011" AS "a" WHERE "a"."說明" <> ' ' GROUP BY "a"."簽核系統", "a"."單號");

-- Home #1678 ViewFIL0055.備註附檔二筆數
CREATE OR REPLACE VIEW "viewfil0055" AS (SELECT "a"."製令單別" AS "單別", "a"."製令單號" AS "單號", "a"."材料序號", "a"."屬性", COUNT("序號") AS "筆數" FROM "fil0037" AS "a" WHERE LENGTH("a"."圖檔") > 0 OR "a"."備註" <> ' ' GROUP BY "a"."製令單別", "a"."製令單號", "a"."材料序號", "a"."屬性");

-- Home #1679 ViewFIL0081.簽核人員檔
CREATE OR REPLACE VIEW "viewfil0081" AS (SELECT "a"."簽核系統", "a"."組別", "a"."簽核順序", "a"."員工編號", COALESCE("b"."員工姓名", ' ') AS "員工姓名", "a"."開始日期", "a"."結束日期", "a"."類別", "a"."啟用", "a"."最後更新者", COALESCE("c"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil1013" AS "a" LEFT JOIN "fil0010" AS "b" ON "b"."員工編號" = "a"."員工編號" LEFT JOIN "fil0010" AS "c" ON "c"."員工編號" = "a"."最後更新者");

-- Home #1748 ViewFIL1010.員工資料檔
CREATE OR REPLACE VIEW "viewfil1010" AS (SELECT "a"."員工編號", "a"."員工姓名", "a"."英文姓名", "a"."公司代碼", COALESCE("f"."名稱", ' ') AS "公司別", "a"."出生日期", "a"."就職日期", "a"."離職日期", "a"."聯絡電話", "a"."emailaddress", "a"."郵遞區號", "a"."通訊地址", "a"."個人密碼", "a"."部門編號", COALESCE("c"."guname", ' ') AS "部門名稱", "a"."身份證號", "a"."停止使用", "a"."主管編號", COALESCE("d"."員工姓名", ' ') AS "主管姓名", "a"."職稱代碼", COALESCE("e"."guname", ' ') AS "職位名稱", "a"."開放時間_起", "a"."開放時間_迄", CASE WHEN COALESCE("g"."內定工站一", ' ') = ' ' THEN 'NONE' ELSE COALESCE("g"."內定工站一", ' ') END AS "內定工站一", "a"."serial_num" AS "流水編號", "a"."flowposi", COALESCE("i"."guname", ' ') AS "簽核職位", "a"."salaryposi", "a"."party" AS "班別代碼", COALESCE("h"."名稱", ' ') AS "班別", CASE WHEN "a"."nation" = ' ' THEN '本國' ELSE "a"."nation" END AS "國籍", "a"."empstatus" AS "薪資類別", "a"."entryid" AS "指定程式", "a"."生產部門禁", "a"."最後更新者", COALESCE("b"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日", "a"."最後更新時" FROM "fil0010" AS "a" LEFT JOIN "fil0010" AS "b" ON "a"."最後更新者" = "b"."員工編號" LEFT JOIN "a30" AS "c" ON "a"."部門編號" = "c"."groupid" LEFT JOIN "fil0010" AS "d" ON "a"."主管編號" = "d"."員工編號" LEFT JOIN "a40" AS "e" ON "a"."職稱代碼" = "e"."serial_num" LEFT JOIN "viewfil0011" AS "f" ON "a"."公司代碼" = "f"."代碼" LEFT JOIN "fil0024" AS "g" ON "g"."員工編號" = "a"."員工編號" LEFT JOIN "fil0025" AS "h" ON "h"."代碼" = "a"."party" LEFT JOIN "a40" AS "i" ON "a"."flowposi" = "i"."serial_num");

-- Home #1749 ViewFIL1010A.員工資料檔
CREATE OR REPLACE VIEW "viewfil1010a" AS (SELECT "a"."員工編號", "a"."員工姓名", COALESCE("f"."名稱", ' ') AS "公司別", "a"."部門編號", COALESCE("c"."guname", ' ') AS "部門名稱", "a"."serial_num" AS "流水編號", COALESCE("h"."名稱", ' ') AS "班別", CASE WHEN "a"."nation" = ' ' THEN '本國' ELSE "a"."nation" END AS "國籍", "a"."最後更新者", COALESCE("b"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日", "a"."最後更新時" FROM "fil0010" AS "a" LEFT JOIN "fil0010" AS "b" ON "a"."最後更新者" = "b"."員工編號" LEFT JOIN "a30" AS "c" ON "a"."部門編號" = "c"."groupid" LEFT JOIN "viewfil0011" AS "f" ON "a"."公司代碼" = "f"."代碼" LEFT JOIN "fil0025" AS "h" ON "h"."代碼" = "a"."party");

-- Home #1751 ViewFIL1013.廠別資料檔
CREATE OR REPLACE VIEW "viewfil1013" AS (SELECT "a"."廠別編號", "a"."廠別名稱", "a"."建立員工", COALESCE("b"."員工姓名", ' ') AS "建立姓名", "a"."建立日期", "a"."最後更新者", COALESCE("c"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0013" AS "a" LEFT JOIN "fil0010" AS "b" ON "a"."建立員工" = "b"."員工編號" LEFT JOIN "fil0010" AS "c" ON "a"."最後更新者" = "c"."員工編號");

-- Home #1754 ViewFIL1015A.廠客聯絡人
CREATE OR REPLACE VIEW "viewfil1015a" AS (SELECT "a"."編號", 0 AS "序號", "a"."聯絡人一" AS "聯絡人", "a"."電話一" AS "電話", "a"."分機一" AS "分機", CAST("a"."最常職務" AS TEXT) AS "職務", "a"."email", ' ' AS "行動電話" FROM "fil0011" AS "a" WHERE "a"."聯絡人一" <> ' ' UNION SELECT "a"."編號", 1 AS "序號", "a"."聯絡人二", "a"."電話二", "a"."分機二", CAST('發票聯絡人' AS TEXT), "a"."email", ' ' FROM "fil0011" AS "a" WHERE "a"."聯絡人二" <> ' ' UNION SELECT "a"."廠客編號", "a"."序號", "a"."聯絡人", "a"."電話", "a"."分機", CAST("a"."職務" AS TEXT), "a"."email", CAST("a"."行動電話" AS TEXT) FROM "fil0014" AS "a");

-- Home #1755 ViewFIL1016.請假資料檔
CREATE OR REPLACE VIEW "viewfil1016" AS (SELECT "a"."單據類別", "a"."單據編號", "a"."單據日期", "a"."員工編號", COALESCE("b"."員工姓名", ' ') AS "員工姓名", "a"."請假日期_起", "a"."請假日期_迄", "a"."請假時間_起", "a"."請假時間_迄", "a"."假別代碼", "a"."事由", "a"."填表人", COALESCE("d"."員工姓名", ' ') AS "填表人姓名", "a"."填表日", "a"."最後更新者", COALESCE("c"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0016" AS "a" LEFT JOIN "fil0010" AS "b" ON "a"."員工編號" = "b"."員工編號" LEFT JOIN "fil0010" AS "c" ON "a"."最後更新者" = "c"."員工編號" LEFT JOIN "fil0010" AS "d" ON "a"."填表人" = "d"."員工編號");

-- Home #1757 ViewFIL1018.科目代碼檔
CREATE OR REPLACE VIEW "viewfil1018" AS (SELECT "a"."科目代碼", "a"."科目名稱", "a"."建立員工", COALESCE("b"."員工姓名", ' ') AS "建立姓名", "a"."建立日期", "a"."最後更新者", COALESCE("c"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0018" AS "a" LEFT JOIN "fil0010" AS "b" ON "a"."建立員工" = "b"."員工編號" LEFT JOIN "fil0010" AS "c" ON "a"."最後更新者" = "c"."員工編號");

-- Home #1759 ViewFIL1021.銀行資料檔
CREATE OR REPLACE VIEW "viewfil1021" AS (SELECT "a"."銀行類別", "a"."類別名稱", "a"."總機構代碼", CONCAT("a"."總機構代碼", ' ', COALESCE("c"."機構名稱", ' ')) AS "總機構名稱", "a"."分支機構代碼", "a"."機構名稱", "a"."地址", "a"."電話", "a"."負責人", "a"."網址", "a"."最後更新者", COALESCE("b"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0021" AS "a" LEFT JOIN "fil0010" AS "b" ON "b"."員工編號" = "a"."最後更新者" LEFT JOIN "fil0021" AS "c" ON "c"."總機構代碼" = "a"."總機構代碼" AND "c"."分支機構代碼" = ' ');

-- Home #1764 ViewFIL1024A.條碼原料入出主檔
CREATE OR REPLACE VIEW "viewfil1024a" AS (SELECT DISTINCT "條碼" FROM "fil0044" WHERE ("條碼" LIKE 'D11%' OR "條碼" LIKE 'E11%') AND "來源" <> ' ');

-- Home #1768 ViewFIL1024E.條碼列印記錄
CREATE OR REPLACE VIEW "viewfil1024e" AS (SELECT "a"."條碼", "a"."序號" AS "條碼序號", "a"."列印日期", "a"."列印時間", "a"."列印人代號", "a"."廠商規格", "a"."廠商批號", "a"."來源", "a"."細分", "a"."開立", REGEXP_SUBSTR("a"."條碼", '[^-]+', 1, 1) AS "單別", REGEXP_SUBSTR("a"."條碼", '[^-]+', 1, 2) AS "單號", COALESCE(TO_NUMBER(REGEXP_SUBSTR("a"."條碼", '[^-]+', 1, 3)), 0) AS "序號", CASE WHEN COALESCE("b"."條碼", ' ') = ' ' THEN 0 ELSE 1 END AS "已收料" FROM "fil0044a" AS "a" LEFT JOIN "fil0043" AS "b" ON "b"."條碼" = "a"."條碼");

-- Home #1769 ViewFIL1024F.條碼發料暫存
CREATE OR REPLACE VIEW "viewfil1024f" AS (SELECT "a"."其它單號" AS "請領單號", "a"."請領料號", SUM("a"."異動數量") AS "異動數量" FROM "fil0044" AS "a" WHERE ("a"."單據類別" = 'TMP') AND "a"."其它單號" <> ' ' GROUP BY "a"."其它單號", "a"."請領料號");

-- Home #1770 ViewFIL1024G.條碼日報回庫
CREATE OR REPLACE VIEW "viewfil1024g" AS (SELECT "a"."其它單號" AS "請領單號", "a"."請領料號", SUM("a"."異動數量") AS "異動數量" FROM "fil0044" AS "a" WHERE "a"."單據類別" = 'C41' AND "a"."來源" = 'I' AND "a"."其它單號" <> ' ' AND "a"."備註" = '回庫' GROUP BY "a"."其它單號", "a"."請領料號");

-- Home #1771 ViewFIL1024H.條碼原料入出首筆
CREATE OR REPLACE VIEW "viewfil1024h" AS (SELECT DISTINCT "條碼", MIN("序號") AS "首筆序號" FROM "fil0044" WHERE ("條碼" LIKE 'D11%' OR "條碼" LIKE 'E11%') AND "來源" = 'I' GROUP BY "條碼");

-- Home #1772 ViewFIL1024I.料號B控制表
CREATE OR REPLACE VIEW "viewfil1024i" AS WITH "tmp0" /* 主檔 */ AS (SELECT DISTINCT "a"."料號", "a"."管制日期" FROM (SELECT DISTINCT "m"."料號", COALESCE(CAST(CASE WHEN "a"."其它日期1" = '00000000' THEN "a"."異動日期" ELSE "a"."其它日期1" END AS TEXT), '00000000') AS "管制日期" FROM "fil0044" AS "a" INNER JOIN "fil0043" AS "m" ON "m"."條碼" = "a"."條碼" INNER JOIN "viewfil1024h" AS "b" ON "b"."條碼" = "a"."條碼" WHERE ("a"."條碼" LIKE 'D11%' OR "a"."條碼" LIKE 'E11%') AND "a"."來源" <> ' ' AND "a"."序號" <> COALESCE("b"."首筆序號", 0) AND ORA_SUBSTR("m"."料號", 1, 1) = 'B' UNION ALL SELECT DISTINCT "m"."料號", COALESCE("e"."單據日期", '00000000') AS "管制日期" FROM "fil0041" AS "a" INNER JOIN "fil0043" AS "m" ON "m"."條碼" = "a"."文數字4" INNER JOIN "fil0040" AS "b" ON "b"."單據類別" = "a"."單別" AND "b"."單據編號" = "a"."單號" AND "b"."單據序號" = "a"."序號" INNER JOIN "fil0031" AS "d" ON "d"."單別" = "a"."單別" AND "d"."單號" = "a"."單號" INNER JOIN "fil0030" AS "e" ON "e"."單據類別" = "a"."單別" AND "e"."單據編號" = "a"."單號" WHERE "a"."單別" = 'C41' AND ("d"."製程代碼" BETWEEN 'C31A' AND 'C31C' OR "d"."製程代碼" = 'C32D') AND ORA_SUBSTR("m"."料號", 1, 1) = 'B') AS "a"), "tmp1" /* 刷回 */ AS (SELECT "m"."料號", COALESCE(TO_CHAR(TO_DATE("a"."異動日期", 'YYYYMMDD') + (CASE WHEN "a"."異動時間" >= '000000' AND "a"."異動時間" <= '070000' THEN -1 ELSE 0 END), 'YYYYMMDD'), '00000000') AS "管制日期", "a"."來源", COUNT("a"."條碼") AS "桶數", SUM("m"."庫存異動數") AS "異動數量" FROM "fil0044" AS "a" INNER JOIN "fil0043" AS "m" ON "m"."條碼" = "a"."條碼" INNER JOIN "viewfil1024h" AS "b" ON "b"."條碼" = "a"."條碼" WHERE ("a"."條碼" LIKE 'D11%' OR "a"."條碼" LIKE 'E11%') AND "a"."來源" = 'I' AND "a"."序號" <> COALESCE("b"."首筆序號", 0) AND ORA_SUBSTR("m"."料號", 1, 1) = 'B' GROUP BY "m"."料號", COALESCE(TO_CHAR(TO_DATE("a"."異動日期", 'YYYYMMDD') + (CASE WHEN "a"."異動時間" >= '000000' AND "a"."異動時間" <= '070000' THEN -1 ELSE 0 END), 'YYYYMMDD'), '00000000'), "a"."來源"), "tmp2" /* 刷出 */ AS (SELECT "m"."料號", COALESCE(CAST(CASE WHEN "a"."其它日期1" = '00000000' THEN "a"."異動日期" ELSE "a"."其它日期1" END AS TEXT), '00000000') AS "管制日期", "a"."來源", COUNT("a"."條碼") AS "桶數", SUM(ABS("m"."庫存異動數")) AS "異動數量" FROM "fil0044" AS "a" INNER JOIN "fil0043" AS "m" ON "m"."條碼" = "a"."條碼" WHERE ("a"."條碼" LIKE 'D11%' OR "a"."條碼" LIKE 'E11%') AND "a"."來源" = 'O' AND ORA_SUBSTR("m"."料號", 1, 1) = 'B' GROUP BY "m"."料號", COALESCE(CAST(CASE WHEN "a"."其它日期1" = '00000000' THEN "a"."異動日期" ELSE "a"."其它日期1" END AS TEXT), '00000000'), "a"."來源"), "tmp3" /* 日報領用 */ AS (SELECT "m"."料號", COALESCE("e"."單據日期", '00000000') AS "管制日期", SUM(CASE WHEN "b"."退庫數量" = 0 THEN 1 ELSE 0 END) AS "桶數", SUM("b"."異動數量" - "b"."退庫數量" - "b"."毛重") AS "異動數量" FROM "fil0041" AS "a" INNER JOIN "fil0043" AS "m" ON "m"."條碼" = "a"."文數字4" INNER JOIN "fil0040" AS "b" ON "b"."單據類別" = "a"."單別" AND "b"."單據編號" = "a"."單號" AND "b"."單據序號" = "a"."序號" INNER JOIN "fil0031" AS "d" ON "d"."單別" = "a"."單別" AND "d"."單號" = "a"."單號" INNER JOIN "fil0030" AS "e" ON "e"."單據類別" = "a"."單別" AND "e"."單據編號" = "a"."單號" WHERE "a"."單別" = 'C41' AND ("d"."製程代碼" BETWEEN 'C31A' AND 'C31C' OR "d"."製程代碼" = 'C32D') AND ORA_SUBSTR("m"."料號", 1, 1) = 'B' AND "b"."異動類別" = 'E' GROUP BY "m"."料號", COALESCE("e"."單據日期", '00000000')) SELECT DISTINCT "a"."料號", COALESCE("a"."管制日期", '00000000') AS "管制日期", COALESCE("b"."異動數量", 0) AS "刷回數量", COALESCE("b"."桶數", 0) AS "刷回桶數", COALESCE("c"."異動數量", 0) AS "刷出數量", COALESCE("c"."桶數", 0) AS "刷出桶數", COALESCE("d"."異動數量", 0) AS "日報使用量", COALESCE("d"."桶數", 0) AS "日報使用桶數" FROM "tmp0" AS "a" LEFT JOIN "tmp1" AS "b" ON "b"."料號" = "a"."料號" AND "b"."管制日期" = "a"."管制日期" LEFT JOIN "tmp2" AS "c" ON "c"."料號" = "a"."料號" AND "c"."管制日期" = "a"."管制日期" LEFT JOIN "tmp3" AS "d" ON "d"."料號" = "a"."料號" AND "d"."管制日期" = "a"."管制日期" WHERE ORA_SUBSTR("a"."料號", 1, 1) = 'B';

-- Home #1773 ViewFIL1024J.條碼列印批號
CREATE OR REPLACE VIEW "viewfil1024j" AS WITH "tmp0" /* 主檔 */ AS (SELECT DISTINCT "m"."列印批號", "m"."條碼" FROM "fil0044a" AS "m" WHERE "m"."列印批號" LIKE 'QRC%') SELECT DISTINCT "a"."列印批號", REGEXP_SUBSTR("a"."條碼", '[^-]+', 1) AS "單據類別", REGEXP_SUBSTR("a"."條碼", '[^-]+', 1, 2) AS "單據編號", TO_NUMBER(REGEXP_SUBSTR("a"."條碼", '[^-]+', 1, 3)) AS "單據序號" FROM "tmp0" AS "a";

-- Home #1779 ViewFIL1027A.版銅最近取版日
CREATE OR REPLACE VIEW "viewfil1027a" AS (SELECT "a"."產品編號" AS "版銅編號", MAX("a"."異動日期") AS "最近取版日期" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C32E' AND "a"."單位代碼" = 'A' GROUP BY "a"."產品編號");

-- Home #1781 ViewFIL1027C.版銅最後狀態
CREATE OR REPLACE VIEW "viewfil1027c" AS (SELECT CAST("a"."單據編號" AS TEXT) AS "單據編號", "a"."異動日期", "a"."最後更新日", CAST("a"."產品編號" AS TEXT) AS "版銅編號", CAST(CASE WHEN "a"."單位代碼" = 'A' THEN '取版' ELSE '回收' END AS TEXT) AS "異動類別", 0 AS "送修", 0 AS "回廠", CAST('1' AS TEXT) AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" LEFT JOIN "fil0010" AS "d" ON "d"."員工編號" = "c"."業務員" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C32E' AND "a"."單位代碼" BETWEEN 'A' AND 'B' UNION ALL SELECT CAST("a"."單據編號" AS TEXT) AS "單據編號", "c"."單據日期", "a"."最後更新日", CAST("a"."產品編號" AS TEXT) AS "版銅編號", CAST('送修' AS TEXT) AS "異動類別", 0 AS "送修申請", 0 AS "回廠", CAST('2' AS TEXT) AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" LEFT JOIN "fil0010" AS "d" ON "d"."員工編號" = "c"."業務員" WHERE "a"."單據類別" = 'F33' UNION ALL SELECT CAST(CONCAT("a"."版銅代碼", ':', "a"."入庫日期", "a"."入庫時間") AS TEXT) AS "單據編號", COALESCE(CASE WHEN "a"."送修" = 0 THEN "a"."入庫日期" ELSE "c"."異動日期" END, ' ') AS "異動日期", "a"."最後更新日", CAST("a"."版銅代碼" AS TEXT) AS "版銅編號", CAST(CASE WHEN "a"."送修" = 0 THEN CASE WHEN POSITION('送修' IN "a"."歸屬流水編號") = 0 THEN '入庫' ELSE '入庫(送修)' END ELSE CASE WHEN "a"."回廠" = 0 THEN '出廠未回' ELSE '出廠已回' END END AS TEXT) AS "異動類別", "a"."送修", "a"."回廠", CAST('3' AS TEXT) AS "來源" FROM "fil004d" AS "a" LEFT JOIN "fil0040" AS "c" ON "c"."單據類別" = 'F33' AND "a"."歸屬流水編號" = "c"."流水編號" LEFT JOIN "fil0010" AS "d" ON "d"."員工編號" = "a"."最後更新者" UNION ALL SELECT CONCAT(CAST("a"."版銅代碼" AS TEXT), ' ', TO_CHAR("a"."最後更新日", 'yyyymmdd'), TO_CHAR("a"."序號", '0000000000')) AS "單據編號", TO_CHAR("a"."最後更新日", 'yyyymmdd') AS "異動日期", "a"."最後更新日", CAST("a"."版銅代碼" AS TEXT) AS "版銅編號", CAST(CASE WHEN "a"."類別" = 'A' THEN '洗版開始' WHEN "a"."類別" = 'B' THEN '洗版' WHEN "a"."類別" = 'C' THEN '停用' ELSE ' ' END AS TEXT) AS "異動類別", 0 AS "送修", 0 AS "回廠", CAST('4' AS TEXT) AS "來源" FROM "fil004e" AS "a" LEFT JOIN "fil0010" AS "d" ON "d"."員工編號" = "a"."最後更新者" UNION ALL SELECT CONCAT(CAST("a"."歸屬代碼" AS TEXT), ' ', TO_CHAR("a"."最後更新日", 'yyyymmdd'), TO_CHAR("a"."序號", '0000000000')) AS "單據編號", TO_CHAR("a"."最後更新日", 'yyyymmdd') AS "異動日期", "a"."最後更新日", CAST("a"."歸屬代碼" AS TEXT) AS "版銅編號", CAST('調入' AS TEXT) AS "異動類別", 0 AS "送修", 0 AS "回廠", CAST('5' AS TEXT) AS "來源" FROM "fil004e" AS "a" LEFT JOIN "fil0010" AS "d" ON "d"."員工編號" = "a"."最後更新者" WHERE "a"."歸屬代碼" <> ' ');

-- Home #1786 ViewFIL2011.異動單最後序號
CREATE OR REPLACE VIEW "viewfil2011" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", MAX("a"."單據序號") AS "最後序號" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "m" ON "a"."單據類別" = "m"."單據類別" AND "a"."單據編號" = "m"."單據編號" GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #1791 ViewFIL2023.類別序號檔(desc)
CREATE OR REPLACE VIEW "viewfil2023" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動類別" AS "類別", "a"."logical2", ROW_NUMBER() OVER (PARTITION BY "a"."單據類別", "a"."單據編號", "a"."異動類別" ORDER BY "a"."單據類別", "a"."單據編號", "a"."單據序號" DESC) AS "desc排序" FROM "fil0040" AS "a");

-- Home #1792 ViewFIL2030.異動單合計
CREATE OR REPLACE VIEW "viewfil2030" AS (SELECT "a"."單據類別", "a"."單據編號", SUM("a"."異動數量") AS "數量", SUM("a"."贈品數量") AS "贈品量", SUM("a"."異動金額") AS "金額", SUM("a"."毛重") AS "毛重", SUM("a"."材積") AS "材積", SUM("a"."製版費") AS "製版費", SUM("a"."燙金費") AS "燙金費", SUM("a"."雷射費") AS "雷射費" FROM "fil0040" AS "a" GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #1793 ViewFIL2040.異動單內容12
CREATE OR REPLACE VIEW "viewfil2040" ("單據類別", "單據編號", "內容") AS SELECT "a"."單據類別", "a"."單據編號", STRING_AGG(CAST(CAST(CONCAT(TRIM(TO_CHAR("a"."異動數量", '999999.999')), ' x ', TRIM(TO_CHAR("a"."異動單價", '99999.999')), ' ', TRIM("a"."產品編號")) AS TEXT) AS TEXT), ',' ORDER BY "a"."單據序號") AS "內容" FROM "fil0040" AS "a" GROUP BY "a"."單據類別", "a"."單據編號";

-- Home #1795 ViewFIL2051.費用合計檔
CREATE OR REPLACE VIEW "viewfil2051" AS (SELECT "a"."單據類別", "a"."單據編號", "a"."幣別", SUM("a"."金額") AS "金額", SUM("a"."稅額") AS "稅額" FROM "fil0042" AS "a" GROUP BY "a"."單據類別", "a"."單據編號", "a"."幣別");

-- Home #1796 ViewFIL2061.裁切異動數
CREATE OR REPLACE VIEW "viewfil2061" AS (/* 入庫 */ SELECT "a"."單別" AS "單別", "a"."單號" AS "單號", "a"."序號", "a"."日期一" AS "異動日期", "a"."文字一" AS "半成品編號", "a"."數字一" * CASE WHEN "a"."報廢" = 1 THEN 0 ELSE 1 END AS "入庫米數", CASE WHEN CASE WHEN "a"."報廢" = 1 THEN 0 ELSE "a"."數字一" END >= COALESCE("e"."裁切規格_m", 0) OR COALESCE("e"."裁切規格_m", 0) = 0 THEN 1 ELSE TRUNC(CAST(CASE WHEN "a"."報廢" = 1 THEN 0 ELSE "a"."數字一" END AS DOUBLE PRECISION) / CASE WHEN CASE WHEN POSITION('R' IN SUBSTRING("p"."產品編號" FROM 1)) = 0 THEN 0 ELSE POSITION('R' IN SUBSTRING("p"."產品編號" FROM 1)) + 1 - 1 END = 0 THEN "e"."裁切規格_m" ELSE "p"."訂購數量" END, 1) END AS "捲數", "f"."有效日期" AS "有效日期", CASE WHEN COALESCE("b"."交貨日期", ' ') = ' ' THEN "a"."日期二" ELSE "b"."交貨日期" END AS "製造日期", "d"."填表人" AS "作業者", 0 AS "報廢米數" FROM "fil00401" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單別" = "b"."單別" AND "a"."單號" = "b"."單號" /* 主檔 */ INNER JOIN "fil0030" AS "d" ON "a"."單別" = "d"."單據類別" AND "a"."單號" = "d"."單據編號" INNER JOIN "fil0040" AS "g" ON "a"."單別" = "g"."單據類別" AND "a"."單號" = "g"."單據編號" AND "a"."序號" = "g"."單據序號" INNER JOIN "fil0032" AS "p" ON "p"."製令單別" = 'C11' AND "p"."製令單號" = REGEXP_SUBSTR("a"."文字一", '[^_]+', 1, 1) LEFT JOIN "fil0033" AS "e" ON "e"."製令單別" = 'C11' AND "e"."製令單號" = REGEXP_SUBSTR("a"."文字一", '[^_]+', 1, 1) AND "e"."加工別" = 'A' LEFT JOIN "fil003f1" AS "f" ON "f"."單據類別" = 'C11' AND "f"."單據編號" = REGEXP_SUBSTR("a"."文字一", '[^_]+', 1, 1) AND "f"."類別" = 'G1' WHERE "a"."單別" = 'C41' AND "g"."異動類別" = 'A' AND "b"."製程代碼" = 'C31D' AND "a"."文字一" <> ' ' UNION ALL /* 調整 */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "單據序號", "d"."單據日期" AS "異動日期", "a"."產品編號" AS "半成品編號", "a"."異動數量" * CASE WHEN "a"."異動類別" = 'C' THEN -1 ELSE 1 END AS "入庫米數", CASE WHEN "a"."異動數量" >= COALESCE("e"."裁切規格_m", 0) OR COALESCE("e"."裁切規格_m", 0) = 0 THEN 1 ELSE TRUNC(CAST("a"."異動數量" * CASE WHEN "a"."異動類別" = 'C' THEN -1 ELSE 1 END AS DOUBLE PRECISION) / CASE WHEN CASE WHEN POSITION('R' IN SUBSTRING("p"."產品編號" FROM 1)) = 0 THEN 0 ELSE POSITION('R' IN SUBSTRING("p"."產品編號" FROM 1)) + 1 - 1 END = 0 THEN "e"."裁切規格_m" ELSE "p"."訂購數量" END, 1) END AS "捲數", '00000000' AS "有效日期", CASE WHEN "d"."匯率日期" = ' ' THEN '00000000' ELSE "d"."匯率日期" END AS "製造日期", "a"."文數字1" AS "作業者", "a"."數值1" * CASE WHEN "a"."異動類別" = 'C' THEN -1 ELSE 1 END AS "報廢米數" FROM "fil0040" AS "a" /* 主檔 */ INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" INNER JOIN "fil0032" AS "p" ON "p"."製令單別" = 'C11' AND "p"."製令單號" = REGEXP_SUBSTR("a"."產品編號", '[^_]+', 1, 1) LEFT JOIN "fil0033" AS "e" ON "e"."製令單別" = 'C11' AND "e"."製令單號" = REGEXP_SUBSTR("a"."產品編號", '[^_]+', 1, 1) AND "e"."加工別" = 'A' WHERE "a"."單據類別" = 'E22' UNION ALL /* 調整 */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "單據序號", "d"."單據日期" AS "異動日期", "a"."產品編號" AS "半成品編號", "a"."異動數量" * CASE WHEN "a"."異動類別" = 'C' THEN -1 ELSE 1 END AS "入庫米數", CASE WHEN "a"."異動數量" >= COALESCE("e"."裁切規格_m", 0) OR COALESCE("e"."裁切規格_m", 0) = 0 THEN 1 ELSE TRUNC(CAST("a"."異動數量" * CASE WHEN "a"."異動類別" = 'C' THEN -1 ELSE 1 END AS DOUBLE PRECISION) / CASE WHEN CASE WHEN POSITION('R' IN SUBSTRING("p"."產品編號" FROM 1)) = 0 THEN 0 ELSE POSITION('R' IN SUBSTRING("p"."產品編號" FROM 1)) + 1 - 1 END = 0 THEN "e"."裁切規格_m" ELSE "p"."訂購數量" END, 1) END AS "捲數", '00000000' AS "有效日期", CASE WHEN "d"."匯率日期" = ' ' THEN '00000000' ELSE "d"."匯率日期" END AS "製造日期", "a"."文數字1" AS "作業者", 0 AS "報廢米數" FROM "fil0040" AS "a" /* 主檔 */ INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" INNER JOIN "fil0032" AS "p" ON "p"."製令單別" = 'C11' AND "p"."製令單號" = REGEXP_SUBSTR("a"."產品編號", '[^_]+', 1, 1) LEFT JOIN "fil0033" AS "e" ON "e"."製令單別" = 'C11' AND "e"."製令單號" = REGEXP_SUBSTR("a"."產品編號", '[^_]+', 1, 1) AND "e"."加工別" = 'A' WHERE "a"."單據類別" = 'E23');

-- Home #1797 ViewFIL2062.裁切合計數
CREATE OR REPLACE VIEW "viewfil2062" AS (/* 入庫 */ SELECT "a"."半成品編號", REGEXP_SUBSTR("a"."半成品編號", '[^_]+', 1, 1) AS "製令單號", MAX("a"."有效日期") AS "有效日期", MAX("a"."製造日期") AS "製造日期", SUM("a"."入庫米數") AS "庫存數", SUM("a"."捲數") AS "捲數", SUM("a"."報廢米數") AS "報廢米數" FROM "viewfil2061" AS "a" GROUP BY "a"."半成品編號", REGEXP_SUBSTR("a"."半成品編號", '[^_]+', 1, 1));

-- Home #1799 ViewFIL2063.包裝異動數
CREATE OR REPLACE VIEW "viewfil2063" AS (/* 入庫 */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號", CASE WHEN "a"."異動日期" = '00000000' THEN "d"."單據日期" ELSE "a"."異動日期" END AS "異動日期", REGEXP_SUBSTR(COALESCE("c"."文字1", ' '), '[^,]+', 1, 1) AS "半成品編號", REGEXP_SUBSTR(REGEXP_SUBSTR(COALESCE("c"."文字1", ' '), '[^,]+', 1, 1), '[^-]+', 1, 1) AS "製令單號", "e"."有效日期", "e"."製造日期" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" /* 主檔 */ INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" LEFT JOIN "viewfil2062" AS "e" ON "e"."半成品編號" = REGEXP_SUBSTR(COALESCE("c"."文字1", ' '), '[^,]+', 1, 1) WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31I' AND REGEXP_SUBSTR(COALESCE("c"."文字1", ' '), '[^,]+', 1, 1) <> ' ' UNION ALL SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" + 1000 AS "單據序號", CASE WHEN "a"."異動日期" = '00000000' THEN "d"."單據日期" ELSE "a"."異動日期" END AS "異動日期", REGEXP_SUBSTR(COALESCE("c"."文字1", ' '), '[^,]+', 1, 2) AS "半成品編號", REGEXP_SUBSTR(REGEXP_SUBSTR(COALESCE("c"."文字1", ' '), '[^,]+', 1, 2), '[^-]+', 1, 1) AS "製令單號", "e"."有效日期", "e"."製造日期" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" /* 主檔 */ INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" LEFT JOIN "viewfil2062" AS "e" ON "e"."半成品編號" = REGEXP_SUBSTR(COALESCE("c"."文字1", ' '), '[^,]+', 1, 2) WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31I' AND REGEXP_SUBSTR(COALESCE("c"."文字1", ' '), '[^,]+', 1, 2) <> ' ' UNION ALL SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" + 2000 AS "單據序號", CASE WHEN "a"."異動日期" = '00000000' THEN "d"."單據日期" ELSE "a"."異動日期" END AS "異動日期", REGEXP_SUBSTR(COALESCE("c"."文字1", ' '), '[^,]+', 1, 3) AS "半成品編號", REGEXP_SUBSTR(REGEXP_SUBSTR(COALESCE("c"."文字1", ' '), '[^,]+', 1, 3), '[^-]+', 1, 1) AS "製令單號", "e"."有效日期", "e"."製造日期" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" /* 主檔 */ INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" LEFT JOIN "viewfil2062" AS "e" ON "e"."半成品編號" = REGEXP_SUBSTR(COALESCE("c"."文字1", ' '), '[^,]+', 1, 3) WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31I' AND REGEXP_SUBSTR(COALESCE("c"."文字1", ' '), '[^,]+', 1, 3) <> ' ' UNION ALL SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" + 3000 AS "單據序號", CASE WHEN "a"."異動日期" = '00000000' THEN "d"."單據日期" ELSE "a"."異動日期" END AS "異動日期", REGEXP_SUBSTR(COALESCE("c"."文字1", ' '), '[^,]+', 1, 4) AS "半成品編號", REGEXP_SUBSTR(REGEXP_SUBSTR(COALESCE("c"."文字1", ' '), '[^,]+', 1, 4), '[^-]+', 1, 1) AS "製令單號", "e"."有效日期", "e"."製造日期" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" /* 主檔 */ INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" LEFT JOIN "viewfil2062" AS "e" ON "e"."半成品編號" = REGEXP_SUBSTR(COALESCE("c"."文字1", ' '), '[^,]+', 1, 4) WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31I' AND REGEXP_SUBSTR(COALESCE("c"."文字1", ' '), '[^,]+', 1, 4) <> ' ' UNION ALL SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" + 4000 AS "單據序號", CASE WHEN "a"."異動日期" = '00000000' THEN "d"."單據日期" ELSE "a"."異動日期" END AS "異動日期", REGEXP_SUBSTR(COALESCE("c"."文字1", ' '), '[^,]+', 1, 5) AS "半成品編號", REGEXP_SUBSTR(REGEXP_SUBSTR(COALESCE("c"."文字1", ' '), '[^,]+', 1, 5), '[^-]+', 1, 1) AS "製令單號", "e"."有效日期", "e"."製造日期" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" /* 主檔 */ INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" LEFT JOIN "viewfil2062" AS "e" ON "e"."半成品編號" = REGEXP_SUBSTR(COALESCE("c"."文字1", ' '), '[^,]+', 1, 5) WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31I' AND REGEXP_SUBSTR(COALESCE("c"."文字1", ' '), '[^,]+', 1, 5) <> ' ' UNION ALL SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" + 5000 AS "單據序號", CASE WHEN "a"."異動日期" = '00000000' THEN "d"."單據日期" ELSE "a"."異動日期" END AS "異動日期", REGEXP_SUBSTR(COALESCE("c"."文字1", ' '), '[^,]+', 1, 6) AS "半成品編號", REGEXP_SUBSTR(REGEXP_SUBSTR(COALESCE("c"."文字1", ' '), '[^,]+', 1, 6), '[^-]+', 1, 1) AS "製令單號", "e"."有效日期", "e"."製造日期" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" /* 主檔 */ INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" LEFT JOIN "viewfil2062" AS "e" ON "e"."半成品編號" = REGEXP_SUBSTR(COALESCE("c"."文字1", ' '), '[^,]+', 1, 6) WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31I' AND REGEXP_SUBSTR(COALESCE("c"."文字1", ' '), '[^,]+', 1, 6) <> ' ');

-- Home #1800 ViewFIL2064.製令裁切數
CREATE OR REPLACE VIEW "viewfil2064" AS (/* 裁切 */ SELECT "製令單號", SUM("捲數") AS "捲數" FROM "viewfil2062" AS "a" WHERE "a"."庫存數" > 0 GROUP BY "製令單號");

-- Home #1801 ViewFIL2065.製令包裝數
CREATE OR REPLACE VIEW "viewfil2065" AS (/* 包裝 */ SELECT REGEXP_SUBSTR("a"."文字一", '[^_]+', 1, 1) AS "製令單號", SUM(COALESCE("d"."捲數", 0)) AS "捲數" FROM "fil00401" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單別" = "b"."單別" AND "a"."單號" = "b"."單號" INNER JOIN "fil0040" AS "c" ON "a"."單別" = "c"."單據類別" AND "a"."單號" = "c"."單據編號" AND "a"."序號" = "c"."單據序號" LEFT JOIN "viewfil2062" AS "d" ON "d"."半成品編號" = "a"."文字一" WHERE "c"."單據類別" = 'C41' AND "c"."異動類別" = 'A' AND "b"."製程代碼" = 'C31I' GROUP BY REGEXP_SUBSTR("a"."文字一", '[^_]+', 1, 1));

-- Home #1802 ViewFIL2066.印檢合計數
CREATE OR REPLACE VIEW "viewfil2066" AS (SELECT "a"."單別", "a"."單號", MAX("a"."前製程米數") AS "前製程米數", MAX("a"."plc抓取米數") AS "plc抓取米數", MAX("a"."合理剔除數") AS "合理剔除數", MAX("a"."不良剔除數") AS "不良剔除數", MAX("a"."檢品數量") AS "檢品數量", MAX("a"."線內不良剔除數") AS "線內不良剔除數", MAX("a"."線外不良剔除數") AS "線外不良剔除數", MAX("a"."備註") AS "備註", STRING_AGG(CAST(COALESCE(TRIM("b"."廠客品號"), ' ') AS TEXT), ',' ORDER BY "b"."廠客品號") AS "製令單號", MAX(COALESCE("e"."回庫數量", 0)) AS "回庫數量" FROM (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "前製程米數", SUM("a"."異動單價") AS "plc抓取米數", SUM("a"."燙金費") AS "合理剔除數", SUM("a"."毛重") AS "不良剔除數", SUM("a"."贈品數量") AS "檢品數量", SUM("a"."雷射費") AS "線外不良剔除數", SUM("a"."夾鏈費") AS "線內不良剔除數", STRING_AGG(CAST(COALESCE(TRIM("c"."文字1"), ' ') AS TEXT), ' ' ORDER BY "a"."單據序號") AS "備註" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31H' GROUP BY "a"."單據類別", "a"."單據編號") AS "a" LEFT JOIN (SELECT DISTINCT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."廠客品號" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31H' AND "a"."廠客品號" <> ' ') AS "b" ON "a"."單別" = "b"."單別" AND "a"."單號" = "b"."單號" LEFT JOIN (SELECT "a"."單據類別", "a"."單據編號", SUM("a"."贈品數量") AS "回庫數量" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'G' AND "b"."製程代碼" = 'C31H' AND "c"."標籤列印次數" > 0 GROUP BY "a"."單據類別", "a"."單據編號") AS "e" ON "e"."單據類別" = "a"."單別" AND "e"."單據編號" = "a"."單號" GROUP BY "a"."單別", "a"."單號");

-- Home #1803 ViewFIL2067.印檢製令合計數
CREATE OR REPLACE VIEW "viewfil2067" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."前置單別" AS "製令單別", "a"."前置單號" AS "製令單號", CASE WHEN "c"."小單位" = 'A' THEN 'A材' WHEN "c"."小單位" = 'B' THEN 'B材' WHEN "c"."小單位" = 'C' THEN '底邊' WHEN "c"."小單位" = 'D' THEN 'A側' WHEN "c"."小單位" = 'E' THEN 'B側' ELSE ' ' END AS "加工別", MIN("a"."單據序號") AS "順序", MAX("a"."產品編號") AS "檢品編號", SUM("a"."異動數量") AS "前製程米數", SUM("a"."異動單價") AS "plc抓取米數", SUM("a"."燙金費") AS "合理剔除數", SUM("a"."毛重") AS "不良剔除數", SUM("a"."雷射費") AS "線外不良剔除數", SUM("a"."夾鏈費") AS "線內不良剔除數", SUM("a"."贈品數量") AS "檢品數量", SUM("a"."折扣率") AS "接頭數", MAX(COALESCE("e"."回庫數量", 0)) AS "回庫數量", MAX(COALESCE("d"."印刷米數", 0) * 1000) AS "生產條件米數", STRING_AGG(CAST(COALESCE(TRIM("c"."文字1"), ' ') AS TEXT), ' ' ORDER BY "a"."單據序號") AS "備註", SUM("a"."qrno") AS "耗時" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN (SELECT "f"."製令單別", "f"."製令單號", SUM("f"."印刷米數") AS "印刷米數" FROM "fil0033" AS "f" WHERE "f"."印刷基材" <> ' ' GROUP BY "f"."製令單別", "f"."製令單號") AS "d" ON "d"."製令單別" = "a"."前置單別" AND "d"."製令單號" = "a"."前置單號" LEFT JOIN (SELECT "a"."單據類別", "a"."單據編號", "a"."前置單號" AS "製令單號", "a"."單位代碼" AS "加工別", SUM("a"."贈品數量") AS "回庫數量" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'G' AND "b"."製程代碼" = 'C31H' AND "c"."標籤列印次數" > 0 GROUP BY "a"."單據類別", "a"."單據編號", "a"."前置單號", "a"."單位代碼") AS "e" ON "e"."單據類別" = "a"."單據類別" AND "e"."單據編號" = "a"."單據編號" AND "a"."前置單號" = "e"."製令單號" AND "a"."單位代碼" = "e"."加工別" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31H' GROUP BY "a"."單據類別", "a"."單據編號", "a"."前置單別", "a"."前置單號", CASE WHEN "c"."小單位" = 'A' THEN 'A材' WHEN "c"."小單位" = 'B' THEN 'B材' WHEN "c"."小單位" = 'C' THEN '底邊' WHEN "c"."小單位" = 'D' THEN 'A側' WHEN "c"."小單位" = 'E' THEN 'B側' ELSE ' ' END);

