CREATE OR REPLACE VIEW "viewfil2068" AS (SELECT "a"."單別", "a"."單號", MAX("a"."前製程米數") AS "前製程米數", MAX("a"."plc抓取米數") AS "plc抓取米數", MAX("a"."合理剔除數") AS "合理剔除數", MAX("a"."不良剔除數") AS "不良剔除數", MAX("a"."檢品數量") AS "檢品數量", MAX("a"."線內不良剔除數") AS "線內不良剔除數", MAX("a"."線外不良剔除數") AS "線外不良剔除數", MAX("a"."備註") AS "備註", STRING_AGG(CAST(COALESCE(TRIM("b"."廠客品號"), ' ') AS TEXT), ',' ORDER BY "b"."廠客品號") AS "製令單號", MAX(COALESCE("e"."回庫數量", 0)) AS "回庫數量" FROM (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "前製程米數", SUM("a"."異動單價") AS "plc抓取米數", SUM("a"."燙金費") AS "合理剔除數", SUM("a"."毛重") AS "不良剔除數", SUM("a"."贈品數量") AS "檢品數量", SUM("a"."雷射費") AS "線外不良剔除數", SUM("a"."夾鏈費") AS "線內不良剔除數", STRING_AGG(CAST(COALESCE(TRIM("c"."文字1"), ' ') AS TEXT), ' ' ORDER BY "a"."單據序號") AS "備註" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31K' GROUP BY "a"."單據類別", "a"."單據編號") AS "a" LEFT JOIN (SELECT DISTINCT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."廠客品號" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31K' AND "a"."廠客品號" <> ' ') AS "b" ON "a"."單別" = "b"."單別" AND "a"."單號" = "b"."單號" LEFT JOIN (SELECT "a"."單據類別", "a"."單據編號", SUM("a"."贈品數量") AS "回庫數量" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'G' AND "b"."製程代碼" = 'C31K' AND "c"."標籤列印次數" > 0 GROUP BY "a"."單據類別", "a"."單據編號") AS "e" ON "e"."單據類別" = "a"."單別" AND "e"."單據編號" = "a"."單號" GROUP BY "a"."單別", "a"."單號");

-- Home #1805 ViewFIL2069.裁檢製令合計數
CREATE OR REPLACE VIEW "viewfil2069" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."前置單別" AS "製令單別", "a"."前置單號" AS "製令單號", MIN("a"."單據序號") AS "順序", MAX("a"."產品編號") AS "檢品編號", SUM("a"."異動數量") AS "前製程米數", SUM("a"."異動單價") AS "plc抓取米數", SUM("a"."燙金費") AS "合理剔除數", SUM("a"."毛重") AS "不良剔除數", SUM("a"."雷射費") AS "線外不良剔除數", SUM("a"."夾鏈費") AS "線內不良剔除數", SUM("a"."贈品數量") AS "檢品數量", SUM("a"."折扣率") AS "接頭數", MAX(COALESCE("e"."回庫數量", 0)) AS "回庫數量", STRING_AGG(CAST(COALESCE(TRIM("c"."文字1"), ' ') AS TEXT), ' ' ORDER BY "a"."單據序號") AS "備註", SUM("a"."qrno") AS "耗時" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN (SELECT "a"."單據類別", "a"."單據編號", "a"."前置單號" AS "製令單號", SUM("a"."贈品數量") AS "回庫數量" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'G' AND "b"."製程代碼" = 'C31H' AND "c"."標籤列印次數" > 0 GROUP BY "a"."單據類別", "a"."單據編號", "a"."前置單號") AS "e" ON "e"."單據類別" = "a"."單據類別" AND "e"."單據編號" = "a"."單據編號" AND "a"."前置單號" = "e"."製令單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31K' GROUP BY "a"."單據類別", "a"."單據編號", "a"."前置單別", "a"."前置單號");

-- Home #1806 ViewFIL2071.前製程庫存明細
CREATE OR REPLACE VIEW "viewfil2071" AS (/* 印刷 */ SELECT 1 AS "庫存參數", "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", CAST('C11' AS TEXT) AS "製令單別", CAST("c"."歸屬編號" AS TEXT) AS "製令單號", CAST("b"."製程代碼" AS TEXT) AS "製程代碼", "c"."歸屬序號" AS "加工次數", CAST("a"."產品編號" AS TEXT) AS "本製程編號", CAST(CONCAT("c"."歸屬編號", '_', "b"."交貨日期_次批", '_', "a"."產品編號") AS TEXT) AS "半成品編號", CAST("b"."交貨日期_次批" AS TEXT) AS "加工別", CAST("a"."前製程編號" AS TEXT) AS "前製程編號", CAST(' ' AS TEXT) AS "熟成條件", ("a"."異動單價" - "a"."夾鏈費") AS "異動數量", "a"."數值2" AS "接頭數", '入庫印刷' AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" INNER JOIN "fil0041" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" AND "a"."單據序號" = "d"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31A' AND "a"."產品編號" <> ' ' UNION ALL /* 淋膜/積層 */ SELECT 1 AS "庫存參數", "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", CAST('C11' AS TEXT) AS "製令單別", CAST("c"."歸屬編號" AS TEXT) AS "製令單號", CAST("b"."製程代碼" AS TEXT) AS "製程代碼", "c"."歸屬序號" AS "加工次數", CAST("a"."產品編號" AS TEXT) AS "本製程編號", CAST(CONCAT("c"."歸屬編號", '_', "b"."交貨日期_次批", '_', "a"."產品編號") AS TEXT) AS "半成品編號", CAST("b"."交貨日期_次批" AS TEXT) AS "加工別", CAST("a"."前製程編號" AS TEXT) AS "前製程編號", CAST("b"."文字4" AS TEXT) AS "熟成條件", ("a"."異動單價" - "a"."夾鏈費") AS "異動數量", "a"."折扣率" AS "接頭數", CASE WHEN "b"."製程代碼" = 'C31B' THEN '入庫淋膜' ELSE '入庫積層' END AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" INNER JOIN "fil0041" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" AND "a"."單據序號" = "d"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" BETWEEN 'C31B' AND 'C31C' AND "a"."產品編號" <> ' ' UNION ALL /* 印刷檢品/裁切檢品入庫 */ SELECT 1 AS "庫存參數", "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", CAST('C11' AS TEXT) AS "製令單別", CAST("a"."前置單號" AS TEXT) AS "製令單號", CAST("b"."製程代碼" AS TEXT) AS "製程代碼", "c"."歸屬序號" AS "加工次數", CAST("a"."產品編號" AS TEXT) AS "本製程編號", CAST(CONCAT("a"."前置單號", '_', "d"."小單位", '_', "a"."產品編號") AS TEXT) AS "半成品編號", CAST("d"."小單位" AS TEXT) AS "加工別", CAST("a"."前製程編號" AS TEXT) AS "前製程編號", CAST(' ' AS TEXT) AS "熟成條件", ("a"."異動單價" - "a"."夾鏈費") AS "異動數量", "a"."折扣率" AS "接頭數", '入庫檢品' AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" INNER JOIN "fil0041" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" AND "a"."單據序號" = "d"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND ("b"."製程代碼" = 'C31H' OR "b"."製程代碼" = 'C31K') AND "a"."產品編號" <> ' ' UNION ALL /* 上臘 */ SELECT 1 AS "庫存參數", "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", CAST('C11' AS TEXT) AS "製令單別", CAST("c"."歸屬編號" AS TEXT) AS "製令單號", CAST("b"."製程代碼" AS TEXT) AS "製程代碼", "c"."歸屬序號" AS "加工次數", CAST("a"."產品編號" AS TEXT) AS "本製程編號", CAST(CONCAT("c"."歸屬編號", '_', "b"."交貨日期_次批", '_', "a"."產品編號") AS TEXT) AS "半成品編號", CAST("b"."交貨日期_次批" AS TEXT) AS "加工別", CAST("a"."前製程編號" AS TEXT) AS "前製程編號", CAST(' ' AS TEXT) AS "熟成條件", ("a"."異動單價" - "a"."夾鏈費") AS "異動數量", "a"."數值2" AS "接頭數", '入庫上臘' AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" INNER JOIN "fil0041" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" AND "a"."單據序號" = "d"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C32D' AND "a"."產品編號" <> ' ' UNION ALL /* 前製程領料 */ SELECT -1 AS "庫存參數", "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", CAST('C11' AS TEXT) AS "製令單別", ORA_SUBSTR(CAST(REGEXP_SUBSTR("d"."文數字4", '[^_]+', 1, 1) AS TEXT), 1, 20) AS "製令單號", ORA_SUBSTR(CAST(REGEXP_SUBSTR("d"."文數字4", '[^\^]+', 1, 2) AS TEXT), 1, 10) AS "製程代碼", 0 AS "加工次數", CAST("a"."前製程編號" AS TEXT) AS "本製程編號", ORA_SUBSTR(CAST(CAST(REGEXP_SUBSTR("d"."文數字4", '[^\^]+', 1, 1) AS TEXT) AS TEXT), 1, 30) AS "半成品編號", ORA_SUBSTR(CAST(REGEXP_SUBSTR("d"."文數字4", '[^_]+', 1, 2) AS TEXT), 1, 10) AS "加工別", CAST("a"."前製程編號" AS TEXT) AS "前製程編號", CAST(' ' AS TEXT) AS "熟成條件", "a"."異動數量" AS "異動數量", "a"."材積" AS "接頭數", '領用' AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" INNER JOIN "fil0041" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" AND "a"."單據序號" = "d"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND ("b"."製程代碼" = 'C32D' OR "b"."製程代碼" = 'C31A' OR "b"."製程代碼" = 'C31B' OR "b"."製程代碼" = 'C31C' OR "b"."製程代碼" = 'C31H' OR "b"."製程代碼" = 'C31K') AND "a"."前製程編號" <> ' ' UNION ALL /* 裁切第一欄領料 */ SELECT -1 AS "庫存參數", "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", CAST('C11' AS TEXT) AS "製令單別", CAST("a"."前製程編號" AS TEXT) AS "製令單號", CAST("a"."相關代碼1" AS TEXT) AS "製程代碼", "c"."歸屬序號" AS "加工次數", CAST("a"."廠客品號" AS TEXT) AS "本製程編號", CAST(CONCAT("a"."前製程編號", '_', "b"."交貨日期_次批", '_', "a"."廠客品號") AS TEXT) AS "半成品編號", CAST("b"."交貨日期_次批" AS TEXT) AS "加工別", CAST("a"."廠客品號" AS TEXT) AS "前製程編號", CAST("b"."文字4" AS TEXT) AS "熟成條件", "a"."異動數量" AS "異動數量", "a"."燙金費" AS "接頭數", '領用裁切' AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" INNER JOIN "fil0041" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" AND "a"."單據序號" = "d"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31D' AND "a"."廠客品號" <> ' ' UNION ALL /* 裁切第二欄領料 */ SELECT -1 AS "庫存參數", "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", CAST('C11' AS TEXT) AS "製令單別", CAST("a"."合併編號" AS TEXT) AS "製令單號", CAST("a"."相關代碼2" AS TEXT) AS "製程代碼", "c"."歸屬序號" AS "加工次數", CAST("a"."前置單號" AS TEXT) AS "本製程編號", CAST(CONCAT("a"."合併編號", '_', "b"."交貨日期_次批", '_', "a"."前置單號") AS TEXT) AS "半成品編號", CAST("b"."交貨日期_次批" AS TEXT) AS "加工別", CAST("a"."前置單號" AS TEXT) AS "前製程編號", CAST("b"."文字4" AS TEXT) AS "熟成條件", "a"."數值1" AS "異動數量", "a"."夾鏈費" AS "接頭數", '領用裁切' AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" INNER JOIN "fil0041" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" AND "a"."單據序號" = "d"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31D' AND "a"."前置單號" <> ' ' UNION ALL /* 退庫：類別G */ SELECT 1 AS "庫存參數", "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", CAST('C11' AS TEXT) AS "製令單別", CAST("a"."前置單號" AS TEXT) AS "製令單號", CAST("a"."前置單別" AS TEXT) AS "製程代碼", "c"."歸屬序號" AS "加工次數", CAST("a"."廠客品號" AS TEXT) AS "本製程編號", CAST(CONCAT("a"."前置單號", '_', "a"."單位代碼", '_', "a"."廠客品號") AS TEXT) AS "半成品編號", CAST("a"."單位代碼" AS TEXT) AS "加工別", CAST("a"."廠客品號" AS TEXT) AS "前製程編號", CAST("b"."文字4" AS TEXT) AS "熟成條件", "a"."贈品數量" AS "異動數量", "a"."數值2" AS "接頭數", '退庫' AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" INNER JOIN (SELECT DISTINCT "a"."單據類別", "a"."單據編號", "a"."單據序號" FROM "fil004a" AS "a") AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" AND "a"."單據序號" = "d"."單據序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'G' AND "a"."廠客品號" <> ' ');

