CREATE OR REPLACE VIEW "viewfil2072" AS (/* 印刷 */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", CAST("c"."歸屬類別" AS TEXT) AS "製令單別", CAST("c"."歸屬編號" AS TEXT) AS "製令單號", CAST("b"."製程代碼" AS TEXT) AS "製程代碼", CAST("a"."產品編號" AS TEXT) AS "本製程編號", CAST("b"."交貨日期_次批" AS TEXT) AS "加工別", CASE WHEN "c"."歸屬序號" = 0 THEN 1 ELSE "c"."歸屬序號" END AS "加工次數", "d"."專案代號" AS "規格", "a"."折扣率" AS "圓周" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" INNER JOIN "fil0041" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" AND "a"."單據序號" = "d"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31A' AND "a"."產品編號" <> ' ' UNION ALL /* 淋膜/積層 */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", CAST("c"."歸屬類別" AS TEXT) AS "製令單別", CAST("c"."歸屬編號" AS TEXT) AS "製令單號", CAST("b"."製程代碼" AS TEXT) AS "製程代碼", CAST("a"."產品編號" AS TEXT) AS "本製程編號", CAST("b"."交貨日期_次批" AS TEXT) AS "加工別", CASE WHEN "c"."歸屬序號" = 0 THEN 1 ELSE "c"."歸屬序號" END AS "加工次數", "d"."專案代號" AS "規格", "a"."氣閥費" AS "圓周" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" INNER JOIN "fil0041" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" AND "a"."單據序號" = "d"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" BETWEEN 'C31B' AND 'C31C' AND "a"."產品編號" <> ' ' UNION ALL /* 印刷檢品/裁切檢品入庫 */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", CAST("a"."前置單別" AS TEXT) AS "製令單別", CAST("a"."前置單號" AS TEXT) AS "製令單號", CAST("b"."製程代碼" AS TEXT) AS "製程代碼", CAST("a"."產品編號" AS TEXT) AS "本製程編號", CAST("d"."小單位" AS TEXT) AS "加工別", "c"."歸屬序號" AS "加工次數", "d"."專案代號" AS "規格", "a"."氣閥費" AS "圓周" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" INNER JOIN "fil0041" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" AND "a"."單據序號" = "d"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND ("b"."製程代碼" = 'C31H' OR "b"."製程代碼" = 'C31K') AND "a"."產品編號" <> ' ' UNION ALL /* 上臘 */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", CAST("c"."歸屬類別" AS TEXT) AS "製令單別", CAST("c"."歸屬編號" AS TEXT) AS "製令單號", CAST("b"."製程代碼" AS TEXT) AS "製程代碼", CAST("a"."產品編號" AS TEXT) AS "本製程編號", CAST("b"."交貨日期_次批" AS TEXT) AS "加工別", "c"."歸屬序號" AS "加工次數", "d"."專案代號" AS "規格", "a"."折扣率" AS "圓周" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" INNER JOIN "fil0041" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" AND "a"."單據序號" = "d"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C32D' AND "a"."產品編號" <> ' ');

