CREATE OR REPLACE VIEW "viewfil2073" AS (SELECT "a"."條碼", MIN("a"."接頭數") AS "接頭數", SUM("a"."異動數量" * "庫存參數") AS "庫存數量" FROM (SELECT "a"."庫存參數", "a"."條碼", "a"."異動數量", FIRST_VALUE("a"."接頭數") OVER (PARTITION BY "a"."條碼" ORDER BY "a"."最後更新日" DESC) AS "接頭數" FROM (SELECT 1 AS "庫存參數", CAST(CONCAT("c"."歸屬編號", '_', "b"."交貨日期_次批", '_', "a"."產品編號", '^', "b"."製程代碼") AS TEXT) AS "條碼", ("a"."異動單價" - "a"."夾鏈費") AS "異動數量", "a"."數值2" AS "接頭數", "a"."最後更新日" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31A' AND "a"."產品編號" <> ' ' UNION ALL /* 淋膜/積層 */ SELECT 1 AS "庫存參數", CAST(CONCAT("c"."歸屬編號", '_', "b"."交貨日期_次批", '_', "a"."產品編號", '^', "b"."製程代碼") AS TEXT) AS "條碼", ("a"."異動單價" - "a"."夾鏈費") AS "異動數量", "a"."折扣率" AS "接頭數", "a"."最後更新日" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" BETWEEN 'C31B' AND 'C31C' AND "a"."產品編號" <> ' ' UNION ALL /* 印刷檢品/裁切檢品入庫 */ SELECT 1 AS "庫存參數", CAST(CONCAT("a"."前置單號", '_', "d"."小單位", '_', "a"."產品編號", '^', "b"."製程代碼") AS TEXT) AS "條碼", ("a"."異動單價" - "a"."夾鏈費") AS "異動數量", "a"."折扣率" AS "接頭數", "a"."最後更新日" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" INNER JOIN "fil0041" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" AND "a"."單據序號" = "d"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND ("b"."製程代碼" = 'C31H' OR "b"."製程代碼" = 'C31K') AND "a"."產品編號" <> ' ' UNION ALL /* 上臘 */ SELECT 1 AS "庫存參數", CAST(CONCAT("c"."歸屬編號", '_', "b"."交貨日期_次批", '_', "a"."產品編號", '^', "b"."製程代碼") AS TEXT) AS "條碼", ("a"."異動單價" - "a"."夾鏈費") AS "異動數量", "a"."qrno" AS "接頭數", "a"."最後更新日" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C32D' AND "a"."產品編號" <> ' ' UNION ALL /* 前製程領料 */ SELECT -1 AS "庫存參數", CAST("d"."文數字4" AS TEXT) AS "條碼", "a"."異動數量" AS "異動數量", "a"."材積" AS "接頭數", "a"."最後更新日" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" INNER JOIN "fil0041" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" AND "a"."單據序號" = "d"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND ("b"."製程代碼" = 'C32D' OR "b"."製程代碼" = 'C31A' OR "b"."製程代碼" = 'C31B' OR "b"."製程代碼" = 'C31C' OR "b"."製程代碼" = 'C31H' OR "b"."製程代碼" = 'C31K') AND "a"."前製程編號" <> ' ' UNION ALL /* 裁切第一欄領料 */ SELECT -1 AS "庫存參數", CAST(CONCAT("a"."前製程編號", '_', "b"."交貨日期_次批", '_', "a"."廠客品號", '^', "a"."相關代碼1") AS TEXT) AS "條碼", "a"."異動數量" AS "異動數量", "a"."燙金費" AS "接頭數", "a"."最後更新日" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31D' AND "a"."廠客品號" <> ' ' UNION ALL /* 裁切第二欄領料 */ SELECT -1 AS "庫存參數", CAST(CONCAT("a"."合併編號", '_', "b"."交貨日期_次批", '_', "a"."前置單號", '^', "a"."相關代碼2") AS TEXT) AS "條碼", "a"."數值1" AS "異動數量", "a"."夾鏈費" AS "接頭數", "a"."最後更新日" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31D' AND "a"."前置單號" <> ' ' UNION ALL /* 退庫：類別G */ SELECT 1 AS "庫存參數", CAST(CONCAT("a"."前置單號", '_', "a"."單位代碼", '_', "a"."廠客品號", '^', "a"."前置單別") AS TEXT) AS "條碼", "a"."贈品數量" AS "異動數量", "a"."數值2" AS "接頭數", "a"."最後更新日" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN (SELECT DISTINCT "a"."單據類別", "a"."單據編號", "a"."單據序號" FROM "fil004a" AS "a") AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" AND "a"."單據序號" = "c"."單據序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'G' AND "a"."廠客品號" <> ' ') AS "a") AS "a" GROUP BY "a"."條碼");

