-- Home #1722 ViewFIL3112.版銅代碼
CREATE OR REPLACE VIEW "viewfil3112" AS (SELECT "a"."代碼類別", "a"."代碼名稱" AS "產品編號", "d"."品名", "d"."規格", "a"."文字參數五" AS "加工別", "a"."邏輯值" AS "系統生成", "a"."日期" AS "庫存異動日期", CASE TRIM("a"."文字參數五") WHEN 'A' THEN 'A材' WHEN 'B' THEN 'B材' WHEN 'C' THEN '底邊' WHEN 'D' THEN 'A側' WHEN 'E' THEN 'B側' ELSE ' ' END AS "加工別名稱", "a"."文字參數一" AS "色順", "a"."系統代碼" AS "代碼", CASE WHEN "a"."數字參數五" = 0 THEN 0 ELSE 1 END AS "滿版", "a"."數字參數" AS "圓周", "a"."數字參數二" AS "版長", "a"."文字參數二" AS "庫位代碼", "a"."文字參數三" AS "色順說明", CASE WHEN "a"."數字參數四" = 0 THEN 0 ELSE 1 END AS "共版", "a"."文字參數四" AS "共版代碼", TRIM(CASE WHEN "a"."數字參數六" = 0 THEN '00000000' ELSE CAST("a"."數字參數六" AS TEXT) END) AS "製造日期", TRIM(CASE WHEN "a"."數字參數三" = 0 THEN '00000000' ELSE CAST("a"."數字參數三" AS TEXT) END) AS "停用日期", "a"."文字參數" AS "說明", "a"."英數參數" AS "停用原因", CASE WHEN "a"."數字參數三" = 0 THEN 0 ELSE 1 END AS "停用", "a"."邏輯值一" AS "倉管確認", "a"."邏輯值二" AS "qrcode手動確認", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", ORA_SUBSTR(REGEXP_SUBSTR("a"."系統代碼", '[^_]+', 1, 3, 'i'), 3, 1) AS "尾碼", CASE WHEN COALESCE("c"."版銅編號", ' ') = ' ' THEN 0 ELSE 1 END AS "有子版", "a"."最後更新日" FROM "fil1014" AS "a" /* 特殊欄位 */ LEFT JOIN "fil003c" AS "c" ON "c"."版銅編號" = "a"."系統代碼" LEFT JOIN "fil0012" AS "d" ON "a"."代碼名稱" = "d"."產品編號" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."代碼類別" = CAST('版銅代碼' AS TEXT));

