-- Home #1736 ViewFIL3126.盤差原因
CREATE OR REPLACE VIEW "viewfil3126" AS (SELECT "a"."系統代碼" AS "代碼", "a"."代碼名稱" AS "名稱", "a"."文字參數" AS "說明", "a"."最後更新者", COALESCE("b"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil1014" AS "a" LEFT JOIN "fil0010" AS "b" ON "b"."員工編號" = "a"."最後更新者" WHERE "a"."代碼類別" = CAST('盤差原因' AS TEXT));

-- Home #1737 ViewFIL3127.材料入庫原因
CREATE OR REPLACE VIEW "viewfil3127" AS (SELECT "a"."系統代碼" AS "代碼", "a"."代碼名稱" AS "名稱", "a"."文字參數" AS "說明", "a"."最後更新者", COALESCE("b"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil1014" AS "a" LEFT JOIN "fil0010" AS "b" ON "b"."員工編號" = "a"."最後更新者" WHERE "a"."代碼類別" = CAST('材料入庫原因' AS TEXT));

-- Home #1738 ViewFIL3128.印製後裁修
CREATE OR REPLACE VIEW "viewfil3128" AS (SELECT "a"."系統代碼" AS "代碼", "a"."代碼名稱" AS "名稱", "a"."文字參數" AS "說明", "a"."數字參數" AS "材料幅寬", "a"."數字參數二" AS "套筒寬度", "a"."數字參數三" AS "印刷幅寬", "a"."最後更新者", COALESCE("b"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil1014" AS "a" LEFT JOIN "fil0010" AS "b" ON "b"."員工編號" = "a"."最後更新者" WHERE "a"."代碼類別" = CAST('印製後裁修' AS TEXT));

-- Home #1740 ViewFIL3801.假別代碼
CREATE OR REPLACE VIEW "viewfil3801" AS (SELECT "a"."系統代碼" AS "代碼", "a"."代碼名稱" AS "名稱", "a"."文字參數" AS "說明", "a"."數字參數" AS "至少小時", "a"."數字參數二" AS "年度限請天數", "a"."數字參數三" AS "扣薪", "a"."數字參數四" AS "扣點", "a"."文字參數一" AS "性別", "a"."邏輯值" AS "天數含假日", "a"."邏輯值一" AS "事由必打", CASE WHEN "a"."文字參數一" = ' ' OR "a"."文字參數一" = '男' THEN 1 ELSE 0 END AS "男性限定", CASE WHEN "a"."文字參數一" = ' ' OR "a"."文字參數一" = '女' THEN 1 ELSE 0 END AS "女性限定", "a"."最後更新者", COALESCE("b"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil1014" AS "a" LEFT JOIN "fil0010" AS "b" ON "b"."員工編號" = "a"."最後更新者" WHERE "a"."代碼類別" = CAST('假別代碼' AS TEXT));

-- Home #1741 ViewFIL3802.工作內容
CREATE OR REPLACE VIEW "viewfil3802" AS (SELECT "a"."系統代碼" AS "代碼", "a"."文字參數" AS "工作內容", "a"."最後更新者", COALESCE("b"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil1014" AS "a" LEFT JOIN "fil0010" AS "b" ON "b"."員工編號" = "a"."最後更新者" WHERE "a"."代碼類別" = CAST('工作內容' AS TEXT));

-- Home #1742 ViewFIL3803.假日設定
CREATE OR REPLACE VIEW "viewfil3803" AS (SELECT "a"."系統代碼" AS "代碼", "a"."代碼名稱" AS "名稱", "a"."日期" AS "假日", "a"."文字參數" AS "說明", "a"."最後更新者", "a"."邏輯值" AS "放假否", COALESCE("b"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil1014" AS "a" LEFT JOIN "fil0010" AS "b" ON "b"."員工編號" = "a"."最後更新者" WHERE "a"."代碼類別" = CAST('假日設定' AS TEXT));

-- Home #1743 ViewFIL3804.行事曆清單
CREATE OR REPLACE VIEW "viewfil3804" AS (SELECT "a"."製令單號" AS "日期", (STRING_AGG(CAST(CONCAT(TRIM(TO_CHAR("b"."序號", '99')), ') ', "b"."主旨", ' 時間:', CASE WHEN "b"."時間" = '000000' THEN '' ELSE CONCAT(' ', ORA_SUBSTR("b"."時間", 1, 2), ':', ORA_SUBSTR("b"."時間", 3, 2)) END, ' 地點:', "b"."地點") AS TEXT), CHR(13) ORDER BY "b"."序號")) AS "主旨", SUM(COALESCE(LENGTH("a"."圖檔"), 0)) AS "附檔大小" FROM "fil0037a" AS "b" INNER JOIN "fil0037" AS "a" ON "b"."單據類別" = "a"."製令單別" AND "b"."單據編號" = "a"."製令單號" AND "b"."序號" = "a"."序號" WHERE "a"."製令單別" = 'CA1' AND "a"."屬性" = '4' AND "a"."材料序號" = 0 GROUP BY "a"."製令單號");

-- Home #1744 ViewFIL3805.日期清單
CREATE OR REPLACE VIEW "viewfil3805" AS (SELECT "日" AS "日期", "陰曆日" AS "陰曆", "休假日" AS "休假", "說明日" AS "說明", "星期" AS "星期" FROM (SELECT "日", "陰曆日", "休假日", "說明日", '星期日' AS "星期" FROM "fil1019" UNION ALL SELECT "一", "陰曆一", "休假一", "說明一", '星期一' AS "星期" FROM "fil1019" UNION ALL SELECT "二", "陰曆二", "休假二", "說明二", '星期二' AS "星期" FROM "fil1019" UNION ALL SELECT "三", "陰曆三", "休假三", "說明三", '星期三' AS "星期" FROM "fil1019" UNION ALL SELECT "四", "陰曆四", "休假四", "說明四", '星期四' AS "星期" FROM "fil1019" UNION ALL SELECT "五", "陰曆五", "休假五", "說明五", '星期五' AS "星期" FROM "fil1019" UNION ALL SELECT "六", "陰曆六", "休假六", "說明六", '星期六' AS "星期" FROM "fil1019") WHERE "日" > '00000000');

-- Home #1745 ViewFIL3806.照片大小合計
CREATE OR REPLACE VIEW "viewfil3806" AS (SELECT "a"."groupid" AS "流水編號", SUM(LENGTH("a"."photo")) AS "檔案大小合計" FROM "fil0100" AS "a" GROUP BY "a"."groupid");

-- Home #1746 ViewFIL3806A.產品照片大小合計
CREATE OR REPLACE VIEW "viewfil3806a" AS (SELECT "b"."產品編號" AS "產品編號", SUM(LENGTH("a"."photo")) AS "檔案大小合計" FROM "fil0100" AS "a" INNER JOIN "fil0030" AS "m" ON "a"."groupid" = "m"."流水編號" INNER JOIN "fil0032" AS "b" ON "m"."單據類別" = "b"."製令單別" AND "m"."單據編號" = "b"."製令單號" GROUP BY "b"."產品編號");

-- Home #1816 ViewFIL4002.估價袋型合計
CREATE OR REPLACE VIEW "viewfil4002" AS (SELECT "b"."單別", "b"."單號", "a"."流水編號", "a"."價格" FROM (SELECT "a"."流水編號", SUM("a"."價格") AS "價格" FROM "fil003j" AS "a" WHERE "a"."選擇" = 1 GROUP BY "a"."流水編號") AS "a" INNER JOIN "fil003i" AS "b" ON "a"."流水編號" = "b"."流水編號");

-- Home #1817 ViewFIL4003.估價燙金費
CREATE OR REPLACE VIEW "viewfil4003" AS (SELECT "a"."流水編號", "a"."單據序號", MAX("b"."異動數量") AS "購買數量", COUNT("a"."序號") AS "共幾色", SUM("a"."版費") AS "版費", SUM("a"."材料單價" * "b"."異動數量") AS "材料費" FROM "fil003j1" AS "a" INNER JOIN "fil0040" AS "b" ON "b"."流水編號" = "a"."流水編號" AND "b"."單據序號" = "a"."單據序號" GROUP BY "a"."流水編號", "a"."單據序號");

-- Home #1818 ViewFIL4004.估價單明細
CREATE OR REPLACE VIEW "viewfil4004" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動類別" AS "類別", "a"."折讓" AS "價格倍率", "a"."贈品數量" AS "合計價格", "a"."異動單價" AS "單價", "a"."異動數量" AS "購買數量", "a"."異動金額" AS "總價", "a"."毛重" AS "色數", "a"."材積" AS "每色製版費", "a"."製版費", "a"."燙金費", "a"."雷射費" AS "雷射開窗", "a"."夾鏈費", "a"."氣閥費", "a"."鐵條費", "a"."異動金額" + "a"."製版費" + "a"."燙金費" + "a"."雷射費" + "a"."夾鏈費" + "a"."氣閥費" + "a"."鐵條費" AS "未稅金額", CONCAT('倍率:', TRIM(TO_CHAR("a"."折讓", '990.00')), ' ', '單價:', TRIM(TO_CHAR(CASE WHEN "a"."異動數量" = 0 THEN 0 ELSE CAST(("a"."異動金額" + "a"."燙金費" + "a"."雷射費" + "a"."夾鏈費" + "a"."氣閥費" + "a"."鐵條費") AS DOUBLE PRECISION) / "a"."異動數量" END, '99,990.00')), ' ', '數量:', TRIM(TO_CHAR("a"."異動數量", '999,999')), ' ', '未稅金額:', TRIM(TO_CHAR("a"."異動金額" + "a"."製版費" + "a"."燙金費" + "a"."雷射費" + "a"."夾鏈費" + "a"."氣閥費" + "a"."鐵條費", '9,999,999'))) AS "說明", "a"."數值1" AS "應稅金額", "a"."備註說明" AS "備註", "a"."流水編號", "a"."最後更新者", COALESCE("b"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" LEFT JOIN "fil0010" AS "b" ON "a"."最後更新者" = "b"."員工編號" WHERE "a"."單據類別" = 'B01');

-- Home #1820 ViewFIL4011.報價單明細
CREATE OR REPLACE VIEW "viewfil4011" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "f"."類別" AS "類別", CASE WHEN "f"."類別" = 'A' THEN '新品' WHEN "f"."類別" = 'B' THEN '重覆訂單' WHEN "f"."類別" = 'C' THEN '改版' ELSE '其他' END AS "類別名稱", "a"."前置單別", "a"."前置單號", CONCAT('倍率:', TRIM(TO_CHAR("d"."折讓", '990.00')), ' ', '單價:', TRIM(TO_CHAR(CASE WHEN "a"."異動數量" = 0 THEN 0 ELSE "a"."數值1" END, '99,990.00')), ' ', '數量:', TRIM(TO_CHAR("a"."異動數量", '999,999')), ' ', '未稅金額:', TRIM(TO_CHAR("a"."異動金額", '9,999,999'))) AS "產品編號", ' ' AS "品名", ' ' AS "規格", ' ' AS "材質", ' ' AS "印刷", "a"."異動數量" AS "數量", "a"."單位代碼", COALESCE("h"."名稱", ' ') AS "單位名稱", "a"."異動單價" AS "單價", "a"."數值1" AS "總體單價", "a"."異動金額" AS "總價", "a"."製版費", "a"."折扣率" AS "色數", "a"."折讓" AS "每色製版費", "a"."燙金費", "a"."雷射費", "a"."贈品數量" AS "未稅金額", "a"."毛重" AS "含稅金額", "a"."材積" AS "含稅訂金", "a"."備註說明" AS "備註", ' ' AS "估價單號", "c"."估價流水編號", "a"."qrno" AS "估價單序號", "a"."流水編號", "a"."最後更新者", COALESCE("b"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" INNER JOIN "fil004g" AS "c" ON "c"."單別" = "a"."單據類別" AND "c"."單號" = "a"."單據編號" AND "c"."序號" = "a"."單據序號" INNER JOIN "fil0031" AS "f" ON "f"."單別" = "a"."單據類別" AND "f"."單號" = "a"."單據編號" LEFT JOIN "fil0040" AS "d" ON "c"."估價流水編號" = "d"."流水編號" AND "a"."qrno" = "d"."單據序號" LEFT JOIN "fil0010" AS "b" ON "a"."最後更新者" = "b"."員工編號" LEFT JOIN "viewfil3103" AS "h" ON "a"."單位代碼" = "h"."代碼" WHERE "a"."單據類別" = 'B11');

-- Home #1821 ViewFIL4012.報價單平均
CREATE OR REPLACE VIEW "viewfil4012" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", AVG("a"."數值1") AS "總體單價" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'B11' AND "a"."數值1" <> 0 GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #1822 ViewFIL401A.報價單合計
CREATE OR REPLACE VIEW "viewfil401a" AS (SELECT "a"."單別", "a"."單號", "a"."數量", "a"."總價", "a"."製版費", "a"."燙金費", "a"."雷射費", "a"."總價" + "a"."製版費" + "a"."燙金費" + "a"."雷射費" AS "合計總價", "c"."稅率", "d"."數值1" AS "訂金率", "d"."訂金", ROUND(CAST(("a"."總價" + "a"."製版費" + "a"."燙金費" + "a"."雷射費") * "c"."稅率" AS DOUBLE PRECISION) / 100) AS "稅額", ROUND(("a"."總價" + "a"."製版費" + "a"."燙金費" + "a"."雷射費") * (1 + CAST("c"."稅率" AS DOUBLE PRECISION) / 100)) AS "含稅價" FROM (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "數量", SUM("a"."異動金額") AS "總價", SUM("a"."製版費") AS "製版費", SUM("a"."燙金費") AS "燙金費", SUM("a"."雷射費") AS "雷射費" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'B11' GROUP BY "a"."單據類別", "a"."單據編號") AS "a" INNER JOIN "fil0030" AS "c" ON "a"."單別" = "c"."單據類別" AND "a"."單號" = "c"."單據編號" INNER JOIN "fil0031" AS "d" ON "a"."單別" = "d"."單別" AND "a"."單號" = "d"."單號");

-- Home #1829 ViewFIL402A.客戶訂單合計
CREATE OR REPLACE VIEW "viewfil402a" AS (SELECT "a"."單別", "a"."單號", "a"."訂單數量", "a"."已交數量", "a"."贈品量", "a"."贈品已交量", "a"."金額", "a"."毛重", "a"."材積", "b"."稅率", ROUND(CAST("a"."金額" * "b"."稅率" AS DOUBLE PRECISION) / 100) AS "稅額", ROUND("a"."金額" * (1 + CAST("b"."稅率" AS DOUBLE PRECISION) / 100)) AS "含稅金額" FROM (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "訂單數量", 0 AS "已交數量", SUM("a"."贈品數量") AS "贈品量", 0 AS "贈品已交量", SUM("a"."異動金額") AS "金額", SUM("a"."毛重") AS "毛重", SUM("a"."材積") AS "材積" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'B31' GROUP BY "a"."單據類別", "a"."單據編號") AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單別" = "b"."單據類別" AND "a"."單號" = "b"."單據編號");

-- Home #1830 ViewFIL402B.報價訂單合計
CREATE OR REPLACE VIEW "viewfil402b" AS (SELECT COALESCE("a"."單據類別", "b"."歸屬類別") AS "單別", COALESCE("a"."單據編號", "b"."歸屬編號") AS "單號", COALESCE("a"."產品編號", "b"."產品編號") AS "產品編號", COALESCE("a"."報價數量", 0) AS "報價數量", COALESCE("b"."訂單數量", 0) AS "訂單數量", COALESCE("a"."報價數量", 0) - COALESCE("b"."訂單數量", 0) AS "未訂購數", COALESCE("a"."報價金額", 0) AS "報價金額", COALESCE("b"."訂單金額", 0) AS "訂單金額" FROM (/* 報價單 */ SELECT "a"."單據類別", "a"."單據編號", "a"."產品編號", SUM("a"."異動數量") AS "報價數量", SUM("a"."異動金額" + "a"."製版費" + "a"."燙金費" + "a"."雷射費") AS "報價金額" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'B11' GROUP BY "a"."單據類別", "a"."單據編號", "a"."產品編號") AS "a" FULL OUTER JOIN (/* 訂單 */ SELECT "b"."歸屬類別", "b"."歸屬編號", "a"."產品編號", SUM("a"."異動數量") AS "訂單數量", SUM("a"."異動金額") AS "訂單金額" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" WHERE "a"."單據類別" = 'B31' GROUP BY "b"."歸屬類別", "b"."歸屬編號", "a"."產品編號") AS "b" ON "a"."單據類別" = "b"."歸屬類別" AND "a"."單據編號" = "b"."歸屬編號" AND "a"."產品編號" = "b"."產品編號");

-- Home #1838 ViewFIL402H.送貨單合計
CREATE OR REPLACE VIEW "viewfil402h" AS (SELECT "a"."單別", "a"."單號", "a"."訂單數量", "a"."已交數量", "a"."贈品量", "a"."贈品已交量", "a"."金額", "a"."毛重", "a"."材積", "b"."稅率", "a"."稅額" AS "稅額", "a"."金額" + "a"."稅額" AS "含稅金額" FROM (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "訂單數量", 0 AS "已交數量", SUM("a"."贈品數量") AS "贈品量", 0 AS "贈品已交量", SUM("a"."異動金額") AS "金額", SUM("a"."異動稅額") AS "稅額", SUM("a"."毛重") AS "毛重", SUM("a"."材積") AS "材積" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'B42' GROUP BY "a"."單據類別", "a"."單據編號") AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單別" = "b"."單據類別" AND "a"."單號" = "b"."單據編號");

-- Home #1841 ViewFIL402K.退貨單合計
CREATE OR REPLACE VIEW "viewfil402k" AS (SELECT "a"."單別", "a"."單號", "a"."訂單數量", "a"."已交數量", "a"."贈品量", "a"."贈品已交量", "a"."金額", "a"."毛重", "a"."材積", "b"."稅率", "a"."稅額", "a"."金額" + "a"."稅額" AS "含稅金額" FROM (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "訂單數量", 0 AS "已交數量", SUM("a"."贈品數量") AS "贈品量", 0 AS "贈品已交量", SUM("a"."異動金額") AS "金額", SUM("a"."異動稅額") AS "稅額", SUM("a"."毛重") AS "毛重", SUM("a"."材積") AS "材積" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'B51' GROUP BY "a"."單據類別", "a"."單據編號") AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單別" = "b"."單據類別" AND "a"."單號" = "b"."單據編號");

-- Home #1849 ViewFIL4030.製令主檔.C11_C報價
CREATE OR REPLACE VIEW "viewfil4030_c" AS (SELECT "a"."製令單別", "a"."製令單號", "b"."歸屬類別" AS "訂單單別", "b"."歸屬編號" AS "訂單單號", "a"."產品編號", "a"."產品名稱", COALESCE("i1"."規格", COALESCE("i2"."規格", ' ')) AS "產品規格", "b"."廠客編號" AS "客戶編號", "b"."單據日期" AS "單據日期", COALESCE("h"."全名", ' ') AS "客戶名稱", "b"."稅別" AS "類別", "a"."成袋數", "i3"."成捲數", COALESCE("i4"."說明一", ' ') AS "報價單號", COALESCE("i5"."總體單價", 0) AS "總體單價", COALESCE("i5"."總體單價", 0) * CASE WHEN "a"."成袋數" = 0 THEN "i3"."成捲數" ELSE "a"."成袋數" END AS "總價", "b"."流水編號" FROM "fil0032" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."製令單別" = "b"."單據類別" AND "a"."製令單號" = "b"."單據編號" LEFT JOIN "fil0030" AS "f" ON "b"."歸屬類別" = "f"."單據類別" AND "b"."歸屬編號" = "f"."單據編號" LEFT JOIN "fil0011" AS "h" ON "b"."廠客編號" = "h"."編號" LEFT JOIN "fil0012" AS "i1" ON "a"."產品編號" = "i1"."產品編號" LEFT JOIN "fil0012" AS "i2" ON TRIM(REGEXP_SUBSTR("a"."產品編號", '([^/]+)', 1, 1)) = "i2"."產品編號" /* 訂單公司別 */ LEFT JOIN "fil0033" AS "i3" ON "a"."製令單別" = "i3"."製令單別" AND "a"."製令單號" = "i3"."製令單號" AND "i3"."加工別" = 'A' INNER JOIN "fil0038" AS "i4" ON "b"."流水編號" = "i4"."流水編號" INNER JOIN "viewfil4012" AS "i5" ON "i5"."單號" = COALESCE("i4"."說明一", ' '));

-- Home #1851 ViewFIL4031.製令色順
CREATE OR REPLACE VIEW "viewfil4031" AS (SELECT "a"."製令單別", "a"."製令單號", "a"."加工別", 1 AS "序號", "a"."印刷色順一" AS "色順" FROM "fil0033" AS "a" WHERE "a"."印刷色順一" <> ' ' UNION ALL SELECT "a"."製令單別", "a"."製令單號", "a"."加工別", 2 AS "序號", "a"."印刷色順二" AS "色順" FROM "fil0033" AS "a" WHERE "a"."印刷色順二" <> ' ' UNION ALL SELECT "a"."製令單別", "a"."製令單號", "a"."加工別", 3 AS "序號", "a"."印刷色順三" AS "色順" FROM "fil0033" AS "a" WHERE "a"."印刷色順三" <> ' ' UNION ALL SELECT "a"."製令單別", "a"."製令單號", "a"."加工別", 4 AS "序號", "a"."印刷色順四" AS "色順" FROM "fil0033" AS "a" WHERE "a"."印刷色順四" <> ' ' UNION ALL SELECT "a"."製令單別", "a"."製令單號", "a"."加工別", 5 AS "序號", "a"."印刷色順五" AS "色順" FROM "fil0033" AS "a" WHERE "a"."印刷色順五" <> ' ' UNION ALL SELECT "a"."製令單別", "a"."製令單號", "a"."加工別", 6 AS "序號", "a"."印刷色順六" AS "色順" FROM "fil0033" AS "a" WHERE "a"."印刷色順六" <> ' ' UNION ALL SELECT "a"."製令單別", "a"."製令單號", "a"."加工別", 7 AS "序號", "a"."印刷色順七" AS "色順" FROM "fil0033" AS "a" WHERE "a"."印刷色順七" <> ' ' UNION ALL SELECT "a"."製令單別", "a"."製令單號", "a"."加工別", 8 AS "序號", "a"."印刷色順八" AS "色順" FROM "fil0033" AS "a" WHERE "a"."印刷色順八" <> ' ' UNION ALL SELECT "a"."製令單別", "a"."製令單號", "a"."加工別", 9 AS "序號", "a"."印刷色順九" AS "色順" FROM "fil0033" AS "a" WHERE "a"."印刷色順九" <> ' ' UNION ALL SELECT "a"."製令單別", "a"."製令單號", "a"."加工別", 10 AS "序號", "a"."印刷色順十" AS "色順" FROM "fil0033" AS "a" WHERE "a"."印刷色順十" <> ' ' UNION ALL SELECT "a"."製令單別", "a"."製令單號", "a"."加工別", 11 AS "序號", "a"."印刷色順十一" AS "色順" FROM "fil0033" AS "a" WHERE "a"."印刷色順十一" <> ' ' UNION ALL SELECT "a"."製令單別", "a"."製令單號", "a"."加工別", 12 AS "序號", "a"."印刷色順十二" AS "色順" FROM "fil0033" AS "a" WHERE "a"."印刷色順十二" <> ' ');

-- Home #1852 ViewFIL4032.製令加工別
CREATE OR REPLACE VIEW "viewfil4032" AS (SELECT "f"."製令單別", "f"."製令單號", "f"."加工別", "f"."成捲數", (CASE WHEN "f"."印刷色順一" = ' ' THEN 0 ELSE 1 END + CASE WHEN "f"."印刷色順二" = ' ' THEN 0 ELSE 1 END + CASE WHEN "f"."印刷色順三" = ' ' THEN 0 ELSE 1 END + CASE WHEN "f"."印刷色順四" = ' ' THEN 0 ELSE 1 END + CASE WHEN "f"."印刷色順五" = ' ' THEN 0 ELSE 1 END + CASE WHEN "f"."印刷色順六" = ' ' THEN 0 ELSE 1 END + CASE WHEN "f"."印刷色順七" = ' ' THEN 0 ELSE 1 END + CASE WHEN "f"."印刷色順八" = ' ' THEN 0 ELSE 1 END + CASE WHEN "f"."印刷色順九" = ' ' THEN 0 ELSE 1 END + CASE WHEN "f"."印刷色順十" = ' ' THEN 0 ELSE 1 END + CASE WHEN "f"."印刷色順十一" = ' ' THEN 0 ELSE 1 END + CASE WHEN "f"."印刷色順十二" = ' ' THEN 0 ELSE 1 END) AS "色順數" FROM "fil0033" AS "f" WHERE "f"."印刷基材" <> ' ');

-- Home #1853 ViewFIL4033.製令膠水
CREATE OR REPLACE VIEW "viewfil4033" AS (SELECT "a"."製令單別", "a"."製令單號", "a"."材料序號", STRING_AGG(CAST(CAST(TRIM(COALESCE("b"."品名", "a"."代碼")) AS TEXT) AS TEXT), ',' ORDER BY "a"."序號") AS "膠水" FROM "fil0037" AS "a" LEFT JOIN "fil0012" AS "b" ON "a"."代碼" = "b"."產品編號" WHERE "a"."屬性" = '3' GROUP BY "a"."製令單別", "a"."製令單號", "a"."材料序號");

-- Home #1855 ViewFIL4035.變更序號
CREATE OR REPLACE VIEW "viewfil4035" AS (SELECT "a"."單據類別" AS "變更單別", "a"."單據編號" AS "變更單號", "a"."歸屬類別" AS "製令單別", "a"."歸屬編號" AS "製令單號", ROW_NUMBER() OVER (PARTITION BY "a"."歸屬編號" ORDER BY "a"."單據編號") AS "序號" FROM "fil0030" AS "a" WHERE "a"."單據類別" = 'C21' AND "a"."歸屬類別" = 'C11');

-- Home #1856 ViewFIL4036.製造日期
CREATE OR REPLACE VIEW "viewfil4036" AS (SELECT "a"."歸屬類別" AS "製令單別", "a"."歸屬編號" AS "製令單號", MAX("a"."單據日期") AS "製造日期" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31E' GROUP BY "a"."歸屬類別", "a"."歸屬編號");

-- Home #1824 ViewFIL403A.工作指示.B21
CREATE OR REPLACE VIEW "viewfil403a" AS (SELECT "a"."單別", "a"."單號", "b"."單據日期", "b"."公司代碼", COALESCE("c"."全名", ' ') AS "公司名稱", "a"."客戶說明" AS "客戶名稱", "a"."產品說明" AS "產品名稱", "a"."指示單別", "a"."接稿日期", "a"."發版日期", "b"."業務員" AS "營業人員", COALESCE("d"."員工姓名", ' ') AS "營業人員姓名", "a"."設計製稿", COALESCE("e"."員工姓名", ' ') AS "設計製稿姓名", "b"."簽核系統", "b"."流水編號", "b"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "b"."填表日", "b"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "b"."最後更新日", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態" FROM "fil0036" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單別" = "b"."單據類別" AND "a"."單號" = "b"."單據編號" LEFT JOIN "viewfil0011" AS "c" ON "b"."公司代碼" = "c"."代碼" LEFT JOIN "fil0010" AS "d" ON "b"."業務員" = "d"."員工編號" LEFT JOIN "fil0010" AS "e" ON "a"."設計製稿" = "e"."員工編號" LEFT JOIN "fil0010" AS "z1" ON "b"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "b"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewfil0030" AS "z3" ON "b"."簽核系統" = "z3"."簽核系統" AND "b"."單據編號" = "z3"."單號");

-- Home #1825 ViewFIL403A1.工作指示用料明細
CREATE OR REPLACE VIEW "viewfil403a1" AS (SELECT "a"."製令單別", "a"."製令單號", "a"."加工類別", "a"."材料序號", TO_NCHAR(CONCAT(CASE WHEN "a"."組合材質結構" = 1 THEN '■' WHEN "a"."組合材質結構" = 0 THEN '/' END, TRIM(CONCAT(CASE WHEN COALESCE("b"."品名", ' ') = ' ' THEN N' ' ELSE CONCAT(TRIM(COALESCE("b"."品名", ' ')), TRIM(COALESCE("b"."規格", ' '))) END, CASE WHEN "a"."材料說明" = ' ' THEN N' ' ELSE CONCAT('(', TRIM("a"."材料說明"), ')') END)), TRIM(CASE WHEN "a"."排在基材前面" = 1 THEN N' ' ELSE CONCAT(CASE WHEN COALESCE("c"."品名", ' ') = ' ' THEN N' ' ELSE CONCAT('_', TRIM(CONCAT(CASE WHEN COALESCE("c"."品名", ' ') = ' ' THEN N' ' ELSE '淋' END, COALESCE("c"."品名", ' '))), ' ', TRIM(CONCAT(COALESCE("a"."厚度", ' '), CASE WHEN COALESCE("a"."厚度", ' ') = ' ' THEN N' ' ELSE 'μ' END))) END, CASE WHEN "a"."塑膠粒說明" = ' ' THEN N' ' ELSE CONCAT('(', TRIM("a"."塑膠粒說明"), ')') END) END))) AS "用料", TO_NCHAR(TRIM(CASE WHEN "a"."排在基材前面" = 0 THEN N' ' ELSE CONCAT(CASE WHEN COALESCE("c"."品名", ' ') = ' ' THEN N' ' ELSE CONCAT(TRIM(CONCAT(CASE WHEN COALESCE("c"."品名", ' ') = ' ' THEN N' ' ELSE '淋' END, COALESCE("c"."品名", ' '))), ' ', TRIM(CONCAT(COALESCE("a"."厚度", ' '), CASE WHEN COALESCE("a"."厚度", ' ') = ' ' THEN N' ' ELSE 'μ' END))) END, CASE WHEN "a"."塑膠粒說明" = ' ' THEN N' ' ELSE CONCAT('(', TRIM("a"."塑膠粒說明"), ')') END) END)) AS "排在基材前面塑膠料", TO_NCHAR(TRIM(CASE WHEN "a"."排在材料前面" = 0 THEN CONCAT(CASE WHEN "a"."組合材質結構" = 1 THEN '■' WHEN "a"."組合材質結構" = 0 THEN '/' END, TRIM(CONCAT(CASE WHEN COALESCE("b"."品名", ' ') = ' ' THEN N' ' ELSE CONCAT(TRIM(COALESCE("b"."品名", ' ')), TRIM(COALESCE("b"."規格", ' '))) END, CASE WHEN "a"."材料說明" = ' ' THEN N' ' ELSE CONCAT('(', TRIM("a"."材料說明"), ')') END)), TRIM(CASE WHEN "a"."排在基材前面" = 1 THEN N' ' ELSE CONCAT(CASE WHEN COALESCE("c"."品名", ' ') = ' ' THEN N' ' ELSE CONCAT('_', TRIM(CONCAT(CASE WHEN COALESCE("c"."品名", ' ') = ' ' THEN N' ' ELSE '淋' END, COALESCE("c"."品名", ' '))), ' ', TRIM(CONCAT(COALESCE("a"."厚度", ' '), CASE WHEN COALESCE("a"."厚度", ' ') = ' ' THEN N' ' ELSE 'μ' END))) END, CASE WHEN "a"."塑膠粒說明" = ' ' THEN N' ' ELSE CONCAT('(', TRIM("a"."塑膠粒說明"), ')') END) END)) ELSE CONCAT(CASE WHEN "a"."組合材質結構" = 1 THEN '■' WHEN "a"."組合材質結構" = 0 THEN '/' END, TRIM(CONCAT(CASE WHEN COALESCE("c"."品名", ' ') = ' ' THEN ' ' ELSE '淋' END, COALESCE("c"."品名", ' '))), ' ', TRIM(CONCAT(COALESCE("a"."厚度", ' '), CASE WHEN COALESCE("a"."厚度", ' ') = ' ' THEN N' ' ELSE 'μ' END)), CASE WHEN "a"."塑膠粒說明" = ' ' THEN N' ' ELSE CONCAT('(', TRIM("a"."塑膠粒說明"), ')') END, TRIM(CASE WHEN COALESCE("c"."品名", ' ') = ' ' THEN N' ' ELSE '/' END), TRIM(CONCAT(CASE WHEN COALESCE("b"."品名", ' ') = ' ' THEN N' ' ELSE CONCAT(TRIM(COALESCE("b"."品名", ' ')), TRIM(COALESCE("b"."規格", ' '))) END, CASE WHEN "a"."材料說明" = ' ' THEN N' ' ELSE CONCAT('(', TRIM("a"."材料說明"), ')') END))) END)) AS "塑料排在用料前面" FROM "fil0034" AS "a" LEFT JOIN "fil0012" AS "b" ON "a"."材料代碼" = "b"."產品編號" LEFT JOIN "fil0012" AS "c" ON "a"."塑膠粒材料代碼" = "c"."產品編號");

-- Home #1826 ViewFIL403B.工作指示用料
CREATE OR REPLACE VIEW "viewfil403b" ("製令單別", "製令單號", "加工類別", "基材", "用料", "排在基材前面塑膠料", "塑料排在用料前面") AS (SELECT "a"."製令單別", "a"."製令單號", "a"."加工別", TRIM(CONCAT(CASE WHEN COALESCE("e"."品名", ' ') = ' ' THEN ' ' ELSE CONCAT(TRIM(COALESCE("e"."品名", ' ')), ' ', TRIM(COALESCE("e"."規格", ' '))) END, CASE WHEN "a"."數位印刷" = 0 THEN ' ' ELSE CONCAT('(', '數位水墨印製後裁修', TRIM(TO_CHAR("a"."印製後裁修", '999')), ')') END, CASE WHEN "a"."基材投入說明" = ' ' THEN ' ' ELSE CONCAT('(', TRIM("a"."基材投入說明"), ')') END)) AS "基材", COALESCE("b"."用料", ' ') AS "用料", COALESCE("b"."排在基材前面塑膠料", ' ') AS "排在基材前面塑膠料", COALESCE("b"."塑料排在用料前面", ' ') AS "塑料排在用料前面" FROM "fil0033" AS "a" LEFT JOIN "fil0012" AS "e" ON "a"."印刷基材" = "e"."產品編號" LEFT JOIN (SELECT "a"."製令單別", "a"."製令單號", "a"."加工類別", STRING_AGG(CAST(CONCAT(CASE WHEN "a"."組合材質結構" = 1 THEN '■' WHEN "a"."組合材質結構" = 0 THEN '/' END, TRIM(CONCAT(CASE WHEN COALESCE("b"."品名", ' ') = ' ' THEN ' ' ELSE CONCAT(TRIM(COALESCE("b"."品名", ' ')), TRIM(COALESCE("b"."規格", ' '))) END, CASE WHEN "a"."材料說明" = ' ' THEN ' ' ELSE CONCAT('(', TRIM("a"."材料說明"), ')') END)), TRIM(CASE WHEN "a"."排在基材前面" = 1 THEN ' ' ELSE CONCAT(CASE WHEN COALESCE("c"."品名", ' ') = ' ' THEN ' ' ELSE CONCAT('_', TRIM(CONCAT(CASE WHEN COALESCE("c"."品名", ' ') = ' ' THEN ' ' ELSE '淋' END, COALESCE("c"."品名", ' '))), ' ', TRIM(CONCAT(COALESCE("a"."厚度", ' '), CASE WHEN COALESCE("a"."厚度", ' ') = ' ' THEN ' ' ELSE 'μ' END))) END, CASE WHEN "a"."塑膠粒說明" = ' ' THEN ' ' ELSE CONCAT('(', TRIM("a"."塑膠粒說明"), ')') END) END)) AS TEXT), '' ORDER BY "a"."材料序號") AS "用料", STRING_AGG(CAST(TRIM(CASE WHEN "a"."排在基材前面" = 0 THEN ' ' ELSE CONCAT(CASE WHEN COALESCE("c"."品名", ' ') = ' ' THEN ' ' ELSE CONCAT(TRIM(CONCAT(CASE WHEN COALESCE("c"."品名", ' ') = ' ' THEN ' ' ELSE '淋' END, COALESCE("c"."品名", ' '))), ' ', TRIM(CONCAT(COALESCE("a"."厚度", ' '), CASE WHEN COALESCE("a"."厚度", ' ') = ' ' THEN ' ' ELSE 'μ' END))) END, CASE WHEN "a"."塑膠粒說明" = ' ' THEN ' ' ELSE CONCAT('(', TRIM("a"."塑膠粒說明"), ')') END) END) AS TEXT), '' ORDER BY "a"."材料序號") AS "排在基材前面塑膠料", STRING_AGG(CAST(TRIM(CASE WHEN "a"."排在材料前面" = 0 THEN CONCAT(CASE WHEN "a"."組合材質結構" = 1 THEN '■' WHEN "a"."組合材質結構" = 0 THEN '/' END, TRIM(CONCAT(CASE WHEN COALESCE("b"."品名", ' ') = ' ' THEN ' ' ELSE CONCAT(TRIM(COALESCE("b"."品名", ' ')), TRIM(COALESCE("b"."規格", ' '))) END, CASE WHEN "a"."材料說明" = ' ' THEN ' ' ELSE CONCAT('(', TRIM("a"."材料說明"), ')') END)), TRIM(CASE WHEN "a"."排在基材前面" = 1 THEN ' ' ELSE CONCAT(CASE WHEN COALESCE("c"."品名", ' ') = ' ' THEN ' ' ELSE CONCAT('_', TRIM(CONCAT(CASE WHEN COALESCE("c"."品名", ' ') = ' ' THEN ' ' ELSE '淋' END, COALESCE("c"."品名", ' '))), ' ', TRIM(CONCAT(COALESCE("a"."厚度", ' '), CASE WHEN COALESCE("a"."厚度", ' ') = ' ' THEN ' ' ELSE 'μ' END))) END, CASE WHEN "a"."塑膠粒說明" = ' ' THEN ' ' ELSE CONCAT('(', TRIM("a"."塑膠粒說明"), ')') END) END)) ELSE CONCAT(CASE WHEN "a"."組合材質結構" = 1 THEN '■' WHEN "a"."組合材質結構" = 0 THEN '/' END, TRIM(CONCAT(CASE WHEN COALESCE("c"."品名", ' ') = ' ' THEN ' ' ELSE '淋' END, COALESCE("c"."品名", ' '))), ' ', TRIM(CONCAT(COALESCE("a"."厚度", ' '), CASE WHEN COALESCE("a"."厚度", ' ') = ' ' THEN ' ' ELSE 'μ' END)), CASE WHEN "a"."塑膠粒說明" = ' ' THEN ' ' ELSE CONCAT('(', TRIM("a"."塑膠粒說明"), ')') END, TRIM(CASE WHEN COALESCE("c"."品名", ' ') = ' ' THEN ' ' ELSE '/' END), TRIM(CONCAT(CASE WHEN COALESCE("b"."品名", ' ') = ' ' THEN ' ' ELSE CONCAT(TRIM(COALESCE("b"."品名", ' ')), TRIM(COALESCE("b"."規格", ' '))) END, CASE WHEN "a"."材料說明" = ' ' THEN ' ' ELSE CONCAT('(', TRIM("a"."材料說明"), ')') END))) END) AS TEXT), ' ' ORDER BY "a"."材料序號") AS "塑料排在用料前面" FROM "fil0034" AS "a" LEFT JOIN "fil0012" AS "b" ON "a"."材料代碼" = "b"."產品編號" LEFT JOIN "fil0012" AS "c" ON "a"."塑膠粒材料代碼" = "c"."產品編號" GROUP BY "a"."製令單別", "a"."製令單號", "a"."加工類別") AS "b" ON "a"."製令單別" = "b"."製令單別" AND "a"."製令單號" = "b"."製令單號" AND "a"."加工別" = "b"."加工類別");

-- Home #1860 ViewFIL4041.製令每日機台排程數
CREATE OR REPLACE VIEW "viewfil4041" AS (SELECT "a"."歸屬類別" AS "製令單別", "a"."歸屬編號" AS "製令單號", "a"."單據日期" AS "排程日期", "b"."製程代碼", "b"."機台代碼", SUM("b"."數量") AS "數量" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" WHERE "a"."單據類別" = 'C31' GROUP BY "a"."歸屬類別", "a"."歸屬編號", "a"."單據日期", "b"."製程代碼", "b"."機台代碼");

-- Home #1861 ViewFIL4041A.製令製程排程數
CREATE OR REPLACE VIEW "viewfil4041a" AS (SELECT "a"."歸屬類別" AS "製令單別", "a"."歸屬編號" AS "製令單號", "b"."製程代碼", SUM("b"."數量") AS "數量" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" WHERE "a"."單據類別" = 'C31' GROUP BY "a"."歸屬類別", "a"."歸屬編號", "b"."製程代碼");

-- Home #1862 ViewFIL4041B.製令日機台加工排
CREATE OR REPLACE VIEW "viewfil4041b" AS (SELECT "a"."歸屬類別" AS "製令單別", "a"."歸屬編號" AS "製令單號", "a"."稅別" AS "加工別", "a"."單據日期" AS "排程日期", "b"."製程代碼", "b"."機台代碼", SUM("b"."數量" * 1000) AS "數量" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" WHERE "a"."單據類別" = 'C31' GROUP BY "a"."歸屬類別", "a"."歸屬編號", "a"."稅別", "a"."單據日期", "b"."製程代碼", "b"."機台代碼");

-- Home #1863 ViewFIL4041C.製令製程加工排
CREATE OR REPLACE VIEW "viewfil4041c" AS (SELECT "a"."歸屬類別" AS "製令單別", "a"."歸屬編號" AS "製令單號", "a"."稅別" AS "加工別", "b"."製程代碼", SUM("b"."數量" * 1000) AS "數量" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" WHERE "a"."單據類別" = 'C31' GROUP BY "a"."歸屬類別", "a"."歸屬編號", "a"."稅別", "b"."製程代碼");

-- Home #1865 ViewFIL4043.製令淋膜積層用料
CREATE OR REPLACE VIEW "viewfil4043" ("製令單別", "製令單號", "加工類別", "材料代碼") AS SELECT "a"."製令單別", "a"."製令單號", "a"."加工類別", STRING_AGG(CAST("a"."材料代碼" AS TEXT), ',' ORDER BY "材料代碼") AS "材料代碼" FROM "fil0034" AS "a" WHERE "a"."材料代碼" <> ' ' GROUP BY "a"."製令單別", "a"."製令單號", "a"."加工類別";

-- Home #1867 ViewFIL4045.製令製程預排
CREATE OR REPLACE VIEW "viewfil4045" ("製程代碼", "預計投產日", "製令單號") AS (SELECT "fil0039"."製程代碼", "fil0039"."預計投產日", STRING_AGG(CAST("fil0039"."製令單號" AS TEXT), ',' ORDER BY "fil0039"."製程代碼", "fil0039"."預計投產日") FROM "fil0039" WHERE "fil0039"."預計投產日" > '00000000' GROUP BY "fil0039"."製程代碼", "fil0039"."預計投產日");

-- Home #1868 ViewFIL4046.製令用料明細
CREATE OR REPLACE VIEW "viewfil4046" ("用途", "製令單別", "製令單號", "加工類別", "材料序號", "材料代碼", "材料名稱") AS (SELECT '印刷基材', "a"."製令單別", "a"."製令單號", CASE WHEN "a"."加工別" = 'A' THEN 'A.A材' WHEN "a"."加工別" = 'B' THEN 'B.B材' WHEN "a"."加工別" = 'C' THEN 'C.底邊' WHEN "a"."加工別" = 'D' THEN 'D.A側' WHEN "a"."加工別" = 'E' THEN 'E.B側' ELSE ' ' END, 0, "a"."印刷基材", CONCAT("b"."品名", ' ', "b"."規格") FROM "fil0033" AS "a", "fil0012" AS "b" WHERE "a"."印刷基材" <> ' ' AND "a"."印刷基材" = "b"."產品編號" UNION ALL SELECT '淋膜積層材料', "a"."製令單別", "a"."製令單號", CASE WHEN "a"."加工類別" = 'A' THEN 'A.A材' WHEN "a"."加工類別" = 'B' THEN 'B.B材' WHEN "a"."加工類別" = 'C' THEN 'C.底邊' WHEN "a"."加工類別" = 'D.A側' THEN 'E' WHEN "a"."加工類別" = 'E.B側' THEN ' ' END, "a"."材料序號", "a"."材料代碼", CONCAT("b"."品名", ' ', "b"."規格") FROM "fil0034" AS "a", "fil0012" AS "b" WHERE "a"."材料代碼" <> ' ' AND "a"."材料代碼" = "b"."產品編號" UNION ALL SELECT '淋膜積層膠水', "a"."製令單別", "a"."製令單號", CASE WHEN "a"."加工類別" = 'A' THEN 'A.A材' WHEN "a"."加工類別" = 'B' THEN 'B.B材' WHEN "a"."加工類別" = 'C' THEN 'C.底邊' WHEN "a"."加工類別" = 'D.A側' THEN 'E' WHEN "a"."加工類別" = 'E.B側' THEN ' ' END, "a"."材料序號", "a"."膠水材料代碼", "b"."品名" FROM "fil0034" AS "a", "fil0012" AS "b" WHERE "a"."膠水材料代碼" <> ' ' AND "a"."膠水材料代碼" = "b"."產品編號" UNION ALL SELECT '淋膜積層塑膠粒', "a"."製令單別", "a"."製令單號", CASE WHEN "a"."加工類別" = 'A' THEN 'A.A材' WHEN "a"."加工類別" = 'B' THEN 'B.B材' WHEN "a"."加工類別" = 'C' THEN 'C.底邊' WHEN "a"."加工類別" = 'D.A側' THEN 'E' WHEN "a"."加工類別" = 'E.B側' THEN ' ' END, "a"."材料序號", "a"."塑膠粒材料代碼", CONCAT("b"."品名", ' ', "a"."厚度", 'μ') FROM "fil0034" AS "a", "fil0012" AS "b" WHERE "a"."塑膠粒材料代碼" <> ' ' AND "a"."塑膠粒材料代碼" = "b"."產品編號" UNION ALL SELECT '上臘', "a"."製令單別", "a"."製令單號", CASE WHEN "a"."加工別" = 'A' THEN 'A.A材' WHEN "a"."加工別" = 'B' THEN 'B.B材' WHEN "a"."加工別" = 'C' THEN 'C.底邊' WHEN "a"."加工別" = 'D.A側' THEN 'E' WHEN "a"."加工別" = 'E.B側' THEN ' ' END, 0, "a"."上臘材料編號", "b"."品名" FROM "fil0033" AS "a", "fil0012" AS "b" WHERE "a"."上臘材料編號" <> ' ' UNION ALL SELECT '紙箱', "a"."製令單別", "a"."製令單號", CASE WHEN "a"."加工別" = 'A' THEN 'A.A材' WHEN "a"."加工別" = 'B' THEN 'B.B材' WHEN "a"."加工別" = 'C' THEN 'C.底邊' WHEN "a"."加工別" = 'D.A側' THEN 'E' WHEN "a"."加工別" = 'E.B側' THEN ' ' END, 0, "a"."紙箱代碼", CONCAT("b"."品名", ' ', "b"."規格") FROM "fil0033" AS "a", "fil0012" AS "b" WHERE "a"."紙箱代碼" <> ' ' AND "a"."紙箱代碼" = "b"."產品編號" UNION ALL SELECT '夾鍊', "a"."製令單別", "a"."製令單號", '主檔', 0, "a"."加工項目_夾鍊代碼", CONCAT("b"."品名", ' ', "b"."規格") FROM "fil0032" AS "a", "fil0012" AS "b" WHERE "a"."加工項目_夾鍊代碼" <> ' ' AND "a"."加工項目_夾鍊代碼" = "b"."產品編號" UNION ALL SELECT '氣閥', "a"."製令單別", "a"."製令單號", '主檔', 0, "a"."加工項目_氣閥代碼", CONCAT("b"."品名", ' ', "b"."規格") FROM "fil0032" AS "a", "fil0012" AS "b" WHERE "a"."加工項目_氣閥代碼" <> ' ' AND "a"."加工項目_氣閥代碼" = "b"."產品編號" UNION ALL SELECT '鐵條', "a"."製令單別", "a"."製令單號", '主檔', 0, "a"."加工項目_鐵條代碼", CONCAT("b"."品名", ' ', "b"."規格") FROM "fil0032" AS "a", "fil0012" AS "b" WHERE "a"."加工項目_鐵條代碼" <> ' ' AND "a"."加工項目_鐵條代碼" = "b"."產品編號" UNION ALL SELECT '無氣閥紙箱', "a"."製令單別", "a"."製令單號", '主檔', 0, "a"."紙箱代碼", CONCAT("b"."品名", ' ', "b"."規格") FROM "fil0032" AS "a", "fil0012" AS "b" WHERE "a"."紙箱代碼" <> ' ' AND "a"."紙箱代碼" = "b"."產品編號" UNION ALL SELECT '氣閥紙箱', "a"."製令單別", "a"."製令單號", '主檔', 0, "a"."紙箱代碼_氣閥", CONCAT("b"."品名", ' ', "b"."規格") FROM "fil0032" AS "a", "fil0012" AS "b" WHERE "a"."紙箱代碼_氣閥" <> ' ' AND "a"."紙箱代碼" = "b"."產品編號");

-- Home #1869 ViewFIL4047.製令用料彙總
CREATE OR REPLACE VIEW "viewfil4047" ("製令單別", "製令單號", "節點", "半成品名稱", "材料") AS SELECT 'C11' AS "單據類別", "a"."製令單號" AS "單據編號", "a"."節點", "a"."半成品名稱", TRIM(CONCAT(TRIM(REPLACE(CONCAT(CASE WHEN "a"."使用半成品" = ' ' THEN ' ' ELSE "a"."使用半成品" END, CASE WHEN "a"."使用半成品二" = ' ' THEN ' ' ELSE '/' END, CASE WHEN "a"."使用半成品二" = ' ' THEN ' ' ELSE "a"."使用半成品二" END, CASE WHEN "a"."使用半成品三" = ' ' THEN ' ' ELSE '/' END, CASE WHEN "a"."使用半成品三" = ' ' THEN ' ' ELSE "a"."使用半成品三" END, CASE WHEN "a"."使用半成品四" = ' ' THEN ' ' ELSE '/' END, CASE WHEN "a"."使用半成品四" = ' ' THEN ' ' ELSE "a"."使用半成品四" END), 'A材B材', 'AB材')), CASE WHEN "a"."使用半成品" = ' ' THEN ' ' ELSE '/' END, CASE WHEN COALESCE("b"."材料名稱", ' ') = ' ' THEN ' ' ELSE COALESCE("b"."材料名稱", ' ') END, CASE WHEN COALESCE("c"."材料名稱", ' ') = ' ' THEN ' ' ELSE '/' END, CASE WHEN COALESCE("c"."材料名稱", ' ') = ' ' THEN ' ' ELSE COALESCE("c"."材料名稱", ' ') END, CASE WHEN COALESCE("d"."材料名稱", ' ') = ' ' THEN ' ' ELSE '/' END, CASE WHEN COALESCE("d"."材料名稱", ' ') = ' ' THEN ' ' ELSE COALESCE("d"."材料名稱", ' ') END, CASE WHEN COALESCE("e"."材料名稱", ' ') = ' ' THEN ' ' ELSE '/' END, CASE WHEN COALESCE("e"."材料名稱", ' ') = ' ' THEN ' ' ELSE COALESCE("e"."材料名稱", ' ') END)) FROM "fil0039" AS "a" LEFT JOIN "viewfil4046" AS "b" ON "a"."物料編號" = "b"."材料代碼" AND "a"."製令單號" = "b"."製令單號" LEFT JOIN "viewfil4046" AS "c" ON "a"."物料編號二" = "c"."材料代碼" AND "a"."製令單號" = "c"."製令單號" LEFT JOIN "viewfil4046" AS "d" ON "a"."物料編號三" = "d"."材料代碼" AND "a"."製令單號" = "d"."製令單號" LEFT JOIN "viewfil4046" AS "e" ON "a"."物料編號四" = "e"."材料代碼" AND "a"."製令單號" = "e"."製令單號";

-- Home #1870 ViewFIL4048.製令共版彙總
CREATE OR REPLACE VIEW "viewfil4048" ("製令單別", "製令單號", "加工別", "色順產品編號") AS SELECT "a"."單據類別", "a"."單據編號", "a"."加工別", STRING_AGG(CAST(CONCAT(CAST("a"."色順" AS TEXT), '：', CAST("a"."產品編號" AS TEXT), CASE WHEN "a"."母版色順代碼" = ' ' THEN ' ' ELSE CAST(CONCAT('(', "a"."母版色順代碼", ')') AS TEXT) END) AS TEXT), '，' ORDER BY "a"."色順") AS "色順產品編號" FROM "fil003c" AS "a" INNER JOIN "fil0012" AS "b" ON "a"."產品編號" = "b"."產品編號" WHERE "a"."產品編號" <> ' ' GROUP BY "a"."單據類別", "a"."單據編號", "a"."加工別" ORDER BY "a"."單據類別", "a"."單據編號", "a"."加工別";

-- Home #1871 ViewFIL4048A.製令標籤
CREATE OR REPLACE VIEW "viewfil4048a" AS SELECT "單據類別", "單據編號", "類別", "單據序號" AS "序號", CASE WHEN "類別" = 'A1' THEN 'A1:TRICOR BRAUN(客製品)' WHEN "類別" = 'A2' THEN 'A2:TRICOR BRAUN(公版品)' WHEN "類別" = 'A3' THEN 'A3:TRICOR BRAUN(客製品_加)' WHEN "類別" = 'A4' THEN 'A4:TRICOR BRAUN(公版品_加)' WHEN "類別" = 'B1' THEN 'B1:The Bag Broker EU' WHEN "類別" = 'B2' THEN 'B2:The Bag Broker EU 可分解' WHEN "類別" = 'B3' THEN 'B3:The Bag Broker UK' WHEN "類別" = 'B4' THEN 'B4:Bag Broker UK 可分解' WHEN "類別" = 'C1' THEN 'C1:The Packaging People' WHEN "類別" = 'C2' THEN 'C2:The Packing People 可分解' WHEN "類別" = 'D1' THEN 'D1:喜美標籤' WHEN "類別" = 'D2' THEN 'D2:盤商標籤' WHEN "類別" = 'E1' THEN 'E1：祥龍,F1：永恆包裝(TBB-其他)
' WHEN "類別" = 'F1' THEN 'F1：永恆包裝(TBB-其他)' ELSE ' ' END AS "類別名稱" FROM "fil003f";

-- Home #1879 ViewFIL4048AB.製令有共版
CREATE OR REPLACE VIEW "viewfil4048ab" AS (SELECT DISTINCT "a"."製令單號" FROM "fil0033" AS "a" WHERE ((CASE WHEN POSITION('共' IN "a"."印刷色順一") = 0 THEN 0 ELSE 1 END + CASE WHEN POSITION('共' IN "a"."印刷色順二") = 0 THEN 0 ELSE 1 END + CASE WHEN POSITION('共' IN "a"."印刷色順三") = 0 THEN 0 ELSE 1 END + CASE WHEN POSITION('共' IN "a"."印刷色順四") = 0 THEN 0 ELSE 1 END + CASE WHEN POSITION('共' IN "a"."印刷色順五") = 0 THEN 0 ELSE 1 END + CASE WHEN POSITION('共' IN "a"."印刷色順六") = 0 THEN 0 ELSE 1 END + CASE WHEN POSITION('共' IN "a"."印刷色順七") = 0 THEN 0 ELSE 1 END + CASE WHEN POSITION('共' IN "a"."印刷色順八") = 0 THEN 0 ELSE 1 END + CASE WHEN POSITION('共' IN "a"."印刷色順九") = 0 THEN 0 ELSE 1 END + CASE WHEN POSITION('共' IN "a"."印刷色順十") = 0 THEN 0 ELSE 1 END) - (CASE WHEN POSITION('母共' IN "a"."印刷色順一") = 0 THEN 0 ELSE 1 END + CASE WHEN POSITION('母共' IN "a"."印刷色順二") = 0 THEN 0 ELSE 1 END + CASE WHEN POSITION('母共' IN "a"."印刷色順三") = 0 THEN 0 ELSE 1 END + CASE WHEN POSITION('母共' IN "a"."印刷色順四") = 0 THEN 0 ELSE 1 END + CASE WHEN POSITION('母共' IN "a"."印刷色順五") = 0 THEN 0 ELSE 1 END + CASE WHEN POSITION('母共' IN "a"."印刷色順六") = 0 THEN 0 ELSE 1 END + CASE WHEN POSITION('母共' IN "a"."印刷色順七") = 0 THEN 0 ELSE 1 END + CASE WHEN POSITION('母共' IN "a"."印刷色順八") = 0 THEN 0 ELSE 1 END + CASE WHEN POSITION('母共' IN "a"."印刷色順九") = 0 THEN 0 ELSE 1 END + CASE WHEN POSITION('母共' IN "a"."印刷色順十") = 0 THEN 0 ELSE 1 END)) > 0 GROUP BY "a"."製令單號");

-- Home #1880 ViewFIL4048AC.製令相關產編
CREATE OR REPLACE VIEW "viewfil4048ac" AS (SELECT DISTINCT "a"."主產品編號", "a"."產品編號" FROM (SELECT "a"."產品編號" AS "主產品編號", "a"."產品編號" AS "產品編號" FROM "fil0032" AS "a" UNION SELECT "b"."產品編號" AS "主產品編號", "a"."無氣閥產品編號" AS "產品編號" FROM "fil003f" AS "a" INNER JOIN "fil0032" AS "b" ON "a"."單據類別" = "b"."製令單別" AND "a"."單據編號" = "b"."製令單號" WHERE "a"."無氣閥產品編號" <> ' ' UNION SELECT "b"."產品編號" AS "主產品編號", "a"."無氣閥有鐵條編號" AS "產品編號" FROM "fil003f" AS "a" INNER JOIN "fil0032" AS "b" ON "a"."單據類別" = "b"."製令單別" AND "a"."單據編號" = "b"."製令單號" WHERE "a"."無氣閥有鐵條編號" <> ' ' UNION SELECT "b"."產品編號" AS "主產品編號", "a"."有氣閥產品編號" AS "產品編號" FROM "fil003f" AS "a" INNER JOIN "fil0032" AS "b" ON "a"."單據類別" = "b"."製令單別" AND "a"."單據編號" = "b"."製令單號" WHERE "a"."有氣閥產品編號" <> ' ' UNION SELECT "b"."產品編號" AS "主產品編號", "a"."有氣閥有鐵條編號" AS "產品編號" FROM "fil003f" AS "a" INNER JOIN "fil0032" AS "b" ON "a"."單據類別" = "b"."製令單別" AND "a"."單據編號" = "b"."製令單號" WHERE "a"."有氣閥有鐵條編號" <> ' ') AS "a" INNER JOIN "a01_18" AS "c" ON "a"."產品編號" = "c"."產品編號" AND (LENGTH("c"."留言") > 0 OR LENGTH("c"."手繪") > 0));

-- Home #1881 ViewFIL4048AD.製令用料清單
CREATE OR REPLACE VIEW "viewfil4048ad" AS (SELECT "a"."製令單別", "a"."製令單號", "a"."加工別", '印刷基材' AS "用途", "a"."印刷基材", "a"."印刷米數" AS "用量" FROM "fil0033" AS "a" WHERE "a"."印刷基材" <> ' ' UNION SELECT "a"."製令單別", "a"."製令單號", "a"."加工別", '上臘材料' AS "用途", "a"."上臘材料編號", 0 AS "用量" FROM "fil0033" AS "a" WHERE "a"."上臘材料編號" <> ' ' UNION SELECT "a"."製令單別", "a"."製令單號", "a"."加工別", '紙箱' AS "用途", "a"."紙箱代碼", CASE WHEN "a"."每箱幾捲" = 0 THEN 0 ELSE CAST(("a"."成捲數" * 1 + CAST("a"."成捲差異比" AS DOUBLE PRECISION) / 100) AS DOUBLE PRECISION) / "a"."每箱幾捲" END AS "用量" FROM "fil0033" AS "a" WHERE "a"."紙箱代碼" <> ' ' UNION SELECT "a"."製令單別", "a"."製令單號", "a"."加工類別" AS "加工別", '膠水' AS "用途", "a"."膠水材料代碼" AS "材料代碼", 0 AS "用量" FROM "fil0034" AS "a" WHERE "a"."膠水材料代碼" <> ' ' UNION SELECT "a"."製令單別", "a"."製令單號", "a"."加工類別" AS "加工別", '塑膠粒' AS "用途", "a"."塑膠粒材料代碼" AS "材料代碼", 0 AS "用量" FROM "fil0034" AS "a" WHERE "a"."塑膠粒材料代碼" <> ' ' UNION SELECT "a"."製令單別", "a"."製令單號", ' ' AS "加工別", '夾鏈' AS "用途", "a"."加工項目_夾鍊代碼" AS "材料代碼", "a"."成袋數" * (1 + CAST("成袋差異比" AS DOUBLE PRECISION) / 100) AS "用量" FROM "fil0032" AS "a" WHERE "a"."加工項目_夾鍊代碼" <> ' ' UNION SELECT "a"."製令單別", "a"."製令單號", ' ' AS "加工別", '夾鏈二' AS "用途", "a"."加工項目_夾鍊代碼二" AS "材料代碼", "a"."成袋數" * (1 + CAST("成袋差異比" AS DOUBLE PRECISION) / 100) AS "用量" FROM "fil0032" AS "a" WHERE "a"."加工項目_夾鍊代碼二" <> ' ' UNION SELECT "a"."製令單別", "a"."製令單號", ' ' AS "加工別", '氣閥' AS "用途", "a"."加工項目_氣閥代碼" AS "材料代碼", "a"."成袋數" * (1 + CAST("成袋差異比" AS DOUBLE PRECISION) / 100) AS "用量" FROM "fil0032" AS "a" WHERE "a"."加工項目_氣閥代碼" <> ' ' UNION SELECT "a"."製令單別", "a"."製令單號", ' ' AS "加工別", '鐵條' AS "用途", "a"."加工項目_鐵條代碼" AS "材料代碼", "a"."成袋數" * (1 + CAST("成袋差異比" AS DOUBLE PRECISION) / 100) AS "用量" FROM "fil0032" AS "a" WHERE "a"."加工項目_鐵條代碼" <> ' ');

-- Home #1882 ViewFIL4048B.裁切標籤(簡版)
CREATE OR REPLACE VIEW "viewfil4048b" AS SELECT "a"."單據類別", "a"."單據編號", "a"."類別", "b"."顯示名稱" AS "類別名稱" FROM "fil003f1" AS "a" INNER JOIN "viewfil3121" AS "b" ON "a"."類別" = "b"."代碼";

-- Home #1883 ViewFIL4048B1.裁切標籤全部
CREATE OR REPLACE VIEW "viewfil4048b1" AS SELECT "a"."單據類別" AS "製令單別", "a"."單據編號" AS "製令單號", "a"."單據序號", 1 AS "產品序號", "a"."類別", CASE WHEN "a"."類別" = 'A1' THEN 'A1:TRICOR BRAUN(客製品)' WHEN "a"."類別" = 'A2' THEN 'A2:TRICOR BRAUN(公版品)' WHEN "a"."類別" = 'A3' THEN 'A3:TRICOR BRAUN(客製品_加)' WHEN "a"."類別" = 'A4' THEN 'A4:TRICOR BRAUN(公版品_加)' WHEN "a"."類別" = 'B1' THEN 'B1:The Bag Broker EU' WHEN "a"."類別" = 'B2' THEN 'B2:The Bag Broker EU 可分解' WHEN "a"."類別" = 'B3' THEN 'B3:The Bag Broker UK' WHEN "a"."類別" = 'B4' THEN 'B4:Bag Broker UK 可分解' WHEN "a"."類別" = 'C1' THEN 'C1:The Packaging People' WHEN "a"."類別" = 'C2' THEN 'C2:The Packing People 可分解' WHEN "a"."類別" = 'D1' THEN 'D1:喜美標籤' WHEN "a"."類別" = 'D2' THEN 'D2:盤商標籤' WHEN "a"."類別" = 'E1' THEN 'E1：祥龍,F1：永恆包裝(TBB-其他)
' WHEN "a"."類別" = 'F1' THEN 'F1：永恆包裝(TBB-其他)' ELSE ' ' END AS "類別名稱", "a"."產品編號", "a"."產品規格" AS "品名規格", CONCAT('(', "a"."產品編號", ')', "a"."產品名稱", ' ', "a"."產品規格") AS "產品編號品名規格", "a"."客戶訂單" AS "po", "a"."產品名稱", "a"."客戶料號", "a"."客戶品號", "a"."客戶名稱", "a"."保存期限", "a"."儲存溫度", "a"."儲存濕度", "a"."廠商" AS "製造廠商", "a"."材質結構" AS "材質" FROM "fil003f1" AS "a";

-- Home #1884 ViewFIL4049.生產排程用料明細
CREATE OR REPLACE VIEW "viewfil4049" ("單據類別", "單據編號", "節點", "用途", "材料代碼", "品名", "備註", "單位", "規格", "厚度", "序號") AS (SELECT 'C11' AS "單據類別", "a"."製令單號" AS "單據編號", "a"."節點", '使用半成品一', CAST(' ' AS TEXT), CAST(CASE WHEN "a"."使用半成品" = ' ' THEN ' ' ELSE "a"."使用半成品" END AS TEXT), "a"."說明", CAST(' ' AS TEXT), CAST(' ' AS TEXT), CAST(' ' AS TEXT), 1 FROM "fil0039" AS "a" WHERE "a"."使用半成品" <> ' ' UNION ALL SELECT 'C11' AS "單據類別", "a"."製令單號" AS "單據編號", "a"."節點", '使用半成品二', CAST(' ' AS TEXT), CAST(CASE WHEN "a"."使用半成品二" = ' ' THEN ' ' ELSE "a"."使用半成品" END AS TEXT), "a"."說明", CAST(' ' AS TEXT), CAST(' ' AS TEXT), CAST(' ' AS TEXT), 2 FROM "fil0039" AS "a" WHERE "a"."使用半成品二" <> ' ' UNION ALL SELECT 'C11' AS "單據類別", "a"."製令單號" AS "單據編號", "a"."節點", '使用半成品三', CAST(' ' AS TEXT), CAST(CASE WHEN "a"."使用半成品三" = ' ' THEN ' ' ELSE "a"."使用半成品" END AS TEXT), "a"."說明", CAST(' ' AS TEXT), CAST(' ' AS TEXT), CAST(' ' AS TEXT), 3 FROM "fil0039" AS "a" WHERE "a"."使用半成品三" <> ' ' UNION ALL SELECT 'C11' AS "單據類別", "a"."製令單號" AS "單據編號", "a"."節點", '使用半成品四', CAST(' ' AS TEXT), CAST(CASE WHEN "a"."使用半成品四" = ' ' THEN ' ' ELSE "a"."使用半成品" END AS TEXT), "a"."說明", CAST(' ' AS TEXT), CAST(' ' AS TEXT), CAST(' ' AS TEXT), 4 FROM "fil0039" AS "a" WHERE "a"."使用半成品四" <> ' ' UNION ALL SELECT 'C11' AS "單據類別", "a"."製令單號" AS "單據編號", "a"."節點", '使用材料一', CAST(COALESCE("a"."物料編號", ' ') AS TEXT), CAST(COALESCE("b"."品名", ' ') AS TEXT), "a"."說明", CAST("b"."單位代碼" AS TEXT), CAST(COALESCE("b"."規格", ' ') AS TEXT), CAST(COALESCE("c"."厚度", ' ') AS TEXT), 5 FROM "fil0039" AS "a" LEFT JOIN "fil0012" AS "b" ON "a"."物料編號" = "b"."產品編號" LEFT JOIN "fil0034" AS "c" ON "c"."塑膠粒材料代碼" = "a"."物料編號" WHERE "a"."物料編號" <> ' ' UNION ALL SELECT 'C11' AS "單據類別", "a"."製令單號" AS "單據編號", "a"."節點", '使用材料二', CAST(COALESCE("a"."物料編號二", ' ') AS TEXT), CAST(COALESCE("b"."品名", ' ') AS TEXT), "a"."說明", CAST("b"."單位代碼" AS TEXT), CAST(COALESCE("b"."規格", ' ') AS TEXT), CAST(COALESCE("c"."厚度", ' ') AS TEXT), 6 FROM "fil0039" AS "a" LEFT JOIN "fil0012" AS "b" ON "a"."物料編號" = "b"."產品編號" LEFT JOIN "fil0034" AS "c" ON "c"."塑膠粒材料代碼" = "a"."物料編號" WHERE "a"."物料編號二" <> ' ' UNION ALL SELECT 'C11' AS "單據類別", "a"."製令單號" AS "單據編號", "a"."節點", '使用材料三', CAST(COALESCE("a"."物料編號三", ' ') AS TEXT), CAST(COALESCE("b"."品名", ' ') AS TEXT), "a"."說明", CAST("b"."單位代碼" AS TEXT), CAST(COALESCE("b"."規格", ' ') AS TEXT), CAST(COALESCE("c"."厚度", ' ') AS TEXT), 7 FROM "fil0039" AS "a" LEFT JOIN "fil0012" AS "b" ON "a"."物料編號" = "b"."產品編號" LEFT JOIN "fil0034" AS "c" ON "c"."塑膠粒材料代碼" = "a"."物料編號" WHERE "a"."物料編號三" <> ' ' UNION ALL SELECT 'C11' AS "單據類別", "a"."製令單號" AS "單據編號", "a"."節點", '使用材料四', CAST(COALESCE("a"."物料編號四", ' ') AS TEXT), CAST(COALESCE("b"."品名", ' ') AS TEXT), "a"."說明", CAST("b"."單位代碼" AS TEXT), CAST(COALESCE("b"."規格", ' ') AS TEXT), CAST(COALESCE("c"."厚度", ' ') AS TEXT), 8 FROM "fil0039" AS "a" LEFT JOIN "fil0012" AS "b" ON "a"."物料編號" = "b"."產品編號" LEFT JOIN "fil0034" AS "c" ON "c"."塑膠粒材料代碼" = "a"."物料編號" WHERE "a"."物料編號四" <> ' ');

-- Home #1886 ViewFIL404A1A.印刷日報看色.C41
CREATE OR REPLACE VIEW "viewfil404a1a" AS (SELECT "b"."單別" AS "單別", "b"."單號" AS "單號", "b"."logical9" AS "開始看色", "b"."logical10" AS "結束看色", "b"."時間二" AS "看色時間起", "b"."時間三" AS "看色時間迄" FROM "fil0031" AS "b" WHERE "b"."單別" = 'C41' AND "b"."製程代碼" = 'C31A');

-- Home #1892 ViewFIL404A3A.印刷油墨領料
CREATE OR REPLACE VIEW "viewfil404a3a" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", CAST("c"."文數字4" AS TEXT) AS "批號", '1.領用' AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0043" AS "d" ON "d"."條碼" = "c"."文數字4" AND "d"."批次匯入" = 1 WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'E' AND "b"."製程代碼" = 'C31A' AND "a"."單據序號" >= 900 AND "d"."料號" LIKE 'B%' UNION ALL /* 報廢 */ SELECT "a"."單據類別" AS "單別", "a"."單據號碼" AS "單號", "a"."單據序號" AS "序號", CAST("a"."條碼" AS TEXT) AS "批號", '2.報廢' AS "來源" FROM "fil0044" AS "a" WHERE "a"."條碼" LIKE 'C31A%' AND "a"."序號" = 9999 AND "a"."庫位" = '報廢');

-- Home #1895 ViewFIL404A5A.上蠟日報合計_32D
CREATE OR REPLACE VIEW "viewfil404a5a" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "前製程米數", SUM("a"."異動單價") AS "plc抓取米數", SUM("a"."燙金費") AS "合理剔除數", SUM("a"."毛重") AS "不良剔除數", SUM("a"."贈品數量") AS "檢品數量", SUM("a"."雷射費") AS "線外不良剔除數", SUM("a"."夾鏈費") AS "線內不良剔除數", SUM("a"."退庫數量") AS "回庫數量" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN (SELECT "a"."單據類別", "a"."單據編號", SUM("a"."贈品數量") AS "回庫數量" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'G' AND "b"."製程代碼" = 'C32D' AND "c"."標籤列印次數" > 0 GROUP BY "a"."單據類別", "a"."單據編號") AS "e" ON "e"."單據類別" = "a"."單據類別" AND "e"."單據編號" = "a"."單據編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C32D' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #1900 ViewFIL404AA.印刷日報合計_C31A
CREATE OR REPLACE VIEW "viewfil404aa" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "前製程米數", SUM(CASE WHEN "c"."檢驗外觀" = ' ' THEN "a"."異動單價" WHEN "c"."檢驗外觀" = 'A' THEN "a"."異動單價" ELSE 0 END) AS "plc抓取米數", SUM("a"."燙金費") AS "合理剔除數", SUM("a"."毛重") AS "不良剔除數", SUM("a"."贈品數量") AS "檢品數量", SUM("a"."雷射費") AS "線外不良剔除數", SUM(CASE WHEN "c"."檢驗外觀" = ' ' THEN "a"."夾鏈費" WHEN "c"."檢驗外觀" = 'A' THEN "a"."夾鏈費" ELSE 0 END) AS "線內不良剔除數", SUM("a"."氣閥費") AS "試刷米數", SUM("a"."退庫數量") AS "回庫數量" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" /* 
		LEFT JOIN 
		(
			SELECT 
				A.單據類別,
				A.單據編號,
				SUM(A.贈品數量) 回庫數量
			FROM
				FIL0040 A
				INNER JOIN FIL0031 B ON A.單據類別 = B.單別 AND A.單據編號 = B.單號
				INNER JOIN FIL0041 C ON A.單據類別 = C.單別 AND A.單據編號 = C.單號 AND A.單據序號 = C.序號
			WHERE
				A.單據類別 = 'C41' AND
				A.異動類別= 'G' AND
				B.製程代碼 = 'C31A'	AND
				C.標籤列印次數 > 0
			GROUP BY
				A.單據類別, 
				A.單據編號
		) E ON E.單據類別 = A.單據類別 AND E.單據編號 = A.單據編號
		*/ WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31A' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #1901 ViewFIL404AB.印刷日報筆數
CREATE OR REPLACE VIEW "viewfil404ab" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."qrno" AS "主檔序號", COUNT("a"."單據序號") AS "筆數" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'C' AND "b"."製程代碼" = 'C31A' GROUP BY "a"."單據類別", "a"."單據編號", "a"."qrno");

-- Home #1902 ViewFIL404AC.印刷前製耗用_C31A
CREATE OR REPLACE VIEW "viewfil404ac" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."鐵條費" AS "群組序號", SUM("a"."數值1") AS "前一筆結餘", SUM("a"."異動數量") AS "前製程米數", SUM("a"."異動單價") AS "plc抓取米數", SUM("a"."燙金費") AS "合理剔除數", SUM("a"."毛重") AS "不良剔除數", SUM("a"."贈品數量") AS "檢品數量" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31A' GROUP BY "a"."單據類別", "a"."單據編號", "a"."鐵條費");

-- Home #1903 ViewFIL404AD.印刷製令合計_C31A
