CREATE OR REPLACE VIEW "viewfil404bd" AS (SELECT "a1"."歸屬類別" AS "製令單別", "a1"."歸屬編號" AS "製令單號", SUM("a"."異動數量") AS "前製程米數", SUM("a"."異動單價") AS "plc抓取米數", SUM("a"."燙金費") AS "合理剔除數", SUM("a"."毛重") AS "不良剔除數", SUM("a"."贈品數量") AS "檢品數量", SUM("a"."雷射費") AS "線外不良剔除數", SUM("a"."夾鏈費") AS "線內不良剔除數", SUM("a"."氣閥費") AS "試刷米數", MAX(COALESCE("e"."回庫數量", 0)) AS "回庫數量", MAX(COALESCE("d"."印刷米數", 0) * 1000) AS "生產條件米數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "a1" ON "a"."單據類別" = "a1"."單據類別" AND "a"."單據編號" = "a1"."單據編號" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN (SELECT "f"."製令單別", "f"."製令單號", SUM("f"."印刷米數") AS "印刷米數" FROM "fil0033" AS "f" WHERE "f"."印刷基材" <> ' ' GROUP BY "f"."製令單別", "f"."製令單號") AS "d" ON "d"."製令單別" = "a1"."歸屬類別" AND "d"."製令單號" = "a1"."歸屬編號" LEFT JOIN (SELECT "a"."單據類別", "a"."單據編號", SUM("a"."贈品數量") AS "回庫數量" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'G' AND "b"."製程代碼" = 'C31B' AND "c"."標籤列印次數" > 0 GROUP BY "a"."單據類別", "a"."單據編號") AS "e" ON "e"."單據類別" = "a"."單據類別" AND "e"."單據編號" = "a"."單據編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31B' GROUP BY "a1"."歸屬類別", "a1"."歸屬編號");

-- Home #1914 ViewFIL404BD1.淋膜單據合計
CREATE OR REPLACE VIEW "viewfil404bd1" AS (SELECT "a"."單據類別", "a"."單據編號", "b"."logical6" AS "改件調機", MAX("a1"."歸屬類別") AS "製令單別", MAX("a1"."歸屬編號") AS "製令單號", SUM("a"."異動數量") AS "前製程米數", SUM("a"."異動單價") AS "plc抓取米數", SUM("a"."燙金費") AS "合理剔除數", SUM("a"."毛重") AS "不良剔除數", SUM("a"."贈品數量") AS "檢品數量", SUM("a"."雷射費") AS "線外不良剔除數", SUM("a"."夾鏈費") AS "線內不良剔除數", SUM("a"."氣閥費") AS "試刷米數", MAX(COALESCE("e"."回庫數量", 0)) AS "回庫數量", MAX(COALESCE("d"."印刷米數", 0) * 1000) AS "生產條件米數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "a1" ON "a"."單據類別" = "a1"."單據類別" AND "a"."單據編號" = "a1"."單據編號" AND "a1"."歸屬編號" <> ' ' INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN (SELECT "f"."製令單別", "f"."製令單號", SUM("f"."印刷米數") AS "印刷米數" FROM "fil0033" AS "f" WHERE "f"."印刷基材" <> ' ' GROUP BY "f"."製令單別", "f"."製令單號") AS "d" ON "d"."製令單別" = "a1"."歸屬類別" AND "d"."製令單號" = "a1"."歸屬編號" LEFT JOIN (SELECT "a"."單據類別", "a"."單據編號", SUM("a"."贈品數量") AS "回庫數量" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'G' AND "b"."製程代碼" = 'C31B' AND "c"."標籤列印次數" > 0 GROUP BY "a"."單據類別", "a"."單據編號") AS "e" ON "e"."單據類別" = "a"."單據類別" AND "e"."單據編號" = "a"."單據編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31B' GROUP BY "a"."單據類別", "a"."單據編號", "b"."logical6");

-- Home #1918 ViewFIL404C3.積層日報筆數
CREATE OR REPLACE VIEW "viewfil404c3" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."qrno" AS "主檔序號", COUNT("a"."單據序號") AS "筆數" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'C' AND "b"."製程代碼" = 'C31C' GROUP BY "a"."單據類別", "a"."單據編號", "a"."qrno");

-- Home #1921 ViewFIL404C4AA.已熟成
CREATE OR REPLACE VIEW "viewfil404c4aa" AS (SELECT "a"."單別" AS "單別", "a"."單號" AS "單號", "a"."序號" AS "序號", CASE WHEN (COALESCE(CASE WHEN "a"."重覆入庫" = 1 AND "a"."出庫日期" > '00000000' THEN '4' WHEN "a"."重覆入庫" = 1 AND "a"."入庫日期" > '00000000' AND "a"."出庫日期" <= '00000000' THEN '2' WHEN "a"."入庫日期" <= '00000000' AND CURRENT_TIMESTAMP > TO_DATE(CONCAT(TRIM("b"."標籤列印日期一"), TRIM("b"."標籤列印時間一")), 'YYYYMMDDHH24:MI:SS') + CAST(1 AS DOUBLE PRECISION) / 24 THEN '1' WHEN "a"."入庫日期" > '00000000' AND "a"."出庫日期" <= '00000000' THEN '2' WHEN "a"."出庫日期" > '00000000' AND TO_DATE(CONCAT(TRIM("a"."出庫日期"), TRIM("a"."出庫時間")), 'YYYYMMDDHH24:MI:SS') < TO_DATE(CONCAT(TRIM("a"."入庫日期"), TRIM("a"."入庫時間")), 'YYYYMMDDHH24:MI:SS') + CAST("e"."數值10" AS DOUBLE PRECISION) / 24 THEN '3' WHEN "a"."出庫日期" > '00000000' AND TO_DATE(CONCAT(TRIM("a"."出庫日期"), TRIM("a"."出庫時間")), 'YYYYMMDDHH24:MI:SS') BETWEEN TO_DATE(CONCAT(TRIM("a"."入庫日期"), TRIM("a"."入庫時間")), 'YYYYMMDDHH24:MI:SS') + CAST("e"."數值10" AS DOUBLE PRECISION) / 24 AND TO_DATE(CONCAT(TRIM("a"."入庫日期"), TRIM("a"."入庫時間")), 'YYYYMMDDHH24:MI:SS') + CAST("e"."數值11" AS DOUBLE PRECISION) / 24 THEN '4' WHEN "a"."出庫日期" > '00000000' AND TO_DATE(CONCAT(TRIM("a"."出庫日期"), TRIM("a"."出庫時間")), 'YYYYMMDDHH24:MI:SS') > TO_DATE(CONCAT(TRIM("a"."入庫日期"), TRIM("a"."入庫時間")), 'YYYYMMDDHH24:MI:SS') + CAST("e"."數值11" AS DOUBLE PRECISION) / 24 THEN '5' ELSE ' ' END, ' ')) > '2' THEN 1 ELSE 0 END AS "已熟成" FROM "fil0041_b" AS "a" INNER JOIN "fil0040" AS "m" ON "a"."單別" = "m"."單據類別" AND "a"."單號" = "m"."單據編號" AND "a"."序號" = "m"."單據序號" INNER JOIN "fil0041" AS "b" ON "a"."單別" = "b"."單別" AND "a"."單號" = "b"."單號" AND "a"."序號" = "b"."序號" INNER JOIN "fil0031" AS "e" ON "a"."單別" = "e"."單別" AND "a"."單號" = "e"."單號" WHERE "a"."單別" = 'C41' AND "m"."異動類別" = 'A' AND ("e"."製程代碼" = 'C31B' OR "e"."製程代碼" = 'C31C') AND "e"."文字4" <> '不用熟成' AND "m"."產品編號" <> ' ' AND "b"."標籤列印日期一" > '20240101' UNION ALL SELECT "a"."單別", "a"."單號", "a"."序號", CASE WHEN ("a"."熟成狀態" > '2') THEN 1 ELSE 0 END AS "已熟成" FROM "fil004k" AS "a");

-- Home #1925 ViewFIL404C5_V1.積層熟成室簡表
CREATE OR REPLACE VIEW "viewfil404c5_v1" AS (SELECT "a"."單別" AS "單別", "a"."單號" AS "單號", "a"."序號" AS "序號", "c"."歸屬編號" AS "製令單號", "m"."產品編號" AS "本製程編號", "e"."交貨日期_次批" AS "加工別", "a"."可提早出庫", "a"."重覆入庫" AS "重覆入庫", COALESCE(CASE WHEN "a"."重覆入庫" = 1 AND "a"."出庫日期" > '00000000' THEN '4' WHEN "a"."重覆入庫" = 1 AND "a"."入庫日期" > '00000000' AND "a"."出庫日期" <= '00000000' THEN '2' WHEN "a"."入庫日期" <= '00000000' AND CURRENT_TIMESTAMP > TO_DATE(CONCAT(TRIM("b"."標籤列印日期一"), TRIM("b"."標籤列印時間一")), 'YYYYMMDDHH24:MI:SS') + CAST(1 AS DOUBLE PRECISION) / 24 THEN '1' WHEN "a"."入庫日期" > '00000000' AND "a"."出庫日期" <= '00000000' THEN '2' WHEN "a"."出庫日期" > '00000000' AND TO_DATE(CONCAT(TRIM("a"."出庫日期"), TRIM("a"."出庫時間")), 'YYYYMMDDHH24:MI:SS') < TO_DATE(CONCAT(TRIM("a"."入庫日期"), TRIM("a"."入庫時間")), 'YYYYMMDDHH24:MI:SS') + CAST("e"."數值10" AS DOUBLE PRECISION) / 24 THEN '3' WHEN "a"."出庫日期" > '00000000' AND TO_DATE(CONCAT(TRIM("a"."出庫日期"), TRIM("a"."出庫時間")), 'YYYYMMDDHH24:MI:SS') BETWEEN TO_DATE(CONCAT(TRIM("a"."入庫日期"), TRIM("a"."入庫時間")), 'YYYYMMDDHH24:MI:SS') + CAST("e"."數值10" AS DOUBLE PRECISION) / 24 AND TO_DATE(CONCAT(TRIM("a"."入庫日期"), TRIM("a"."入庫時間")), 'YYYYMMDDHH24:MI:SS') + CAST("e"."數值11" AS DOUBLE PRECISION) / 24 THEN '4' WHEN "a"."出庫日期" > '00000000' AND TO_DATE(CONCAT(TRIM("a"."出庫日期"), TRIM("a"."出庫時間")), 'YYYYMMDDHH24:MI:SS') > TO_DATE(CONCAT(TRIM("a"."入庫日期"), TRIM("a"."入庫時間")), 'YYYYMMDDHH24:MI:SS') + CAST("e"."數值11" AS DOUBLE PRECISION) / 24 THEN '5' ELSE ' ' END, ' ') AS "熟成狀態", CASE WHEN "a"."入庫日期" > '00000000' THEN TO_DATE(CONCAT(TRIM("a"."入庫日期"), TRIM("a"."入庫時間")), 'YYYYMMDDHH24:MI:SS') + CAST("e"."數值10" AS DOUBLE PRECISION) / 24 ELSE ADD_MONTHS(CURRENT_TIMESTAMP, 12) END AS "應出庫日時起", CASE WHEN "a"."入庫日期" > '00000000' THEN TO_DATE(CONCAT(TRIM("a"."入庫日期"), TRIM("a"."入庫時間")), 'YYYYMMDDHH24:MI:SS') + CAST("e"."數值11" AS DOUBLE PRECISION) / 24 ELSE ADD_MONTHS(CURRENT_TIMESTAMP, 12) END AS "應出庫日時迄", "a"."入庫日期" AS "熟成入庫日期", "a"."入庫時間" AS "熟成入庫時間", "a"."出庫日期" AS "熟成出庫日期", "a"."出庫時間" AS "熟成出庫時間", "e"."製程代碼", CASE WHEN CONCAT(TRIM("a"."入庫日期"), "a"."入庫時間") > CONCAT(TRIM("a"."出庫日期"), "a"."出庫時間") THEN CONCAT(TRIM("a"."入庫日期"), "a"."入庫時間") ELSE CONCAT(TRIM("a"."出庫日期"), "a"."出庫時間") END AS "最後入出日時" FROM "fil0041_b" AS "a" INNER JOIN "fil0040" AS "m" ON "a"."單別" = "m"."單據類別" AND "a"."單號" = "m"."單據編號" AND "a"."序號" = "m"."單據序號" INNER JOIN "fil0041" AS "b" ON "a"."單別" = "b"."單別" AND "a"."單號" = "b"."單號" AND "a"."序號" = "b"."序號" INNER JOIN "fil0030" AS "c" ON "a"."單別" = "c"."單據類別" AND "a"."單號" = "c"."單據編號" INNER JOIN "fil0031" AS "e" ON "a"."單別" = "e"."單別" AND "a"."單號" = "e"."單號" WHERE "a"."單別" = 'C41' AND "m"."異動類別" = 'A' AND ("e"."製程代碼" = 'C31B' OR "e"."製程代碼" = 'C31C') AND "e"."文字4" <> '不用熟成' AND "m"."產品編號" <> ' ' AND "b"."標籤列印日期一" > '20240101' UNION ALL SELECT "a"."單別", "a"."單號", "a"."序號", "a"."製令單號", "a"."本製程編號", "a"."加工別", "a"."可提早出庫", "a"."重覆入庫", "a"."熟成狀態", "a"."應出庫日時起", "a"."應出庫日時迄", "a"."熟成入庫日期", "a"."熟成入庫時間", "a"."熟成出庫日期", "a"."熟成出庫時間", "e"."製程代碼", CASE WHEN CONCAT(TRIM("a"."熟成入庫日期"), "a"."熟成入庫時間") > CONCAT(TRIM("a"."熟成出庫日期"), "a"."熟成出庫時間") THEN CONCAT(TRIM("a"."熟成入庫日期"), "a"."熟成入庫時間") ELSE CONCAT(TRIM("a"."熟成出庫日期"), "a"."熟成出庫時間") END AS "最後入出日時" FROM "fil004k" AS "a" INNER JOIN "fil0031" AS "e" ON "a"."單別" = "e"."單別" AND "a"."單號" = "e"."單號");

-- Home #1927 ViewFIL404CA.積層日報合計_C31C
CREATE OR REPLACE VIEW "viewfil404ca" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "前製程米數", SUM("a"."異動單價") AS "plc抓取米數", SUM("a"."燙金費") AS "合理剔除數", SUM("a"."毛重") AS "不良剔除數", SUM("a"."贈品數量") AS "檢品數量", SUM("a"."雷射費") AS "線外不良剔除數", SUM("a"."夾鏈費") AS "線內不良剔除數", SUM("a"."氣閥費") AS "試刷米數", MAX(COALESCE("e"."回庫數量", 0)) + SUM("a"."退庫數量") AS "回庫數量" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN (SELECT "a"."單據類別", "a"."單據編號", SUM("a"."贈品數量") AS "回庫數量" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'G' AND "b"."製程代碼" = 'C31C' AND "c"."標籤列印次數" > 0 GROUP BY "a"."單據類別", "a"."單據編號") AS "e" ON "e"."單據類別" = "a"."單據類別" AND "e"."單據編號" = "a"."單據編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31C' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #1928 ViewFIL404CB.積層前製耗用_C31C
CREATE OR REPLACE VIEW "viewfil404cb" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."鐵條費" AS "群組序號", SUM("a"."數值1") AS "前一筆結餘", SUM("a"."異動數量") AS "前製程米數", SUM("a"."異動單價") AS "plc抓取米數", SUM("a"."燙金費") AS "合理剔除數", SUM("a"."毛重") AS "不良剔除數", SUM("a"."贈品數量") AS "檢品數量" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31C' GROUP BY "a"."單據類別", "a"."單據編號", "a"."鐵條費");

-- Home #1929 ViewFIL404CC.前製製令機台每日
CREATE OR REPLACE VIEW "viewfil404cc" AS (SELECT "c"."歸屬類別" AS "製令單別", "c"."歸屬編號" AS "製令單號", CASE WHEN "b"."製程代碼" = 'C31E' THEN ' ' ELSE "b"."交貨日期_次批" END AS "加工別", "b"."製程代碼", "c"."單據日期" AS "作業日期", "b"."機台代碼", SUM(CASE WHEN "b"."製程代碼" = 'C31D' THEN CAST((CASE WHEN "a"."材積" + COALESCE("d"."包裝數量", 0) < "a"."異動單價" - "a"."qrno" THEN 0 ELSE "a"."材積" + COALESCE("d"."包裝數量", 0) - "a"."異動單價" - "a"."qrno" END) AS DOUBLE PRECISION) / 1000 WHEN "b"."製程代碼" = 'C31E' THEN CASE WHEN "d"."數值14" = 0 THEN "a"."贈品數量" ELSE "d"."數值14" END ELSE "a"."異動單價" - "a"."夾鏈費" END) AS "數量" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" LEFT JOIN "fil0041" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" AND "a"."單據序號" = "d"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND ("b"."製程代碼" BETWEEN 'C31A' AND 'C31E' OR "b"."製程代碼" = 'C32D') GROUP BY "c"."歸屬類別", "c"."歸屬編號", "b"."交貨日期_次批", "c"."單據日期", "b"."製程代碼", "b"."機台代碼");

-- Home #1930 ViewFIL404CD.前製製令生產彙總
CREATE OR REPLACE VIEW "viewfil404cd" AS (SELECT "c"."歸屬類別" AS "製令單別", "c"."歸屬編號" AS "製令單號", "b"."交貨日期_次批" AS "加工別", "b"."製程代碼", SUM("a"."異動單價" - "a"."夾鏈費") AS "數量" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND ("b"."製程代碼" BETWEEN 'C31A' AND 'C31C' OR "b"."製程代碼" = 'C32D') GROUP BY "c"."歸屬類別", "c"."歸屬編號", "b"."交貨日期_次批", "b"."製程代碼");

-- Home #1931 ViewFIL404CD0.積層製令合計_31B
CREATE OR REPLACE VIEW "viewfil404cd0" AS (SELECT "a1"."歸屬類別" AS "製令單別", "a1"."歸屬編號" AS "製令單號", SUM("a"."異動數量") AS "前製程米數", SUM("a"."異動單價") AS "plc抓取米數", SUM("a"."燙金費") AS "合理剔除數", SUM("a"."毛重") AS "不良剔除數", SUM("a"."贈品數量") AS "檢品數量", SUM("a"."雷射費") AS "線外不良剔除數", SUM("a"."夾鏈費") AS "線內不良剔除數", SUM("a"."氣閥費") AS "試刷米數", MAX(COALESCE("e"."回庫數量", 0)) AS "回庫數量", MAX(COALESCE("d"."印刷米數", 0) * 1000) AS "生產條件米數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "a1" ON "a"."單據類別" = "a1"."單據類別" AND "a"."單據編號" = "a1"."單據編號" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN (SELECT "f"."製令單別", "f"."製令單號", SUM("f"."印刷米數") AS "印刷米數" FROM "fil0033" AS "f" WHERE "f"."印刷基材" <> ' ' GROUP BY "f"."製令單別", "f"."製令單號") AS "d" ON "d"."製令單別" = "a1"."歸屬類別" AND "d"."製令單號" = "a1"."歸屬編號" LEFT JOIN (SELECT "a"."單據類別", "a"."單據編號", SUM("a"."贈品數量") AS "回庫數量" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'G' AND "b"."製程代碼" = 'C31C' AND "c"."標籤列印次數" > 0 GROUP BY "a"."單據類別", "a"."單據編號") AS "e" ON "e"."單據類別" = "a"."單據類別" AND "e"."單據編號" = "a"."單據編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31C' GROUP BY "a1"."歸屬類別", "a1"."歸屬編號");

-- Home #1932 ViewFIL404CD1.淋膜單據合計
CREATE OR REPLACE VIEW "viewfil404cd1" AS (SELECT "a"."單據類別", "a"."單據編號", "b"."logical6" AS "改件調機", MAX("a1"."歸屬類別") AS "製令單別", MAX("a1"."歸屬編號") AS "製令單號", SUM("a"."異動數量") AS "前製程米數", SUM("a"."異動單價") AS "plc抓取米數", SUM("a"."燙金費") AS "合理剔除數", SUM("a"."毛重") AS "不良剔除數", SUM("a"."贈品數量") AS "檢品數量", SUM("a"."雷射費") AS "線外不良剔除數", SUM("a"."夾鏈費") AS "線內不良剔除數", SUM("a"."氣閥費") AS "試刷米數", MAX(COALESCE("e"."回庫數量", 0)) AS "回庫數量", MAX(COALESCE("d"."印刷米數", 0) * 1000) AS "生產條件米數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "a1" ON "a"."單據類別" = "a1"."單據類別" AND "a"."單據編號" = "a1"."單據編號" AND "a1"."歸屬編號" <> ' ' INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN (SELECT "f"."製令單別", "f"."製令單號", SUM("f"."印刷米數") AS "印刷米數" FROM "fil0033" AS "f" WHERE "f"."印刷基材" <> ' ' GROUP BY "f"."製令單別", "f"."製令單號") AS "d" ON "d"."製令單別" = "a1"."歸屬類別" AND "d"."製令單號" = "a1"."歸屬編號" LEFT JOIN (SELECT "a"."單據類別", "a"."單據編號", SUM("a"."贈品數量") AS "回庫數量" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'G' AND "b"."製程代碼" = 'C31C' AND "c"."標籤列印次數" > 0 GROUP BY "a"."單據類別", "a"."單據編號") AS "e" ON "e"."單據類別" = "a"."單據類別" AND "e"."單據編號" = "a"."單據編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31C' GROUP BY "a"."單據類別", "a"."單據編號", "b"."logical6");

-- Home #1935 ViewFIL404D3.裁切日報明細結餘
CREATE OR REPLACE VIEW "viewfil404d3" AS (SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", COALESCE(CONCAT("c"."文數字4", TRIM(CASE WHEN "c"."文數字5" = ' ' THEN ' ' ELSE CONCAT(',', "c"."文數字5") END)), ' ') AS "前製程條碼", SUM(CASE WHEN "a"."異動類別" = 'A' THEN "a"."異動數量" + "a"."數值1" ELSE 0 END + CASE WHEN "a"."異動類別" = 'A' THEN "a"."數值1" ELSE 0 END - (CASE WHEN "a"."異動類別" = 'A' THEN "a"."材積" ELSE 0 END + CASE WHEN "a"."異動類別" = 'A' THEN COALESCE("c"."包裝數量", 0) ELSE 0 END + CASE WHEN "a"."異動類別" = 'A' THEN "a"."數值2" ELSE 0 END + CASE WHEN "a"."異動類別" = 'A' THEN "a"."數值3" ELSE 0 END) - CASE WHEN "a"."異動類別" = 'A' THEN 0 ELSE "a"."贈品數量" END) OVER (PARTITION BY "a"."單據編號" ORDER BY "a"."單據序號") AS "結餘米數" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" /* 製令副檔取條數 */ INNER JOIN "fil0030" AS "m" ON "a"."單據類別" = "m"."單據類別" AND "a"."單據編號" = "m"."單據編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31D');

-- Home #1936 ViewFIL404DA.裁切日報合計_C31D
CREATE OR REPLACE VIEW "viewfil404da" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", MAX(TO_CHAR("a"."最後更新日", 'YYYYMMDDHH24MISS')) AS "最後更新日時", SUM("a"."材積" * "d"."條數") AS "入庫捲數", SUM("a"."異動數量" + "a"."數值1") AS "前製程米數", SUM("a"."雷射費" + "a"."氣閥費") AS "裁切米數", SUM("a"."異動單價") AS "故障米數", SUM("a"."qrno") AS "客戶要求數", SUM("a"."數值2") AS "線外剔除數", SUM("a"."數值3") AS "合理剔除數", SUM("a"."贈品數量" + "a"."異動單價") AS "使用米數", SUM("a"."異動數量" + "a"."數值1" - ("a"."材積" + COALESCE("c"."包裝數量", 0) + "a"."數值2" + "a"."數值3")) - MAX(COALESCE("e"."回庫數量", 0)) AS "結餘米數", SUM("a"."材積") AS "plc抓取米數", SUM(COALESCE("c"."包裝數量", 0)) AS "上次尾數", MAX(COALESCE("e"."回庫數量", 0)) AS "回庫數量", COUNT("a"."單據序號") AS "資料筆數" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" /* 製令副檔取條數 */ INNER JOIN "fil0030" AS "m" ON "a"."單據類別" = "m"."單據類別" AND "a"."單據編號" = "m"."單據編號" INNER JOIN "fil0033" AS "d" ON "m"."歸屬類別" = "d"."製令單別" AND "m"."歸屬編號" = "d"."製令單號" AND "d"."加工別" = 'A' LEFT JOIN (SELECT "a"."單據類別", "a"."單據編號", SUM("a"."贈品數量") AS "回庫數量" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'G' AND "b"."製程代碼" = 'C31D' AND "c"."標籤列印次數" > 0 GROUP BY "a"."單據類別", "a"."單據編號") AS "e" ON "e"."單據類別" = "a"."單據類別" AND "e"."單據編號" = "a"."單據編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31D' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #1937 ViewFIL404DA1.裁切製令合計
CREATE OR REPLACE VIEW "viewfil404da1" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "b"."logical6" AS "改件調機", MAX("m"."歸屬類別") AS "製令單別", MAX("m"."歸屬編號") AS "製令單號", SUM("a"."材積" * "d"."條數") AS "入庫捲數", SUM("a"."異動數量" + "a"."數值1") AS "前製程米數", SUM("a"."雷射費" + "a"."氣閥費") AS "裁切米數", SUM("a"."異動單價") AS "不良剔除數", SUM("a"."qrno") AS "客戶要求數", SUM("a"."數值2") AS "線外不良剔除數", SUM("a"."數值3") AS "合理不良剔除數", SUM("a"."贈品數量" + "a"."異動單價") AS "使用米數", SUM("a"."異動數量" + "a"."數值1" - ("a"."材積" + COALESCE("c"."包裝數量", 0) + "a"."數值2" + "a"."數值3")) - MAX(COALESCE("e"."回庫數量", 0)) AS "結餘米數", SUM("a"."材積") AS "plc抓取米數", SUM(COALESCE("c"."包裝數量", 0)) AS "上次尾數", MAX(COALESCE("e"."回庫數量", 0)) AS "回庫數量", COUNT("a"."單據序號") AS "資料筆數" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" /* 製令副檔取條數 */ INNER JOIN "fil0030" AS "m" ON "a"."單據類別" = "m"."單據類別" AND "a"."單據編號" = "m"."單據編號" INNER JOIN "fil0033" AS "d" ON "m"."歸屬類別" = "d"."製令單別" AND "m"."歸屬編號" = "d"."製令單號" AND "d"."加工別" = 'A' LEFT JOIN (SELECT "a"."單據類別", "a"."單據編號", SUM("a"."贈品數量") AS "回庫數量" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'G' AND "b"."製程代碼" = 'C31D' AND "c"."標籤列印次數" > 0 GROUP BY "a"."單據類別", "a"."單據編號") AS "e" ON "e"."單據類別" = "a"."單據類別" AND "e"."單據編號" = "a"."單據編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31D' GROUP BY "a"."單據類別", "a"."單據編號", "b"."logical6");

-- Home #1938 ViewFIL404DB.裁切日報捲數_C31D
CREATE OR REPLACE VIEW "viewfil404db" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", ("a"."贈品數量" + COALESCE("c"."包裝數量", 0)) AS "每捲數量", SUM(REGEXP_COUNT("a"."產品編號", ',') + 1) AS "幾捲" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" /* 製令副檔取條數 */ INNER JOIN "fil0030" AS "m" ON "a"."單據類別" = "m"."單據類別" AND "a"."單據編號" = "m"."單據編號" INNER JOIN "fil0033" AS "d" ON "m"."歸屬類別" = "d"."製令單別" AND "m"."歸屬編號" = "d"."製令單號" AND "d"."加工別" = 'A' WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31D' AND "a"."logical1" = 0 GROUP BY "a"."單據類別", "a"."單據編號", ("a"."贈品數量" + COALESCE("c"."包裝數量", 0)));

-- Home #1940 ViewFIL404DD.裁切日報報廢_C31D
CREATE OR REPLACE VIEW "viewfil404dd" AS (SELECT "a"."單別", "a"."單號", SUM("a"."報廢") AS "報廢筆數", SUM("a"."重整") AS "重整筆數" FROM "fil00401" AS "a" GROUP BY "a"."單別", "a"."單號");

-- Home #1941 ViewFIL404DE.裁切製令彙總_C31D
CREATE OR REPLACE VIEW "viewfil404de" AS (SELECT "a"."製令單號", SUM("a"."幾捲") AS "捲數" FROM (SELECT "e"."歸屬編號" AS "製令單號", COUNT("m"."細分") AS "幾捲" FROM "fil00401" AS "m" INNER JOIN "fil0040" AS "a" ON "a"."單據類別" = "m"."單別" AND "a"."單據編號" = "m"."單號" AND "a"."單據序號" = "m"."序號" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" /* 製令副檔取條數 */ INNER JOIN "fil0030" AS "e" ON "m"."單別" = "e"."單據類別" AND "m"."單號" = "e"."單據編號" WHERE "m"."單別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31D' AND "m"."報廢" = 0 GROUP BY "e"."歸屬編號") AS "a" GROUP BY "a"."製令單號");

-- Home #1944 ViewFIL404E1A.製袋目前製令.C41
CREATE OR REPLACE VIEW "viewfil404e1a" AS (SELECT DISTINCT "b"."機台代碼", FIRST_VALUE("a"."歸屬編號") OVER (PARTITION BY "b"."機台代碼" ORDER BY "a"."最後更新日" DESC RANGE BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS "製令單號" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31E' AND "b"."時間二" = '000000');

-- Home #1945 ViewFIL404E1C.製袋製令箱數.C41
CREATE OR REPLACE VIEW "viewfil404e1_c" AS (SELECT "a"."單據類別", "a"."單據編號", "a"."異動數量" AS "箱號", COUNT("a"."單據序號") AS "幾箱" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" = 'C31E' GROUP BY "a"."單據類別", "a"."單據編號", "a"."異動數量");

-- Home #1948 ViewFIL404E2A.製袋日報明細_A
CREATE OR REPLACE VIEW "viewfil404e2_a" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "b"."文數字1" AS "ａ材編號", "b"."數值1" AS "ａ材領料米數", "b"."數值5" AS "ａ接頭數", "b"."數值10" AS "ａ切刀次數", "b"."logical1" AS "ａ結案", "b"."文數字2" AS "ｂ材編號", "b"."數值2" AS "ｂ材領料米數", "b"."數值6" AS "ｂ接頭數", "b"."數值11" AS "ｂ切刀次數", "b"."logical2" AS "ｂ結案", "b"."文數字3" AS "側邊編號", "b"."數值3" AS "側邊領料米數", "b"."數值7" AS "側接頭數", "b"."數值12" AS "側切刀次數", "b"."logical3" AS "側結案", "b"."文數字4" AS "底邊編號", "b"."數值4" AS "底邊領料米數", "b"."數值8" AS "底接頭數", "b"."數值13" AS "底切刀次數", "b"."logical4" AS "底結案", "a"."異動數量" AS "箱號", "b"."logical5" AS "氣閥", "a"."贈品數量" AS "數量", "b"."數值14" AS "補尾數", "a"."毛重" AS "重量", "a"."前置單別" AS "不良原因", "a"."前置單號" AS "外箱標示", "b"."手動品名" AS "不良原因說明", "b"."手動規格" AS "外箱標示說明", "a"."單位代碼", "a"."倉庫代碼" AS "庫別代碼", "b"."專案代號" AS "成品檢驗單號", "d"."歸屬類別" AS "製令單別", "d"."歸屬編號" AS "製令單號", "d"."單據日期" AS "作業日期", "c"."交貨日期" AS "製造日期", "a"."logical3" AS "待重工" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "d" ON "d"."單據類別" = "a"."單據類別" AND "d"."單據編號" = "a"."單據編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" = 'C31E');

-- Home #1949 ViewFIL404E2B.製袋日報明細_B
CREATE OR REPLACE VIEW "viewfil404e2_b" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", STRING_AGG(CAST("a"."異動數量" AS TEXT), ' ' ORDER BY "a"."單據編號") AS "箱號" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" = 'C31E' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #2047 ViewFIL404E3_S2.成品異動狀態
CREATE OR REPLACE VIEW "viewfil404e3_s2" AS (SELECT CONCAT("d"."歸屬編號", '-', TRIM(TO_CHAR("a"."異動數量", '0000'))) AS "批號", 1 AS "製袋", CASE WHEN "c"."製程代碼" = 'C31F' THEN 1 ELSE 0 END AS "氣閥", CASE WHEN "c"."製程代碼" = 'C31G' THEN 1 ELSE 0 END AS "鐵條", 0 AS "異動", 0 AS "重工", 0 AS "出貨", 0 AS "品檢", CASE WHEN "c"."製程代碼" = 'C31E' THEN TO_NCHAR('製袋') WHEN "c"."製程代碼" = 'C31G' THEN TO_NCHAR('鐵條') ELSE TO_NCHAR('氣閥') END AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" LEFT JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" WHERE "a"."異動類別" = 'A' AND ("c"."製程代碼" = 'C31E' OR "c"."製程代碼" = 'C31F' OR "c"."製程代碼" = 'C31G') UNION ALL SELECT "b"."批號" AS "批號", 1 AS "製袋", "b"."logical2" AS "氣閥", "b"."logical3" AS "鐵條", CASE WHEN "a"."單據類別" = 'E32' THEN 1 ELSE 0 END AS "異動", CASE WHEN "a"."單據類別" = 'E33' THEN 1 ELSE 0 END AS "重工", CASE WHEN "a"."單據類別" = 'E35' THEN 1 ELSE 0 END AS "重工", CASE WHEN "a"."單據類別" = 'E37' THEN 1 ELSE 0 END AS "品檢", CASE WHEN "a"."單據類別" = 'E32' THEN TO_NCHAR('異動') WHEN "a"."單據類別" = 'E33' THEN TO_NCHAR('重工') WHEN "a"."單據類別" = 'E35' THEN TO_NCHAR('出貨') ELSE TO_NCHAR('品檢') END AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" WHERE "a"."單據類別" = 'E32' OR "a"."單據類別" = 'E33' OR "a"."單據類別" = 'E35' OR "a"."單據類別" = 'E37');

-- Home #2048 ViewFIL404E3_S3.成品箱號對照
CREATE OR REPLACE VIEW "viewfil404e3_s3" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動數量" AS "箱號", "d"."單據日期" AS "作業日期", CONCAT("d"."歸屬編號", '-', TRIM(TO_CHAR("a"."異動數量", '0000'))) AS "批號", "d"."歸屬類別" AS "製令類別", "d"."歸屬編號" AS "製令單號", "a"."流水編號" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" WHERE "a"."異動類別" = 'A' AND "c"."製程代碼" = 'C31E' UNION SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動數量" AS "箱號", "d"."單據日期" AS "作業日期", "b"."批號" AS "批號", CAST('C11' AS TEXT) AS "製令類別", "a"."廠客品號" AS "製令單號", "a"."流水編號" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" WHERE "a"."單據類別" = 'E32' OR "a"."單據類別" = 'E37');

-- Home #2049 ViewFIL404E3_S4.異動檔(含調整)
CREATE OR REPLACE VIEW "viewfil404e3_s4" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動日期", "d"."歸屬編號" AS "製令單號", "a"."異動數量" AS "箱號", CASE WHEN "c"."製程代碼" = 'C31E' THEN CASE WHEN "b"."數值14" = 0 THEN "a"."贈品數量" ELSE "b"."數值14" END ELSE "b"."數值5" * -1 END AS "數量", 0 AS "報廢數量", CONCAT("d"."歸屬編號", '-', TRIM(TO_CHAR("a"."異動數量", '0000'))) AS "批號", 1 AS "製袋", CASE WHEN "c"."製程代碼" = 'C31F' THEN 1 ELSE 0 END AS "氣閥", CASE WHEN "c"."製程代碼" = 'C31G' THEN 1 ELSE 0 END AS "鐵條", 0 AS "異動", 0 AS "重工", 0 AS "出貨", 0 AS "品檢", CASE WHEN "c"."製程代碼" = 'C31E' THEN TO_NCHAR('製袋') WHEN "c"."製程代碼" = 'C31G' THEN TO_NCHAR('鐵條') ELSE TO_NCHAR('氣閥') END AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" WHERE "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31E' AND 'C31G' UNION ALL SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動日期", "a"."廠客品號" AS "製令單號", "a"."異動數量" AS "箱號", COALESCE(CASE WHEN "a"."單據類別" = 'E35' THEN "a"."贈品數量" * -1 WHEN "a"."單據類別" = 'E37' THEN "b"."數值5" * -1 WHEN "a"."單據類別" = 'E34' THEN 0 ELSE "a"."贈品數量" END, 0) AS "數量", COALESCE(CASE WHEN "a"."單據類別" = 'E33' THEN "b"."數值5" ELSE 0 END, 0) AS "報廢數量", "b"."批號" AS "批號", 1 AS "製袋", "b"."logical2" AS "氣閥", "b"."logical3" AS "鐵條", CASE WHEN "a"."單據類別" = 'E32' THEN 1 ELSE 0 END AS "異動", CASE WHEN "a"."單據類別" = 'E33' THEN 1 ELSE 0 END AS "重工", CASE WHEN "a"."單據類別" = 'E35' THEN 1 ELSE 0 END AS "重工", CASE WHEN "a"."單據類別" = 'E37' THEN 1 ELSE 0 END AS "品檢", CASE WHEN "a"."單據類別" = 'E32' THEN TO_NCHAR('異動') WHEN "a"."單據類別" = 'E33' THEN TO_NCHAR('重工') WHEN "a"."單據類別" = 'E35' THEN TO_NCHAR('出貨') WHEN "a"."單據類別" = 'E37' THEN TO_NCHAR('品檢') ELSE ' ' END AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" WHERE "a"."單據類別" BETWEEN 'E32' AND 'E37' UNION ALL SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動日期", "a"."廠客品號" AS "製令單號", "a"."異動數量" AS "箱號", "a"."贈品數量" AS "數量", 0 AS "報廢數量", "c"."批號", 0 AS "製袋", 0 AS "氣閥", 0 AS "鐵條", 1 AS "異動", 0 AS "重工", 0 AS "出貨", 0 AS "品檢", TO_NCHAR('盤點') FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'F32' AND "a"."異動類別" = '1' AND /* 半成品 */ "b"."稅別" = 'B' /* 廠內 */);

-- Home #2050 ViewFIL404E3_S5.異動檔(來源)
CREATE OR REPLACE VIEW "viewfil404e3_s5" AS (SELECT CONCAT("d"."歸屬編號", '-', TRIM(TO_CHAR("a"."異動數量", '0000'))) AS "批號", TO_NCHAR('製袋') AS "來源", "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "d"."單據日期" FROM "fil0040" AS "a" LEFT JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" WHERE "a"."異動類別" = 'A' AND "c"."製程代碼" = 'C31E' UNION ALL SELECT "b"."批號" AS "批號", CASE WHEN "a"."單據類別" = 'E32' THEN TO_NCHAR('異動') ELSE TO_NCHAR('重工') END AS "來源", "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "d"."單據日期" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" WHERE "a"."單據類別" BETWEEN 'E32' AND 'E33');

-- Home #2051 ViewFIL404E3_S6.製令箱號
CREATE OR REPLACE VIEW "viewfil404e3_s6" AS (SELECT DISTINCT "a"."製令單號", MAX("a"."箱號") AS "箱號" FROM (SELECT DISTINCT "d"."歸屬編號" AS "製令單號", "a"."異動數量" AS "箱號" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" WHERE "a"."異動類別" = 'A' AND ("c"."製程代碼" = 'C31E' OR "c"."製程代碼" = 'C31F' OR "c"."製程代碼" = 'C31G') UNION ALL SELECT DISTINCT "a"."廠客品號" AS "製令單號", "a"."異動數量" AS "箱號" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" WHERE ("a"."單據類別" = 'E32' OR "a"."單據類別" = 'E33' OR "a"."單據類別" = 'E35' OR "a"."單據類別" = 'E37')) AS "a" GROUP BY "a"."製令單號");

-- Home #2053 ViewFIL404E4_S.成品製程狀態
CREATE OR REPLACE VIEW "viewfil404e4_s" AS (SELECT "a"."批號" AS "批號", CASE WHEN SUM("製袋") = 0 THEN 0 ELSE 1 END AS "製袋", CASE WHEN SUM("氣閥") = 0 THEN 0 ELSE 1 END AS "氣閥", CASE WHEN SUM("鐵條") = 0 THEN 0 ELSE 1 END AS "鐵條", CASE WHEN SUM("異動") = 0 THEN 0 ELSE 1 END AS "異動", CASE WHEN SUM("重工") = 0 THEN 0 ELSE 1 END AS "重工", CASE WHEN SUM("出貨") = 0 THEN 0 ELSE 1 END AS "出貨", CASE WHEN SUM("品檢") = 0 THEN 0 ELSE 1 END AS "品檢" FROM "viewfil404e3_s2" AS "a" GROUP BY "a"."批號");

-- Home #2062 ViewFIL404E4_T1.成品結存數
CREATE OR REPLACE VIEW "viewfil404e4_t1" AS (SELECT "a"."批號", SUM("a"."數量") AS "數量" FROM (SELECT CONCAT("d"."歸屬編號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))) AS "批號", SUM(CASE WHEN "c"."製程代碼" = 'C31E' THEN COALESCE(CASE WHEN "b"."數值14" = 0 THEN "a"."贈品數量" ELSE "b"."數值14" END, 0) WHEN "c"."製程代碼" = 'C31F' THEN COALESCE(("b"."數值5" + "a"."燙金費") * -1, 0) WHEN "c"."製程代碼" = 'C31G' THEN COALESCE(("b"."數值5" + "a"."燙金費") * -1, 0) ELSE 0 END) AS "數量" FROM "fil0040" AS "a", "fil0041" AS "b", "fil0031" AS "c", "fil0030" AS "d" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" AND "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" AND "c"."製程代碼" BETWEEN 'C31E' AND 'C31G' GROUP BY CONCAT("d"."歸屬編號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))) UNION ALL SELECT CONCAT("a"."廠客品號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))) AS "批號", SUM(CASE WHEN "a"."單據類別" = 'E32' THEN COALESCE("a"."贈品數量", 0) WHEN "a"."單據類別" = 'E33' THEN COALESCE("a"."贈品數量", 0) + COALESCE("b"."數值5", 0) WHEN "a"."單據類別" = 'E37' THEN COALESCE("b"."數值5" * -1, 0) ELSE 0 END) AS "數量" FROM "fil0040" AS "a", "fil0041" AS "b" WHERE ("a"."單據類別" = 'E32' OR "a"."單據類別" = 'E33' OR "a"."單據類別" = 'E37') AND "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" GROUP BY CONCAT("a"."廠客品號", '-', TRIM(TO_CHAR("a"."異動數量", '0009')))) AS "a" GROUP BY "a"."批號");

-- Home #2056 ViewFIL404E4_T2.成品氣閥重量
CREATE OR REPLACE VIEW "viewfil404e4_t2" AS (SELECT CONCAT("d"."歸屬編號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))) AS "批號", SUM(COALESCE("b"."數值5" * -1, 0)) AS "數量" FROM "fil0040" AS "a", "fil0041" AS "b", "fil0031" AS "c", "fil0030" AS "d" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" = 'C31F' AND "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" AND "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" GROUP BY CONCAT("d"."歸屬編號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))));

-- Home #2057 ViewFIL404E4_T3.成品鐵條重量
CREATE OR REPLACE VIEW "viewfil404e4_t3" AS (SELECT CONCAT("d"."歸屬編號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))) AS "批號", SUM(COALESCE("b"."數值5" * -1, 0)) AS "數量" FROM "fil0040" AS "a", "fil0041" AS "b", "fil0031" AS "c", "fil0030" AS "d" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" = 'C31G' AND "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" AND "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" GROUP BY CONCAT("d"."歸屬編號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))));

-- Home #2058 ViewFIL404E4_T4.成品異動重量
CREATE OR REPLACE VIEW "viewfil404e4_t4" AS (SELECT CONCAT("a"."廠客品號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))) AS "批號", SUM(COALESCE("a"."贈品數量", 0)) AS "數量", SUM(COALESCE("a"."毛重", 0)) AS "重量" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" WHERE "a"."單據類別" = 'E32' GROUP BY CONCAT("a"."廠客品號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))));

-- Home #2059 ViewFIL404E4_T5.成品重工重量
CREATE OR REPLACE VIEW "viewfil404e4_t5" AS (SELECT CONCAT("a"."廠客品號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))) AS "批號", SUM(COALESCE("a"."贈品數量", 0)) AS "數量", SUM(COALESCE("a"."毛重", 0)) AS "重量", SUM(COALESCE("b"."數值5", 0)) AS "報廢數量" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" WHERE "a"."單據類別" = 'E33' GROUP BY CONCAT("a"."廠客品號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))));

-- Home #2060 ViewFIL404E4_T6.成品品檢重量
CREATE OR REPLACE VIEW "viewfil404e4_t6" AS (SELECT CONCAT("a"."廠客品號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))) AS "批號", SUM(COALESCE("b"."數值5" * -1, 0)) AS "數量" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" WHERE "a"."單據類別" = 'E37' GROUP BY CONCAT("a"."廠客品號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))));

-- Home #2063 ViewFIL404E4_T7.成品庫存合計
CREATE OR REPLACE VIEW "viewfil404e4_t7" AS (SELECT REGEXP_SUBSTR("a"."批號", '[^-]+', 1, 1) AS "製令號碼", SUM("a"."結存數量") AS "結存數量", SUM("a"."結存重量") AS "結存重量" FROM "fil004h" AS "a" GROUP BY REGEXP_SUBSTR("a"."批號", '[^-]+', 1, 1));

-- Home #2064 ViewFIL404E4_T8.成品批號
CREATE OR REPLACE VIEW "viewfil404e4_t8" AS (SELECT DISTINCT "a"."批號" FROM "fil004l" AS "a");

-- Home #2068 ViewFIL404E7.製袋平均重量
CREATE OR REPLACE VIEW "viewfil404e7" AS (SELECT DISTINCT "a"."製令單別", "a"."製令單號", "a"."箱號", FIRST_VALUE("a"."平均袋重") OVER (PARTITION BY "製令單別", "製令單號", "箱號" ORDER BY "單號" ASC) AS "平均袋重", FIRST_VALUE("a"."紙箱重量") OVER (PARTITION BY "製令單別", "製令單號", "箱號" ORDER BY "單號" ASC) AS "紙箱重量", FIRST_VALUE("a"."作業人員") OVER (PARTITION BY "製令單別", "製令單號", "箱號" ORDER BY "單號" ASC) AS "作業人員", FIRST_VALUE("a"."作業員二") OVER (PARTITION BY "製令單別", "製令單號", "箱號" ORDER BY "單號" ASC) AS "作業員二", FIRST_VALUE("a"."作業員三") OVER (PARTITION BY "製令單別", "製令單號", "箱號" ORDER BY "單號" ASC) AS "作業員三", FIRST_VALUE("a"."作業人員姓名") OVER (PARTITION BY "製令單別", "製令單號", "箱號" ORDER BY "單號" ASC) AS "作業人員姓名", FIRST_VALUE("a"."作業員二姓名") OVER (PARTITION BY "製令單別", "製令單號", "箱號" ORDER BY "單號" ASC) AS "作業員二姓名", FIRST_VALUE("a"."作業員三姓名") OVER (PARTITION BY "製令單別", "製令單號", "箱號" ORDER BY "單號" ASC) AS "作業員三姓名" FROM (SELECT "c1"."歸屬類別" AS "製令單別", "c1"."歸屬編號" AS "製令單號", "a"."異動數量" AS "箱號", CASE WHEN "a"."贈品數量" = 0 THEN 0 ELSE CAST(("a"."毛重" - COALESCE("d"."單價下限率", 0)) AS DOUBLE PRECISION) / "a"."贈品數量" END AS "平均袋重", COALESCE("d"."單價下限率", 0) AS "紙箱重量", CONCAT("a"."單據編號", '-', TO_CHAR("a"."單據序號", '0000')) AS "單號", "c1"."業務員" AS "作業人員", COALESCE("e"."員工姓名", ' ') AS "作業人員姓名", "c"."文數字10" AS "作業員二", COALESCE("g"."員工姓名", ' ') AS "作業員二姓名", "c"."文數字11" AS "作業員三", COALESCE("h"."員工姓名", ' ') AS "作業員三姓名" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "c1" ON "a"."單據類別" = "c1"."單據類別" AND "a"."單據編號" = "c1"."單據編號" INNER JOIN "fil0041" AS "b" ON "b"."單別" = "a"."單據類別" AND "b"."單號" = "a"."單據編號" AND "b"."序號" = "a"."單據序號" LEFT JOIN "fil0010" AS "e" ON "c1"."業務員" = "e"."員工編號" LEFT JOIN "fil0010" AS "g" ON "c"."文數字10" = "g"."員工編號" LEFT JOIN "fil0010" AS "h" ON "c"."文數字11" = "h"."員工編號" LEFT JOIN "fil0012" AS "d" ON "d"."產品編號" = CASE WHEN "b"."logical5" = 0 THEN CASE WHEN "c"."數值17" <> "a"."贈品數量" THEN CASE WHEN "c"."文數字12" = ' ' THEN "c"."文數字7" ELSE "c"."文數字12" END ELSE "c"."文數字7" END ELSE CASE WHEN "c"."數值19" <> "a"."贈品數量" THEN CASE WHEN "c"."文數字12" = ' ' THEN "c"."文數字8" ELSE "c"."文數字12" END ELSE "c"."文數字8" END END WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" = 'C31E') AS "a");

-- Home #2069 ViewFIL404E71.製袋批號首筆重
CREATE OR REPLACE VIEW "viewfil404e71" AS (SELECT DISTINCT "a"."批號", COALESCE(FIRST_VALUE("a"."平均袋重") OVER (PARTITION BY "a"."批號" ORDER BY "單號" ASC), 0) AS "平均袋重" FROM (SELECT CONCAT("c1"."歸屬編號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))) AS "批號", CONCAT("a"."單據編號", '-', TO_CHAR("a"."單據序號", '0000')) AS "單號", CASE WHEN "a"."贈品數量" = 0 THEN 0 ELSE CAST("a"."毛重" AS DOUBLE PRECISION) / "a"."贈品數量" END AS "平均袋重" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "c1" ON "a"."單據類別" = "c1"."單據類別" AND "a"."單據編號" = "c1"."單據編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" = 'C31E' AND "a"."贈品數量" <> 0) AS "a");

-- Home #2070 ViewFIL404E72A.製袋每日產量
CREATE OR REPLACE VIEW "viewfil404e72a" AS (SELECT "b"."專案代號" AS "成品檢驗單號", SUM(CASE WHEN "b"."數值14" = 0 THEN "a"."贈品數量" ELSE "b"."數值14" END) AS "每日產量" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" = 'C31E' AND "b"."專案代號" <> ' ' GROUP BY "b"."專案代號");

-- Home #2071 ViewFIL404E73.製袋平均磅重
CREATE OR REPLACE VIEW "viewfil404e73" AS (SELECT DISTINCT "a"."製令單別", "a"."製令單號", COALESCE(FIRST_VALUE("a"."箱號") OVER (PARTITION BY "a"."製令單別", "a"."製令單號" ORDER BY "a"."製令單別", "a"."製令單號", "a"."箱號" ASC), 0) AS "箱號", COALESCE(FIRST_VALUE("a"."平均袋重") OVER (PARTITION BY "a"."製令單別", "a"."製令單號" ORDER BY "a"."製令單別", "a"."製令單號", "a"."箱號" ASC), 0) AS "平均袋重" FROM (SELECT "c1"."歸屬類別" AS "製令單別", "c1"."歸屬編號" AS "製令單號", "a"."異動數量" AS "箱號", CASE WHEN "a"."贈品數量" = 0 THEN 0 ELSE CAST(("a"."毛重" - COALESCE("d"."單價下限率", 0)) AS DOUBLE PRECISION) / "a"."贈品數量" END AS "平均袋重" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "c1" ON "a"."單據類別" = "c1"."單據類別" AND "a"."單據編號" = "c1"."單據編號" INNER JOIN "fil0041" AS "b" ON "b"."單別" = "a"."單據類別" AND "b"."單號" = "a"."單據編號" AND "b"."序號" = "a"."單據序號" LEFT JOIN "fil0012" AS "d" ON "d"."產品編號" = CASE WHEN "b"."logical5" = 0 THEN CASE WHEN "c"."數值17" <> "a"."贈品數量" THEN CASE WHEN "c"."文數字12" = ' ' THEN "c"."文數字7" ELSE "c"."文數字12" END ELSE "c"."文數字7" END ELSE CASE WHEN "c"."數值19" <> "a"."贈品數量" THEN CASE WHEN "c"."文數字12" = ' ' THEN "c"."文數字8" ELSE "c"."文數字12" END ELSE "c"."文數字8" END END WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" = 'C31E' AND "a"."毛重" - COALESCE("d"."單價下限率", 0) > 0) AS "a");

-- Home #2072 ViewFIL404E74.製袋製令合計
CREATE OR REPLACE VIEW "viewfil404e74" AS (SELECT "d"."歸屬編號" AS "製令單號", MAX("a"."異動數量") AS "最後箱號", SUM(CASE WHEN "b"."數值14" = 0 THEN "a"."贈品數量" ELSE "b"."數值14" END) AS "數量", SUM(CASE WHEN "b"."數值14" = 0 THEN "a"."毛重" ELSE "a"."毛重" * CASE WHEN "a"."贈品數量" = 0 THEN 0 ELSE (CAST("b"."數值14" AS DOUBLE PRECISION) / "a"."贈品數量") END END) AS "重量" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" LEFT JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" WHERE "a"."異動類別" = 'A' AND "c"."製程代碼" = 'C31E' GROUP BY "d"."歸屬編號");

-- Home #2073 ViewFIL404E75.成品批號平均重量
CREATE OR REPLACE VIEW "viewfil404e75" AS (SELECT DISTINCT "a"."批號", (SELECT CAST("b"."製袋重量" AS DOUBLE PRECISION) / "b"."數量" FROM "fil004l" AS "b" WHERE "b"."批號" = "a"."批號" AND "b"."製袋重量" > 0 ORDER BY "異動日期" FETCH FIRST 1 ROWS ONLY) AS "平均製袋重量", (SELECT CAST("b"."氣閥重量" AS DOUBLE PRECISION) / "b"."數量" FROM "fil004l" AS "b" WHERE "b"."批號" = "a"."批號" AND "b"."氣閥重量" > 0 ORDER BY "異動日期" FETCH FIRST 1 ROWS ONLY) AS "平均氣閥重量", (SELECT CAST("b"."鐵條重量" AS DOUBLE PRECISION) / "b"."數量" FROM "fil004l" AS "b" WHERE "b"."批號" = "a"."批號" AND "b"."鐵條重量" > 0 ORDER BY "異動日期" FETCH FIRST 1 ROWS ONLY) AS "平均鐵條重量", (SELECT "b"."紙箱重量" FROM "fil004l" AS "b" WHERE "b"."批號" = "a"."批號" AND "b"."紙箱重量" > 0 ORDER BY "異動日期" FETCH FIRST 1 ROWS ONLY) AS "紙箱重量" FROM "fil004l" AS "a");

-- Home #2074 ViewFIL404E8.品檢平均重量
CREATE OR REPLACE VIEW "viewfil404e8" AS (SELECT CAST('C11' AS TEXT) AS "製令單別", "a"."廠客品號" AS "製令單號", "a"."異動數量" AS "箱號", CASE WHEN SUM("a"."贈品數量") = 0 THEN 0 ELSE CAST(SUM("a"."毛重") AS DOUBLE PRECISION) / SUM("a"."贈品數量") END AS "平均袋重" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'E37' GROUP BY CAST('C11' AS TEXT), "a"."廠客品號", "a"."異動數量");

-- Home #2075 ViewFIL404E81.箱號異動首筆重
CREATE OR REPLACE VIEW "viewfil404e81" AS (SELECT DISTINCT "a"."批號", COALESCE(FIRST_VALUE("a"."平均袋重") OVER (PARTITION BY "a"."批號" ORDER BY "a"."單號" ASC), 0) AS "平均袋重" FROM (SELECT CONCAT("a"."廠客品號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))) AS "批號", CONCAT("a"."單據編號", '-', TO_CHAR("a"."單據序號", '0000')) AS "單號", CASE WHEN "a"."贈品數量" = 0 THEN 0 ELSE CAST("a"."毛重" AS DOUBLE PRECISION) / "a"."贈品數量" END AS "平均袋重" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'E32' AND "a"."贈品數量" <> 0) AS "a");

-- Home #1951 ViewFIL404EA.製袋日報合計_C31E
CREATE OR REPLACE VIEW "viewfil404ea" AS (SELECT "a"."單別", "a"."單號", "a"."ａ材領料米數", "a"."ｂ材領料米數", "a"."側邊領料米數", "a"."底邊領料米數", "a"."ａ切刀次數", "a"."ｂ切刀次數", "a"."側切刀次數", "a"."底切刀次數", "a"."繳庫總袋數" + "c"."送貨地址序號" + CASE WHEN "c"."logical11" = 0 THEN "c"."聯絡人序號" ELSE 0 END AS "總切刀次數", "a"."補足上次尾數", "a"."補足上次尾數_箱數", "a"."繳庫袋數", "a"."繳庫袋數_箱數", "a"."尾數成品", "a"."尾數成品_箱數", "a"."繳庫總袋數", "a"."繳庫袋數_箱數" + "a"."補足上次尾數_箱數" + "a"."尾數成品_箱數" AS "繳庫總袋數_箱數", "a"."尾數成品二", "a"."尾數成品二_箱數", "a"."待重工總袋數", "a"."待重工總箱數", "c"."送貨地址序號" AS "報廢數", "c"."聯絡人序號" AS "重整數", "c"."logical4" AS "結束", "c"."logical5" AS "待補", CASE WHEN "c"."數值6" = 0 OR "a"."ａ材領料米數" = 0 THEN 0 ELSE ROUND(CAST("a"."繳庫總袋數" AS DOUBLE PRECISION) / (CAST(1000 AS DOUBLE PRECISION) / "c"."數值6" * "a"."ａ材領料米數") * 100, 0) END AS "不良剔除後成品率", "c"."數值6" AS "展開尺寸_寬", "e"."成袋數" AS "生產條件成袋數", "a"."a材退庫", "a"."b材退庫", "a"."側邊退庫", "a"."底邊退庫" FROM (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM(("c"."數值1" - "c"."數值15" - "c"."數值19") * CASE WHEN "m"."邏輯值一" = 1 THEN 2 ELSE 1 END) AS "ａ材領料米數", SUM("c"."數值2" - "c"."數值16" - "c"."數值20") AS "ｂ材領料米數", SUM("c"."數值3" - "c"."數值18" - "c"."數值22") AS "側邊領料米數", SUM("c"."數值4" - "c"."數值17" - "c"."數值21") AS "底邊領料米數", SUM("c"."數值10") AS "ａ切刀次數", SUM("c"."數值11") AS "ｂ切刀次數", SUM("c"."數值12") AS "側切刀次數", SUM("c"."數值13") AS "底切刀次數", SUM("c"."數值14") AS "補足上次尾數", SUM(CASE WHEN "c"."數值14" = 0 THEN 0 ELSE 1 END) AS "補足上次尾數_箱數", SUM(CASE WHEN "a"."贈品數量" = CASE WHEN "a"."單據序號" = "d"."序號" /* 末一筆 */ OR ("a"."單據序號" IS NULL AND "d"."序號" /* 末一筆 */ IS NULL) THEN CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END WHEN "a"."單據序號" = "e"."序號" /* 末二筆 */ OR ("a"."單據序號" IS NULL AND "e"."序號" /* 末二筆 */ IS NULL) THEN CASE WHEN "d"."logical2" /* 雙膜 */ = 0 THEN "a"."贈品數量" /* 非雙膜數量全計 */ ELSE CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END END ELSE "a"."贈品數量" /* 非末一二筆數量全計 */ END OR ("a"."贈品數量" IS NULL AND CASE WHEN "a"."單據序號" = "d"."序號" /* 末一筆 */ OR ("a"."單據序號" IS NULL AND "d"."序號" /* 末一筆 */ IS NULL) THEN CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END WHEN "a"."單據序號" = "e"."序號" /* 末二筆 */ OR ("a"."單據序號" IS NULL AND "e"."序號" /* 末二筆 */ IS NULL) THEN CASE WHEN "d"."logical2" /* 雙膜 */ = 0 THEN "a"."贈品數量" /* 非雙膜數量全計 */ ELSE CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END END ELSE "a"."贈品數量" /* 非末一二筆數量全計 */ END IS NULL) THEN CASE WHEN "c"."數值14" /* 補尾數 */ = 0 THEN "a"."贈品數量" ELSE 0 END ELSE 0 END) AS "繳庫袋數", SUM(CASE WHEN "a"."贈品數量" = CASE WHEN "a"."單據序號" = "d"."序號" /* 末一筆 */ OR ("a"."單據序號" IS NULL AND "d"."序號" /* 末一筆 */ IS NULL) THEN CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END WHEN "a"."單據序號" = "e"."序號" /* 末二筆 */ OR ("a"."單據序號" IS NULL AND "e"."序號" /* 末二筆 */ IS NULL) THEN CASE WHEN "d"."logical2" /* 雙膜 */ = 0 THEN "a"."贈品數量" /* 非雙膜數量全計 */ ELSE CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END END ELSE "a"."贈品數量" /* 非末一二筆數量全計 */ END OR ("a"."贈品數量" IS NULL AND CASE WHEN "a"."單據序號" = "d"."序號" /* 末一筆 */ OR ("a"."單據序號" IS NULL AND "d"."序號" /* 末一筆 */ IS NULL) THEN CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END WHEN "a"."單據序號" = "e"."序號" /* 末二筆 */ OR ("a"."單據序號" IS NULL AND "e"."序號" /* 末二筆 */ IS NULL) THEN CASE WHEN "d"."logical2" /* 雙膜 */ = 0 THEN "a"."贈品數量" /* 非雙膜數量全計 */ ELSE CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END END ELSE "a"."贈品數量" /* 非末一二筆數量全計 */ END IS NULL) THEN CASE WHEN "c"."數值14" /* 補尾數 */ = 0 THEN 1 ELSE 0 END ELSE 0 END) AS "繳庫袋數_箱數", SUM(CASE WHEN "a"."單據序號" = "d"."序號" /* 末一筆 */ OR ("a"."單據序號" IS NULL AND "d"."序號" /* 末一筆 */ IS NULL) THEN CASE WHEN "a"."贈品數量" = CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END OR ("a"."贈品數量" IS NULL AND CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END IS NULL) THEN 0 ELSE "a"."贈品數量" END WHEN "a"."單據序號" = "e"."序號" /* 末二筆 */ OR ("a"."單據序號" IS NULL AND "e"."序號" /* 末二筆 */ IS NULL) THEN CASE WHEN "d"."logical2" /* 雙膜 */ = 0 THEN 0 ELSE CASE WHEN "a"."贈品數量" = CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END OR ("a"."贈品數量" IS NULL AND CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END IS NULL) THEN 0 ELSE "a"."贈品數量" END END ELSE 0 END) AS "尾數成品", SUM(CASE WHEN "a"."單據序號" = "d"."序號" /* 末一筆 */ OR ("a"."單據序號" IS NULL AND "d"."序號" /* 末一筆 */ IS NULL) THEN CASE WHEN "a"."贈品數量" = CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END OR ("a"."贈品數量" IS NULL AND CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END IS NULL) THEN 0 ELSE "b"."logical4" END WHEN "a"."單據序號" = "e"."序號" /* 末二筆 */ OR ("a"."單據序號" IS NULL AND "e"."序號" /* 末二筆 */ IS NULL) THEN CASE WHEN "d"."logical2" /* 雙膜 */ = 0 THEN 0 ELSE CASE WHEN "a"."贈品數量" = CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END OR ("a"."贈品數量" IS NULL AND CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END IS NULL) THEN 0 ELSE "b"."logical4" END END ELSE 0 END) AS "尾數成品_箱數" /* 有尾數成品且結束則1箱 */, SUM(CASE WHEN "a"."單據序號" = "e"."序號" /* 末二筆 */ OR ("a"."單據序號" IS NULL AND "e"."序號" /* 末二筆 */ IS NULL) THEN CASE WHEN "d"."logical2" /* 雙膜 */ = 0 THEN 0 ELSE CASE WHEN "a"."贈品數量" = CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END OR ("a"."贈品數量" IS NULL AND CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END IS NULL) THEN 0 ELSE "a"."贈品數量" END END ELSE 0 END) AS "尾數成品二", SUM(CASE WHEN "a"."單據序號" = "e"."序號" /* 末二筆 */ OR ("a"."單據序號" IS NULL AND "e"."序號" /* 末二筆 */ IS NULL) THEN CASE WHEN "d"."logical2" /* 雙膜 */ = 0 THEN 0 ELSE CASE WHEN "a"."贈品數量" = CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END OR ("a"."贈品數量" IS NULL AND CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END IS NULL) THEN 0 ELSE "b"."logical4" END END ELSE 0 END) AS "尾數成品二_箱數", SUM(CASE WHEN "c"."數值14" = 0 THEN "a"."贈品數量" ELSE "c"."數值14" END) AS "繳庫總袋數", SUM(CASE WHEN "a"."logical3" = 1 THEN CASE WHEN "c"."數值14" = 0 THEN "a"."贈品數量" ELSE "c"."數值14" END ELSE 0 END) AS "待重工總袋數", (SUM(CASE WHEN "a"."logical3" = 1 THEN CASE WHEN "a"."贈品數量" = CASE WHEN "a"."單據序號" = "d"."序號" /* 末一筆 */ OR ("a"."單據序號" IS NULL AND "d"."序號" /* 末一筆 */ IS NULL) THEN CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END WHEN "a"."單據序號" = "e"."序號" /* 末二筆 */ OR ("a"."單據序號" IS NULL AND "e"."序號" /* 末二筆 */ IS NULL) THEN CASE WHEN "d"."logical2" /* 雙膜 */ = 0 THEN "a"."贈品數量" /* 非雙膜數量全計 */ ELSE CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END END ELSE "a"."贈品數量" /* 非末一二筆數量全計 */ END OR ("a"."贈品數量" IS NULL AND CASE WHEN "a"."單據序號" = "d"."序號" /* 末一筆 */ OR ("a"."單據序號" IS NULL AND "d"."序號" /* 末一筆 */ IS NULL) THEN CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END WHEN "a"."單據序號" = "e"."序號" /* 末二筆 */ OR ("a"."單據序號" IS NULL AND "e"."序號" /* 末二筆 */ IS NULL) THEN CASE WHEN "d"."logical2" /* 雙膜 */ = 0 THEN "a"."贈品數量" /* 非雙膜數量全計 */ ELSE CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END END ELSE "a"."贈品數量" /* 非末一二筆數量全計 */ END IS NULL) THEN CASE WHEN "c"."數值14" /* 補尾數 */ = 0 THEN 1 ELSE 0 END ELSE 0 END ELSE 0 END) + SUM(CASE WHEN "a"."logical3" = 1 THEN CASE WHEN "c"."數值14" = 0 THEN 0 ELSE 1 END ELSE 0 END) + SUM(CASE WHEN "a"."logical3" = 1 THEN CASE WHEN "a"."單據序號" = "d"."序號" /* 末一筆 */ OR ("a"."單據序號" IS NULL AND "d"."序號" /* 末一筆 */ IS NULL) THEN CASE WHEN "a"."贈品數量" = CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END OR ("a"."贈品數量" IS NULL AND CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END IS NULL) THEN 0 ELSE "b"."logical4" END WHEN "a"."單據序號" = "e"."序號" /* 末二筆 */ OR ("a"."單據序號" IS NULL AND "e"."序號" /* 末二筆 */ IS NULL) THEN CASE WHEN "d"."logical2" /* 雙膜 */ = 0 THEN 0 ELSE CASE WHEN "a"."贈品數量" = CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END OR ("a"."贈品數量" IS NULL AND CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END IS NULL) THEN 0 ELSE "b"."logical4" END END ELSE 0 END ELSE 0 END)) AS "待重工總箱數", SUM("c"."數值19") AS "a材退庫", SUM("c"."數值20") AS "b材退庫", SUM("c"."數值21") AS "側邊退庫", SUM("c"."數值22") AS "底邊退庫" /*
			B.數值17 紙箱_無氣閥_每箱幾袋
			B.數值19 紙箱_氣閥_每箱幾袋
			B.Logical4 結束
			B.Logical5 待補
			C.Logical5 氣閥
			C.數值14 補尾數
			D.Logical2 雙膜
			*/ FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "m" ON "a"."單據類別" = "m"."單據類別" AND "a"."單據編號" = "m"."單據編號" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "viewfil2023" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" AND "d"."類別" = 'A' AND "d"."desc排序" = 1 LEFT JOIN "viewfil2023" AS "e" ON "a"."單據類別" = "e"."單別" AND "a"."單據編號" = "e"."單號" AND "e"."類別" = 'A' AND "e"."desc排序" = 2 WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31E' GROUP BY "a"."單據類別", "a"."單據編號") AS "a" INNER JOIN "fil0030" AS "b" ON "b"."單據類別" = "a"."單別" AND "a"."單號" = "b"."單據編號" INNER JOIN "fil0031" AS "c" ON "a"."單別" = "c"."單別" AND "a"."單號" = "c"."單號" INNER JOIN "fil0032" AS "e" ON "e"."製令單別" = "b"."歸屬類別" AND "e"."製令單號" = "b"."歸屬編號");

-- Home #1955 ViewFIL404EE.製袋日報分析工時
CREATE OR REPLACE VIEW "viewfil404ee" AS (SELECT "a"."單據編號" AS "單號", "a"."單據日期" AS "作業日期", CAST((86400 - (TO_NUMBER(ORA_SUBSTR("b"."時間一", 1, 2)) * 60 * 60 + TO_NUMBER(ORA_SUBSTR("b"."時間一", 3, 2)) * 60 + TO_NUMBER(ORA_SUBSTR("b"."時間一", 5, 6)))) AS DOUBLE PRECISION) / 3600 AS "工作時數", '1' AS "類別" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31E' AND "b"."時間一" > "b"."時間二" UNION SELECT "a"."單據編號" AS "單號", TO_CHAR(TO_DATE("a"."單據日期", 'yyyymmdd') + 1, 'yyyymmdd') AS "作業日期", CAST((TO_NUMBER(ORA_SUBSTR("b"."時間二", 1, 2)) * 60 * 60 + TO_NUMBER(ORA_SUBSTR("b"."時間二", 3, 2)) * 60 + TO_NUMBER(ORA_SUBSTR("b"."時間二", 5, 6))) AS DOUBLE PRECISION) / 3600 AS "工作時數", '2' AS "類別" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31E' AND "b"."時間一" > "b"."時間二" UNION SELECT "a"."單據編號" AS "單號", "a"."單據日期" AS "作業日期", CAST(((TO_NUMBER(ORA_SUBSTR("b"."時間二", 1, 2)) * 60 * 60 + TO_NUMBER(ORA_SUBSTR("b"."時間二", 3, 2)) * 60 + TO_NUMBER(ORA_SUBSTR("b"."時間二", 5, 6))) - (TO_NUMBER(ORA_SUBSTR("b"."時間一", 1, 2)) * 60 * 60 + TO_NUMBER(ORA_SUBSTR("b"."時間一", 3, 2)) * 60 + TO_NUMBER(ORA_SUBSTR("b"."時間一", 5, 6)))) AS DOUBLE PRECISION) / 3600 AS "工作時數", '3' AS "類別" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31E' AND "b"."時間一" < "b"."時間二");

-- Home #1956 ViewFIL404EF.製袋日報分析人員
CREATE OR REPLACE VIEW "viewfil404ef" AS (SELECT "a"."單別", "a"."單號", "a"."作業人員", "a"."作業人員姓名", "a"."作業人數" FROM (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", CAST(COALESCE("a"."業務員", ' ') AS TEXT) AS "作業人員", CAST(COALESCE("e"."員工姓名", ' ') AS TEXT) AS "作業人員姓名", CASE WHEN "a"."業務員" = ' ' THEN 0 ELSE 1 END + CASE WHEN "b"."文數字10" = ' ' THEN 0 ELSE 1 END + CASE WHEN "b"."文數字11" = ' ' THEN 0 ELSE 1 END AS "作業人數" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0010" AS "e" ON "a"."業務員" = "e"."員工編號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31E' AND "a"."業務員" <> ' ' UNION SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", CAST(COALESCE("b"."文數字10", ' ') AS TEXT) AS "作業人員", CAST(COALESCE("e"."員工姓名", ' ') AS TEXT) AS "作業人員姓名", CASE WHEN "a"."業務員" = ' ' THEN 0 ELSE 1 END + CASE WHEN "b"."文數字10" = ' ' THEN 0 ELSE 1 END + CASE WHEN "b"."文數字11" = ' ' THEN 0 ELSE 1 END AS "作業人數" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0010" AS "e" ON "b"."文數字10" = "e"."員工編號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31E' AND "b"."文數字10" <> ' ' UNION SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", CAST(COALESCE("b"."文數字11", ' ') AS TEXT) AS "作業人員", CAST(COALESCE("e"."員工姓名", ' ') AS TEXT) AS "作業人員姓名", CASE WHEN "a"."業務員" = ' ' THEN 0 ELSE 1 END + CASE WHEN "b"."文數字10" = ' ' THEN 0 ELSE 1 END + CASE WHEN "b"."文數字11" = ' ' THEN 0 ELSE 1 END AS "作業人數" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0010" AS "e" ON "b"."文數字11" = "e"."員工編號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31E' AND "b"."文數字11" <> ' ') AS "a");

-- Home #1957 ViewFIL404EG.製袋日報檢查次數
CREATE OR REPLACE VIEW "viewfil404eg" AS (SELECT "a"."單別" AS "單別", "a"."單號" AS "單號", COUNT("a"."序號") AS "筆數" FROM "fil0049" AS "a" WHERE "a"."單別" = 'C41' GROUP BY "a"."單別", "a"."單號");

-- Home #1962 ViewFIL404F4.氣閥袋重報廢
CREATE OR REPLACE VIEW "viewfil404f4" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "報廢數量" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "c1" ON "a"."單據類別" = "c1"."單別" AND "a"."單據編號" = "c1"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c1"."製程代碼" = 'C31F' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #1963 ViewFIL404FA.氣閥日報合計_C31F
CREATE OR REPLACE VIEW "viewfil404fa" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."贈品數量" - CASE WHEN "a"."贈品數量" = "b"."數值2" OR ("a"."贈品數量" IS NULL AND "b"."數值2" IS NULL) THEN 0 ELSE "a"."贈品數量" END) AS "繳庫袋數", COUNT("a"."單據序號") - SUM(CASE WHEN "a"."贈品數量" = "b"."數值2" OR ("a"."贈品數量" IS NULL AND "b"."數值2" IS NULL) THEN 0 ELSE 1 END) AS "繳庫袋數_箱數", SUM("a"."贈品數量") AS "繳庫總袋數", COUNT("a"."單據序號") AS "繳庫總袋數_箱數", SUM(CASE WHEN "a"."贈品數量" = "b"."數值2" OR ("a"."贈品數量" IS NULL AND "b"."數值2" IS NULL) THEN 0 ELSE "a"."贈品數量" END) AS "尾數成品", SUM(CASE WHEN "a"."贈品數量" = "b"."數值2" OR ("a"."贈品數量" IS NULL AND "b"."數值2" IS NULL) THEN 0 ELSE 1 END) AS "尾數成品_箱數", MAX("b"."數值2") AS "每箱幾袋", MAX("a"."單據序號") AS "序號" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31F' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #1967 ViewFIL404FE.氣閥日報彙總_C31F
CREATE OR REPLACE VIEW "viewfil404fe" AS (SELECT "a"."單別", "a"."單號", STRING_AGG(CAST(CONCAT(TRIM(TO_CHAR("a"."繳庫箱數", '999')), '箱 X ', TRIM(TO_CHAR("a"."繳庫袋數", '99999')), '袋') AS TEXT), ',' ORDER BY "a"."序號" DESC) AS "彙總" FROM (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."贈品數量" AS "繳庫袋數", MIN("a"."單據序號") AS "序號", COUNT("a"."單據序號") AS "繳庫箱數" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31F' GROUP BY "a"."單據類別", "a"."單據編號", "a"."贈品數量") AS "a" GROUP BY "a"."單別", "a"."單號");

-- Home #1975 ViewFIL404F_G.氣閥鐵條作業人員
CREATE OR REPLACE VIEW "viewfil404f_g" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "c"."單據日期" AS "作業日期", "c"."歸屬類別" AS "製令單別", "c"."歸屬編號" AS "製令單號", "c"."業務員" AS "作業人員", "a"."time1" AS "每箱結束時間", CONCAT(CASE WHEN "a"."time1" >= "b"."時間一" THEN "c"."單據日期" ELSE TO_CHAR(TO_DATE("c"."單據日期", 'yyyymmdd') + 1, 'yyyymmdd') END, "a"."time1") AS "計件日時", "b"."製程代碼", "a"."贈品數量" AS "繳庫袋數" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND ("b"."製程代碼" = 'C31F' OR "b"."製程代碼" = 'C31G'));

-- Home #1971 ViewFIL404GA.鐵條日報合計_C31G
CREATE OR REPLACE VIEW "viewfil404ga" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."贈品數量" - CASE WHEN "a"."贈品數量" = "b"."數值2" OR ("a"."贈品數量" IS NULL AND "b"."數值2" IS NULL) THEN 0 ELSE "a"."贈品數量" END) AS "繳庫袋數", COUNT("a"."單據序號") - SUM(CASE WHEN "a"."贈品數量" = "b"."數值2" OR ("a"."贈品數量" IS NULL AND "b"."數值2" IS NULL) THEN 0 ELSE 1 END) AS "繳庫袋數_箱數", SUM("a"."贈品數量") AS "繳庫總袋數", COUNT("a"."單據序號") AS "繳庫總袋數_箱數", SUM(CASE WHEN "a"."贈品數量" = "b"."數值2" OR ("a"."贈品數量" IS NULL AND "b"."數值2" IS NULL) THEN 0 ELSE "a"."贈品數量" END) AS "尾數成品", SUM(CASE WHEN "a"."贈品數量" = "b"."數值2" OR ("a"."贈品數量" IS NULL AND "b"."數值2" IS NULL) THEN 0 ELSE 1 END) AS "尾數成品_箱數", MAX("b"."數值2") AS "每箱幾袋", MAX("a"."單據序號") AS "序號" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31G' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #1974 ViewFIL404GE.鐵條日報彙總_C31G
CREATE OR REPLACE VIEW "viewfil404ge" AS (SELECT "a"."單別", "a"."單號", STRING_AGG(CAST(CONCAT(TRIM(TO_CHAR("a"."繳庫箱數", '999')), '箱 X ', TRIM(TO_CHAR("a"."繳庫袋數", '99999')), '袋') AS TEXT), ',' ORDER BY "a"."序號" DESC) AS "彙總" FROM (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."贈品數量" AS "繳庫袋數", MIN("a"."單據序號") AS "序號", COUNT("a"."單據序號") AS "繳庫箱數" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31G' GROUP BY "a"."單據類別", "a"."單據編號", "a"."贈品數量") AS "a" GROUP BY "a"."單別", "a"."單號");

-- Home #1984 ViewFIL404K2.成捲日報合計_C31I
CREATE OR REPLACE VIEW "viewfil404k2" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", COUNT("a"."單據序號") AS "全部箱數", SUM(CASE WHEN "b"."數值1" = "c"."包裝數量" OR ("b"."數值1" IS NULL AND "c"."包裝數量" IS NULL) THEN 0 ELSE 1 END) AS "尾數箱", SUM(COALESCE("c"."包裝數量", 0)) AS "全部捲數", SUM(CASE WHEN "b"."數值1" = COALESCE("c"."包裝數量", 0) OR ("b"."數值1" IS NULL AND COALESCE("c"."包裝數量", 0) IS NULL) THEN 0 ELSE COALESCE("c"."包裝數量", 0) END) AS "尾數捲數" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0041" AS "c" ON "c"."單別" = "a"."單據類別" AND "c"."單號" = "a"."單據編號" AND "c"."序號" = "a"."單據序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31I' AND COALESCE("c"."包裝數量", 0) > 0 GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #1986 ViewFIL404K3.成捲細分_C31I
CREATE OR REPLACE VIEW "viewfil404k3" AS (SELECT "a"."單別", "a"."單號", "a"."序號", "a"."細分", "c"."異動數量" AS "箱號", "a"."文字一" AS "半成品編號", "a"."數字一" AS "數量", "c"."毛重" AS "重量", "a"."日期一" AS "入庫日期", "a"."日期二" AS "製造日期", CONCAT(RTRIM("a"."單號"), TRIM(TO_CHAR("a"."序號", '0000'))) AS "單號序號" FROM "fil00401" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單別" = "b"."單別" AND "a"."單號" = "b"."單號" INNER JOIN "fil0040" AS "c" ON "a"."單別" = "c"."單據類別" AND "a"."單號" = "c"."單據編號" AND "a"."序號" = "c"."單據序號" WHERE "a"."單別" = 'C41' AND "b"."製程代碼" = 'C31I');

-- Home #1985 ViewFIL404K4.成捲最後箱號_C311
CREATE OR REPLACE VIEW "viewfil404k4" AS (SELECT "d"."歸屬類別" AS "製令單別", "d"."歸屬編號" AS "製令單號", MAX("c"."異動數量") AS "箱號" FROM "fil00401" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單別" = "b"."單別" AND "a"."單號" = "b"."單號" INNER JOIN "fil0040" AS "c" ON "a"."單別" = "c"."單據類別" AND "a"."單號" = "c"."單據編號" AND "a"."序號" = "c"."單據序號" INNER JOIN "fil0030" AS "d" ON "a"."單別" = "d"."單據類別" AND "a"."單號" = "d"."單據編號" WHERE "a"."單別" = 'C41' AND "b"."製程代碼" = 'C31I' GROUP BY "d"."歸屬類別", "d"."歸屬編號");

-- Home #1987 ViewFIL404K5.成捲製令捲數_C31I
CREATE OR REPLACE VIEW "viewfil404k5" AS (SELECT "d"."歸屬類別" AS "製令單別", "d"."歸屬編號" AS "製令單號", SUM(COALESCE("c"."包裝數量", 0)) AS "捲數" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0041" AS "c" ON "c"."單別" = "a"."單據類別" AND "c"."單號" = "a"."單據編號" AND "c"."序號" = "a"."單據序號" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31I' AND COALESCE("c"."包裝數量", 0) > 0 GROUP BY "d"."歸屬類別", "d"."歸屬編號");

-- Home #1988 ViewFIL404K6.成捲製令箱號_C31I
CREATE OR REPLACE VIEW "viewfil404k6" AS (SELECT DISTINCT "d"."歸屬類別" AS "製令單別", "d"."歸屬編號" AS "製令單號", "a"."異動數量" AS "箱號" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0041" AS "c" ON "c"."單別" = "a"."單據類別" AND "c"."單號" = "a"."單據編號" AND "c"."序號" = "a"."單據序號" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31I');

-- Home #1989 ViewFIL404K7.成捲批號庫存
CREATE OR REPLACE VIEW "viewfil404k7" AS WITH "tmp1" AS (SELECT REGEXP_SUBSTR(REGEXP_SUBSTR("a"."文字一", '[^_]+', 1, 1), '[^-]+', 1, 1) AS "製令單號", "a"."文字一" AS "條碼", 1 AS "數量" FROM "fil00401" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單別" = "b"."單別" AND "a"."單號" = "b"."單號" INNER JOIN "fil0040" AS "c" ON "a"."單別" = "c"."單據類別" AND "a"."單號" = "c"."單據編號" AND "a"."序號" = "c"."單據序號" WHERE "a"."單別" = 'C41' AND "b"."製程代碼" = 'C31I' UNION ALL SELECT REGEXP_SUBSTR(REGEXP_SUBSTR("a"."條碼", '[^_]+', 1, 1), '[^-]+', 1, 1) AS "製令單號", "a"."條碼", -1 AS "數量" FROM "fil0044" AS "a" WHERE "a"."單據類別" = 'B42' AND "a"."來源" = 'O' GROUP BY REGEXP_SUBSTR(REGEXP_SUBSTR("a"."條碼", '[^_]+', 1, 1), '[^-]+', 1, 1), "a"."條碼") SELECT "a"."製令單號", "a"."條碼", SUM("a"."數量") AS "庫存數" FROM "tmp1" AS "a" GROUP BY "a"."製令單號", "a"."條碼";

-- Home #1990 ViewFIL404K8.成捲製令庫存
CREATE OR REPLACE VIEW "viewfil404k8" AS WITH "tmp1" AS (SELECT REGEXP_SUBSTR(REGEXP_SUBSTR("a"."文字一", '[^_]+', 1, 1), '[^-]+', 1, 1) AS "製令單號", "a"."文字一" AS "條碼", 1 AS "數量" FROM "fil00401" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單別" = "b"."單別" AND "a"."單號" = "b"."單號" INNER JOIN "fil0040" AS "c" ON "a"."單別" = "c"."單據類別" AND "a"."單號" = "c"."單據編號" AND "a"."序號" = "c"."單據序號" WHERE "a"."單別" = 'C41' AND "b"."製程代碼" = 'C31I' UNION ALL SELECT REGEXP_SUBSTR(REGEXP_SUBSTR("a"."條碼", '[^_]+', 1, 1), '[^-]+', 1, 1) AS "製令單號", "a"."條碼", -1 AS "數量" FROM "fil0044" AS "a" WHERE "a"."單據類別" = 'B42' AND "a"."來源" = 'O' GROUP BY REGEXP_SUBSTR(REGEXP_SUBSTR("a"."條碼", '[^_]+', 1, 1), '[^-]+', 1, 1), "a"."條碼") SELECT "a"."製令單號", SUM("a"."數量") AS "庫存數" FROM "tmp1" AS "a" GROUP BY "a"."製令單號";

-- Home #1991 ViewFIL404Z1.製程機台日報筆數
CREATE OR REPLACE VIEW "viewfil404z1" AS (SELECT "a"."製程代碼", "a"."機台代碼", "b"."單據日期" AS "作業日期", "b"."歸屬類別" AS "製令單別", "b"."歸屬編號" AS "製令單號", COUNT(*) AS "筆數" FROM "fil0031" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單別" = "b"."單據類別" AND "a"."單號" = "b"."單據編號" WHERE "a"."單別" = 'C41' AND "b"."歸屬編號" <> ' ' GROUP BY "a"."製程代碼", "a"."機台代碼", "b"."單據日期", "b"."歸屬類別", "b"."歸屬編號");

-- Home #1994 ViewFIL404Z4.機台材料領用合計
CREATE OR REPLACE VIEW "viewfil404z4" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "領用數量", SUM("a"."贈品數量") AS "回庫數量", SUM("a"."毛重") AS "報廢數量" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'C' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #1997 ViewFIL404Z8.機台材料報廢合計
CREATE OR REPLACE VIEW "viewfil404z8" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "報廢數量" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'D' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #1999 ViewFIL404ZA.印刷油墨領用合計
CREATE OR REPLACE VIEW "viewfil404za" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "領用數量", SUM("a"."贈品數量") AS "回庫數量" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'E' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #2000 ViewFIL404ZB.印刷批號領用耗用
CREATE OR REPLACE VIEW "viewfil404zb" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "b"."批號", SUM(CASE WHEN "a"."異動類別" = 'C' THEN "a"."異動數量" ELSE 0 END) AS "領用數量", SUM(CASE WHEN "a"."異動類別" = 'A' THEN "a"."異動數量" ELSE 0 END) AS "耗用數量" /* 印刷米數 */ FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" BETWEEN 'A' AND 'C' AND "a"."異動類別" <> 'B' GROUP BY "a"."單據類別", "a"."單據編號", "b"."批號");

-- Home #2001 ViewFIL404ZC.日報製令生產日期
CREATE OR REPLACE VIEW "viewfil404zc" AS (SELECT "a"."單據類別" AS "單別", "a"."歸屬類別", "a"."歸屬編號", MAX("b"."交貨日期") AS "生產日期" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31D' GROUP BY "a"."單據類別", "a"."歸屬類別", "a"."歸屬編號");

-- Home #2002 ViewFIL404ZD.裁切製造日期
CREATE OR REPLACE VIEW "viewfil404zd" AS (SELECT "a"."歸屬類別" AS "製令單別", "a"."歸屬編號" AS "製令單號", MAX("a"."製造日期") AS "製造日期" FROM (SELECT "a"."歸屬類別", "a"."歸屬編號", MAX("b"."交貨日期") AS "製造日期" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31D' AND "b"."交貨日期" <> ' ' GROUP BY "a"."歸屬類別", "a"."歸屬編號" UNION ALL SELECT "a"."歸屬類別", "a"."歸屬編號", MAX("a"."匯率日期") AS "製造日期" FROM "fil0030" AS "a" WHERE "a"."單據類別" = 'E22' AND "a"."匯率日期" <> ' ' GROUP BY "a"."歸屬類別", "a"."歸屬編號") AS "a" GROUP BY "a"."歸屬類別", "a"."歸屬編號");

-- Home #2003 ViewFIL404ZE.製令最後製造日
CREATE OR REPLACE VIEW "viewfil404ze" AS (SELECT "a"."歸屬類別" AS "製令單別", "a"."歸屬編號" AS "製令單號", MAX("a"."製造日期") AS "製造日期" FROM (SELECT "a"."歸屬類別", "a"."歸屬編號", "b"."交貨日期" AS "製造日期" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31E' AND "b"."交貨日期" <> ' ' UNION ALL SELECT 'C11' AS "歸屬類別", "a"."廠客品號" AS "歸屬編號", "a"."預交日" AS "製造日期" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'E32' AND "a"."預交日" <> ' ' UNION ALL SELECT 'C11' AS "歸屬類別", "a"."廠客品號" AS "歸屬編號", "a"."預交日" AS "製造日期" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'E37' AND "a"."預交日" <> ' ') AS "a" GROUP BY "a"."歸屬類別", "a"."歸屬編號");

-- Home #2004 ViewFIL404ZE_A.製令箱最後製日
CREATE OR REPLACE VIEW "viewfil404ze_a" AS (SELECT "a"."歸屬類別" AS "製令單別", "a"."歸屬編號" AS "製令單號", "a"."箱號", MAX("a"."製造日期") AS "製造日期" FROM (SELECT "a"."歸屬類別", "a"."歸屬編號", "m"."異動數量" AS "箱號", "b"."交貨日期" AS "製造日期" FROM "fil0040" AS "m" INNER JOIN "fil0030" AS "a" ON "a"."單據類別" = "m"."單據類別" AND "a"."單據編號" = "m"."單據編號" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31E' AND "b"."交貨日期" <> ' ' UNION ALL SELECT 'C11' AS "歸屬類別", "a"."廠客品號" AS "歸屬編號", "a"."異動數量" AS "箱號", "a"."預交日" AS "製造日期" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'E32' AND "a"."預交日" <> ' ' UNION ALL SELECT 'C11' AS "歸屬類別", "a"."廠客品號" AS "歸屬編號", "a"."異動數量" AS "箱號", "a"."預交日" AS "製造日期" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'E37' AND "a"."預交日" <> ' ') AS "a" GROUP BY "a"."歸屬類別", "a"."歸屬編號", "a"."箱號");

-- Home #2005 ViewFIL404ZF.機台材料別彙總
CREATE OR REPLACE VIEW "viewfil404zf" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."產品編號" AS "材料編號", SUM("a"."異動數量") AS "領用數量", SUM("a"."贈品數量") AS "回庫數量", SUM("a"."毛重") AS "報廢數量" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'C' GROUP BY "a"."單據類別", "a"."單據編號", "a"."產品編號");

-- Home #2006 ViewFIL404ZF_A.機台主檔別彙總
CREATE OR REPLACE VIEW "viewfil404zf_a" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."qrno" AS "主檔別", SUM("a"."異動數量") AS "領用數量", SUM("a"."退庫數量") AS "回庫數量", SUM("a"."毛重") AS "報廢數量", SUM("a"."燙金費") AS "合理剔除數" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'C' AND "a"."qrno" > 0 GROUP BY "a"."單據類別", "a"."單據編號", "a"."qrno");

-- Home #2007 ViewFIL404ZG.前製程半成品退庫
CREATE OR REPLACE VIEW "viewfil404zg" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."文數字1" AS "半成品編號", "a"."廠客品號" AS "製程編號", "a"."前置單號" AS "製令單號", "a"."單位代碼" AS "加工別", "a"."前置單別" AS "製程代碼", "z2"."名稱" AS "製程名稱", "a"."預交日" AS "回庫日期", "a"."贈品數量" AS "回庫數量", "a"."數值2" AS "接頭數", "a"."備註說明", "b"."標籤列印次數", "b"."標籤列印日期一", "b"."標籤列印時間一", "a"."合併編號" AS "退庫條碼", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" LEFT JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" LEFT JOIN "viewfil310n" AS "z2" ON "a"."前置單別" = "z2"."代碼" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'G');

-- Home #2008 ViewFIL404ZH前製半成品退庫合計
CREATE OR REPLACE VIEW "viewfil404zh" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."贈品數量") AS "回庫數量" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'G' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #2011 ViewFIL404ZK,製令產量明細
CREATE OR REPLACE VIEW "viewfil404zk" AS (SELECT CAST(CASE WHEN "b"."製程代碼" = 'C31A' THEN '印刷' WHEN "b"."製程代碼" = 'C32D' THEN '上臘' WHEN "b"."製程代碼" = 'C31B' THEN '淋膜' ELSE '積層' END AS TEXT) AS "製程", "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "c"."歸屬類別" AS "製令單別", "c"."歸屬編號" AS "製令單號", SUM("a"."異動單價" - "a"."夾鏈費") AS "入庫米數" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND ("b"."製程代碼" BETWEEN 'C31A' AND 'C31D' OR "b"."製程代碼" = 'C32D') GROUP BY CAST(CASE WHEN "b"."製程代碼" = 'C31A' THEN '印刷' WHEN "b"."製程代碼" = 'C32D' THEN '上臘' WHEN "b"."製程代碼" = 'C31B' THEN '淋膜' ELSE '積層' END AS TEXT), "a"."單據類別", "a"."單據編號", "c"."歸屬類別", "c"."歸屬編號" UNION ALL SELECT CAST('裁切' AS TEXT) AS "製程", "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "c"."歸屬類別" AS "製令單別", "c"."歸屬編號" AS "製令單號", SUM(CASE WHEN "a"."材積" + COALESCE("d"."包裝數量", 0) < "a"."異動單價" - "a"."qrno" THEN 0 ELSE "a"."材積" + COALESCE("d"."包裝數量", 0) - "a"."異動單價" - "a"."qrno" END) AS "入庫米數" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" LEFT JOIN "fil0041" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" AND "a"."單據序號" = "d"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31D' GROUP BY CAST('裁切' AS TEXT), "a"."單據類別", "a"."單據編號", "c"."歸屬類別", "c"."歸屬編號" UNION ALL /* 製袋/氣閥/鐵條/成捲 */ SELECT CAST(CASE WHEN "b"."製程代碼" = 'C31E' THEN '製袋' WHEN "b"."製程代碼" = 'C31F' THEN '氣閥' WHEN "b"."製程代碼" = 'C31G' THEN '鐵條' ELSE '成捲' END AS TEXT) AS "製程", "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "d"."歸屬類別" AS "製令單別", "d"."歸屬編號" AS "製令單號", SUM(CASE WHEN "b"."製程代碼" = 'C31E' THEN CASE WHEN "c"."數值14" = 0 THEN "a"."贈品數量" ELSE "c"."數值14" END WHEN "b"."製程代碼" = 'C31F' THEN "a"."贈品數量" WHEN "b"."製程代碼" = 'C31G' THEN "a"."贈品數量" WHEN "b"."製程代碼" = 'C31I' THEN COALESCE("c"."包裝數量", 0) END) AS "繳庫總袋數" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND ("b"."製程代碼" BETWEEN 'C31E' AND 'C31G' OR "b"."製程代碼" = 'C31I') GROUP BY CAST(CASE WHEN "b"."製程代碼" = 'C31E' THEN '製袋' WHEN "b"."製程代碼" = 'C31F' THEN '氣閥' WHEN "b"."製程代碼" = 'C31G' THEN '鐵條' ELSE '成捲' END AS TEXT), "a"."單據類別", "a"."單據編號", "d"."歸屬類別", "d"."歸屬編號");

-- Home #2012 ViewFIL404ZL,製令產量彙總
CREATE OR REPLACE VIEW "viewfil404zl" AS (SELECT CAST(CASE WHEN "b"."製程代碼" = 'C31A' THEN '1.印刷' WHEN "b"."製程代碼" = 'C32D' THEN '2.上臘' WHEN "b"."製程代碼" = 'C31B' THEN '3.淋膜' ELSE '4.積層' END AS TEXT) AS "製程", "c"."歸屬類別" AS "製令單別", "c"."歸屬編號" AS "製令單號", SUM("a"."異動單價" - "a"."夾鏈費") AS "入庫米數" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND ("b"."製程代碼" BETWEEN 'C31A' AND 'C31D' OR "b"."製程代碼" = 'C32D') GROUP BY CAST(CASE WHEN "b"."製程代碼" = 'C31A' THEN '1.印刷' WHEN "b"."製程代碼" = 'C32D' THEN '2.上臘' WHEN "b"."製程代碼" = 'C31B' THEN '3.淋膜' ELSE '4.積層' END AS TEXT), "c"."歸屬類別", "c"."歸屬編號" UNION ALL SELECT CAST('5.裁切' AS TEXT) AS "製程", "c"."歸屬類別" AS "製令單別", "c"."歸屬編號" AS "製令單號", SUM(CASE WHEN "a"."材積" + COALESCE("d"."包裝數量", 0) < "a"."異動單價" - "a"."qrno" THEN 0 ELSE "a"."材積" + COALESCE("d"."包裝數量", 0) - "a"."異動單價" - "a"."qrno" END) AS "入庫米數" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" LEFT JOIN "fil0041" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" AND "a"."單據序號" = "d"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31D' GROUP BY CAST('裁切' AS TEXT), "c"."歸屬類別", "c"."歸屬編號" UNION ALL /* 製袋/氣閥/鐵條/成捲 */ SELECT CAST(CASE WHEN "b"."製程代碼" = 'C31E' THEN '6.製袋' WHEN "b"."製程代碼" = 'C31F' THEN '7.氣閥' WHEN "b"."製程代碼" = 'C31G' THEN '8.鐵條' ELSE '9.成捲' END AS TEXT) AS "製程", "d"."歸屬類別" AS "製令單別", "d"."歸屬編號" AS "製令單號", SUM(CASE WHEN "b"."製程代碼" = 'C31E' THEN CASE WHEN "c"."數值14" = 0 THEN "a"."贈品數量" ELSE "c"."數值14" END WHEN "b"."製程代碼" = 'C31F' THEN "a"."贈品數量" WHEN "b"."製程代碼" = 'C31G' THEN "a"."贈品數量" WHEN "b"."製程代碼" = 'C31I' THEN COALESCE("c"."包裝數量", 0) END) AS "繳庫總袋數" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND ("b"."製程代碼" BETWEEN 'C31E' AND 'C31G' OR "b"."製程代碼" = 'C31I') GROUP BY CAST(CASE WHEN "b"."製程代碼" = 'C31E' THEN '6.製袋' WHEN "b"."製程代碼" = 'C31F' THEN '7.氣閥' WHEN "b"."製程代碼" = 'C31G' THEN '8.鐵條' ELSE '9.成捲' END AS TEXT), "d"."歸屬類別", "d"."歸屬編號");

-- Home #2014 ViewFIL404ZN,製令製程備註
CREATE OR REPLACE VIEW "viewfil404zn" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", 'C11' AS "製令單別", CASE WHEN "b"."製程代碼" = 'C31H' THEN "a"."前置單號" WHEN "b"."製程代碼" = 'C31K' THEN "a"."前置單號" ELSE "d"."歸屬編號" END AS "製令單號", "e"."產品編號" AS "產品編號", CASE WHEN "b"."製程代碼" = 'C31A' THEN '印刷' WHEN "b"."製程代碼" = 'C31B' THEN '淋膜' WHEN "b"."製程代碼" = 'C31C' THEN '積層' WHEN "b"."製程代碼" = 'C31D' THEN '裁切' WHEN "b"."製程代碼" = 'C31E' THEN '製袋' WHEN "b"."製程代碼" = 'C31F' THEN '氣閥' WHEN "b"."製程代碼" = 'C31G' THEN '鐵條' WHEN "b"."製程代碼" = 'C31H' THEN '印刷檢品' WHEN "b"."製程代碼" = 'C31I' THEN '成捲' WHEN "b"."製程代碼" = 'C31K' THEN '裁切檢品' WHEN "b"."製程代碼" = 'C32D' THEN '上蠟' ELSE ' ' END AS "製程", "a"."產品編號" AS "製程編號", CASE WHEN ("b"."製程代碼" BETWEEN 'C31A' AND 'C31D') OR "b"."製程代碼" = 'C32D' THEN CASE WHEN "b"."交貨日期_次批" = 'A' THEN 'A材' WHEN "b"."交貨日期_次批" = 'B' THEN 'B材' WHEN "b"."交貨日期_次批" = 'C' THEN '底邊' WHEN "b"."交貨日期_次批" = 'D' THEN 'A側' WHEN "b"."交貨日期_次批" = 'E' THEN 'B側' ELSE ' ' END ELSE ' ' END AS "加工別", CASE WHEN ("b"."製程代碼" BETWEEN 'C31E' AND 'C32I') THEN "a"."異動數量" ELSE 0 END AS "箱號", CASE WHEN "b"."製程代碼" = 'C31H' THEN "c"."文字1" WHEN "b"."製程代碼" = 'C31K' THEN "c"."文字1" ELSE "a"."備註說明" END AS "備註說明" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" INNER JOIN "fil0032" AS "e" ON "e"."製令單別" = 'C11' AND CASE WHEN "b"."製程代碼" = 'C31H' THEN "a"."前置單號" WHEN "b"."製程代碼" = 'C31K' THEN "a"."前置單號" ELSE "d"."歸屬編號" END = "e"."製令單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND CASE WHEN "b"."製程代碼" = 'C31H' THEN "c"."文字1" WHEN "b"."製程代碼" = 'C31K' THEN "c"."文字1" ELSE "a"."備註說明" END <> ' ' AND ("b"."製程代碼" BETWEEN 'C31A' AND 'C31I') OR "b"."製程代碼" = 'C32D');

-- Home #2017 ViewFil404ZQ.製令日報入庫數
CREATE OR REPLACE VIEW "viewfil404zq" AS (SELECT "a"."單別", "a"."單號", "a"."入庫數" FROM (SELECT "a"."單別" /* 印刷(C31A) */, "a"."單號", "a"."plc抓取米數" - "a"."線內不良剔除數" AS "入庫數" FROM "viewfil404aa" AS "a" UNION SELECT "a"."單別" /* 上臘(C32D) */, "a"."單號", "a"."plc抓取米數" - "a"."線內不良剔除數" AS "入庫數" FROM "viewfil404a5a" AS "a" UNION SELECT "a"."單別" /* 淋膜(C31B) */, "a"."單號", "a"."plc抓取米數" - "a"."線內不良剔除數" AS "入庫數" FROM "viewfil404ba" AS "a" UNION SELECT "a"."單別" /* 積層(C31C) */, "a"."單號", "a"."plc抓取米數" - "a"."線內不良剔除數" AS "入庫數" FROM "viewfil404ca" AS "a" UNION SELECT "a"."單別" /* 裁切(C31D) */, "a"."單號", "a"."plc抓取米數" + "上次尾數" - "a"."故障米數" - "a"."客戶要求數" AS "入庫數" FROM "viewfil404da" AS "a" UNION SELECT "a"."單別" /* 印刷檢品(C31H) */, "a"."單號", "a"."plc抓取米數" - "a"."線內不良剔除數" AS "入庫數" FROM "viewfil2066" AS "a" UNION SELECT "a"."單別" /* 裁切檢品(C31K) */, "a"."單號", "a"."plc抓取米數" - "a"."線內不良剔除數" AS "入庫數" FROM "viewfil2068" AS "a" UNION SELECT "a"."單別" /* 製袋(C31E) */, "a"."單號", "a"."繳庫總袋數" AS "入庫數" FROM "viewfil404ea" AS "a" UNION SELECT "a"."單別" /* 氣閥(C31F) */, "a"."單號", "a"."繳庫總袋數" AS "入庫數" FROM "viewfil404fa" AS "a" UNION SELECT "a"."單別" /* 鐵條(C31G) */, "a"."單號", "a"."繳庫總袋數" AS "入庫數" FROM "viewfil404ga" AS "a" UNION SELECT "a"."單別" /* 成捲(C31I) */, "a"."單號", "a"."全部捲數" AS "入庫數" FROM "viewfil404k2" AS "a") AS "a" INNER JOIN "fil0030" AS "b" ON "b"."單據類別" = "a"."單別" AND "b"."單據編號" = "a"."單號" WHERE "b"."單據日期" > '2025');

-- Home #2018 ViewFil404ZR.成品總標籤明細
CREATE OR REPLACE VIEW "viewfil404zr" AS WITH "tmp" AS (SELECT CONCAT("a"."單別", '_', "a"."單號") AS "總標籤", "c"."異動數量" AS "箱號", "a"."文字一" AS "產品標籤", "d"."歸屬編號" AS "製令單號", "a"."數字一" AS "數量", "a"."單別", "a"."單號", "b"."製程代碼", "e"."名稱" FROM "fil00401" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單別" = "b"."單別" AND "a"."單號" = "b"."單號" INNER JOIN "fil0040" AS "c" ON "a"."單別" = "c"."單據類別" AND "a"."單號" = "c"."單據編號" AND "a"."序號" = "c"."單據序號" INNER JOIN "fil0030" AS "d" ON "d"."單據類別" = "a"."單別" AND "d"."單據編號" = "a"."單號" INNER JOIN "viewfil310n" AS "e" ON "e"."代碼類別" = '製程代碼' AND "e"."代碼" = "b"."製程代碼" WHERE "a"."單別" = 'C41' AND "b"."製程代碼" = 'C31I' UNION ALL SELECT CONCAT("a"."單據類別", '_', "a"."單據編號") AS "總標籤", "a"."異動數量" AS "箱號", CONCAT("a"."廠客品號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))) AS "產品標籤", "a"."廠客品號" AS "製令單號", "a"."贈品數量" AS "數量", "a"."單據類別", "a"."單據編號", "a"."單據類別", "e"."名稱" FROM "fil0040" AS "a" INNER JOIN "viewfil310n" AS "e" ON "e"."代碼類別" = '單據類別' AND "e"."代碼" = "a"."單據類別" WHERE "a"."單據類別" = 'E37' UNION ALL SELECT CONCAT("a"."單據類別", '_', "a"."單據編號", '-', TRIM(TO_CHAR("qrno", '009'))) AS "總標籤", "a"."異動數量" AS "箱號", CONCAT("d"."歸屬編號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))) AS "產品標籤", "d"."歸屬編號" AS "製令單號", "a"."贈品數量" AS "數量", "a"."單據類別", "a"."單據編號", "c"."製程代碼", "e"."名稱" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "d" ON "d"."單據類別" = "a"."單據類別" AND "d"."單據編號" = "a"."單據編號" INNER JOIN "viewfil310n" AS "e" ON "e"."代碼類別" = '製程代碼' AND "e"."代碼" = "c"."製程代碼" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" = 'C31E' AND "qrno" > 0) SELECT CASE WHEN COALESCE("b"."最後總標籤", ' ') = ' ' THEN "a"."總標籤" ELSE "b"."最後總標籤" END AS "總標籤", "a"."箱號", "a"."產品標籤", "a"."製令單號", "a"."數量", "a"."單別", "a"."單號", "a"."製程代碼", "a"."名稱" FROM "tmp" AS "a" LEFT JOIN "fil0044b" AS "b" ON "b"."產品標籤" = "a"."產品標籤";

-- Home #2019 ViewFil404ZS.成品總標籤
CREATE OR REPLACE VIEW "viewfil404zs" AS (SELECT DISTINCT "a"."總標籤", "a"."製令單號", "a"."名稱" AS "製程名稱" FROM "viewfil404zr" AS "a");

-- Home #2021 ViewFIL4051.原物料請領明細
CREATE OR REPLACE VIEW "viewfil4051" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."產品編號" AS "料號", COALESCE("c"."品名", ' ') AS "品名", COALESCE("c"."規格", ' ') AS "規格", "a"."異動數量" AS "請領數量", "a"."數值4" AS "庫存異動數", "a"."單位代碼", COALESCE("d"."名稱", ' ') AS "單位名稱", "a"."備註說明", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" LEFT JOIN "fil0012" AS "c" ON "a"."產品編號" = "c"."產品編號" LEFT JOIN "viewfil3103" AS "d" ON "a"."單位代碼" = "d"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."單據類別" = 'C4L');

-- Home #2022 ViewFIL405A.原物料請領合計
CREATE OR REPLACE VIEW "viewfil405a" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "請領數量" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'C4L' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #2023 ViewFIL405B.原物料請領製令合計
CREATE OR REPLACE VIEW "viewfil405b" AS (SELECT "a"."單別" AS "單別", "a"."單號" AS "單號", "a"."文字一" AS "製令單別", "a"."文字二" AS "製令單號", "a"."文字三" AS "加工別", "a"."數字一" AS "色順數", "b"."產品編號" AS "料號", SUM("a"."數字四") AS "請領數量" FROM "fil00401" AS "a" INNER JOIN "fil0040" AS "b" ON "b"."單據類別" = "a"."單別" AND "b"."單據編號" = "a"."單號" AND "b"."單據序號" = "a"."序號" WHERE "a"."單別" = 'C4L' GROUP BY "a"."單別", "a"."單號", "a"."文字一", "a"."文字二", "a"."文字三", "a"."數字一", "b"."產品編號");

-- Home #2026 ViewFIL406A.原物料領料合計
CREATE OR REPLACE VIEW "viewfil406a" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "發料數量" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'C4M' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #2028 ViewFIL408C.請領單發料數
CREATE OR REPLACE VIEW "viewfil408c" AS (SELECT "a"."請領單別", "a"."請領單號", SUM("a"."請領數量") AS "請領數量", SUM("a"."發料數量") AS "發料數量" FROM (SELECT CASE WHEN "a"."單據類別" = 'C4L' THEN "a"."單據類別" ELSE "b"."歸屬類別" END AS "請領單別", CASE WHEN "a"."單據類別" = 'C4L' THEN "a"."單據編號" ELSE "b"."歸屬編號" END AS "請領單號", CASE WHEN "a"."單據類別" = 'C4L' THEN "a"."異動數量" ELSE 0 END AS "請領數量", CASE WHEN "a"."單據類別" = 'C4M' THEN "a"."異動數量" ELSE 0 END AS "發料數量" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" WHERE "a"."單據類別" BETWEEN 'C4L' AND 'C4M') AS "a" GROUP BY "a"."請領單別", "a"."請領單號");

-- Home #2035 ViewFIL4102.製袋巡檢次數
CREATE OR REPLACE VIEW "viewfil4102" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "c"."機台代碼" AS "作業區域", "a"."單據日期" AS "巡檢日期", "a"."歸屬編號" AS "製令單號", "c"."箱號", "c"."檢驗時間", ROW_NUMBER() OVER (PARTITION BY "c"."機台代碼", "a"."歸屬編號", "a"."單據日期" ORDER BY "c"."檢驗時間" ASC) AS "次數" FROM "fil0030" AS "a" INNER JOIN "fil003g" AS "c" ON "a"."流水編號" = "c"."主檔流水編號" WHERE "a"."單據類別" = 'C47');

-- Home #2037 ViewFIL4112.氣閥巡檢次數
CREATE OR REPLACE VIEW "viewfil4112" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "c"."機台代碼" AS "作業區域", "a"."單據日期" AS "巡檢日期", "a"."歸屬編號" AS "製令單號", "c"."箱號", "c"."檢驗時間", ROW_NUMBER() OVER (PARTITION BY "c"."機台代碼", "a"."歸屬編號", "a"."單據日期" ORDER BY "c"."檢驗時間" ASC) AS "次數" FROM "fil0030" AS "a" INNER JOIN "fil003h" AS "c" ON "a"."流水編號" = "c"."主檔流水編號" WHERE "a"."單據類別" = 'C45');

-- Home #2039 ViewFIL4122.鐵條巡檢次數
CREATE OR REPLACE VIEW "viewfil4122" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "c"."機台代碼" AS "作業區域", "a"."單據日期" AS "巡檢日期", "a"."歸屬編號" AS "製令單號", "c"."箱號", "c"."檢驗時間", ROW_NUMBER() OVER (PARTITION BY "c"."機台代碼", "a"."歸屬編號", "a"."單據日期" ORDER BY "c"."檢驗時間" ASC) AS "次數" FROM "fil0030" AS "a" INNER JOIN "fil003h" AS "c" ON "a"."流水編號" = "c"."主檔流水編號" WHERE "a"."單據類別" = 'C46');

-- Home #2151 ViewFIL4A0A.請購單合計
CREATE OR REPLACE VIEW "viewfil4a0a" AS (SELECT "a"."單別", "a"."單號", "a"."數量", "a"."總價", "b"."稅率", ROUND(CAST("a"."總價" * "b"."稅率" AS DOUBLE PRECISION) / 100) AS "稅額", ROUND("a"."總價" * (1 + CAST("b"."稅率" AS DOUBLE PRECISION) / 100)) AS "含稅價" FROM (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "數量", SUM("a"."異動金額") AS "總價" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'D01' GROUP BY "a"."單據類別", "a"."單據編號") AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單別" = "b"."單據類別" AND "a"."單號" = "b"."單據編號");

-- Home #2155 ViewFIL4A1B.請購採購數
CREATE OR REPLACE VIEW "viewfil4a1b" AS (SELECT "a"."單別", "a"."單號", "a"."序號", "a"."廠客編號", "a"."料號", "a"."請購數量", COALESCE("b"."採購數量", 0) AS "採購數量", CASE WHEN COALESCE("b"."採購數量", 0) > COALESCE("a"."請購數量", 0) THEN 0 ELSE COALESCE("a"."請購數量", 0) - COALESCE("b"."採購數量", 0) END AS "未採購數", "a"."請購金額", COALESCE("b"."採購金額", 0) AS "採購金額", CASE WHEN (CASE WHEN COALESCE("b"."採購數量", 0) > COALESCE("a"."請購數量", 0) THEN 0 ELSE COALESCE("a"."請購數量", 0) - COALESCE("b"."採購數量", 0) END) = 0 OR "a"."結案" = 1 THEN 1 ELSE 0 END AS "結案" FROM (/* 請購單 */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."相關代碼1" AS "廠客編號", "a"."產品編號" AS "料號", SUM("a"."異動數量") AS "請購數量", SUM("a"."異動金額") AS "請購金額", MAX("a"."logical1") AS "結案" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'D01' GROUP BY "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."相關代碼1", "a"."產品編號") AS "a" LEFT JOIN (/* 採購 */ SELECT "b"."歸屬類別" AS "單別", "b"."歸屬編號" AS "單號", "a"."數值1" AS "序號", SUM("a"."異動數量") AS "採購數量", SUM("a"."異動金額") AS "採購金額" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" WHERE "a"."單據類別" = 'D11' AND "b"."歸屬編號" <> ' ' GROUP BY "b"."歸屬類別", "b"."歸屬編號", "a"."數值1") AS "b" ON "a"."單別" = "b"."單別" AND "a"."單號" = "b"."單號" AND "a"."序號" = "b"."序號");

-- Home #2156 ViewFIL4A1C.請購採購數by單號
CREATE OR REPLACE VIEW "viewfil4a1c" AS (SELECT COALESCE("a"."單別", "b"."單別") AS "單別", COALESCE("a"."單號", "b"."單號") AS "單號", COALESCE("a"."請購數量", 0) AS "請購數量", COALESCE("b"."採購數量", 0) AS "採購數量", COALESCE("a"."請購數量", 0) - COALESCE("b"."採購數量", 0) AS "未採購數", COALESCE("a"."請購金額", 0) AS "請購金額", COALESCE("b"."採購金額", 0) AS "採購金額" FROM (/* 請購 */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "請購數量", SUM("a"."異動金額") AS "請購金額" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'D01' GROUP BY "a"."單據類別", "a"."單據編號") AS "a" FULL OUTER JOIN (/* 採購 */ SELECT "b"."歸屬類別" AS "單別", "b"."歸屬編號" AS "單號", SUM("a"."異動數量") AS "採購數量", SUM("a"."異動金額") AS "採購金額" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" WHERE "a"."單據類別" = 'D11' AND "b"."歸屬編號" <> ' ' GROUP BY "b"."歸屬類別", "b"."歸屬編號") AS "b" ON "a"."單別" = "b"."單別" AND "a"."單號" = "b"."單號");

-- Home #2164 ViewFIL4A2A.進料單發票合計
CREATE OR REPLACE VIEW "viewfil4a2a" AS (SELECT "a"."單別", "a"."單號", "a"."數量", "a"."贈品", "a"."總價", "a"."重量", "b"."稅率", "a"."稅額" AS "稅額", "a"."總價" + "a"."稅額" AS "含稅價", "a"."原幣總價" FROM (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "數量", SUM("a"."贈品數量") AS "贈品", SUM("a"."異動金額") AS "總價", SUM("a"."異動稅額") AS "稅額", SUM("a"."毛重") AS "重量", SUM(COALESCE("b"."數值2", 0)) AS "原幣總價" FROM "fil0040" AS "a" LEFT JOIN "fil0041" AS "b" ON "b"."單別" = "a"."單據類別" AND "b"."單號" = "a"."單據編號" AND "b"."序號" = "a"."單據序號" WHERE "a"."單據類別" = 'D21' AND "a"."異動類別" = ' ' GROUP BY "a"."單據類別", "a"."單據編號") AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單別" = "b"."單據類別" AND "a"."單號" = "b"."單據編號");

-- Home #2166 ViewFIL4A2C.採購進料額
CREATE OR REPLACE VIEW "viewfil4a2c" AS (SELECT "a"."前置單別" AS "採購單別", "a"."前置單號" AS "採購單號", SUM("c"."數值2") AS "進料原幣總價", SUM("a"."異動金額") AS "進料台幣總價" FROM "fil0040" AS "a" /* 主檔 */ INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ LEFT JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'D21' AND "a"."異動類別" = ' ' GROUP BY "a"."前置單別", "a"."前置單號");

-- Home #2169 ViewFIL4A3A.進料檢驗單合計
CREATE OR REPLACE VIEW "viewfil4a3a" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "數量" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'D31' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #2172 ViewFIL4A4A.退料單合計
CREATE OR REPLACE VIEW "viewfil4a4a" AS (SELECT "a"."單別", "a"."單號", "a"."數量", "a"."贈品", "a"."總價", "b"."稅率", "a"."稅額", "a"."總價" + "a"."稅額" AS "含稅價" FROM (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "數量", SUM("a"."贈品數量") AS "贈品", SUM("a"."異動金額") AS "總價", SUM("a"."異動稅額") AS "稅額" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'D41' AND "a"."異動類別" = 'A' GROUP BY "a"."單據類別", "a"."單據編號") AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單別" = "b"."單據類別" AND "a"."單號" = "b"."單據編號");

-- Home #2179 ViewFIL4A4H.客供品合計
CREATE OR REPLACE VIEW "viewfil4a4h" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "數量", SUM("a"."數值4") AS "庫存異動數" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'D51' AND "a"."異動類別" = ' ' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #2182 ViewFIL4A4K.客供品退料合計
CREATE OR REPLACE VIEW "viewfil4a4k" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."數值4") AS "庫存異動數", SUM("a"."異動數量") AS "數量" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'D52' AND "a"."異動類別" = 'S' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #2183 ViewFIL4A4L.客供品料號
CREATE OR REPLACE VIEW "viewfil4a4l" AS (SELECT DISTINCT "a"."產品編號" AS "產品編號" FROM "fil0043" AS "m" INNER JOIN "fil0040" AS "a" ON "a"."單據類別" = "m"."單別" AND "a"."單據編號" = "m"."單號" AND "a"."單據序號" = "序號" WHERE "m"."單別" = 'D51' AND "a"."產品編號" <> ' ');

-- Home #2268 ViewFIL5001.PLC機台位置
CREATE OR REPLACE VIEW "viewfil5001" AS (SELECT DISTINCT "a"."機台代碼", "a"."位置" FROM "fil300b" AS "a");

-- Home #2187 ViewFILA010.採購進度表
CREATE OR REPLACE VIEW "viewfila010" AS (SELECT "a"."採購單號", "a"."單據日期", ' ' AS "父階", ' ' AS "父階單別", ' ' AS "父階單號", CONCAT(TRIM("a"."單據類別"), '.', "a"."單據編號") AS "子階", "a"."單據類別" AS "子階單別", "a"."單據編號" AS "子階單號" FROM "fil0030" AS "a" WHERE "a"."單據類別" = 'D11' /* 採購單 */ UNION SELECT "a"."採購單號", "a"."單據日期", CONCAT(TRIM("a"."歸屬類別"), '.', "a"."歸屬編號") AS "父階", "a"."歸屬類別" AS "父階單別", "a"."歸屬編號" AS "父階單號", CONCAT(TRIM("a"."單據類別"), '.', "a"."單據編號") AS "子階", "a"."單據類別" AS "子階單別", "a"."單據編號" AS "子階單號" FROM "fil0030" AS "a" WHERE "a"."單據類別" = 'D21' /* 進料單 */ UNION SELECT "a"."採購單號", "a"."單據日期", CONCAT(TRIM("a"."歸屬類別"), '.', "a"."歸屬編號") AS "父階", "a"."歸屬類別" AS "父階單別", "a"."歸屬編號" AS "父階單號", CONCAT(TRIM("a"."單據類別"), '.', "a"."單據編號") AS "子階", "a"."單據類別" AS "子階單別", "a"."單據編號" AS "子階單號" FROM "fil0030" AS "a" WHERE "a"."單據類別" = 'D41' /* 退料單 */ UNION SELECT "a"."採購單號", "a"."單據日期", CONCAT(TRIM("a"."歸屬類別"), '.', "a"."歸屬編號") AS "父階", "a"."歸屬類別" AS "父階單別", "a"."歸屬編號" AS "父階單號", CONCAT(TRIM("a"."單據類別"), '.', "a"."單據編號") AS "子階", "a"."單據類別" AS "子階單別", "a"."單據編號" AS "子階單號" FROM "fil0030" AS "a" WHERE "a"."單據類別" = 'D31') /* 檢驗單 */;

-- Home #2192 ViewFILE01A.原物料入庫合計
CREATE OR REPLACE VIEW "viewfile01a" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "庫存數量", SUM("a"."異動單價") AS "包裝數量" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'E11' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #2193 ViewFILE01B.廠商批號對照
CREATE OR REPLACE VIEW "viewfile01b" AS (SELECT DISTINCT "c"."批號", "a"."廠客品號" AS "廠商批號" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'E11');

-- Home #2199 ViewFILE027.裁切材料合計
CREATE OR REPLACE VIEW "viewfile027" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "調整數量" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'E13' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #2200 ViewFILE02A.調整單合計
CREATE OR REPLACE VIEW "viewfile02a" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "調整數量" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'E12' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #2203 ViewFILE02D.裁切調整單合計
CREATE OR REPLACE VIEW "viewfile02d" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."異動類別", SUM("a"."異動數量") AS "調整數量", SUM("a"."數值1") AS "報廢數量" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'E22' GROUP BY "a"."單據類別", "a"."單據編號", "a"."異動類別");

-- Home #2206 ViewFILE02J.裁切入庫單合計
CREATE OR REPLACE VIEW "viewfile02j" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."異動類別", SUM("a"."異動數量") AS "調整數量" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'E23' GROUP BY "a"."單據類別", "a"."單據編號", "a"."異動類別");

-- Home #2220 ViewFILE02L.半成品入庫明細
CREATE OR REPLACE VIEW "viewfile02l" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."前置單別" AS "製令單別", "a"."前置單號" AS "製令單號", "a"."產品編號" AS "本製程編號", "a"."廠客品號" AS "製程編號", "c"."小單位" AS "加工別", "c"."批號" AS "批號", "a"."異動日期" AS "盤點日期", "a"."預交日" AS "製造日期", "a"."其它日期" AS "有效日期", "a"."異動單價" AS "庫存數量", "a"."接頭數", "a"."相關代碼1" AS "規格", "a"."相關代碼2" AS "廠商批號", "a"."相關代碼3" AS "廠商規格", "a"."備註說明", "c"."標籤列印次數", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."單據類別" = 'E24' AND "a"."異動類別" = 'A');

-- Home #2221 ViewFILE02M.半成品入庫合計
CREATE OR REPLACE VIEW "viewfile02m" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "庫存數量", SUM("a"."異動單價") AS "包裝數量" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'E24' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #2076 ViewFILE030.箱號異動主檔.E32
CREATE OR REPLACE VIEW "viewfile030" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."公司代碼", COALESCE("e"."全名", ' ') AS "公司名稱", "a"."單據日期", "a"."簽核系統", "a"."備註", "a"."業務員" AS "倉管員", COALESCE("d"."員工姓名", ' ') AS "倉管員姓名", "a"."流水編號", "a"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "a"."填表日", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日", COALESCE("f"."簽核狀態", '0') AS "簽核狀態" FROM "fil0030" AS "a" /*
	INNER JOIN FIL0031 B ON A.單據類別 = B.單別 AND A.單據編號 = B.單號
	*/ LEFT JOIN "fil0010" AS "d" ON "a"."業務員" = "d"."員工編號" LEFT JOIN "viewfil0011" AS "e" ON "a"."公司代碼" = "e"."代碼" LEFT JOIN "viewfil0030" AS "f" ON "a"."簽核系統" = "f"."簽核系統" AND "a"."單據編號" = "f"."單號" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" WHERE "a"."單據類別" = 'E32');

-- Home #2078 ViewFILE032.箱號異動合計
CREATE OR REPLACE VIEW "viewfile032" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", COUNT("a"."異動數量") AS "庫存數量", SUM("a"."贈品數量") AS "包裝數量" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'E32' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #2079 ViewFILE032A.箱號異動平均重量
CREATE OR REPLACE VIEW "viewfile032a" AS (SELECT CAST('C11' AS TEXT) AS "製令單別", "a"."廠客品號" AS "製令單號", "a"."異動數量" AS "箱號", CASE WHEN SUM("a"."贈品數量") = 0 THEN 0 ELSE CAST(SUM("a"."毛重") AS DOUBLE PRECISION) / SUM("a"."贈品數量") END AS "平均袋重", MAX(COALESCE("b"."單價下限率", 0)) AS "紙箱重量", MAX(CASE WHEN "a"."贈品數量" = 0 THEN 0 ELSE CAST(COALESCE("c"."數值2", 0) AS DOUBLE PRECISION) / "a"."贈品數量" END) AS "氣閥重量", MAX(CASE WHEN "a"."贈品數量" = 0 THEN 0 ELSE CAST(COALESCE("c"."數值3", 0) AS DOUBLE PRECISION) / "a"."贈品數量" END) AS "鐵條重量", MAX(COALESCE("c"."數值1", 0)) AS "每袋幾束" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN "fil0012" AS "b" ON "a"."前置單號" = "b"."產品編號" WHERE "a"."單據類別" = 'E32' GROUP BY CAST('C11' AS TEXT), "a"."廠客品號", "a"."異動數量");

-- Home #2082 ViewFILE035.成品重工合計
CREATE OR REPLACE VIEW "viewfile035" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."異動類別", SUM("a"."贈品數量") AS "包裝數量", SUM("a"."毛重" + "c"."數值2" + "c"."數值3" + "c"."數值8") AS "重量", COUNT("單據序號") AS "箱數", SUM("c"."數值2") AS "氣閥重量", SUM("c"."數值3") AS "鐵條重量", SUM("a"."毛重") AS "製袋重量", SUM("c"."數值8") AS "紙箱重量" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'E33' GROUP BY "a"."單據類別", "a"."單據編號", "a"."異動類別");

-- Home #2083 ViewFILE035A.重工平均重量
CREATE OR REPLACE VIEW "viewfile035a" AS (SELECT CAST('C11' AS TEXT) AS "製令類別", "a"."廠客品號" AS "製令單號", "a"."異動數量" AS "箱號", CAST(SUM("a"."毛重") AS DOUBLE PRECISION) / SUM("a"."贈品數量" * CASE WHEN "a"."異動類別" = 'A' THEN -1 ELSE 1 END) AS "平均袋重", SUM("a"."贈品數量" * CASE WHEN "a"."異動類別" = 'A' THEN -1 ELSE 1 END) AS "數量", SUM("a"."毛重" * CASE WHEN "a"."異動類別" = 'A' THEN -1 ELSE 1 END) AS "製袋重量", SUM("b"."數值2" * CASE WHEN "a"."異動類別" = 'A' THEN -1 ELSE 1 END) AS "氣閥重量", SUM("b"."數值3" * CASE WHEN "a"."異動類別" = 'A' THEN -1 ELSE 1 END) AS "鐵條重量", SUM("b"."數值8" * CASE WHEN "a"."異動類別" = 'A' THEN -1 ELSE 1 END) AS "紙箱重量" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" WHERE "a"."單據類別" = 'E33' AND "a"."贈品數量" <> 0 GROUP BY CAST('C11' AS TEXT), "a"."廠客品號", "a"."異動數量");

-- Home #2084 ViewFILE036.成品出廠主檔.E35
CREATE OR REPLACE VIEW "viewfile036" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."公司代碼", COALESCE("e"."全名", ' ') AS "公司名稱", "a"."單據日期", "a"."簽核系統", "a"."備註", "a"."業務員" AS "倉管員", COALESCE("d"."員工姓名", ' ') AS "倉管員姓名", "a"."流水編號", "a"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "a"."填表日", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "b"."製程代碼" AS "車號", "a"."最後更新日", COALESCE("f"."簽核狀態", '0') AS "簽核狀態", CASE WHEN COALESCE("dbms_lob".getlength("g"."圖檔"), 0) = 0 THEN 0 ELSE 1 END AS "廠商簽收" FROM "fil0030" AS "a" LEFT JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0010" AS "d" ON "a"."業務員" = "d"."員工編號" LEFT JOIN "viewfil0011" AS "e" ON "a"."公司代碼" = "e"."代碼" LEFT JOIN "viewfil0030" AS "f" ON "a"."簽核系統" = "f"."簽核系統" AND "a"."單據編號" = "f"."單號" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN "fil0037" AS "g" ON "a"."單據類別" = "g"."製令單別" AND "a"."單據編號" = "g"."製令單號" AND "g"."材料序號" = 0 WHERE "a"."單據類別" = 'E35');

-- Home #2086 ViewFILE038.成品出廠合計
CREATE OR REPLACE VIEW "viewfile038" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."數值1") AS "箱數", SUM("a"."贈品數量") AS "包裝數量" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'E35' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #2088 ViewFILE039A.成品品檢主檔客編
CREATE OR REPLACE VIEW "viewfile039a" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", STRING_AGG(CAST("a"."廠客編號" AS TEXT), ',' ORDER BY "a"."廠客編號") AS "客戶編號" FROM (SELECT DISTINCT "a"."單據類別", "a"."單據編號", "b"."廠客編號" FROM "fil0040" AS "a" LEFT JOIN "fil0030" AS "b" ON "b"."單據類別" = 'C11' AND "a"."廠客品號" = "b"."單據編號" WHERE "a"."單據類別" = 'E37') AS "a" GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #2090 ViewFILE03B.成品品檢合計(嘜頭)
CREATE OR REPLACE VIEW "viewfile03b" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", COUNT("a"."異動數量") AS "箱數", SUM("a"."贈品數量") AS "包裝數量", SUM("a"."毛重") AS "淨重", SUM("a"."毛重") + 15 AS "毛重" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'E37' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #2091 ViewFILE03C.成品調整平均重量
CREATE OR REPLACE VIEW "viewfile03c" AS (SELECT "a"."廠客品號" AS "製令單號", "a"."異動數量" AS "箱號", "a"."單據類別" AS "來源單別", CASE WHEN SUM("a"."贈品數量") = 0 THEN 0 ELSE CAST(SUM("a"."毛重") AS DOUBLE PRECISION) / SUM("a"."贈品數量") END AS "平均袋重" FROM "fil0040" AS "a" WHERE "a"."單據類別" BETWEEN 'E32' AND 'E33' GROUP BY "a"."廠客品號", "a"."異動數量", "a"."單據類別");

-- Home #2093 ViewFILE03E.成品批號庫存
CREATE OR REPLACE VIEW "viewfile03e" AS (SELECT "a"."批號", ROUND(COALESCE(CASE WHEN "b"."結存數量" < 0 THEN 0 ELSE "b"."結存數量" END, 0)) AS "結存數量", ROUND(COALESCE("c"."製袋平均重量" * COALESCE(CASE WHEN "b"."結存數量" < 0 THEN 0 ELSE "b"."結存數量" END, 0), 0), 2) AS "製袋重量", COALESCE("c"."生產日期", ' ') AS "生產日期", ROUND(COALESCE("d"."氣閥平均重量" * COALESCE(CASE WHEN "b"."結存數量" < 0 THEN 0 ELSE "b"."結存數量" END, 0), 0), 2) AS "氣閥重量", ROUND(COALESCE("e"."鐵條平均重量" * COALESCE(CASE WHEN "b"."結存數量" < 0 THEN 0 ELSE "b"."結存數量" END, 0), 0), 2) AS "鐵條重量", ROUND(COALESCE("f"."紙箱重量", 0), 2) AS "紙箱重量", CASE WHEN COALESCE("g"."筆數", 0) = 0 THEN 0 ELSE 1 END AS "箱號異動", CASE WHEN COALESCE("h"."筆數", 0) = 0 THEN 0 ELSE 1 END AS "重工", CASE WHEN COALESCE("i"."筆數", 0) = 0 THEN 0 ELSE 1 END AS "品檢", COALESCE("c"."製袋平均重量", 0) AS "製袋平均重量", COALESCE("d"."氣閥平均重量", 0) AS "氣閥平均重量", COALESCE("e"."鐵條平均重量", 0) AS "鐵條平均重量" FROM "viewfil404e4_t8" AS "a" LEFT JOIN (SELECT DISTINCT "a"."批號", FIRST_VALUE("a"."數量") OVER (PARTITION BY "a"."批號" ORDER BY "a"."最後更新日時" DESC) AS "結存數量" FROM "fil004l" AS "a") AS "b" ON "b"."批號" = "a"."批號" LEFT JOIN (SELECT DISTINCT "a"."批號", FIRST_VALUE("a"."異動日期") OVER (PARTITION BY "a"."批號" ORDER BY "a"."最後更新日時" ASC) AS "生產日期", FIRST_VALUE(CAST("a"."製袋重量" AS DOUBLE PRECISION) / "a"."數量") OVER (PARTITION BY "a"."批號" ORDER BY "a"."最後更新日時" DESC) AS "製袋平均重量" FROM "fil004l" AS "a" WHERE "a"."製袋重量" > 0 AND "a"."數量" > 0) AS "c" ON "c"."批號" = "a"."批號" LEFT JOIN (SELECT DISTINCT "a"."批號", FIRST_VALUE(CAST("a"."氣閥重量" AS DOUBLE PRECISION) / "a"."數量") OVER (PARTITION BY "a"."批號" ORDER BY "a"."最後更新日時" DESC) AS "氣閥平均重量" FROM "fil004l" AS "a" WHERE "a"."氣閥重量" > 0 AND "a"."數量" > 0) AS "d" ON "d"."批號" = "a"."批號" LEFT JOIN (SELECT DISTINCT "a"."批號", FIRST_VALUE(CAST("a"."鐵條重量" AS DOUBLE PRECISION) / "a"."數量") OVER (PARTITION BY "a"."批號" ORDER BY "a"."最後更新日時" DESC) AS "鐵條平均重量" FROM "fil004l" AS "a" WHERE "a"."鐵條重量" > 0 AND "a"."數量" > 0) AS "e" ON "e"."批號" = "a"."批號" LEFT JOIN (SELECT DISTINCT "a"."批號", FIRST_VALUE("a"."紙箱重量") OVER (PARTITION BY "a"."批號" ORDER BY "a"."最後更新日時" DESC) AS "紙箱重量" FROM "fil004l" AS "a" WHERE "a"."紙箱重量" > 0 AND "a"."數量" > 0) AS "f" ON "f"."批號" = "a"."批號" LEFT JOIN (SELECT DISTINCT "a"."批號", COUNT("a"."批號") AS "筆數" FROM "fil004l" AS "a" WHERE "a"."來源" = '異動' GROUP BY "a"."批號") AS "g" ON "g"."批號" = "a"."批號" LEFT JOIN (SELECT DISTINCT "a"."批號", COUNT("a"."批號") AS "筆數" FROM "fil004l" AS "a" WHERE "a"."來源" = '重工' GROUP BY "a"."批號") AS "h" ON "h"."批號" = "a"."批號" LEFT JOIN (SELECT DISTINCT "a"."批號", COUNT("a"."批號") AS "筆數" FROM "fil004l" AS "a" WHERE "a"."來源" = '品檢' GROUP BY "a"."批號") AS "i" ON "i"."批號" = "a"."批號");

-- Home #2094 ViewFILE03F.成品批號庫存彙總
CREATE OR REPLACE VIEW "viewfile03f" AS (SELECT REGEXP_SUBSTR("a"."批號", '[^-]+', 1, 1) AS "製令單號", SUM("a"."結存數量") AS "結存數量", SUM(CASE WHEN "a"."結存數量" = 0 THEN 0 ELSE "a"."製袋重量" + "a"."氣閥重量" + "a"."鐵條重量" + "紙箱重量" END) AS "結存重量", CASE WHEN SUM("a"."結存數量") = 0 THEN 0 ELSE CAST(SUM("a"."製袋重量") AS DOUBLE PRECISION) / SUM("a"."結存數量") END AS "平均製袋重量", CASE WHEN SUM("a"."結存數量") = 0 THEN 0 ELSE CAST(SUM("a"."氣閥重量") AS DOUBLE PRECISION) / SUM("a"."結存數量") END AS "平均氣閥重量", CASE WHEN SUM("a"."結存數量") = 0 THEN 0 ELSE CAST(SUM("a"."鐵條重量") AS DOUBLE PRECISION) / SUM("a"."結存數量") END AS "平均鐵條重量" FROM "viewfile03e" AS "a" GROUP BY REGEXP_SUBSTR("a"."批號", '[^-]+', 1, 1));

-- Home #2097 ViewFILE042.貨櫃製令合計
CREATE OR REPLACE VIEW "viewfile042" AS (SELECT "a"."單別", "a"."單號", "a"."製令單號", "a"."產品編號", "a"."箱數", "a"."數量", ROW_NUMBER() OVER (PARTITION BY "a"."單別", "a"."單號" ORDER BY "a"."製令單號") AS "製令序號" FROM (SELECT "b"."歸屬類別" AS "單別", "b"."歸屬編號" AS "單號", "a"."廠客品號" AS "製令單號", "a"."產品編號", COUNT("a"."異動數量") AS "箱數", SUM("a"."贈品數量") AS "數量" FROM "fil0040" AS "a" /* 貨櫃號碼 */ INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" AND "b"."歸屬類別" = 'E38' WHERE "a"."單據類別" = 'E37' GROUP BY "b"."歸屬類別", "b"."歸屬編號", "a"."廠客品號", "a"."產品編號") AS "a");

-- Home #2098 ViewFILE043.貨櫃號碼合計
CREATE OR REPLACE VIEW "viewfile043" AS (SELECT "b"."歸屬類別" AS "單別", "b"."歸屬編號" AS "單號", COUNT("a"."異動數量") AS "箱數", SUM("a"."贈品數量") AS "數量", SUM("a"."毛重") AS "淨重", SUM("a"."毛重" + 15) AS "毛重" FROM "fil0040" AS "a" /* 貨櫃號碼 */ INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" AND "b"."歸屬類別" = 'E38' WHERE "a"."單據類別" = 'E37' GROUP BY "b"."歸屬類別", "b"."歸屬編號");

-- Home #2099 ViewFILE044.嘜頭製令合計
CREATE OR REPLACE VIEW "viewfile044" AS (SELECT "a"."單別", "a"."單號", "a"."嘜頭序號", "a"."製令單號", "a"."產品編號", "a"."箱數", "a"."數量", COALESCE("b"."英文品名", ' ') AS "品名", COALESCE("b"."客戶成品尺寸", ' ') AS "客戶成品尺寸", COALESCE("b"."客戶最終名稱", ' ') AS "客戶最終名稱" FROM (SELECT "b"."歸屬類別" AS "單別", "b"."歸屬編號" AS "單號", "b"."歸屬序號" AS "嘜頭序號", "a"."廠客品號" AS "製令單號", "a"."產品編號", COUNT("a"."異動數量") AS "箱數", SUM("a"."贈品數量") AS "數量" FROM "fil0040" AS "a" /* 貨櫃號碼 */ INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" AND "b"."歸屬類別" = 'E38' WHERE "a"."單據類別" = 'E37' GROUP BY "b"."歸屬類別", "b"."歸屬編號", "b"."歸屬序號", "a"."廠客品號", "a"."產品編號") AS "a" LEFT JOIN "fil0012" AS "b" ON "a"."產品編號" = "b"."產品編號");

-- Home #2100 ViewFILE045.貨櫃明細(B)INV
CREATE OR REPLACE VIEW "viewfile045" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", COALESCE("c"."製令序號", 0) AS "製令序號", "b"."文字1" AS "description", "a"."產品編號" AS "製令單號", "a"."異動數量" AS "數量", "a"."單位代碼" AS "單位", "a"."異動單價" AS "單價", "a"."異動金額" AS "金額", COALESCE("b"."文字2", ' ') AS "客戶最終名稱", "a"."備註說明" AS "備註", "b"."logical1" AS "板費", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" LEFT JOIN "viewfile042" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."產品編號" = "c"."製令單號" LEFT JOIN "fil0012" AS "d" ON "a"."產品編號" = "d"."產品編號" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."單據類別" = 'E38' AND "a"."異動類別" = 'B');

-- Home #2101 ViewFILE046.貨櫃合計(B)INV
CREATE OR REPLACE VIEW "viewfile046" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "數量", SUM("a"."異動金額") AS "金額" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'E38' AND "a"."異動類別" = 'B' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #2105 ViewFILF011.委外加工明細
CREATE OR REPLACE VIEW "viewfilf011" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", COALESCE("h"."產品編號", "a"."產品編號") AS "料號", COALESCE("h"."產品名稱", COALESCE("e"."品名", ' ')) AS "品名", COALESCE("e"."規格", ' ') AS "規格", "a"."異動日期", COALESCE("f"."製造日期", ' ') AS "製造日期", "a"."異動數量" AS "箱號", "a"."贈品數量" AS "包裝數量", "a"."毛重" AS "重量", "a"."數值1" AS "箱數", "c"."批號", "a"."廠客品號" AS "製令單號", "a"."備註說明", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN "fil0032" AS "h" ON "h"."製令單別" = 'C11' AND "h"."製令單號" = "a"."廠客品號" /* 製造日期 */ LEFT JOIN "viewfil4036" AS "f" ON "a"."廠客品號" = "f"."製令單號" LEFT JOIN "fil0012" AS "e" ON "a"."產品編號" = "e"."產品編號" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."單據類別" = 'F11');

-- Home #2106 ViewFILF012.委外加工合計
CREATE OR REPLACE VIEW "viewfilf012" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."數值1") AS "箱數", SUM("a"."贈品數量") AS "包裝數量" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'F11' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #2107 ViewFILF013.委外批號填表日
CREATE OR REPLACE VIEW "viewfilf013" AS (SELECT "d"."工站代碼", "a"."批號", MIN("c"."填表日") AS "填表日" FROM "fil0041" AS "a" INNER JOIN "fil0030" AS "c" ON "a"."單別" = "c"."單據類別" AND "a"."單號" = "c"."單據編號" INNER JOIN "fil0031" AS "d" ON "a"."單別" = "d"."單別" AND "a"."單號" = "d"."單號" WHERE "a"."單別" = 'F11' GROUP BY "d"."工站代碼", "a"."批號");

-- Home #2109 ViewFILF015.委外製令填表日
CREATE OR REPLACE VIEW "viewfilf015" AS (SELECT "d"."工站代碼", "e"."廠客品號" AS "製令單號", MIN("c"."填表日") AS "填表日" FROM "fil0040" AS "e" INNER JOIN "fil0030" AS "c" ON "e"."單據類別" = "c"."單據類別" AND "e"."單據編號" = "c"."單據編號" INNER JOIN "fil0031" AS "d" ON "e"."單據類別" = "d"."單別" AND "e"."單據編號" = "d"."單號" WHERE "e"."單據類別" = 'F11' GROUP BY "d"."工站代碼", "e"."廠客品號");

-- Home #2110 ViewFILF016.委外加工生產明細
CREATE OR REPLACE VIEW "viewfilf016" AS (SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "b"."製程代碼", "b"."工站代碼", "c"."歸屬編號" AS "製令單號", "a"."贈品數量" AS "生產數量", "d"."數值5" AS "報廢數量" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "d" ON "d"."單別" = "a"."單據類別" AND "d"."單號" = "a"."單據編號" AND "d"."序號" = "a"."單據序號" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" INNER JOIN "viewfilf015" AS "e" ON "b"."工站代碼" = "e"."工站代碼" AND "c"."歸屬編號" = "e"."製令單號" AND "c"."填表日" >= "e"."填表日" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" BETWEEN 'C31F' AND 'C31G');

-- Home #2112 ViewFILF021.委外回廠明細
CREATE OR REPLACE VIEW "viewfilf021" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", COALESCE("h"."產品編號", "a"."產品編號") AS "料號", COALESCE("h"."產品名稱", COALESCE("e"."品名", ' ')) AS "品名", COALESCE("e"."規格", ' ') AS "規格", "a"."異動日期", COALESCE("f"."製造日期", ' ') AS "製造日期", "a"."異動數量" AS "箱號", "a"."贈品數量" AS "包裝數量", "a"."毛重" AS "重量", "a"."數值1" AS "箱數", "a"."logical1" AS "退回", "c"."批號", "a"."廠客品號" AS "製令單號", "a"."備註說明", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN "fil0032" AS "h" ON "h"."製令單別" = 'C11' AND "h"."製令單號" = "a"."廠客品號" /* 製造日期 */ LEFT JOIN "viewfil4036" AS "f" ON "a"."廠客品號" = "f"."製令單號" LEFT JOIN "fil0012" AS "e" ON "a"."產品編號" = "e"."產品編號" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."單據類別" = 'F21');

-- Home #2113 ViewFILF022.委外回廠合計
CREATE OR REPLACE VIEW "viewfilf022" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."數值1") AS "箱數", SUM("a"."贈品數量") AS "包裝數量" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'F21' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #2116 ViewFILF031A.庫存盤點明細簡表
CREATE OR REPLACE VIEW "viewfilf031a" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."產品編號" AS "料號", "c"."批號", "a"."異動日期", COALESCE("a"."贈品數量", 0) AS "盤點數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'F31');

-- Home #2117 ViewFILF032.庫存盤點合計
CREATE OR REPLACE VIEW "viewfilf032" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."數值1") AS "箱數", SUM("a"."贈品數量") AS "數量", SUM("a"."異動單價") AS "庫存數", SUM("a"."贈品數量" - "a"."異動單價") AS "差異數", SUM("a"."異動金額") AS "委外數" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'F31' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #2120 ViewFILF042.盤點調整合計
CREATE OR REPLACE VIEW "viewfilf042" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."贈品數量") AS "數量" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'F32' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #2122 ViewFILF051.版銅送修出廠
CREATE OR REPLACE VIEW "viewfilf051" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."產品編號" AS "版銅編號", "b"."品名", "b"."規格", "b"."圓周", "b"."版長", "b"."說明", "a"."異動數量" AS "數量", "a"."異動日期" AS "交期", "a"."文數字1" AS "出庫單號", "a"."備註說明", COALESCE("d"."文字1", ' ') AS "出廠原因", COALESCE("e"."回廠", 0) AS "回廠", COALESCE(TO_CHAR("e"."回廠日期", 'YYYYMMDD HH24:MI:SS'), ' ') AS "回廠日期", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" INNER JOIN "viewfil3112" AS "b" ON "a"."產品編號" = "b"."代碼" LEFT JOIN "fil0041" AS "d" ON "d"."單別" = "a"."單據類別" AND "d"."單號" = "a"."單據編號" AND "d"."序號" = "a"."單據序號" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" LEFT JOIN "fil004d" AS "e" ON "e"."歸屬流水編號" = "a"."流水編號" WHERE "a"."單據類別" = 'F33');

-- Home #2123 ViewFILF052.版銅送修合計
CREATE OR REPLACE VIEW "viewfilf052" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "出廠數", SUM(CASE WHEN "a"."文數字1" = ' ' THEN 0 ELSE "a"."異動數量" END) AS "出庫數", SUM(COALESCE("b"."回廠", 0)) AS "回廠數", CASE WHEN SUM("a"."異動數量") = SUM(CASE WHEN "a"."文數字1" = ' ' THEN 0 ELSE "a"."異動數量" END) THEN 1 ELSE 0 END AS "已出庫", CASE WHEN SUM("a"."異動數量") = SUM(COALESCE("b"."回廠", 0)) THEN 1 ELSE 0 END AS "已結案" FROM "fil0040" AS "a" LEFT JOIN (SELECT "a"."歸屬流水編號", MAX("a"."回廠") AS "回廠" FROM "fil004d" AS "a" WHERE "a"."歸屬流水編號" <> ' ' GROUP BY "a"."歸屬流水編號") AS "b" ON "a"."流水編號" = "b"."歸屬流水編號" WHERE "a"."單據類別" = 'F33' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #2125 ViewFILF054.版銅送修出庫
CREATE OR REPLACE VIEW "viewfilf054" AS (SELECT 'F34' AS "單別", "a"."文數字1" AS "單號", "a"."單據序號" AS "序號", "a"."單據編號" AS "出廠單號", "b"."單據日期" AS "日期", "a"."異動數量" AS "數量", "a"."產品編號" AS "版銅編號", "c"."品名", "c"."規格", "c"."說明", "c"."圓周", "c"."版長", "a"."備註說明", "d"."回廠", "d"."回廠日期", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "b"."單據類別" = 'F34' AND "b"."單據編號" = "a"."文數字1" /* 版銅代碼 */ INNER JOIN "viewfil3112" AS "c" ON "a"."產品編號" = "c"."代碼" /* 回廠 */ LEFT JOIN "fil004d" AS "d" ON "a"."流水編號" = "d"."歸屬流水編號" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."單據類別" /* 出庫F34與出廠F33同一筆記錄，出庫單號記錄於文數字1 */ = 'F33' AND "a"."文數字1" <> ' ');

-- Home #2126 ViewFILF055.版銅出庫合計
CREATE OR REPLACE VIEW "viewfilf055" AS (SELECT 'F34' AS "單別", "a"."文數字1" AS "單號", COUNT(*) AS "筆數", SUM("a"."異動數量") AS "數量" FROM "fil0040" AS "a" WHERE "a"."單據類別" /* 出庫F34與出廠F33同一筆記錄，出庫單號記錄於文數字1 */ = 'F33' AND "a"."文數字1" <> ' ' GROUP BY "a"."文數字1");

-- Home #2129 ViewFILF063.期初庫存合計
CREATE OR REPLACE VIEW "viewfilf063" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."贈品數量") AS "數量", SUM("a"."異動金額") AS "金額" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'F35' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #2131 ViewFILF0W1.委外半成品異動檔
CREATE OR REPLACE VIEW "viewfilf0w1" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "h"."產品編號", "h"."產品名稱" AS "品名", "e"."規格", "a"."異動日期", "a"."異動數量" AS "箱號", "a"."贈品數量" AS "數量", "a"."毛重" AS "重量", "a"."數值1" AS "箱數", "b"."批號", CASE WHEN "a"."單據類別" = 'F11' THEN 1 WHEN "a"."單據類別" = 'F21' THEN -1 ELSE 1 END AS "庫存參數", "a"."廠客品號" AS "製令單號", "a"."異動日期" AS "製造日期", "c"."製程代碼", "g"."製程名稱", "c"."工站代碼", "g"."名稱" AS "工站名稱", "g"."製程工站", CASE WHEN "a"."單據類別" = 'F11' THEN '加工' WHEN "a"."單據類別" = 'F21' THEN '回廠' ELSE '調整' END AS "類別", "a"."備註說明", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" /* 表頭特殊欄位 */ INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" /* 簽收 */ INNER JOIN "fil0037" AS "d" ON "a"."單據類別" = "d"."製令單別" AND "a"."單據編號" = "d"."製令單號" AND "d"."材料序號" = 0 AND ((COALESCE("dbms_lob".getlength("d"."圖檔"), 0) > 0) OR "a"."單據類別" = 'F32') /* 產品編號 */ INNER JOIN "fil0032" AS "h" ON "h"."製令單別" = 'C11' AND "h"."製令單號" = "a"."廠客品號" /* 成品 */ INNER JOIN "fil0012" AS "e" ON "h"."產品編號" = "e"."產品編號" AND "e"."產品類別" = 'F' /* 委外工站 */ INNER JOIN "viewfil310o" AS "g" ON "c"."工站代碼" = "g"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."單據類別" BETWEEN 'F11' AND 'F32' AND "a"."單據類別" <> 'F31');

-- Home #2278 ViewFILH003.員工排休表
CREATE OR REPLACE VIEW "viewfilh003" AS (SELECT "a"."申請人", "a"."年度", "a"."單號", "b"."一月", "b"."二月", "b"."三月", "b"."四月", "b"."五月", "b"."六月", "b"."七月", "b"."八月", "b"."九月", "b"."十月", "b"."十一月", "b"."十二月", "b"."一月" + "b"."二月" + "b"."三月" + "b"."四月" + "b"."五月" + "b"."六月" + "b"."七月" + "b"."八月" + "b"."九月" + "b"."十月" + "b"."十一月" + "b"."十二月" AS "合計" FROM (SELECT "a"."申請人", "a"."年度", "a"."單號" FROM (SELECT "a".*, ROW_NUMBER() OVER (PARTITION BY "a"."申請人", "a"."年度" ORDER BY "a"."生效日期" DESC) AS "rn" FROM "hrfil1032" AS "a" WHERE "a"."單號" <> ' ') AS "a" WHERE "rn" = 1) AS "a" INNER JOIN "hrfil1032" AS "b" ON "a"."單號" = "b"."單號");

-- Home #2283 ViewFILH005C.氣閥計件加班
CREATE OR REPLACE VIEW "viewfilh005c" AS WITH "tmp1" AS (SELECT "a"."製令單別" AS "單別", "a"."製令單號" AS "單號", "a"."材料序號" AS "序號", "a"."相關單號" AS "氣閥日報", SUM("a"."數字一") AS "氣閥產量" FROM "fil0037" AS "a" INNER JOIN "fil0031" AS "b" ON "b"."單別" = "a"."相關單別" AND "b"."單號" = "a"."相關單號" WHERE "a"."製令單別" = 'H03' AND "a"."屬性" = '4' AND "a"."相關單別" = 'C41' AND "b"."製程代碼" = 'C31F' GROUP BY "a"."製令單別", "a"."製令單號", "a"."材料序號", "a"."相關單號"), "tmp2" AS (SELECT "a1"."單據類別" AS "單別", "a1"."單據編號" AS "單號", "a1"."單據序號" AS "序號", "a1"."產品編號" AS "申請人代號", CASE WHEN "a1"."異動日期" = '00000000' THEN "b1"."單據日期" ELSE "a1"."異動日期" END AS "加班日期", COALESCE("e1"."員工姓名", ' ') AS "申請人姓名", "a1"."贈品數量" - "a1"."異動單價" - "a1"."異動金額" AS "單據加班時數" FROM "fil0040" AS "a1" /* 特殊欄位 */ INNER JOIN "fil0030" AS "b1" ON "a1"."單據類別" = "b1"."單據類別" AND "a1"."單據編號" = "b1"."單據編號" LEFT JOIN "fil0010" AS "e1" ON "a1"."產品編號" = "e1"."員工編號" WHERE "a1"."單據類別" = 'H03') SELECT "a"."單別", "a"."單號", "a"."序號", "a"."氣閥日報", "a"."氣閥產量", "b"."申請人代號", "b"."申請人姓名", "b"."加班日期", "b"."單據加班時數", "c"."歸屬編號" AS "製令單號" FROM "tmp1" AS "a" INNER JOIN "tmp2" AS "b" ON "a"."單別" = "b"."單別" AND "a"."單號" = "b"."單號" AND "a"."序號" = "b"."序號" INNER JOIN "fil0030" AS "c" ON "c"."單據類別" = 'C41' AND "c"."單據編號" = "a"."氣閥日報";

-- Home #2284 ViewFILH006.加班費合計
CREATE OR REPLACE VIEW "viewfilh006" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", COALESCE("m"."數量", 0) AS "數量", COALESCE("m"."時數", 0) AS "時數", COALESCE("m"."申請人", ' ') AS "申請人" FROM "fil0030" AS "a" LEFT JOIN (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "數量", SUM("a"."贈品數量") AS "時數", "utl_raw".cast_to_nvarchar2(STRING_AGG(CAST(CONCAT("utl_raw".cast_to_raw(CONCAT("b"."員工姓名", '[')), "utl_raw".cast_to_raw(TRIM(TO_NCHAR(ROUND("a"."贈品數量" - "a"."異動單價" - "a"."異動金額", 1), '90D9'))), "utl_raw".cast_to_raw(N'小時]')) AS TEXT), "utl_raw".cast_to_raw(N',') ORDER BY "a"."單據類別", "a"."單據編號")) AS "申請人" FROM "fil0040" AS "a" LEFT JOIN "fil0010" AS "b" ON "a"."產品編號" = "b"."員工編號" WHERE "a"."單據類別" = 'H03' GROUP BY "a"."單據類別", "a"."單據編號") AS "m" ON "m"."單別" = "a"."單據類別" AND "m"."單號" = "a"."單據編號" WHERE "a"."單據類別" = 'H03');

-- Home #2285 ViewFILH006A.加班日筆數
CREATE OR REPLACE VIEW "viewfilh006a" AS (SELECT "a"."產品編號" AS "申請人", CASE WHEN "a"."異動日期" = '00000000' THEN "b"."單據日期" ELSE "a"."異動日期" END AS "加班日期", COUNT("a"."單據序號") AS "筆數" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'H03' AND "a"."產品編號" <> ' ' GROUP BY "a"."產品編號", CASE WHEN "a"."異動日期" = '00000000' THEN "b"."單據日期" ELSE "a"."異動日期" END);

-- Home #2293 ViewFILH013.員工當次請假時數
CREATE OR REPLACE VIEW "viewfilh013" AS (SELECT "a"."單據編號", SUM("a"."異動數量") AS "請假時數" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'H01' GROUP BY "a"."單據編號");

-- Home #2296 ViewFILH016.每月假日天數
CREATE OR REPLACE VIEW "viewfilh016" AS (SELECT CAST("年月" AS TEXT) AS "年月", SUM(CASE WHEN "休假日" = 0 THEN 0 WHEN "休假日" = 1 THEN 0 ELSE 1 END + CASE WHEN "休假一" = 0 THEN 0 WHEN "休假一" = 1 THEN 0 ELSE 1 END + CASE WHEN "休假二" = 0 THEN 0 WHEN "休假二" = 1 THEN 0 ELSE 1 END + CASE WHEN "休假三" = 0 THEN 0 WHEN "休假三" = 1 THEN 0 ELSE 1 END + CASE WHEN "休假四" = 0 THEN 0 WHEN "休假四" = 1 THEN 0 ELSE 1 END + CASE WHEN "休假五" = 0 THEN 0 WHEN "休假五" = 1 THEN 0 ELSE 1 END + CASE WHEN "休假六" = 0 THEN 0 WHEN "休假六" = 1 THEN 0 ELSE 1 END) AS "假日天數" FROM "fil1019" GROUP BY CAST("年月" AS TEXT));

-- Home #2301 ViewFILH021.每日加班一
CREATE OR REPLACE VIEW "viewfilh021" AS (SELECT "a"."申請人", "a"."加班日期", SUM("a"."加班小時") AS "加班小時", MIN("a"."上班時間") AS "上班時間", MAX("a"."下班時間") AS "下班時間", SUM(ROUND("a"."加班費", 1)) AS "加班費" FROM "hrfil0021" AS "a" WHERE "a"."上班時間" > '000000' GROUP BY "a"."申請人", "a"."加班日期");

-- Home #2302 ViewFILH022.每月加班一
CREATE OR REPLACE VIEW "viewfilh022" AS (SELECT "a"."申請人", ORA_SUBSTR("a"."加班日期", 1, 6) AS "加班年月", SUM("a"."加班小時") AS "加班小時", SUM(ROUND("a"."加班費", 1)) AS "加班費" FROM "hrfil0021" AS "a" GROUP BY "a"."申請人", ORA_SUBSTR("a"."加班日期", 1, 6));

-- Home #2305 ViewFILH025.費用申請合計
CREATE OR REPLACE VIEW "viewfilh025" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "金額" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'H11' GROUP BY "a"."單據類別", "a"."單據編號");

-- Home #2272 ViewFILHS01.個人薪資主檔
CREATE OR REPLACE VIEW "viewfilhs01" AS (SELECT ORA_SUBSTR("b"."年月", 1, 6) AS "年月", "a"."員工編號", "a"."員工姓名", "b"."公司代碼", "c"."guname" AS "公司別", "a"."部門編號", "a"."部門名稱", "a"."職位名稱", "a"."國籍", "b"."薪資分群", COALESCE("b"."所得稅率", 0) AS "所得稅率", COALESCE("b"."健保卡號", ' ') AS "健保卡號", COALESCE("b"."勞保費", 0) AS "勞保費", COALESCE("b"."健保費", 0) AS "健保費", COALESCE("b"."自提退休金", 0) AS "自提退休金", COALESCE("b"."二代健保", 0) AS "二代健保", COALESCE("b"."本薪", 0) AS "本薪", COALESCE("b"."職務津貼", 0) AS "職務津貼", COALESCE("b"."出勤日支", 0) AS "出勤日支", COALESCE("b"."出勤津貼", 0) AS "出勤津貼", COALESCE("b"."交通津貼", 0) AS "交通津貼", COALESCE("b"."技術津貼", 0) AS "技術津貼", COALESCE("b"."午餐津貼", 0) AS "午餐津貼", COALESCE("b"."伙食津貼", 0) AS "伙食津貼", COALESCE("b"."othfee1", 0) AS "午餐日支", COALESCE("b"."othfee2", 0) AS "借支", COALESCE("b"."othfee3", 0) AS "固定所得稅", COALESCE("b"."othfee4", 0) AS "退休金提撥", COALESCE(CAST(("b"."本薪" + "b"."職務津貼" + "b"."出勤津貼" + "b"."交通津貼" + "b"."技術津貼" + "b"."午餐津貼" + "b"."伙食津貼") AS DOUBLE PRECISION) / 30, 0) AS "特休日支", COALESCE("b"."職等", 0) AS "職等", COALESCE("b"."職級", 0) AS "職級", COALESCE("b"."薪點", 0) AS "薪點" FROM "hrfil2001" AS "b" INNER JOIN "viewfil1010" AS "a" ON "b"."員工編號" = "a"."員工編號" LEFT JOIN "a50" AS "c" ON "c"."cmpid" = "b"."公司代碼" WHERE "a"."停止使用" = 0);

-- Home #2273 ViewFILHS02.月薪資彙總
CREATE OR REPLACE VIEW "viewfilhs02" AS (SELECT "a"."年月", "a"."員工編號", "a"."員工姓名", "a"."身份證", "a"."工資卡號", "a"."公司代碼", "a"."薪資分群", "a"."部門代號", "a"."部門", "a"."職稱", "a"."出差", "a"."遲到", "a"."早退", "a"."假別一", "a"."假別二", "a"."假別三", "a"."假別四", "a"."假別五", "a"."假別六", "a"."假別七", "a"."假別八", "a"."假別九", "a"."假別十", "a"."假別十一", "a"."假別十二", "a"."假別十三", "a"."本薪", "a"."職務津貼", "a"."出勤日支", "a"."出勤津貼", "a"."交通津貼", "a"."技術津貼", "a"."午餐津貼", "a"."特休津貼", "a"."伙食津貼", "a"."夜班津貼", "a"."大夜津貼", "a"."車馬費", "a"."加班費", "a"."本月應發金額", "a"."事病假薪點", "a"."遲到早退扣支", "a"."調補扣支", "a"."借支", "a"."自提退休金", "a"."所得稅", "a"."勞保費", "a"."健保費", "a"."二代健保", "a"."加班費一", "a"."加班費二", "a"."實發金額", "a"."上班打卡日", "a"."加班計算日薪", "a"."特休計算日薪", "a"."平日前2小時", "a"."平日前4小時", "a"."平日大於4小時", "a"."休息日前2小時", "a"."休息日前8小時", "a"."休息日大於8小時", "a"."例假日前8小時", "a"."例假日大於8小時", "a"."例假日大於10小時", "a"."例假日補休小時", "a"."國定假日前8小時", "a"."國定假日大於8小時", "a"."國定假日大於10小時", COALESCE("b"."製程代碼", ' ') AS "製程代碼", COALESCE("b"."成本類別", ' ') AS "成本類別", CASE WHEN "a"."上班打卡日" = 0 THEN 0 ELSE CAST(("a"."本月應發金額" - "a"."事病假薪點" - "a"."遲到早退扣支" - "a"."調補扣支") AS DOUBLE PRECISION) / ("a"."上班打卡日" * 8 + ("a"."平日前2小時" + "a"."平日前4小時" + "a"."平日大於4小時" + "a"."休息日大於8小時" + "a"."例假日大於8小時" + "a"."例假日大於10小時" + "a"."國定假日大於8小時" + "a"."國定假日大於10小時" - "a"."休息日前2小時" - "a"."休息日前8小時" - "a"."例假日前8小時" - "a"."國定假日前8小時")) END AS "實際直接人工時薪", CASE WHEN "a"."上班打卡日" = 0 THEN 0 ELSE CAST(("a"."本薪" + "a"."職務津貼" + "a"."出勤津貼" + "a"."交通津貼" + "a"."技術津貼" + "a"."特休津貼" + "a"."加班費" - "a"."借支" - "a"."事病假薪點") AS DOUBLE PRECISION) / ("a"."上班打卡日" * 8 + ("a"."平日前2小時" + "a"."平日前4小時" + "a"."平日大於4小時" + "a"."休息日大於8小時" + "a"."例假日大於8小時" + "a"."例假日大於10小時" + "a"."國定假日大於8小時" + "a"."國定假日大於10小時" - "a"."休息日前2小時" - "a"."休息日前8小時" - "a"."例假日前8小時" - "a"."國定假日前8小時")) END AS "直接人工時薪" FROM "hrfil2006" AS "a" LEFT JOIN "hrfil2001" AS "b" ON ORA_SUBSTR("b"."年月", 1, 6) = ORA_SUBSTR("a"."年月", 1, 6) AND "b"."員工編號" = "a"."員工編號");

-- Home #2274 ViewFILHS03.年薪資彙總
CREATE OR REPLACE VIEW "viewfilhs03" AS (SELECT ORA_SUBSTR("a"."年月", 1, 4) AS "年度", "a"."員工編號", SUM("a"."出差") AS "特休支薪天數", SUM("a"."遲到") AS "遲到", SUM("a"."早退") AS "早退", SUM("a"."假別一") AS "病假", SUM("a"."假別二") AS "事假", SUM("a"."假別三") AS "公傷病假", SUM("a"."假別四") AS "調補", SUM("a"."假別五") AS "公假", SUM("a"."假別六") AS "婚假", SUM("a"."假別七") AS "喪假", SUM("a"."假別八") AS "特別休假", SUM("a"."假別九") AS "產假", SUM("a"."假別十") AS "產檢假", SUM("a"."假別十一") AS "陪產假", SUM("a"."假別十二") AS "調補剩餘", SUM("a"."假別十三") AS "調補減少", SUM("a"."本薪") AS "本薪", SUM("a"."職務津貼") AS "職務津貼", SUM("a"."出勤日支") AS "出勤日支", SUM("a"."出勤津貼") AS "出勤津貼", SUM("a"."交通津貼") AS "交通津貼", SUM("a"."技術津貼") AS "技術津貼", SUM("a"."午餐津貼") AS "午餐津貼", SUM("a"."特休津貼") AS "特休津貼", SUM("a"."伙食津貼") AS "伙食津貼", SUM("a"."夜班津貼") AS "夜班津貼", SUM("a"."大夜津貼") AS "大夜津貼", SUM("a"."加班費") AS "加班費", SUM("a"."車馬費") AS "車馬費", SUM("a"."本月應發金額") AS "本月應發金額", SUM("a"."事病假薪點") AS "病假薪點", SUM("a"."遲到早退扣支") AS "遲到早退扣支", SUM("a"."調補扣支") AS "調補扣支", SUM("a"."借支") AS "借支", SUM("a"."自提退休金") AS "自提退休金", SUM("a"."所得稅") AS "所得稅", SUM("a"."勞保費") AS "勞保費", SUM("a"."健保費") AS "健保費", SUM("a"."二代健保") AS "二代健保", SUM("a"."加班費一") AS "加班費一", SUM("a"."加班費二") AS "加班費二", SUM("a"."實發金額") AS "實發金額", SUM("a"."上班打卡日") AS "上班打卡日", SUM("a"."加班計算日薪") AS "加班計算日薪", SUM("a"."特休計算日薪") AS "特休計算日薪", SUM("a"."平日前2小時") AS "日前2小時", SUM("a"."平日前4小時") AS "平日前4小時", SUM("a"."平日大於4小時") AS "日大於4小時", SUM("a"."休息日前2小時") AS "休息日前2小時", SUM("a"."休息日前8小時") AS "休息日前8小時", SUM("a"."休息日大於8小時") AS "休息日大於8小時", SUM("a"."例假日前8小時") AS "假日前8小時", SUM("a"."例假日大於8小時") AS "例假日大於8小時", SUM("a"."例假日大於10小時") AS "例假日大於10小時", SUM("a"."例假日補休小時") AS "例假日補休小時", SUM("a"."國定假日前8小時") AS "國定假日前8小時", SUM("a"."國定假日大於8小時") AS "國定假日大於8小時", SUM("a"."國定假日大於10小時") AS "國定假日大於10小時" FROM "hrfil2006" AS "a" LEFT JOIN "hrfil1002a" AS "b" ON "b"."syskey" = 'EMP' WHERE ORA_SUBSTR("a"."年月", 1, 6) <= ORA_SUBSTR("b"."關帳年月", 1, 6) GROUP BY ORA_SUBSTR("a"."年月", 1, 4), "a"."員工編號");

-- Home #2208 ViewFILM000S.料碼最後倉位
CREATE OR REPLACE VIEW "viewfilm000s" AS (SELECT DISTINCT "條碼", LAST_VALUE("庫位") OVER (PARTITION BY "條碼" ORDER BY "序號" RANGE BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS "目前庫位" FROM "fil0044" WHERE "條碼" <> ' ' AND "庫位" <> ' ');

-- Home #2240 ViewFILM008H_WK.不分倉庫存數
CREATE OR REPLACE VIEW "viewfilm008h_wk" AS (SELECT CAST('C11' AS TEXT) AS "製令單別", REGEXP_SUBSTR("a"."批號", '[^_]+', 1) AS "製令單號", REGEXP_SUBSTR("a"."批號", '[A-Z]+', 1) AS "加工別", REGEXP_SUBSTR("a"."批號", '[A-Z][0-9][0-9][A-Z]') AS "製程代碼", "a"."批號" AS "半成品編號", SUM(COALESCE("a"."異動數", 0)) AS "庫存數" FROM (SELECT "a"."批號", "a"."異動數" FROM "wkfilm018h" AS "a") AS "a" GROUP BY CAST('C11' AS TEXT), REGEXP_SUBSTR("a"."批號", '[^_]+', 1), REGEXP_SUBSTR("a"."批號", '[A-Z]+', 1), REGEXP_SUBSTR("a"."批號", '[A-Z][0-9][0-9][A-Z]'), "a"."批號");

-- Home #2214 ViewFILM008S_WK.材料庫存數
CREATE OR REPLACE VIEW "viewfilm008s_wk" AS (SELECT "a"."料號" AS "材料編號", "e"."品名", "e"."規格", "a"."庫存數" FROM (SELECT "f"."料號", SUM(COALESCE("a"."庫存數", 0)) AS "庫存數" FROM "wkfilm017s" AS "a" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "a"."批號" GROUP BY "f"."料號") AS "a" INNER JOIN "fil0012" AS "e" ON "e"."產品編號" = "a"."料號");

-- Home #2230 ViewFILM016.不分倉庫存數(批號)
CREATE OR REPLACE VIEW "viewfilm016" AS (SELECT "a"."批號", SUM("a"."異動數") AS "庫存數" FROM (SELECT "c"."批號", CASE WHEN "a"."單據類別" = 'D21' THEN "a"."數值4" ELSE ("a"."異動數量" + "a"."贈品數量") END * "b"."材料庫存參數" AS "異動數" FROM "fil0040" AS "a" /* 庫存參數 */ INNER JOIN "viewfil0020" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "b"."材料庫存參數" <> 0 /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" /* 單位換算
			LEFT JOIN FIL0012 E ON A.產品編號 = E.產品編號
			LEFT JOIN ViewFIL1017 F ON A.單位代碼 = F.從 AND E.單位代碼 = F.到
			*/ WHERE "c"."批號" <> ' ' UNION ALL /* 發料 */ SELECT "c"."批號", "a"."異動數量" AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" /* 單位換算
			LEFT JOIN FIL0012 G ON A.產品編號 = G.產品編號
			LEFT JOIN ViewFIL1017 H ON A.單位代碼 = H.從 AND G.單位代碼 = H.到
			*/ WHERE "a"."單據類別" = 'C4M' AND "c"."批號" <> ' ' UNION ALL /* 材料領用,報廢,油墨領用 */ SELECT "b"."批號", "a"."異動數量" * -1 AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" /* 單位換算
			LEFT JOIN FIL0012 C ON A.產品編號 = C.產品編號
			LEFT JOIN ViewFIL1017 E ON A.單位代碼 = E.從 AND C.單位代碼 = E.到
			*/ WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" BETWEEN 'C' AND 'E' AND "a"."異動數量" <> 0 AND "b"."批號" <> ' ' UNION ALL /* 材料領用.氣閥.鐵條-批號1 */ SELECT "b"."文數字1" AS "批號", "b"."數值1" * -1 AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "b"."文數字1" <> ' ' UNION ALL /* 材料領用.氣閥.鐵條-批號2 */ SELECT "b"."文數字2" AS "批號", "b"."數值2" * -1 AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "b"."文數字2" <> ' ' UNION ALL /* 發料回庫(+) */ SELECT "b"."批號", "a"."贈品數量" * 1 AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" /* 單位換算
			LEFT JOIN FIL0012 C ON A.產品編號 = C.產品編號
			LEFT JOIN ViewFIL1017 E ON A.單位代碼 = E.從 AND C.單位代碼 = E.到
			*/ WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'C' AND "a"."贈品數量" <> 0 /* 廠內盤點調整 */ UNION ALL SELECT "c"."批號", ("a"."異動數量" + "a"."贈品數量") AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'F32' AND "a"."異動類別" = '2') AS "a" GROUP BY "a"."批號");

-- Home #2233 ViewFILM018A.製/裁材料異動檔
CREATE OR REPLACE VIEW "viewfilm018a" AS (/* A材 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "b"."製程代碼", "a"."異動類別", "a"."異動日期" AS "單據日期", "c"."文數字1" AS "批號", "a"."最後更新日", ("c"."數值1" - "c"."數值19") AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "c"."文數字1" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31E' AND "c"."文數字1" <> ' ' UNION ALL /* B材 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "b"."製程代碼", "a"."異動類別", "a"."異動日期" AS "單據日期", "c"."文數字2" AS "批號", "a"."最後更新日", ("c"."數值2" - "c"."數值20") AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "c"."文數字2" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31E' AND "c"."文數字2" <> ' ' UNION ALL /* 側邊 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "b"."製程代碼", "a"."異動類別", "a"."異動日期" AS "單據日期", "c"."文數字3" AS "批號", "a"."最後更新日", ("c"."數值3" - "c"."數值21") AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "c"."文數字3" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31E' AND "c"."文數字3" <> ' ' UNION ALL /* 底邊 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."異動類別", "b"."製程代碼", "a"."異動日期" AS "單據日期", CAST("c"."文數字4" AS TEXT) AS "批號", "a"."最後更新日", ("c"."數值4" - "c"."數值22") AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "c"."文數字4" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31E' AND "c"."文數字4" <> ' ' UNION ALL /* 裁切一 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "b"."製程代碼", "a"."異動類別", "a"."異動日期" AS "單據日期", CAST("c"."文數字4" AS TEXT) AS "批號", "a"."最後更新日", ("a"."異動數量") AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "c"."文數字4" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31D' AND "c"."文數字4" <> ' ' UNION ALL /* 裁切二 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "b"."製程代碼", "a"."異動類別", "a"."異動日期" AS "單據日期", CAST("c"."文數字5" AS TEXT) AS "批號", "a"."最後更新日", ("a"."數值1") AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "c"."文數字4" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31D' AND "c"."文數字5" <> ' ');

