."單號" LEFT JOIN "fil0020" AS "i" ON "a"."部門編號" = "i"."部門編號" LEFT JOIN "viewfil3107" AS "j" ON "a"."收付方式" = "j"."代碼" LEFT JOIN "viewfil3103" AS "k" ON "b"."材積單位" = "k"."代碼" LEFT JOIN "fil0013" AS "l" ON "a"."廠別編號" = "l"."廠別編號" LEFT JOIN "viewfil0011" AS "m" ON "a"."公司代碼" = "m"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewofobjproperties" AS "z3" ON "a"."流水編號" = "z3"."單據流水號" WHERE "a"."單據類別" = 'B31');

-- Home #1832 ViewFIL402D.客戶訂單回簽及佐證
CREATE OR REPLACE VIEW "viewfil402d" AS (SELECT "m"."單別", "m"."單號" AS "報價單號", "a"."單號" AS "製令單號", TO_CHAR("n"."填表日", 'YYYYMMDDHH24MISS') AS "建檔日時", COALESCE("b"."客戶回簽日時", '00000000000000') AS "客戶回簽日時", COALESCE("c"."佐證上傳日時", '00000000000000') AS "佐證上傳日時", LEAST(COALESCE("b"."客戶回簽日時", 'Z'), COALESCE("c"."佐證上傳日時", 'Z')) AS "最早上傳日時", COALESCE("m"."單據日期", '00000000') AS "報價日期", COALESCE("m"."廠客編號", ' ') AS "客戶編號", COALESCE("m"."廠客簡稱", ' ') AS "客戶簡稱", COALESCE("m"."廠客全名", ' ') AS "客戶全名", COALESCE("m"."業務員", ' ') AS "業務員", COALESCE("m"."業務員姓名", ' ') AS "業務員姓名", COALESCE("m"."客戶回簽", 0) AS "客戶回簽", COALESCE("m"."客戶佐證", 0) AS "客戶佐證", COALESCE("m"."產品編號", ' ') AS "產品編號", COALESCE("m"."品名", ' ') AS "品名", COALESCE("m"."規格", ' ') AS "規格", "m"."不用回簽報價單" FROM "viewfil4010" AS "m" LEFT JOIN "fil0038" AS "a" ON "m"."單別" = 'B11' AND "m"."單號" = "a"."說明一" LEFT JOIN "fil0030" AS "n" ON "n"."單據類別" = "a"."單別" AND "n"."單據編號" = "a"."單號" LEFT JOIN (SELECT "a"."單號", MIN(CONCAT("a"."建檔日", "建檔時")) AS "客戶回簽日時" FROM "fil1011" AS "a" WHERE "a"."簽核系統" = 'B11.APK' GROUP BY "a"."單號") AS "b" ON "b"."單號" = "a"."說明一" LEFT JOIN (SELECT "a"."單號", MIN(CONCAT("a"."建檔日", "建檔時")) AS "佐證上傳日時" FROM "fil1011" AS "a" WHERE "a"."簽核系統" = 'B11.APK_A' GROUP BY "a"."單號") AS "c" ON "c"."單號" = "a"."說明一");

