CREATE OR REPLACE VIEW "viewfil402da" AS (SELECT "m"."單別", "m"."單號" AS "報價單號", ORA_SUBSTR(COALESCE("a"."製令單號", ' '), 1, 200) AS "製令單號", TO_CHAR("n"."填表日", 'YYYYMMDDHH24MISS') AS "建檔日時", COALESCE("b"."客戶回簽日時", '00000000000000') AS "客戶回簽日時", COALESCE("c"."佐證上傳日時", '00000000000000') AS "佐證上傳日時", LEAST(COALESCE("b"."客戶回簽日時", 'Z'), COALESCE("c"."佐證上傳日時", 'Z')) AS "最早上傳日時", COALESCE("m"."單據日期", '00000000') AS "報價日期", COALESCE("m"."廠客編號", ' ') AS "客戶編號", COALESCE("m"."廠客簡稱", ' ') AS "客戶簡稱", COALESCE("m"."廠客全名", ' ') AS "客戶全名", COALESCE("m"."業務員", ' ') AS "業務員", COALESCE("m"."業務員姓名", ' ') AS "業務員姓名", COALESCE("m"."客戶回簽", 0) AS "客戶回簽", COALESCE("m"."客戶佐證", 0) AS "客戶佐證", COALESCE("m"."產品編號", ' ') AS "產品編號", COALESCE("m"."品名", ' ') AS "品名", COALESCE("m"."規格", ' ') AS "規格", "m"."不用回簽報價單" FROM "viewfil4010" AS "m" LEFT JOIN "fil0030" AS "n" ON "n"."單據類別" = "m"."單別" AND "n"."單據編號" = "m"."單號" LEFT JOIN (SELECT "a"."說明一", STRING_AGG(CAST("a"."單號" AS TEXT), ',' ORDER BY "a"."流水編號") AS "製令單號" FROM "fil0038" AS "a" WHERE "a"."單別" = 'C11' AND "a"."說明一" <> ' ' GROUP BY "a"."說明一") AS "a" ON "m"."單號" = "a"."說明一" LEFT JOIN (SELECT "a"."單號", MIN(CONCAT("a"."建檔日", "建檔時")) AS "客戶回簽日時" FROM "fil1011" AS "a" WHERE "a"."簽核系統" = 'B11.APK' GROUP BY "a"."單號") AS "b" ON "b"."單號" = "a"."說明一" LEFT JOIN (SELECT "a"."單號", MIN(CONCAT("a"."建檔日", "建檔時")) AS "佐證上傳日時" FROM "fil1011" AS "a" WHERE "a"."簽核系統" = 'B11.APK_A' GROUP BY "a"."單號") AS "c" ON "c"."單號" = "a"."說明一" WHERE "m"."不用回簽報價單" = 0 AND "m"."簽核狀態" = 'E');

