."單號" LEFT JOIN "fil0020" AS "i" ON "a"."部門編號" = "i"."部門編號" LEFT JOIN "viewfil3107" AS "j" ON "a"."收付方式" = "j"."代碼" LEFT JOIN "viewfil3103" AS "k" ON "b"."材積單位" = "k"."代碼" LEFT JOIN "fil0013" AS "l" ON "a"."廠別編號" = "l"."廠別編號" LEFT JOIN "viewfil0011" AS "m" ON "a"."公司代碼" = "m"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewofobjproperties" AS "z3" ON "a"."流水編號" = "z3"."單據流水號" WHERE "a"."單據類別" = 'B51');

