CREATE OR REPLACE VIEW "viewfil4030a" AS (SELECT "a"."製令單別", "a"."製令單號", "a"."前置單別", "a"."前置單號", "b"."單據日期" AS "填單日期", "b"."簽核系統", "b"."簽核系統_結案", "a"."產品編號", "a"."產品名稱", COALESCE("i1"."規格", COALESCE("i2"."規格", ' ')) AS "產品規格", ' ' AS "材質結構", "b"."歸屬類別" AS "訂單單別", "b"."歸屬編號" AS "訂單單號", "b"."廠客編號" AS "客戶編號", COALESCE("h"."全名", ' ') AS "客戶名稱", COALESCE("h1"."serial_num", ' ') AS "業務流水編號", COALESCE("f"."公司代碼", "b"."公司代碼") AS "公司代碼", COALESCE("m"."名稱", ' ') AS "公司名稱", COALESCE("g"."單據序號", 0) AS "明細序號", CASE WHEN "a"."成袋數" = 0 THEN COALESCE("n1"."成捲數", COALESCE("n2"."成捲數", COALESCE("n3"."成捲數", COALESCE("n4"."成捲數", 0)))) ELSE "a"."成袋數" END AS "訂購數量", "b"."匯率日期" AS "預交日", "a"."印刷單位", COALESCE("j"."名稱", ' ') AS "印刷單位名稱", "a"."包裝方式", COALESCE("k"."名稱", ' ') AS "包裝方式說明", "a"."油墨種類", COALESCE("l"."名稱", ' ') AS "油墨種類名稱", "a"."送貨地址", "b"."流水編號", CONCAT("a"."製令單號", '(', TRIM("a"."製令單別"), ')', '/', COALESCE("h"."全名", ' '), '/', "a"."產品名稱") AS "主旨", COALESCE("c"."serial_num", ' ') AS "員工流水編號", "b"."稅別" AS "類別", "b"."填表人", COALESCE("c"."員工姓名", ' ') AS "填表人姓名", "b"."填表日", "b"."最後更新者", COALESCE("d"."員工姓名", ' ') AS "更新者姓名", "b"."最後更新日", COALESCE("e"."簽核狀態", ' ') AS "簽核狀態", CASE WHEN "b"."確認碼" = ' ' THEN 0 ELSE 1 END AS "改版" FROM "fil0032" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."製令單別" = "b"."單據類別" AND "a"."製令單號" = "b"."單據編號" LEFT JOIN "fil0010" AS "c" ON "b"."填表人" = "c"."員工編號" LEFT JOIN "fil0010" AS "d" ON "b"."最後更新者" = "d"."員工編號" LEFT JOIN "viewofobjproperties" AS "e" ON "b"."流水編號" = "e"."單據流水號" /* 訂單 */ LEFT JOIN "fil0030" AS "f" ON "b"."歸屬類別" = "f"."單據類別" AND "b"."歸屬編號" = "f"."單據編號" LEFT JOIN "fil0040" AS "g" ON "b"."歸屬類別" = "g"."單據類別" AND "b"."歸屬編號" = "g"."單據編號" AND "a"."產品編號" = "g"."產品編號" /* 客戶 */ LEFT JOIN "fil0011" AS "h" ON "b"."廠客編號" = "h"."編號" LEFT JOIN "fil0010" AS "h1" ON "h"."採購人員" = "h1"."員工編號" /* 規格(成品尺寸) */ LEFT JOIN "fil0012" AS "i1" ON "a"."產品編號" = "i1"."產品編號" LEFT JOIN "fil0012" AS "i2" ON TRIM(REGEXP_SUBSTR("a"."產品編號", '([^/]+)', 1, 1)) = "i2"."產品編號" /* 印刷單位 */ LEFT JOIN "viewfil3103" AS "j" ON "a"."印刷單位" = "j"."代碼" /* 包裝方式 */ LEFT JOIN "viewfil310c" AS "k" ON "a"."包裝方式" = "k"."代碼" /* 油墨種類 */ LEFT JOIN "viewfil3109" AS "l" ON "a"."油墨種類" = "l"."代碼" /* 訂單公司別 */ LEFT JOIN "viewfil0011" AS "m" ON "f"."公司代碼" = "m"."代碼" /* 成捲數 */ LEFT JOIN "fil0033" AS "n1" ON "a"."製令單別" = "n1"."製令單別" AND "a"."製令單號" = "n1"."製令單號" AND "n1"."加工別" = 'A' LEFT JOIN "fil0033" AS "n2" ON "a"."製令單別" = "n2"."製令單別" AND "a"."製令單號" = "n2"."製令單號" AND "n2"."加工別" = 'B' LEFT JOIN "fil0033" AS "n3" ON "a"."製令單別" = "n3"."製令單別" AND "a"."製令單號" = "n3"."製令單號" AND "n3"."加工別" = 'C' LEFT JOIN "fil0033" AS "n4" ON "a"."製令單別" = "n4"."製令單別" AND "a"."製令單號" = "n4"."製令單號" AND "n4"."加工別" = 'D' WHERE "b"."稅別" = 'A');

