-- Home #1848 ViewFIL4030.製令主檔.C11_B
CREATE OR REPLACE VIEW "viewfil4030_b" AS (SELECT "a"."製令單別", "a"."製令單號", "b"."歸屬類別" AS "訂單單別", "b"."歸屬編號" AS "訂單單號", "a"."產品編號", "a"."產品名稱", COALESCE("i1"."規格", COALESCE("i2"."規格", ' ')) AS "產品規格", "b"."廠客編號" AS "客戶編號", "b"."匯率日期" AS "預交日", COALESCE("h"."全名", ' ') AS "客戶名稱", COALESCE("f"."公司代碼", "b"."公司代碼") AS "公司代碼", COALESCE("m"."名稱", ' ') AS "公司名稱", "b"."稅別" AS "類別", "a"."成袋數" AS "訂單成袋數", "i3"."成捲數" AS "訂單成捲數", COALESCE("i4"."捲數", 0) AS "裁切捲數", COALESCE("i5"."捲數", 0) AS "包裝捲數", COALESCE("i6"."數量", 0) AS "製袋數量", CASE WHEN "a"."成袋數" = 0 THEN 0 ELSE CAST(COALESCE("i6"."數量", 0) AS DOUBLE PRECISION) / "a"."成袋數" END AS "製袋完成率", CASE WHEN "i3"."成捲數" = 0 THEN 0 ELSE CAST(COALESCE("i4"."捲數", 0) AS DOUBLE PRECISION) / "i3"."成捲數" END AS "裁切完成率", CASE WHEN "i3"."成捲數" = 0 THEN 0 ELSE CAST(COALESCE("i5"."捲數", 0) AS DOUBLE PRECISION) / "i3"."成捲數" END AS "包裝完成率", CASE WHEN CASE WHEN POSITION('R' IN SUBSTRING("a"."產品編號" FROM 1)) = 0 THEN 0 ELSE POSITION('R' IN SUBSTRING("a"."產品編號" FROM 1)) + 1 - 1 END > 0 THEN CASE WHEN "i3"."成捲數" = 0 THEN 0 ELSE CAST(COALESCE("i5"."捲數", 0) AS DOUBLE PRECISION) / "i3"."成捲數" END ELSE CASE WHEN "a"."成袋數" = 0 THEN 0 ELSE CAST(COALESCE("i6"."數量", 0) AS DOUBLE PRECISION) / "a"."成袋數" END END AS "達成率", CASE WHEN CASE WHEN POSITION('R' IN SUBSTRING("a"."產品編號" FROM 1)) = 0 THEN 0 ELSE POSITION('R' IN SUBSTRING("a"."產品編號" FROM 1)) + 1 - 1 END > 0 THEN COALESCE("i5"."捲數", 0) ELSE COALESCE("i6"."數量", 0) END AS "總入庫數", "f"."單據日期" AS "作業日期", "b"."流水編號" FROM "fil0032" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."製令單別" = "b"."單據類別" AND "a"."製令單號" = "b"."單據編號" LEFT JOIN "fil0030" AS "f" ON "a"."製令單別" = "f"."單據類別" AND "a"."製令單號" = "f"."單據編號" LEFT JOIN "fil0011" AS "h" ON "b"."廠客編號" = "h"."編號" LEFT JOIN "fil0012" AS "i1" ON "a"."產品編號" = "i1"."產品編號" LEFT JOIN "fil0012" AS "i2" ON TRIM(REGEXP_SUBSTR("a"."產品編號", '([^/]+)', 1, 1)) = "i2"."產品編號" /* 訂單公司別 */ LEFT JOIN "viewfil0011" AS "m" ON "f"."公司代碼" = "m"."代碼" LEFT JOIN "fil0033" AS "i3" ON "a"."製令單別" = "i3"."製令單別" AND "a"."製令單號" = "i3"."製令單號" AND "i3"."加工別" = 'A' LEFT JOIN "viewfil2064" AS "i4" ON "a"."製令單號" = "i4"."製令單號" LEFT JOIN "viewfil2065" AS "i5" ON "a"."製令單號" = "i5"."製令單號" LEFT JOIN "viewfil404e74" AS "i6" ON "a"."製令單號" = "i6"."製令單號");

