承辦人姓名", COALESCE("r"."員工姓名", ' ') AS "確認_加工課_承辦人姓名", COALESCE("s"."員工姓名", ' ') AS "確認_會計課_承辦人姓名", COALESCE("t"."員工姓名", ' ') AS "確認_總務課_承辦人姓名", COALESCE("u"."員工姓名", ' ') AS "確認_積層課_承辦人姓名", COALESCE("v"."員工姓名", ' ') AS "確認_製袋課_承辦人姓名", COALESCE("w"."員工姓名", ' ') AS "確認_廠務課_承辦人姓名", COALESCE("x"."員工姓名", ' ') AS "確認_其他單位_承辦人姓名", "b"."簽核系統", "b"."簽核系統_結案", "b"."流水編號", "b"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "b"."填表日", "b"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "b"."最後更新日", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態" FROM "fil0035" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單別" = "b"."單據類別" AND "a"."單號" = "b"."單據編號" /* 製令 */ LEFT JOIN "viewfil4030" AS "c" ON "b"."歸屬類別" = "c"."製令單別" AND "b"."歸屬編號" = "c"."製令單號" LEFT JOIN "fil0010" AS "z1" ON "b"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "b"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewfil0030" AS "z3" ON "b"."簽核系統" = "z3"."簽核系統" AND "b"."單據編號" = "z3"."單號" LEFT JOIN "fil0011" AS "d" ON "a"."變更別_廠商" = "d"."編號" LEFT JOIN "fil0020" AS "e" ON "a"."變更別_單位_製程" = "e"."部門編號" LEFT JOIN "fil0020" AS "f" ON "a"."變更別_單位_交期" = "f"."部門編號" LEFT JOIN "fil0010" AS "g" ON "a"."知會單位_營業課_承辦人" = "g"."員工編號" LEFT JOIN "fil0010" AS "h" ON "a"."知會單位_印刷課_承辦人" = "h"."員工編號" LEFT JOIN "fil0010" AS "i" ON "a"."知會單位_加工課_承辦人" = "i"."員工編號" LEFT JOIN "fil0010" AS "j" ON "a"."知會單位_會計課_承辦人" = "j"."員工編號" LEFT JOIN "fil0010" AS "k" ON "a"."知會單位_總務課_承辦人" = "k"."員工編號" LEFT JOIN "fil0010" AS "l" ON "a"."知會單位_積層課_承辦人" = "l"."員工編號" LEFT JOIN "fil0010" AS "m" ON "a"."知會單位_製袋課_承辦人" = "m"."員工編號" LEFT JOIN "fil0010" AS "n" ON "a"."知會單位_廠務課_承辦人" = "n"."員工編號" LEFT JOIN "fil0010" AS "o" ON "a"."知會單位_其他單位_承辦人" = "o"."員工編號" LEFT JOIN "fil0010" AS "p" ON "a"."確認_營業課_承辦人" = "p"."員工編號" LEFT JOIN "fil0010" AS "q" ON "a"."確認_印刷課_承辦人" = "q"."員工編號" LEFT JOIN "fil0010" AS "r" ON "a"."確認_加工課_承辦人" = "r"."員工編號" LEFT JOIN "fil0010" AS "s" ON "a"."確認_會計課_承辦人" = "s"."員工編號" LEFT JOIN "fil0010" AS "t" ON "a"."確認_總務課_承辦人" = "t"."員工編號" LEFT JOIN "fil0010" AS "u" ON "a"."確認_積層課_承辦人" = "u"."員工編號" LEFT JOIN "fil0010" AS "v" ON "a"."確認_製袋課_承辦人" = "v"."員工編號" LEFT JOIN "fil0010" AS "w" ON "a"."確認_廠務課_承辦人" = "w"."員工編號" LEFT JOIN "fil0010" AS "x" ON "a"."確認_其他單位_承辦人" = "x"."員工編號");

-- Home #1858 ViewFIL4040M.生產排程彙總.C31
CREATE OR REPLACE VIEW "viewfil4040m" AS (SELECT DISTINCT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "b"."製程代碼", "b"."機台代碼", COALESCE("e"."名稱", ' ') AS "機台名稱", "a"."單據日期" AS "排程日期", "b"."數值1" AS "作業順序", "b"."聯絡人序號" AS "序號" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "viewfil310p" AS "e" ON "b"."機台代碼" = "e"."代碼" WHERE "a"."單據類別" = 'C31' UNION SELECT DISTINCT "a"."製令單別" AS "單別", "a"."製令單號" AS "單號", "b"."製程代碼", "a"."製令單別" AS "機台代碼", COALESCE("b"."名稱", ' ') AS "機台名稱", "a"."製令單號" AS "排程日期", 0 AS "作業順序", 0 AS "序號" FROM "fil0037" AS "a" INNER JOIN "viewfil310p" AS "b" ON "a"."製令單別" = "b"."代碼");

-- Home #1859 ViewFIL4040S.生產排程比較C31
CREATE OR REPLACE VIEW "viewfil4040s" AS (SELECT "a"."製令單別", "a"."製令單號", "a"."加工別", CASE WHEN "a"."加工別" = 'A' THEN 'A材' WHEN "a"."加工別" = 'B' THEN 'B材' WHEN "a"."加工別" = 'C' THEN '底邊' WHEN "a"."加工別" = 'D' THEN 'A側' WHEN "a"."加工別" = 'E' THEN 'B側' ELSE ' ' END AS "加工別名稱", "a"."排程日期", "a"."製程代碼", "a"."機台代碼", COALESCE("c"."名稱", ' ') AS "製程名稱", COALESCE("e"."名稱", ' ') AS "機台名稱", "a"."數量" AS "排程數量", COALESCE("b"."數量", 0) AS "生產數量", (CASE WHEN COALESCE("f"."印刷色順一", ' ') = ' ' THEN 0 ELSE 1 END + CASE WHEN COALESCE("f"."印刷色順二", ' ') = ' ' THEN 0 ELSE 1 END + CASE WHEN COALESCE("f"."印刷色順三", ' ') = ' ' THEN 0 ELSE 1 END + CASE WHEN COALESCE("f"."印刷色順四", ' ') = ' ' THEN 0 ELSE 1 END + CASE WHEN COALESCE("f"."印刷色順五", ' ') = ' ' THEN 0 ELSE 1 END + CASE WHEN COALESCE("f"."印刷色順六", ' ') = ' ' THEN 0 ELSE 1 END + CASE WHEN COALESCE("f"."印刷色順七", ' ') = ' ' THEN 0 ELSE 1 END + CASE WHEN COALESCE("f"."印刷色順八", ' ') = ' ' THEN 0 ELSE 1 END + CASE WHEN COALESCE("f"."印刷色順九", ' ') = ' ' THEN 0 ELSE 1 END + CASE WHEN COALESCE("f"."印刷色順十", ' ') = ' ' THEN 0 ELSE 1 END) AS "色順數" FROM "viewfil4041b" AS "a" LEFT JOIN "viewfil404cc" AS "b" ON "a"."製令單別" = "b"."製令單別" AND "a"."製令單號" = "b"."製令單號" AND "a"."加工別" = "b"."加工別" AND "a"."排程日期" = "b"."作業日期" AND "a"."製程代碼" = "b"."製程代碼" AND "a"."機台代碼" = "b"."機台代碼" LEFT JOIN "viewfil310n" AS "c" ON "a"."製程代碼" = "c"."代碼" LEFT JOIN "viewfil310p" AS "e" ON "a"."機台代碼" = "e"."代碼" LEFT JOIN "fil0033" AS "f" ON "a"."製令單別" = "f"."製令單別" AND "a"."製令單號" = "f"."製令單號" AND "a"."加工別" = "f"."加工別");

-- Home #1864 ViewFIL4042.製令製程結構
CREATE OR REPLACE VIEW "viewfil4042" AS (SELECT "m"."製令單號", "m"."節點", "m"."製程代碼", "m"."ab底側", "m"."ab底側二", "m"."ab底側三", "m"."ab底側四", "m"."使用半成品", "m"."使用半成品二", "m"."使用半成品三", "m"."使用半成品四", "m"."物料編號", "m"."物料編號二", "m"."物料編號三", "m"."物料編號四", "m"."工作代碼", "m"."預計投產日", "m"."實際投產日", REPLACE(CONCAT(CASE WHEN "m"."製程代碼" = 'C32A' THEN '燙金' WHEN "m"."製程代碼" = 'C32B' THEN '數位噴墨' WHEN "m"."製程代碼" = 'C32C' THEN '品檢' WHEN "m"."製程代碼" = 'C32D' THEN '上臘' ELSE COALESCE(TRIM("a"."名稱"), ' ') END, REPLACE(TRIM(CONCAT(TRIM("m"."ab底側"), TRIM("m"."ab底側二"), TRIM("m"."ab底側三"), TRIM("m"."ab底側四"))), '()', ''), '半成品', CASE WHEN COALESCE("b"."名稱", ' ') = ' ' THEN '' ELSE '#' END, COALESCE(TRIM("b"."名稱"), ' '), REPLACE("m"."預計投產日", '00000000', ''), RTRIM(CONCAT(' ', TRIM(CASE WHEN COALESCE(TRIM("c"."名稱"), ' ') = ' ' THEN ' ' ELSE CONCAT('＠', COALESCE(TRIM("c"."名稱無代碼"), ' ')) END)))), 'A材B材', 'AB材') AS "名稱", "m"."父節點", "m"."說明", "m"."半成品名稱" FROM "fil0039" AS "m" LEFT JOIN "viewfil310n" AS "a" ON "m"."製程代碼" = "a"."代碼" LEFT JOIN "viewfil310t" AS "b" ON "m"."工作代碼" = "b"."代碼" LEFT JOIN "viewfil310p" AS "c" ON "m"."機台代碼" = "c"."代碼");

-- Home #1866 ViewFIL4044.製令製程選項
CREATE OR REPLACE VIEW "viewfil4044" AS (SELECT "m"."製令單號", TO_NCHAR('A材') AS "名稱", TO_NCHAR('A材') AS "名稱二", ' ' AS "節點" FROM "viewfil4030" AS "m" UNION ALL SELECT "m"."製令單號", TO_NCHAR('B材') AS "名稱", TO_NCHAR('B材') AS "名稱二", ' ' AS "節點" FROM "viewfil4030" AS "m" UNION ALL SELECT "m"."製令單號", TO_NCHAR('底材') AS "名稱", TO_NCHAR('底材') AS "名稱二", ' ' AS "節點" FROM "viewfil4030" AS "m" UNION ALL SELECT "m"."製令單號", TO_NCHAR('A側') AS "名稱", TO_NCHAR('A側') AS "名稱二", ' ' AS "節點" FROM "viewfil4030" AS "m" UNION ALL SELECT "m"."製令單號", TO_NCHAR('B側') AS "名稱", TO_NCHAR('B側') AS "名稱二", ' ' AS "節點" FROM "viewfil4030" AS "m");

-- Home #1876 ViewFIL4048A5.製令單別標籤
CREATE OR REPLACE VIEW "viewfil4048a5" AS SELECT DISTINCT "a"."製令類別", "a"."製令單號", "a"."單據類別", "a"."製程代碼", FIRST_VALUE("a"."產品編號") OVER (PARTITION BY "a"."製令類別", "a"."製令單號", "a"."單據類別" ORDER BY "a"."作業日期" DESC) AS "產品編號" FROM (SELECT "d"."歸屬類別" AS "製令類別", "d"."歸屬編號" AS "製令單號", "a"."單據類別", "c"."製程代碼", "d"."單據日期" AS "作業日期", "a"."產品編號" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" LEFT JOIN "viewfil404e7" AS "g" ON "d"."歸屬類別" = "g"."製令單別" AND "d"."歸屬編號" = "g"."製令單號" AND "a"."異動數量" = "g"."箱號" WHERE "a"."異動類別" = 'A' AND ("c"."製程代碼" = 'C31E' OR "c"."製程代碼" = 'C31F' OR "c"."製程代碼" = 'C31G') AND "a"."產品編號" <> ' ' UNION ALL SELECT CAST('C11' AS TEXT) AS "製令類別", "a"."廠客品號" AS "製令單號", "a"."單據類別", CAST(' ' AS TEXT) AS "製程代碼", "d"."單據日期" AS "作業日期", "a"."產品編號" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" LEFT JOIN "viewfil404e7" AS "j" ON CAST('C11' AS TEXT) = "j"."製令單別" AND "a"."廠客品號" = "j"."製令單號" AND "a"."異動數量" = "j"."箱號" WHERE ("a"."單據類別" = 'E32' OR "a"."單據類別" = 'E33' OR "a"."單據類別" = 'E35' OR "a"."單據類別" = 'E37') AND "a"."產品編號" <> ' ') AS "a";

-- Home #1877 ViewFIL4048A6.製令單別最後標籤
CREATE OR REPLACE VIEW "viewfil4048a6" AS SELECT DISTINCT "a"."製令類別", "a"."製令單號", FIRST_VALUE("a"."產品編號") OVER (PARTITION BY "a"."製令類別", "a"."製令單號" ORDER BY "a"."作業日期" DESC) AS "產品編號" FROM (SELECT "d"."歸屬類別" AS "製令類別", "d"."歸屬編號" AS "製令單號", "d"."單據日期" AS "作業日期", "a"."產品編號" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" LEFT JOIN "viewfil404e7" AS "g" ON "d"."歸屬類別" = "g"."製令單別" AND "d"."歸屬編號" = "g"."製令單號" AND "a"."異動數量" = "g"."箱號" WHERE "a"."異動類別" = 'A' AND ("c"."製程代碼" = 'C31E' OR "c"."製程代碼" = 'C31F' OR "c"."製程代碼" = 'C31G') AND "a"."產品編號" <> ' ' UNION ALL SELECT CAST('C11' AS TEXT) AS "製令類別", "a"."廠客品號" AS "製令單號", "d"."單據日期" AS "作業日期", "a"."產品編號" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" LEFT JOIN "viewfil404e7" AS "j" ON CAST('C11' AS TEXT) = "j"."製令單別" AND "a"."廠客品號" = "j"."製令單號" AND "a"."異動數量" = "j"."箱號" WHERE ("a"."單據類別" = 'E32' OR "a"."單據類別" = 'E33' OR "a"."單據類別" = 'E35' OR "a"."單據類別" = 'E37') AND "a"."產品編號" <> ' ') AS "a";

-- Home #1878 ViewFIL4048AA.製令用料需求明細
CREATE OR REPLACE VIEW "viewfil4048aa" AS (/* 夾鍊一 */ SELECT "a"."製令單別", "a"."製令單號", "a"."加工項目_夾鍊代碼" AS "料號", "a"."成袋數" * "a"."加工項目_夾鍊mm" AS "需求量", CAST('夾鍊一' AS TEXT) AS "類別" FROM "fil0032" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."製令單別" = "b"."單據類別" AND "a"."製令單號" = "b"."單據編號" INNER JOIN "viewofobjproperties" AS "c" ON "b"."流水編號" = "c"."單據流水號" WHERE "b"."邏輯值一" = 0 AND "c"."簽核狀態" = 'E' AND "a"."加工項目_夾鍊代碼" <> ' ' UNION /* 夾鍊二 */ SELECT "a"."製令單別", "a"."製令單號", "a"."加工項目_夾鍊代碼二" AS "料號", "a"."成袋數" * "a"."加工項目_夾鍊mm二" AS "需求量", CAST('夾鍊二' AS TEXT) AS "類別" FROM "fil0032" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."製令單別" = "b"."單據類別" AND "a"."製令單號" = "b"."單據編號" INNER JOIN "viewofobjproperties" AS "c" ON "b"."流水編號" = "c"."單據流水號" WHERE "b"."邏輯值一" = 0 AND "c"."簽核狀態" = 'E' AND "a"."加工項目_夾鍊代碼二" <> ' ' UNION /* 氣閥 */ SELECT "a"."製令單別", "a"."製令單號", "a"."加工項目_氣閥代碼" AS "料號", "a"."成袋數" * "a"."加工項目_氣閥mm" AS "需求量", CAST('氣閥' AS TEXT) AS "類別" FROM "fil0032" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."製令單別" = "b"."單據類別" AND "a"."製令單號" = "b"."單據編號" INNER JOIN "viewofobjproperties" AS "c" ON "b"."流水編號" = "c"."單據流水號" WHERE "b"."邏輯值一" = 0 AND "c"."簽核狀態" = 'E' AND "a"."加工項目_氣閥代碼" <> ' ' UNION /* 鐵條 */ SELECT "a"."製令單別", "a"."製令單號", "a"."加工項目_鐵條代碼" AS "料號", "a"."成袋數" * "a"."加工項目_鐵條mm" AS "需求量", CAST('鐵條' AS TEXT) AS "類別" FROM "fil0032" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."製令單別" = "b"."單據類別" AND "a"."製令單號" = "b"."單據編號" INNER JOIN "viewofobjproperties" AS "c" ON "b"."流水編號" = "c"."單據流水號" WHERE "b"."邏輯值一" = 0 AND "c"."簽核狀態" = 'E' AND "a"."加工項目_鐵條代碼" <> ' ' UNION /* 紙箱_無氣閥 */ SELECT "a"."製令單別", "a"."製令單號", "a"."紙箱代碼" AS "料號", "a"."成袋數" AS "需求量", CAST('紙箱無氣閥' AS TEXT) AS "類別" FROM "fil0032" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."製令單別" = "b"."單據類別" AND "a"."製令單號" = "b"."單據編號" INNER JOIN "viewofobjproperties" AS "c" ON "b"."流水編號" = "c"."單據流水號" WHERE "b"."邏輯值一" = 0 AND "c"."簽核狀態" = 'E' AND "a"."紙箱代碼" <> ' ' UNION /* 紙箱_氣閥 */ SELECT "a"."製令單別", "a"."製令單號", "a"."紙箱代碼_氣閥" AS "料號", "a"."成袋數" AS "需求量", CAST('紙箱有氣閥' AS TEXT) AS "類別" FROM "fil0032" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."製令單別" = "b"."單據類別" AND "a"."製令單號" = "b"."單據編號" INNER JOIN "viewofobjproperties" AS "c" ON "b"."流水編號" = "c"."單據流水號" WHERE "b"."邏輯值一" = 0 AND "c"."簽核狀態" = 'E' AND "a"."紙箱代碼_氣閥" <> ' ');

-- Home #1885 ViewFIL404A1.印刷日報主檔.C41
CREATE OR REPLACE VIEW "viewfil404a1" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期" AS "作業日期", "a"."歸屬類別" AS "製令單別", "a"."歸屬編號" AS "製令單號", "c"."公司代碼", "c"."公司名稱", "c"."訂單單別", "c"."訂單單號", "b"."機台代碼", COALESCE("d"."名稱", ' ') AS "機台名稱", CASE WHEN "b"."交貨日期_次批" = 'A' THEN 'A材' WHEN "b"."交貨日期_次批" = 'B' THEN 'B材' WHEN "b"."交貨日期_次批" = 'C' THEN '底邊' WHEN "b"."交貨日期_次批" = 'D' THEN 'A側' WHEN "b"."交貨日期_次批" = 'E' THEN 'B側' ELSE ' ' END AS "加工別", "b"."交貨日期_天" AS "本日件數順序", CONCAT("a"."單據編號", '(', TRIM("a"."單據類別"), ')', '/製令:', COALESCE("a"."歸屬編號", ' '), '/', "c"."產品名稱") AS "主旨", "c"."客戶編號", "c"."客戶名稱", "c"."產品編號", "c"."產品名稱", "c"."產品規格", "b"."文數字2" AS "試刷料號", COALESCE("f"."品名", ' ') AS "試刷料名稱", COALESCE("f"."規格", ' ') AS "試刷料規格", "b"."文數字4" AS "正式料號", COALESCE("g"."品名", ' ') AS "正式料名稱", COALESCE("g"."規格", ' ') AS "正式料規格", "b"."回簽" AS "打樣", "b"."logical4" AS "結束", "b"."logical5" AS "待補", "b"."logical6" AS "改件調機", "b"."數值11" AS "試刷料米數", "b"."logical1" AS "使用廢料試刷", "b"."付款方式" AS "看色人員", CASE WHEN "b"."付款方式" = '1' THEN '客戶' WHEN "b"."付款方式" = '2' THEN '副理' WHEN "b"."付款方式" = '3' THEN '營業' WHEN "b"."付款方式" = '4' THEN '自己' WHEN "b"."付款方式" = '5' THEN '其他' ELSE ' ' END AS "看色人員說明", "b"."文數字13" AS "其他看色人員", "b"."票期" AS "印刷色數", "b"."運輸方式" AS "頭出尾出", CASE WHEN "b"."運輸方式" = 'A' THEN '頭出' WHEN "b"."運輸方式" = 'B' THEN '尾出' WHEN "b"."運輸方式" = 'c' THEN '均可' ELSE ' ' END AS "頭出尾出說明", "b"."付款方式" AS "印刷面", CASE WHEN "b"."付款方式" = 'A' THEN '表刷' WHEN "b"."付款方式" = 'B' THEN '裡刷' WHEN "b"."付款方式" = 'C' THEN '霧化' ELSE ' ' END AS "印刷面說明", "b"."時間一" AS "開始時間", "b"."時間六" AS "收拾時間", "b"."時間五" AS "結束時間", "b"."時間四" AS "印刷時間", CASE WHEN "b"."時間三" = '000000' THEN 0 ELSE (TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間三" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間三"), 'yyyymmddhh24miss') - TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間二" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間二"), 'yyyymmddhh24miss')) * 24 END AS "看色耗時", CASE WHEN "b"."時間五" = '000000' THEN 0 ELSE (TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間五" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間五"), 'yyyymmddhh24miss') - TO_DATE(CONCAT(TRIM("a"."單據日期"), "b"."時間一"), 'yyyymmddhh24miss')) * 24 END AS "總耗時", TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間二" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間二"), 'yyyymmddhh24miss') AS "看色日時起", TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間三" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間三"), 'yyyymmddhh24miss') AS "看色日時迄", TO_DATE(CONCAT(TRIM("a"."單據日期"), "b"."時間一"), 'yyyymmddhh24miss') AS "開始日時", TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間五" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間五"), 'yyyymmddhh24miss') AS "結束日時", TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間六" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間六"), 'yyyymmddhh24miss') AS "停機日時", TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間四" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間四"), 'yyyymmddhh24miss') AS "印刷日時", "b"."數值3" AS "版銅圓周", "b"."聯絡人序號" AS "加工速度", "a"."簽核系統", "a"."備註", "a"."業務員" AS "作業人員", COALESCE("e"."員工姓名", ' ') AS "作業人員姓名", "a"."確認碼", "b"."logical3" AS "餘料回庫", "a"."倉庫代碼" AS "餘料回庫預設庫別", "a"."邏輯值一" AS "代客戶看色", "b"."logical9" AS "開始看色", "b"."logical10" AS "結束看色", "b"."logical13" AS "重印刷", "b"."時間二" AS "看色時間起", "b"."時間三" AS "看色時間迄", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態", COALESCE("b"."數量", 0) AS "生產數量", (CASE WHEN COALESCE("z4"."印刷色順一", ' ') = ' ' THEN 0 ELSE 1 END + CASE WHEN COALESCE("z4"."印刷色順二", ' ') = ' ' THEN 0 ELSE 1 END + CASE WHEN COALESCE("z4"."印刷色順三", ' ') = ' ' THEN 0 ELSE 1 END + CASE WHEN COALESCE("z4"."印刷色順四", ' ') = ' ' THEN 0 ELSE 1 END + CASE WHEN COALESCE("z4"."印刷色順五", ' ') = ' ' THEN 0 ELSE 1 END + CASE WHEN COALESCE("z4"."印刷色順六", ' ') = ' ' THEN 0 ELSE 1 END + CASE WHEN COALESCE("z4"."印刷色順七", ' ') = ' ' THEN 0 ELSE 1 END + CASE WHEN COALESCE("z4"."印刷色順八", ' ') = ' ' THEN 0 ELSE 1 END + CASE WHEN COALESCE("z4"."印刷色順九", ' ') = ' ' THEN 0 ELSE 1 END + CASE WHEN COALESCE("z4"."印刷色順十", ' ') = ' ' THEN 0 ELSE 1 END) AS "色順數", "a"."流水編號", "a"."填表人", "d"."單位主管流水編號", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", COALESCE("z1"."serial_num", ' ') AS "員工流水編號", "a"."填表日", COALESCE("j"."ccp筆數", 0) AS "ccp筆數", COALESCE("z5"."印刷米數", 0) AS "生產條件捲數", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "viewfil4030" AS "c" ON "a"."歸屬類別" = "c"."製令單別" AND "a"."歸屬編號" = "c"."製令單號" LEFT JOIN "viewfil310p" AS "d" ON "b"."機台代碼" = "d"."代碼" LEFT JOIN "fil0010" AS "e" ON "a"."業務員" = "e"."員工編號" LEFT JOIN "fil0012" AS "f" ON "b"."文數字2" = "f"."產品編號" LEFT JOIN "fil0012" AS "g" ON "b"."文數字4" = "g"."產品編號" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewofobjproperties" AS "z3" ON "a"."流水編號" = "z3"."單據流水號" LEFT JOIN (SELECT "a"."單別", "a"."單號", COUNT("序號") AS "ccp筆數" FROM "fil004i" AS "a" GROUP BY "a"."單別", "a"."單號") AS "j" ON "j"."單別" = "a"."單據類別" AND "j"."單號" = "a"."單據編號" LEFT JOIN "fil0033" AS "z4" ON "a"."歸屬類別" = "z4"."製令單別" AND "a"."歸屬編號" = "z4"."製令單號" AND "z4"."加工別" = "b"."交貨日期_次批" LEFT JOIN "fil0033" AS "z5" ON "a"."歸屬類別" = "z5"."製令單別" AND "a"."歸屬編號" = "z5"."製令單號" AND "z5"."加工別" = 'A' WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31A');

-- Home #1887 ViewFIL404A1B.印刷日報成本.C41
CREATE OR REPLACE VIEW "viewfil404a1b" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期" AS "作業日期", "a"."歸屬編號" AS "製令單號", "c"."訂單單號", "c"."產品編號", "b"."logical4" AS "結束", "b"."logical5" AS "待補", "b"."logical6" AS "改件調機", (CASE WHEN "a"."業務員" = ' ' THEN 0 ELSE 1 END + CASE WHEN "b"."文數字10" = ' ' THEN 0 ELSE 1 END + CASE WHEN "b"."文數字11" = ' ' THEN 0 ELSE 1 END + CASE WHEN "b"."文數字12" = ' ' THEN 0 ELSE 1 END) AS "加工人數", CASE WHEN "b"."時間五" = '000000' THEN 0 ELSE (TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間五" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間五"), 'yyyymmddhh24miss') - TO_DATE(CONCAT(TRIM("a"."單據日期"), "b"."時間一"), 'yyyymmddhh24miss')) * 24 END AS "總耗時", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態", "b"."製程代碼" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "viewfil4030" AS "c" ON "a"."歸屬類別" = "c"."製令單別" AND "a"."歸屬編號" = "c"."製令單號" LEFT JOIN "viewofobjproperties" AS "z3" ON "a"."流水編號" = "z3"."單據流水號" WHERE "a"."單據類別" = 'C41' AND ("b"."製程代碼" BETWEEN 'C31A' AND 'C31C' OR "b"."製程代碼" = 'C32D'));

-- Home #1888 ViewFIL404A1C.印刷日報簡檔.C41
CREATE OR REPLACE VIEW "viewfil404a1c" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期" AS "作業日期", "a"."歸屬編號" AS "製令單號", "b"."機台代碼", COALESCE("d"."名稱", ' ') AS "機台名稱", "c"."客戶編號", "c"."客戶名稱" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "viewfil4030" AS "c" ON "a"."歸屬類別" = "c"."製令單別" AND "a"."歸屬編號" = "c"."製令單號" LEFT JOIN "viewfil310p" AS "d" ON "b"."機台代碼" = "d"."代碼" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31A');

-- Home #1889 ViewFIL404A2.印刷日報明細
CREATE OR REPLACE VIEW "viewfil404a2" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動日期" AS "日期", "a"."前置單號" AS "前製程編號", "a"."異動數量" AS "領料米數", "a"."產品編號" AS "材料編號", "a"."異動單價" - "夾鏈費" AS "印刷米數", "a"."前置單別" AS "印刷處理面", "a"."廠客品號" AS "紙粗細面", "a"."折扣率" AS "圓周數值", "a"."異動金額" AS "引入張力", "a"."logical1" AS "版銅完整度", "a"."數值2" AS "不良標記數量", "a"."文數字1" AS "半成品編號", "a"."備註說明", "c"."批號", "a"."產品編號" AS "本製程編號", COALESCE("e"."品名", ' ') AS "品名", COALESCE("e"."規格", ' ') AS "規格", "a"."異動數量" AS "前製程米數", "a"."異動單價" AS "plc抓取米數", "a"."燙金費" AS "合理剔除數", "a"."毛重" AS "不良剔除數", "a"."贈品數量" AS "檢品數量", "a"."雷射費" AS "線外不良剔除數", "a"."夾鏈費" AS "線內不良剔除數", "a"."氣閥費" AS "試刷米數", "c"."文數字4" AS "前製程條碼", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN "viewfil310p" AS "d" ON "b"."機台代碼" = "d"."代碼" LEFT JOIN "fil0012" AS "e" ON "a"."產品編號" = "e"."產品編號" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31A' AND "d"."印刷上蠟版銅" = 0);

-- Home #1890 ViewFIL404A2A.印刷日報明細結餘
CREATE OR REPLACE VIEW "viewfil404a2a" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動類別", "a"."產品編號" AS "本製程編號", "a"."鐵條費" AS "序號1", "a"."前製程編號", "a"."數值1" AS "結餘數", "a"."異動單價" AS "plc抓取米數", "a"."其它日期" AS "plc抓取日", "a"."最後更新日" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN "viewfil310p" AS "d" ON "b"."機台代碼" = "d"."代碼" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31A' AND "c"."檢驗外觀" < 'B' AND "d"."印刷上蠟版銅" = 0);

-- Home #1891 ViewFIL404A3.印刷油墨色順
CREATE OR REPLACE VIEW "viewfil404a3" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."數值1" AS "色順", "a"."廠客品號" AS "色順名稱", "a"."預交日" AS "調色日期", "b"."批號", "a"."產品編號" AS "材料編號", COALESCE("c"."品名", ' ') AS "品名", COALESCE("c"."規格", ' ') AS "規格", "a"."文數字1" AS "油墨配比", "d1"."歸屬類別" AS "製令單別", "d1"."歸屬編號" AS "製令單號", "c1"."客戶編號", "c1"."客戶名稱", "c1"."產品編號", "c1"."產品名稱", "c1"."產品規格", "a"."備註說明", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" INNER JOIN "fil0030" AS "d1" ON "a"."單據類別" = "d1"."單據類別" AND "a"."單據編號" = "d1"."單據編號" LEFT JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" LEFT JOIN "fil0012" AS "c" ON "a"."產品編號" = "c"."產品編號" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" INNER JOIN "viewfil4030" AS "c1" ON "d1"."歸屬類別" = "c1"."製令單別" AND "d1"."歸屬編號" = "c1"."製令單號" WHERE "a"."單據類別" = 'C41' AND "d"."製程代碼" = 'C31A' AND "a"."異動類別" = 'B');

-- Home #1893 ViewFIL404A4.上蠟日報主檔.C32D
CREATE OR REPLACE VIEW "viewfil404a4" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期" AS "作業日期", "a"."歸屬類別" AS "製令單別", "a"."歸屬編號" AS "製令單號", "c"."公司代碼", "c"."公司名稱", "c"."訂單單別", "c"."訂單單號", "b"."機台代碼", COALESCE("d"."名稱", ' ') AS "機台名稱", CASE WHEN "b"."交貨日期_次批" = 'A' THEN 'A材' WHEN "b"."交貨日期_次批" = 'B' THEN 'B材' WHEN "b"."交貨日期_次批" = 'C' THEN '底邊' WHEN "b"."交貨日期_次批" = 'D' THEN 'A側' WHEN "b"."交貨日期_次批" = 'E' THEN 'B側' ELSE ' ' END AS "加工別", "b"."交貨日期_天" AS "本日件數順序", CONCAT("a"."單據編號", '(', TRIM("a"."單據類別"), ')', '/製令:', COALESCE("a"."歸屬編號", ' '), '/', "c"."產品名稱") AS "主旨", "c"."客戶編號", "c"."客戶名稱", "c"."產品編號", "c"."產品名稱", "c"."產品規格", "b"."運輸方式" AS "頭出尾出", CASE WHEN "b"."運輸方式" = 'A' THEN '頭出' WHEN "b"."運輸方式" = 'B' THEN '尾出' WHEN "b"."運輸方式" = 'c' THEN '均可' ELSE ' ' END AS "頭出尾出說明", "b"."文字1" AS "蠟名稱", "a"."匯率日期" AS "蠟進貨日期", "b"."時間一" AS "開始時間", "b"."時間五" AS "結束時間", "b"."時間二" AS "溶蠟時間", CASE WHEN "b"."時間二" = '000000' THEN 0 ELSE (TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間二" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間二"), 'yyyymmddhh24miss') - TO_DATE(CONCAT(TRIM("a"."單據日期"), "b"."時間一"), 'yyyymmddhh24miss')) * 24 END AS "前置耗時", CASE WHEN "b"."時間五" = '000000' THEN 0 ELSE (TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間五" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間五"), 'yyyymmddhh24miss') - TO_DATE(CONCAT(TRIM("a"."單據日期"), "b"."時間一"), 'yyyymmddhh24miss')) * 24 END AS "總耗時", "b"."聯絡人序號" AS "加工速度", "a"."簽核系統", "a"."備註", "a"."業務員" AS "作業人員", COALESCE("e"."員工姓名", ' ') AS "作業人員姓名", "a"."確認碼", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態", "b"."logical4" AS "結束", "b"."logical5" AS "待補", "b"."logical6" AS "改件調機", COALESCE("z5"."印刷米數", 0) AS "生產條件捲數", "a"."流水編號", "a"."填表人", "d"."單位主管流水編號", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", COALESCE("z1"."serial_num", ' ') AS "員工流水編號", "a"."填表日", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "viewfil4030" AS "c" ON "a"."歸屬類別" = "c"."製令單別" AND "a"."歸屬編號" = "c"."製令單號" LEFT JOIN "viewfil310p" AS "d" ON "b"."機台代碼" = "d"."代碼" LEFT JOIN "fil0010" AS "e" ON "a"."業務員" = "e"."員工編號" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewofobjproperties" AS "z3" ON "a"."流水編號" = "z3"."單據流水號" LEFT JOIN "fil0033" AS "z5" ON "a"."歸屬類別" = "z5"."製令單別" AND "a"."歸屬編號" = "z5"."製令單號" AND "z5"."加工別" = 'A' WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C32D');

-- Home #1894 ViewFIL404A5.上蠟日報明細
CREATE OR REPLACE VIEW "viewfil404a5" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動日期" AS "日期", "a"."前製程編號" AS "前製程編號顯示", "a"."前置單號" AS "前製程編號", "a"."異動數量" AS "領料米數", "a"."產品編號" AS "本製程編號", "a"."異動單價" AS "上蠟米數", "a"."qrno" AS "接頭數量", "a"."燙金費" AS "合理剔除數", "a"."雷射費" AS "線內不良數", "a"."夾鏈費" AS "線外不良數", "a"."毛重" AS "不良剔除數", "a"."數值1" AS "本筆結餘", "a"."異動金額" AS "上蠟前厚度", "a"."數值2" AS "上蠟前重量", "a"."數值3" AS "上蠟後厚度", "a"."數值4" AS "上蠟後重量", "a"."數值5" AS "塗佈量", "a"."材積" AS "前製程接頭數", "a"."折讓" AS "蠟槽溫度", "a"."製版費" AS "前冷卻輪溫度", "a"."氣閥費" AS "後冷卻輪溫度", "a"."鐵條費" AS "壓胴壓力kg", "a"."前置單別" AS "反頂", CASE WHEN "a"."前置單別" = 'L' THEN '左' WHEN "a"."前置單別" = 'R' THEN '右' WHEN "a"."前置單別" = 'B' THEN '均有' ELSE '無' END AS "反頂說明", "a"."相關代碼1" AS "網點清晰度", "a"."文數字1" AS "半成品編號", "f"."文數字4" AS "前製程條碼", "a"."單位代碼", COALESCE("d"."名稱", ' ') AS "單位名稱", "a"."倉庫代碼" AS "庫別代碼", COALESCE("e"."名稱", ' ') AS "庫別名稱", "a"."備註說明", "a"."結案碼", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "f" ON "a"."單據類別" = "f"."單別" AND "a"."單據編號" = "f"."單號" AND "a"."單據序號" = "f"."序號" LEFT JOIN "viewfil310p" AS "c" ON "b"."機台代碼" = "c"."代碼" LEFT JOIN "viewfil3103" AS "d" ON "a"."單位代碼" = "d"."代碼" LEFT JOIN "viewfil3106" AS "e" ON "a"."倉庫代碼" = "e"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C32D' AND "c"."印刷上蠟版銅" = 1);

-- Home #1896 ViewFIL404A6.版銅日報主檔.C41
CREATE OR REPLACE VIEW "viewfil404a6" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期" AS "作業日期", CONCAT("a"."單據編號", '(', TRIM("a"."單據類別"), ')') AS "主旨", "a"."公司代碼", COALESCE("e"."名稱", ' ') AS "公司名稱", "b"."製程代碼", "b"."機台代碼", COALESCE("d"."名稱", ' ') AS "機台名稱", "a"."備註", "a"."業務員" AS "作業人員", COALESCE("c"."員工姓名", ' ') AS "作業人員姓名", "a"."確認碼", COALESCE("f"."製令單號", ' ') AS "製令單號", "a"."簽核系統", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態", "a"."流水編號", "a"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "a"."填表日", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0030" AS "a" /* 特殊欄位 */ INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" /* */ LEFT JOIN "fil0010" AS "c" ON "a"."業務員" = "c"."員工編號" LEFT JOIN "viewfil310p" AS "d" ON "b"."機台代碼" = "d"."代碼" LEFT JOIN "viewfil0011" AS "e" ON "a"."公司代碼" = "e"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewofobjproperties" AS "z3" ON "a"."流水編號" = "z3"."單據流水號" LEFT JOIN (SELECT "a"."單據類別", "a"."單據編號", STRING_AGG(CAST(CAST(TRIM("a"."前置單號") AS TEXT) AS TEXT), ',' ORDER BY "a"."單據序號") AS "製令單號" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C32E' GROUP BY "a"."單據類別", "a"."單據編號") AS "f" ON "f"."單據類別" = "a"."單據類別" AND "f"."單據編號" = "a"."單據編號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C32E' AND "d"."印刷上蠟版銅" = 2);

-- Home #1897 ViewFIL404A7.版銅日報明細
CREATE OR REPLACE VIEW "viewfil404a7" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動日期" AS "日期", "a"."前置單別" AS "製令單別", "a"."前置單號" AS "製令單號", "d"."前置單號" AS "對應製令單號", "f"."共版", "f"."版長", "f"."圓周", "a"."產品編號" AS "版銅代碼", COALESCE("d"."產品編號", ' ') AS "產品編號", COALESCE("d"."產品名稱", ' ') AS "產品名稱", COALESCE("f"."規格", ' ') AS "產品規格", COALESCE("f"."說明", ' ') AS "說明", "a"."單位代碼" AS "取版回收", CASE WHEN "a"."單位代碼" = 'A' THEN '取版' WHEN "a"."單位代碼" = 'B' THEN '回收' ELSE ' ' END AS "取版或回收", "a"."logical1" AS "印刷色數", "a"."logical2" AS "內容校對", "a"."logical3" AS "清潔度", "a"."備註說明" AS "不良原因", "a"."異動金額" AS "不良版序", "a"."結案碼" AS "處置", CASE WHEN "a"."結案碼" = 'A' THEN '重製' WHEN "a"."結案碼" = 'B' THEN '重鍍' ELSE ' ' END AS "處置說明", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "viewfil310p" AS "c" ON "b"."機台代碼" = "c"."代碼" /* 製令 */ INNER JOIN "fil0032" AS "d" ON "a"."前置單別" = "d"."製令單別" AND "a"."前置單號" = "d"."製令單號" /* 版銅 */ LEFT JOIN "viewfil3112" AS "f" ON "a"."產品編號" = "f"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C32E' AND "c"."印刷上蠟版銅" = 2);

-- Home #1898 ViewFIL404A8.製令版銅日報
CREATE OR REPLACE VIEW "viewfil404a8" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "d"."單據序號" AS "序號", "a"."單據日期" AS "作業日期", "b"."機台代碼", COALESCE("c"."名稱", ' ') AS "機台名稱", "d"."前置單別" AS "製令單別", "d"."前置單號" AS "製令單號", "d"."產品編號" AS "對應製令單號" FROM "fil0030" AS "a" /* 特殊欄位 */ INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" /* */ LEFT JOIN "viewfil310p" AS "c" ON "b"."機台代碼" = "c"."代碼" /* 檢品明細 */ INNER JOIN "fil0040" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" AND "d"."異動類別" = 'A' WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C32E' AND "c"."印刷上蠟版銅" = 2);

-- Home #1899 ViewFIL404A9.版銅製令簽收
CREATE OR REPLACE VIEW "viewfil404a9" AS (SELECT "a"."單別", "a"."單號", "a"."製令", CASE WHEN COALESCE("dbms_lob".getlength("b"."圖檔"), 0) = 0 THEN 0 ELSE 1 END AS "簽收", "b"."代碼" AS "簽收人", COALESCE("c"."員工姓名", ' ') AS "簽收人姓名" FROM (SELECT DISTINCT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."前置單號" AS "製令" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "viewfil310p" AS "c" ON "b"."機台代碼" = "c"."代碼" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "a"."單位代碼" = 'A' AND /* 取版 */ "b"."製程代碼" = 'C32E' AND "c"."印刷上蠟版銅" = 2) AS "a" LEFT JOIN "fil0037" AS "b" ON "a"."單別" = "b"."製令單別" AND "a"."單號" = "b"."製令單號" AND "b"."材料序號" = 0 AND "a"."製令" = "b"."屬性" LEFT JOIN "fil0010" AS "c" ON "b"."代碼" = "c"."員工編號");

-- Home #1907 ViewFIL404B1.淋膜日報主檔.C41
CREATE OR REPLACE VIEW "viewfil404b1" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期" AS "作業日期", "a"."歸屬類別" AS "製令單別", "a"."歸屬編號" AS "製令單號", CASE WHEN "b"."交貨日期_次批" = 'A' THEN 'A材' WHEN "b"."交貨日期_次批" = 'B' THEN 'B材' WHEN "b"."交貨日期_次批" = 'C' THEN '底邊' WHEN "b"."交貨日期_次批" = 'D' THEN 'A側' WHEN "b"."交貨日期_次批" = 'E' THEN 'B側' ELSE ' ' END AS "加工別", CONCAT("a"."單據編號", '(', TRIM("a"."單據類別"), ')', '/製令:', COALESCE("a"."歸屬編號", ' '), '/', "c"."產品名稱") AS "主旨", "c"."公司代碼", "c"."公司名稱", "c"."訂單單別", "c"."訂單單號", "b"."機台代碼", COALESCE("d"."名稱", ' ') AS "機台名稱", "b"."交貨日期_天" AS "本日件數順序", "c"."客戶編號", "c"."客戶名稱", "c"."產品編號", "c"."產品名稱", "c"."產品規格", "b"."logical4" AS "待補", "b"."logical5" AS "結束", "b"."logical6" AS "改件調機", "b"."回簽" AS "側", "b"."材料編號一" AS "基材", 0 AS "打樣", COALESCE("z5"."印刷米數", 0) AS "生產條件捲數", COALESCE("f"."品名", ' ') AS "基材名稱", COALESCE("f"."規格", ' ') AS "基材規格", "b"."材料編號二" AS "中間材", COALESCE("g"."品名", ' ') AS "中間材名稱", COALESCE("g"."規格", ' ') AS "中間材規格", "b"."材料編號三" AS "副材", COALESCE("h"."品名", ' ') AS "副材名稱", COALESCE("h"."規格", ' ') AS "副材規格", TO_CHAR(CASE WHEN "b"."時間四" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd') AS "貼合日期", "b"."時間一" AS "開始時間", "b"."時間二" AS "接班時間", "b"."時間三" AS "損耗時間", "b"."時間四" AS "貼合時間", "b"."時間五" AS "結束時間", "b"."時間六" AS "收拾時間", CASE WHEN "b"."時間四" = '000000' THEN 0 ELSE (TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間四" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間四"), 'yyyymmddhh24miss') - TO_DATE(CONCAT(TRIM("a"."單據日期"), "b"."時間一"), 'yyyymmddhh24miss')) * 24 END AS "前置耗時", CASE WHEN "b"."時間五" = '000000' THEN 0 ELSE (TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間五" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間五"), 'yyyymmddhh24miss') - TO_DATE(CONCAT(TRIM("a"."單據日期"), "b"."時間一"), 'yyyymmddhh24miss')) * 24 END AS "總耗時", "b"."訂金" AS "損耗人員", "b"."票期" AS "貼合人員", "b"."送貨地址序號" AS "結束人員", "b"."聯絡人序號" AS "收拾人員", "b"."數量" AS "貼合速度", "b"."數值1" AS "冷卻輪溫度", "b"."數值2" AS "版目前", "b"."數值3" AS "版目後", "b"."數值4" AS "配比1", "b"."數值5" AS "配比2", "b"."數值6" AS "配比3", "b"."數值7" AS "配比4", "b"."數值8" AS "配比5", "b"."數值9" AS "配比6", "b"."文字1" AS "前槽接著劑", "b"."文字2" AS "前槽硬化劑", "b"."文字3" AS "前槽溶劑", "b"."文字4" AS "後槽接著劑", "b"."文字5" AS "後槽硬化劑", "b"."文字6" AS "後槽溶劑", "a"."簽核系統", "a"."備註", "a"."業務員" AS "作業人員", COALESCE("e"."員工姓名", ' ') AS "作業人員姓名", "a"."確認碼", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態", "a"."流水編號", "a"."填表人", "d"."單位主管流水編號", COALESCE("z1"."serial_num", ' ') AS "員工流水編號", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "a"."填表日", COALESCE("j"."ccp筆數", 0) AS "ccp筆數", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日", "a"."採購單號" AS "沿用單號" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" /* 製令 */ INNER JOIN "viewfil4030" AS "c" ON "a"."歸屬類別" = "c"."製令單別" AND "a"."歸屬編號" = "c"."製令單號" LEFT JOIN "viewfil310p" AS "d" ON "b"."機台代碼" = "d"."代碼" LEFT JOIN "fil0010" AS "e" ON "a"."業務員" = "e"."員工編號" LEFT JOIN "fil0012" AS "f" ON "b"."材料編號一" = "f"."產品編號" LEFT JOIN "fil0012" AS "g" ON "b"."材料編號二" = "g"."產品編號" LEFT JOIN "fil0012" AS "h" ON "b"."材料編號三" = "h"."產品編號" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewofobjproperties" AS "z3" ON "a"."流水編號" = "z3"."單據流水號" LEFT JOIN "fil0033" AS "z5" ON "a"."歸屬類別" = "z5"."製令單別" AND "a"."歸屬編號" = "z5"."製令單號" AND "z5"."加工別" = 'A' LEFT JOIN (SELECT "a"."單別", "a"."單號", COUNT("序號") AS "ccp筆數" FROM "fil004i" AS "a" GROUP BY "a"."單別", "a"."單號") AS "j" ON "j"."單別" = "a"."單據類別" AND "j"."單號" = "a"."單據編號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31B');

