CREATE OR REPLACE VIEW "viewfil404e1_b" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期" AS "作業日期", "b"."交貨日期" AS "製造日期", "a"."歸屬類別" AS "製令單別", "a"."歸屬編號" AS "製令單號", "b"."機台代碼", "b"."logical4" AS "結束", "b"."logical5" AS "待補", "b"."數值16" AS "紙箱_無氣閥_每束幾袋", "b"."數值17" AS "紙箱_無氣閥_每箱幾袋", "b"."文數字7" AS "紙箱代碼1", "b"."數值18" AS "紙箱_氣閥_每束幾袋", "b"."數值19" AS "紙箱_氣閥_每箱幾袋", "b"."文數字8" AS "紙箱代碼2", "b"."文數字12" AS "尾數紙箱", "b"."文數字4" AS "抬頭1", "b"."文數字5" AS "抬頭2", "b"."文數字6" AS "抬頭3", "b"."文數字9" AS "待補日報號碼", "c1"."加工項目_氣閥代碼" AS "氣閥代碼", "c1"."加工項目_鐵條代碼" AS "鐵條代碼", "a"."業務員" AS "作業人員", "b"."文數字10" AS "作業員二", "b"."文數字11" AS "作業員三" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "viewfil4030" AS "c" ON "a"."歸屬類別" = "c"."製令單別" AND "a"."歸屬編號" = "c"."製令單號" INNER JOIN "fil0032" AS "c1" ON "a"."歸屬類別" = "c1"."製令單別" AND "a"."歸屬編號" = "c1"."製令單號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31E');

-- Home #1946 ViewFIL404E1D.製袋日報主檔.C41
CREATE OR REPLACE VIEW "viewfil404e1_d" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期" AS "作業日期", "a"."歸屬類別" AS "製令單別", "a"."歸屬編號" AS "製令單號", "c"."公司代碼", "c"."公司名稱", "c"."訂單單別", "c"."訂單單號", "b"."機台代碼", COALESCE("d"."名稱", ' ') AS "機台名稱", "b"."交貨日期_天" AS "本日件數順序", CONCAT("a"."單據編號", '(', TRIM("a"."單據類別"), ')', '/製令:', COALESCE("a"."歸屬編號", ' '), '/', "c"."產品名稱") AS "主旨", "c"."客戶編號", "c"."客戶名稱", "c"."產品編號", "c"."產品名稱", "c"."產品規格", "b"."logical3" AS "改件調機", "b"."logical4" AS "結束", "b"."logical5" AS "待補", "b"."時間一" AS "開始時間", "b"."時間五" AS "結束時間", "a"."簽核系統", "a"."備註", "a"."業務員" AS "作業人員", COALESCE("e"."員工姓名", ' ') AS "作業人員姓名", "b"."文數字10" AS "作業員二", COALESCE("g"."員工姓名", ' ') AS "作業員二姓名", "b"."文數字11" AS "作業員三", COALESCE("h"."員工姓名", ' ') AS "作業員三姓名", "a"."確認碼", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態", "a"."邏輯值一" AS "雙膜", "a"."流水編號", "a"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "d"."單位主管流水編號", COALESCE("z1"."serial_num", ' ') AS "員工流水編號", "a"."填表日" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "viewfil4030" AS "c" ON "a"."歸屬類別" = "c"."製令單別" AND "a"."歸屬編號" = "c"."製令單號" LEFT JOIN "viewfil310p" AS "d" ON "b"."機台代碼" = "d"."代碼" LEFT JOIN "fil0010" AS "e" ON "a"."業務員" = "e"."員工編號" LEFT JOIN "fil0010" AS "g" ON "b"."文數字10" = "g"."員工編號" LEFT JOIN "fil0010" AS "h" ON "b"."文數字11" = "h"."員工編號" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewofobjproperties" AS "z3" ON "a"."流水編號" = "z3"."單據流水號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31E');

-- Home #2046 ViewFIL404E3_S1.成品異動品檢前
CREATE OR REPLACE VIEW "viewfil404e3_s1" AS (SELECT "d"."歸屬編號" AS "製令單號", "a"."異動數量" AS "箱號", COALESCE(CASE WHEN "c"."製程代碼" = 'C31E' THEN CASE WHEN "b"."數值14" = 0 THEN "a"."贈品數量" ELSE "b"."數值14" END ELSE "b"."數值5" * -1 END, 0) AS "數量", 0 AS "報廢數量", COALESCE(CASE WHEN "c"."製程代碼" = 'C31E' THEN CASE WHEN "b"."數值14" = 0 THEN "a"."毛重" ELSE "a"."毛重" * (CAST("b"."數值14" AS DOUBLE PRECISION) / "a"."贈品數量") END ELSE "b"."數值5" * -1 * "g"."平均袋重" END, 0) AS "重量", CONCAT("d"."歸屬編號", '-', TRIM(TO_CHAR("a"."異動數量", '0000'))) AS "批號", 1 AS "製袋", CASE WHEN "c"."製程代碼" = 'C31F' THEN 1 ELSE 0 END AS "氣閥", CASE WHEN "c"."製程代碼" = 'C31G' THEN 1 ELSE 0 END AS "鐵條", 0 AS "異動", 0 AS "重工", 0 AS "出貨", 0 AS "品檢", CASE WHEN "c"."製程代碼" = 'C31E' THEN TO_NCHAR('製袋') WHEN "c"."製程代碼" = 'C31G' THEN TO_NCHAR('鐵條') ELSE TO_NCHAR('氣閥') END AS "來源", "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" LEFT JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" LEFT JOIN "viewfil404e7" AS "g" ON "d"."歸屬類別" = "g"."製令單別" AND "d"."歸屬編號" = "g"."製令單號" AND "a"."異動數量" = "g"."箱號" WHERE "a"."異動類別" = 'A' AND ("c"."製程代碼" = 'C31E' OR "c"."製程代碼" = 'C31F' OR "c"."製程代碼" = 'C31G') UNION ALL SELECT "a"."廠客品號" AS "製令單號", "a"."異動數量" AS "箱號", COALESCE(CASE WHEN "a"."單據類別" = 'E35' THEN "a"."贈品數量" * -1 WHEN "a"."單據類別" = 'E37' THEN "b"."數值5" * -1 ELSE "a"."贈品數量" END, 0) AS "數量", COALESCE(CASE WHEN "a"."單據類別" = 'E33' THEN "b"."數值5" ELSE 0 END, 0), COALESCE(CASE WHEN "a"."單據類別" = 'E35' THEN ("a"."贈品數量" * -1 * "j"."平均袋重") WHEN "a"."單據類別" = 'E37' THEN ("b"."數值5" * -1 * "j"."平均袋重") ELSE "a"."毛重" END, 0) AS "重量", "b"."批號" AS "批號", 1 AS "製袋", "b"."logical2" AS "氣閥", "b"."logical3" AS "鐵條", CASE WHEN "a"."單據類別" = 'E32' THEN 1 ELSE 0 END AS "異動", CASE WHEN "a"."單據類別" = 'E33' THEN 1 ELSE 0 END AS "重工", CASE WHEN "a"."單據類別" = 'E35' THEN 1 ELSE 0 END AS "重工", CASE WHEN "a"."單據類別" = 'E37' THEN 1 ELSE 0 END AS "品檢", CASE WHEN "a"."單據類別" = 'E32' THEN TO_NCHAR('異動') WHEN "a"."單據類別" = 'E33' THEN TO_NCHAR('重工') WHEN "a"."單據類別" = 'E35' THEN TO_NCHAR('出貨') ELSE TO_NCHAR('品檢') END AS "來源", "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" LEFT JOIN "viewfil404e7" AS "j" ON CAST('C11' AS TEXT) = "j"."製令單別" AND "a"."廠客品號" = "j"."製令單號" AND "a"."異動數量" = "j"."箱號" WHERE "a"."單據類別" = 'E32' OR "a"."單據類別" = 'E33' OR "a"."單據類別" = 'E35');

-- Home #2054 ViewFIL404E4_S1.成品品檢前合計
CREATE OR REPLACE VIEW "viewfil404e4_s1" AS (SELECT "a"."批號" AS "批號", CASE WHEN SUM("製袋") = 0 THEN 0 ELSE 1 END AS "製袋", CASE WHEN SUM("氣閥") = 0 THEN 0 ELSE 1 END AS "氣閥", CASE WHEN SUM("鐵條") = 0 THEN 0 ELSE 1 END AS "鐵條", CASE WHEN SUM("異動") = 0 THEN 0 ELSE 1 END AS "異動", CASE WHEN SUM("重工") = 0 THEN 0 ELSE 1 END AS "重工", CASE WHEN SUM("出貨") = 0 THEN 0 ELSE 1 END AS "出貨", CASE WHEN SUM("品檢") = 0 THEN 0 ELSE 1 END AS "品檢", MAX("a"."箱號") AS "箱號", SUM("a"."數量") AS "數量", SUM("a"."報廢數量") AS "報廢數量", SUM("a"."數量" * CASE WHEN COALESCE("c"."平均袋重", 0) = 0 THEN COALESCE("b"."平均袋重", 0) ELSE COALESCE("c"."平均袋重", 0) END) AS "重量", CASE WHEN SUM("a"."數量") = 0 THEN 0 ELSE CAST(SUM("a"."數量" * CASE WHEN COALESCE("c"."平均袋重", 0) = 0 THEN COALESCE("b"."平均袋重", 0) ELSE COALESCE("c"."平均袋重", 0) END) AS DOUBLE PRECISION) / SUM("a"."數量") END AS "平均重量" FROM "viewfil404e3_s1" AS "a" LEFT JOIN "viewfil404e7" AS "b" ON "a"."製令單號" = "b"."製令單號" AND "a"."箱號" = "b"."箱號" LEFT JOIN "viewfil404e8" AS "c" ON "a"."製令單號" = "c"."製令單號" AND "a"."箱號" = "c"."箱號" GROUP BY "a"."批號");

-- Home #2061 ViewFIL404E4_T.成品數量合計
CREATE OR REPLACE VIEW "viewfil404e4_t" AS (SELECT "a"."批號", SUM("a"."數量") AS "數量", SUM("a"."數量" * CASE WHEN COALESCE("b"."平均袋重", 0) = 0 THEN "c"."平均袋重" ELSE "b"."平均袋重" END) AS "製袋重量", AVG(CASE WHEN COALESCE("b"."平均袋重", 0) = 0 THEN "c"."平均袋重" ELSE "b"."平均袋重" END) AS "平均袋重" FROM (SELECT CONCAT("d"."歸屬編號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))) AS "批號", SUM(COALESCE(CASE WHEN "b"."數值14" = 0 THEN "a"."贈品數量" ELSE "b"."數值14" END, 0)) AS "數量", SUM(COALESCE(CASE WHEN "b"."數值14" = 0 THEN "a"."毛重" ELSE "a"."毛重" * CASE WHEN "a"."贈品數量" = 0 THEN 0 ELSE (CAST("b"."數值14" AS DOUBLE PRECISION) / "a"."贈品數量") END END, 0)) AS "重量" FROM "fil0040" AS "a", "fil0041" AS "b", "fil0031" AS "c", "fil0030" AS "d" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" = 'C31E' AND "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" AND "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" GROUP BY CONCAT("d"."歸屬編號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))) UNION ALL SELECT CONCAT("d"."歸屬編號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))) AS "批號", SUM(COALESCE(("b"."數值5" + "a"."燙金費") * -1, 0)) AS "數量", 0 AS "重量" FROM "fil0040" AS "a", "fil0041" AS "b", "fil0031" AS "c", "fil0030" AS "d" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" = 'C31F' AND "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" AND "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" GROUP BY CONCAT("d"."歸屬編號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))) UNION ALL SELECT CONCAT("d"."歸屬編號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))) AS "批號", SUM(COALESCE(("b"."數值5" + "a"."燙金費") * -1, 0)) AS "數量", 0 AS "重量" FROM "fil0040" AS "a", "fil0041" AS "b", "fil0031" AS "c", "fil0030" AS "d" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" = 'C31G' AND "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" AND "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" GROUP BY CONCAT("d"."歸屬編號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))) UNION ALL SELECT CONCAT("a"."廠客品號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))) AS "批號", SUM(COALESCE("a"."贈品數量", 0)) AS "數量", SUM(COALESCE("a"."毛重", 0)) AS "重量" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" WHERE "a"."單據類別" = 'E32' GROUP BY CONCAT("a"."廠客品號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))) UNION ALL SELECT CONCAT("a"."廠客品號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))) AS "批號", SUM(COALESCE("a"."贈品數量", 0)) AS "數量", SUM(COALESCE("a"."毛重", 0)) AS "重量" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" WHERE "a"."單據類別" = 'E33' GROUP BY CONCAT("a"."廠客品號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))) UNION ALL SELECT CONCAT("a"."廠客品號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))) AS "批號", SUM(COALESCE("b"."數值5", 0)) AS "數量", SUM(COALESCE(CASE WHEN "b"."數值5" = 0 THEN 0 ELSE "b"."數值5" * (CASE WHEN "a"."贈品數量" = 0 THEN 0 ELSE CAST("a"."毛重" AS DOUBLE PRECISION) / "a"."贈品數量" END) END, 0)) AS "重量" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" WHERE "a"."單據類別" = 'E33' GROUP BY CONCAT("a"."廠客品號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))) UNION ALL SELECT CONCAT("a"."廠客品號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))) AS "批號", SUM(("a"."贈品數量" - COALESCE("b"."數值1", 0)) + COALESCE("b"."數值5" * -1, 0)) AS "數量", 0 AS "重量" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" WHERE "a"."單據類別" = 'E37' GROUP BY CONCAT("a"."廠客品號", '-', TRIM(TO_CHAR("a"."異動數量", '0009')))) AS "a" LEFT JOIN "viewfil404e71" AS "b" ON "a"."批號" = "b"."批號" LEFT JOIN "viewfil404e81" AS "c" ON "a"."批號" = "c"."批號" GROUP BY "a"."批號");

-- Home #1952 ViewFIL404EB.製袋日報業務員
CREATE OR REPLACE VIEW "viewfil404eb" AS (SELECT "a"."單別", "a"."單號", "c"."單據日期", "b"."機台代碼", COALESCE("f"."名稱", ' ') AS "機台名稱", "c"."歸屬類別" AS "製令單別", "c"."歸屬編號" AS "製令單號", "a"."作業人員", "a"."作業人員姓名", "a"."作業人數", CAST("d"."繳庫總袋數" AS DOUBLE PRECISION) / "a"."作業人數" AS "繳庫總袋數", CAST("d"."繳庫總袋數_箱數" AS DOUBLE PRECISION) / "a"."作業人數" AS "繳庫總箱數", CAST("d"."報廢數" AS DOUBLE PRECISION) / "a"."作業人數" AS "報廢數", "d"."不良剔除後成品率", "b"."數值1" AS "製袋速度", "e"."產品編號", "e"."產品名稱", "e"."產品規格" FROM (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", CAST(COALESCE("a"."業務員", ' ') AS TEXT) AS "作業人員", CAST(COALESCE("e"."員工姓名", ' ') AS TEXT) AS "作業人員姓名", CASE WHEN "a"."業務員" = ' ' THEN 0 ELSE 1 END + CASE WHEN "b"."文數字10" = ' ' THEN 0 ELSE 1 END + CASE WHEN "b"."文數字11" = ' ' THEN 0 ELSE 1 END AS "作業人數" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0010" AS "e" ON "a"."業務員" = "e"."員工編號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31E' AND "a"."業務員" <> ' ' UNION SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", CAST(COALESCE("b"."文數字10", ' ') AS TEXT) AS "作業人員", CAST(COALESCE("e"."員工姓名", ' ') AS TEXT) AS "作業人員姓名", CASE WHEN "a"."業務員" = ' ' THEN 0 ELSE 1 END + CASE WHEN "b"."文數字10" = ' ' THEN 0 ELSE 1 END + CASE WHEN "b"."文數字11" = ' ' THEN 0 ELSE 1 END AS "作業人數" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0010" AS "e" ON "b"."文數字10" = "e"."員工編號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31E' AND "b"."文數字10" <> ' ' UNION SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", CAST(COALESCE("b"."文數字11", ' ') AS TEXT) AS "作業人員", CAST(COALESCE("e"."員工姓名", ' ') AS TEXT) AS "作業人員姓名", CASE WHEN "a"."業務員" = ' ' THEN 0 ELSE 1 END + CASE WHEN "b"."文數字10" = ' ' THEN 0 ELSE 1 END + CASE WHEN "b"."文數字11" = ' ' THEN 0 ELSE 1 END AS "作業人數" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0010" AS "e" ON "b"."文數字11" = "e"."員工編號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31E' AND "b"."文數字11" <> ' ') AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單別" = "b"."單別" AND "a"."單號" = "b"."單號" INNER JOIN "fil0030" AS "c" ON "a"."單別" = "c"."單據類別" AND "a"."單號" = "c"."單據編號" INNER JOIN "viewfil404ea" AS "d" ON "a"."單別" = "d"."單別" AND "a"."單號" = "d"."單號" INNER JOIN "viewfil4030" AS "e" ON "c"."歸屬類別" = "e"."製令單別" AND "c"."歸屬編號" = "e"."製令單號" LEFT JOIN "viewfil310p" AS "f" ON "b"."機台代碼" = "f"."代碼");

-- Home #1953 ViewFIL404EC.製袋日報分析主檔
CREATE OR REPLACE VIEW "viewfil404ec" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期" AS "作業日期", "a"."歸屬類別" AS "製令單別", "a"."歸屬編號" AS "製令單號", "b"."機台代碼", COALESCE("d"."名稱", ' ') AS "機台名稱", "f"."客戶編號", "f"."客戶名稱", "f"."產品編號", "f"."產品名稱", "f"."產品規格", TO_TIMESTAMP(CONCAT("a"."單據日期", ' ', CASE WHEN "b"."時間一" < '000000' OR "b"."時間一" > '235959' THEN '000000' ELSE "b"."時間一" END), 'syyyymmdd hh24:mi:ss') AS "開始時間", TO_TIMESTAMP(CONCAT(CASE WHEN "b"."時間一" > "b"."時間二" THEN TO_CHAR(TO_DATE("a"."單據日期", 'yyyymmdd') + 1, 'yyyymmdd') ELSE "a"."單據日期" END, ' ', CASE WHEN "b"."時間二" < '000000' OR "b"."時間二" > '235959' THEN '000000' ELSE "b"."時間二" END), 'syyyymmdd hh24:mi:ss') AS "結束時間", CASE WHEN COALESCE("d"."委外", 0) = 0 THEN '廠內' ELSE '委外' END AS "委外", "a"."業務員" AS "作業人員", COALESCE("e"."員工姓名", ' ') AS "作業人員姓名", COALESCE("c"."繳庫總袋數", 0) AS "繳庫總袋數", COALESCE("c"."繳庫總袋數_箱數", 0) AS "繳庫總袋數_箱數", COALESCE("c"."報廢數", 0) AS "報廢數", COALESCE("c"."重整數", 0) AS "重整數", CASE WHEN (COALESCE("c"."繳庫總袋數", 0) + COALESCE("c"."報廢數", 0)) = 0 THEN 0 ELSE CAST(COALESCE("c"."報廢數", 0) AS DOUBLE PRECISION) / (COALESCE("c"."繳庫總袋數", 0) + COALESCE("c"."報廢數", 0)) END AS "報廢率", CAST(COALESCE("c"."不良剔除後成品率", 0) AS DOUBLE PRECISION) / 100 AS "不良剔除後成品率", CASE WHEN "b"."logical3" = 0 THEN '生產' ELSE '調機' END AS "生產或調機" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "viewfil404ea" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" LEFT JOIN "viewfil310p" AS "d" ON "b"."機台代碼" = "d"."代碼" LEFT JOIN "fil0010" AS "e" ON "a"."業務員" = "e"."員工編號" INNER JOIN "viewfil4030" AS "f" ON "a"."歸屬類別" = "f"."製令單別" AND "a"."歸屬編號" = "f"."製令單號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31E');

-- Home #1959 ViewFIL404F1.氣閥日報主檔.C41
CREATE OR REPLACE VIEW "viewfil404f1" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期" AS "作業日期", "a"."歸屬類別" AS "製令單別", "a"."歸屬編號" AS "製令單號", "c"."公司代碼", "c"."公司名稱", "c"."訂單單別", "c"."訂單單號", "b"."機台代碼", COALESCE("d"."名稱", ' ') AS "機台名稱", COALESCE("d"."委外", 0) AS "委外", "d"."單位主管流水編號", "b"."交貨日期_天" AS "本日件數順序", CONCAT("a"."單據編號", '(', TRIM("a"."單據類別"), ')', '/製令:', COALESCE("a"."歸屬編號", ' '), '/', "c"."產品名稱") AS "主旨", "c"."客戶編號", "c"."客戶名稱", "c"."產品編號", "c"."產品名稱", "c"."產品規格", "a"."匯率類別" AS "作業面", "b"."時間一" AS "開始時間", "b"."時間二" AS "生產時間", "b"."時間三" AS "吃飯時間", "b"."時間四" AS "支援時間", "b"."時間五" AS "結束時間", "b"."時間六" AS "收拾時間", "b"."數值1" AS "每束幾袋", "b"."數值2" AS "每箱幾袋", "b"."數值5" AS "下壓秒數", "a"."稅率" AS "左距邊", "b"."訂金" AS "右距邊", "a"."簽核系統", "a"."備註", "a"."業務員" AS "作業人員", COALESCE("e"."員工姓名", ' ') AS "作業人員姓名", "a"."確認碼", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態", "a"."流水編號", "a"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", COALESCE("z1"."serial_num", ' ') AS "員工流水編號", "a"."填表日", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "viewfil4030" AS "c" ON "a"."歸屬類別" = "c"."製令單別" AND "a"."歸屬編號" = "c"."製令單號" LEFT JOIN "viewfil310p" AS "d" ON "b"."機台代碼" = "d"."代碼" LEFT JOIN "fil0010" AS "e" ON "a"."業務員" = "e"."員工編號" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewofobjproperties" AS "z3" ON "a"."流水編號" = "z3"."單據流水號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31F');

-- Home #1960 ViewFIL404F2.氣閥日報明細
CREATE OR REPLACE VIEW "viewfil404f2" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "b"."文數字1" AS "批號1", "b"."文數字2" AS "批號2", "b"."數值1" AS "數量1", "b"."數值2" AS "數量2", "a"."異動日期" AS "日期", "a"."異動數量" AS "箱號", "a"."贈品數量" AS "繳庫袋數", "b"."logical1" AS "位置是否正確", "b"."logical2" AS "下壓間隙", "b"."數值3" AS "溫度", "b"."數值4" AS "壓力", "b"."logical3" AS "牢固完整度", "a"."單位代碼", COALESCE("d"."名稱", ' ') AS "單位名稱", "a"."倉庫代碼" AS "庫別代碼", COALESCE("e"."名稱", ' ') AS "庫別名稱", "a"."文數字1" AS "半成品編號", "a"."time1" AS "每箱結束時間", "b"."數值5" AS "紙袋報廢數", "b"."數值6" AS "成品庫存數", "b"."數值7" AS "庫存數1", "b"."數值8" AS "庫存數2", "b"."數值9" AS "建檔時的庫存1", "b"."數值10" AS "建檔時的庫存2", "a"."備註說明", "a"."結案碼", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" LEFT JOIN "viewfil3103" AS "d" ON "a"."單位代碼" = "d"."代碼" LEFT JOIN "viewfil3106" AS "e" ON "a"."倉庫代碼" = "e"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" = 'C31F');

-- Home #1964 ViewFIL404FB.氣閥日報分析主檔
CREATE OR REPLACE VIEW "viewfil404fb" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期" AS "作業日期", "a"."歸屬類別" AS "製令單別", "a"."歸屬編號" AS "製令單號", "b"."機台代碼", COALESCE("d"."名稱", ' ') AS "機台名稱", "f"."客戶編號", "f"."客戶名稱", "f"."產品編號", "f"."產品名稱", "f"."產品規格", TO_TIMESTAMP(CONCAT("a"."單據日期", ' ', CASE WHEN "b"."時間一" < '000000' OR "b"."時間一" > '235959' THEN '000000' ELSE "b"."時間一" END), 'syyyymmdd hh24:mi:ss') AS "開始時間", TO_TIMESTAMP(CONCAT(CASE WHEN "b"."時間一" > "b"."時間二" THEN TO_CHAR(TO_DATE("a"."單據日期", 'yyyymmdd') + 1, 'yyyymmdd') ELSE "a"."單據日期" END, ' ', CASE WHEN "b"."時間二" < '000000' OR "b"."時間二" > '235959' THEN '000000' ELSE "b"."時間二" END), 'syyyymmdd hh24:mi:ss') AS "結束時間", CASE WHEN COALESCE("d"."委外", 0) = 0 THEN '廠內' ELSE '委外' END AS "委外", "a"."業務員" AS "作業人員", COALESCE("e"."員工姓名", ' ') AS "作業人員姓名", "c"."繳庫總袋數", "c"."繳庫總袋數_箱數" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "viewfil404fa" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" LEFT JOIN "viewfil310p" AS "d" ON "b"."機台代碼" = "d"."代碼" LEFT JOIN "fil0010" AS "e" ON "a"."業務員" = "e"."員工編號" INNER JOIN "viewfil4030" AS "f" ON "a"."歸屬類別" = "f"."製令單別" AND "a"."歸屬編號" = "f"."製令單號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31F');

-- Home #1966 ViewFIL404FD.氣閥日報分析合併
CREATE OR REPLACE VIEW "viewfil404fd" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期" AS "作業日期", "a"."歸屬類別" AS "製令單別", "a"."歸屬編號" AS "製令單號", "b"."機台代碼", COALESCE("d"."名稱", ' ') AS "機台名稱", COALESCE("d"."委外", 0) AS "委外", "c"."客戶編號", "c"."客戶名稱", "c"."產品編號", "c"."產品名稱", "c"."產品規格", "a"."業務員" AS "作業人員", COALESCE("e"."員工姓名", ' ') AS "作業人員姓名", COALESCE("g"."報廢數量", 0) AS "報廢數量", COALESCE("f"."繳庫總袋數", 0) AS "繳庫總袋數", CASE WHEN COALESCE("f"."繳庫總袋數", 0) = 0 THEN 0 ELSE CAST(COALESCE("g"."報廢數量", 0) AS DOUBLE PRECISION) / COALESCE("f"."繳庫總袋數", 0) END * 100 AS "報廢率" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "viewfil4030" AS "c" ON "a"."歸屬類別" = "c"."製令單別" AND "a"."歸屬編號" = "c"."製令單號" LEFT JOIN "viewfil310p" AS "d" ON "b"."機台代碼" = "d"."代碼" LEFT JOIN "fil0010" AS "e" ON "a"."業務員" = "e"."員工編號" LEFT JOIN (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."贈品數量") AS "繳庫總袋數" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31F' GROUP BY "a"."單據類別", "a"."單據編號") AS "f" ON "f"."單別" = "a"."單據類別" AND "f"."單號" = "a"."單據編號" LEFT JOIN (SELECT "a"."單據類別", "a"."單據編號", SUM("a"."異動數量") AS "報廢數量" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "c1" ON "a"."單據類別" = "c1"."單別" AND "a"."單據編號" = "c1"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'D' AND "c1"."製程代碼" = 'C31F' GROUP BY "a"."單據類別", "a"."單據編號") AS "g" ON "g"."單據類別" = "a"."單據類別" AND "g"."單據編號" = "a"."單據編號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31F');

-- Home #1968 ViewFIL404G1.鐵條日報主檔.C41
CREATE OR REPLACE VIEW "viewfil404g1" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期" AS "作業日期", "a"."歸屬類別" AS "製令單別", "a"."歸屬編號" AS "製令單號", "c"."公司代碼", "c"."公司名稱", "c"."訂單單別", "c"."訂單單號", "b"."機台代碼", COALESCE("d"."名稱", ' ') AS "機台名稱", COALESCE("d"."委外", 0) AS "委外", "d"."單位主管流水編號", "b"."交貨日期_天" AS "本日件數順序", CONCAT("a"."單據編號", '(', TRIM("a"."單據類別"), ')', '/製令:', COALESCE("a"."歸屬編號", ' '), '/', "c"."產品名稱") AS "主旨", "c"."客戶編號", "c"."客戶名稱", "c"."產品編號", "c"."產品名稱", "c"."產品規格", "a"."匯率類別" AS "作業面", "b"."時間一" AS "開始時間", "b"."時間五" AS "結束時間", "b"."數值1" AS "每束幾袋", "b"."數值2" AS "每箱幾袋", "b"."數值5" AS "下壓秒數", "a"."稅率" AS "出袋距離_左", "b"."訂金" AS "出袋距離_右", "a"."簽核系統", "a"."備註", "a"."業務員" AS "作業人員", COALESCE("e"."員工姓名", ' ') AS "作業人員姓名", "a"."確認碼", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態", "a"."流水編號", "a"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", COALESCE("z1"."serial_num", ' ') AS "員工流水編號", "a"."填表日", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "viewfil4030" AS "c" ON "a"."歸屬類別" = "c"."製令單別" AND "a"."歸屬編號" = "c"."製令單號" LEFT JOIN "viewfil310p" AS "d" ON "b"."機台代碼" = "d"."代碼" LEFT JOIN "fil0010" AS "e" ON "a"."業務員" = "e"."員工編號" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewofobjproperties" AS "z3" ON "a"."流水編號" = "z3"."單據流水號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31G');

-- Home #1970 ViewFIL404G2.鐵條日報明細
CREATE OR REPLACE VIEW "viewfil404g2" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "b"."文數字1" AS "批號1", "b"."文數字2" AS "批號2", "b"."數值1" AS "數量1", "b"."數值2" AS "數量2", "a"."異動日期" AS "日期", "a"."異動數量" AS "箱號", "a"."贈品數量" AS "繳庫袋數", "b"."logical1" AS "位置是否正確", "b"."數值3" AS "溫度", "b"."數值4" AS "壓力", "b"."logical3" AS "牢固完整度", "a"."單位代碼", COALESCE("d"."名稱", ' ') AS "單位名稱", "a"."倉庫代碼" AS "庫別代碼", COALESCE("e"."名稱", ' ') AS "庫別名稱", "a"."文數字1" AS "半成品編號", "a"."time1" AS "每箱結束時間", "b"."數值5" AS "紙袋報廢數", "b"."數值6" AS "成品庫存數", "b"."數值7" AS "庫存數1", "b"."數值8" AS "庫存數2", "b"."數值9" AS "建檔時的庫存1", "b"."數值10" AS "建檔時的庫存2", "a"."備註說明", "a"."結案碼", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" LEFT JOIN "viewfil3103" AS "d" ON "a"."單位代碼" = "d"."代碼" LEFT JOIN "viewfil3106" AS "e" ON "a"."倉庫代碼" = "e"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" = 'C31G');

-- Home #1972 ViewFIL404GB.鐵條日報分析主檔
CREATE OR REPLACE VIEW "viewfil404gb" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期" AS "作業日期", "a"."歸屬類別" AS "製令單別", "a"."歸屬編號" AS "製令單號", "b"."機台代碼", COALESCE("d"."名稱", ' ') AS "機台名稱", "f"."客戶編號", "f"."客戶名稱", "f"."產品編號", "f"."產品名稱", "f"."產品規格", TO_TIMESTAMP(CONCAT("a"."單據日期", ' ', CASE WHEN "b"."時間一" < '000000' OR "b"."時間一" > '235959' THEN '000000' ELSE "b"."時間一" END), 'syyyymmdd hh24:mi:ss') AS "開始時間", TO_TIMESTAMP(CONCAT(CASE WHEN "b"."時間一" > "b"."時間二" THEN TO_CHAR(TO_DATE("a"."單據日期", 'yyyymmdd') + 1, 'yyyymmdd') ELSE "a"."單據日期" END, ' ', CASE WHEN "b"."時間二" < '000000' OR "b"."時間二" > '235959' THEN '000000' ELSE "b"."時間二" END), 'syyyymmdd hh24:mi:ss') AS "結束時間", CASE WHEN COALESCE("d"."委外", 0) = 0 THEN '廠內' ELSE '委外' END AS "委外", "a"."業務員" AS "作業人員", COALESCE("e"."員工姓名", ' ') AS "作業人員姓名", "c"."繳庫總袋數", "c"."繳庫總袋數_箱數" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "viewfil404ga" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" LEFT JOIN "viewfil310p" AS "d" ON "b"."機台代碼" = "d"."代碼" LEFT JOIN "fil0010" AS "e" ON "a"."業務員" = "e"."員工編號" INNER JOIN "viewfil4030" AS "f" ON "a"."歸屬類別" = "f"."製令單別" AND "a"."歸屬編號" = "f"."製令單號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31G');

-- Home #1976 ViewFIL404H1.印檢日報主檔.C41
CREATE OR REPLACE VIEW "viewfil404h1" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期" AS "作業日期", "a"."公司代碼", COALESCE("e"."名稱", ' ') AS "公司名稱", "b"."機台代碼", COALESCE("d"."名稱", ' ') AS "機台名稱", "a"."備註", "a"."業務員" AS "作業人員", COALESCE("c"."員工姓名", ' ') AS "作業人員姓名", "a"."確認碼", "b"."貿易條件" AS "標籤機代碼", "a"."簽核系統", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態", CONCAT("a"."單據編號", '(', TRIM("a"."單據類別"), ')') AS "主旨", "d"."單位主管流水編號", COALESCE("z1"."serial_num", ' ') AS "員工流水編號", "a"."流水編號", "a"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "a"."填表日", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日", "b"."時間一" AS "起始時間", "b"."時間五" AS "結束時間", CASE WHEN "b"."時間五" = '000000' THEN 0 ELSE (TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間五" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間五"), 'yyyymmddhh24miss') - TO_DATE(CONCAT(TRIM("a"."單據日期"), "b"."時間一"), 'yyyymmddhh24miss')) * 24 END AS "總耗時", "b"."logical6" AS "改件調整" FROM "fil0030" AS "a" /* 特殊欄位 */ INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" /* */ LEFT JOIN "fil0010" AS "c" ON "a"."業務員" = "c"."員工編號" LEFT JOIN "viewfil310p" AS "d" ON "b"."機台代碼" = "d"."代碼" LEFT JOIN "viewfil0011" AS "e" ON "a"."公司代碼" = "e"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewofobjproperties" AS "z3" ON "a"."流水編號" = "z3"."單據流水號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31H');

-- Home #1977 ViewFIL404H2.印檢日報明細_C31H
CREATE OR REPLACE VIEW "viewfil404h2" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "m"."單據日期" AS "日期", "c"."time1" AS "開始時間", "c"."time2" AS "結束時間", "a"."前置單別" AS "製令單別", "a"."前置單號" AS "製令單號", "c"."小單位" AS "加工別", "d"."公司代碼", "d"."公司名稱", "d"."訂單單別", "d"."訂單單號", "d"."客戶編號", "d"."客戶名稱", "d"."產品編號", "d"."產品名稱", "d"."產品規格", "a"."前製程編號", "a"."異動數量" AS "前製程米數", "a"."產品編號" AS "檢品編號", "a"."贈品數量" AS "檢品米數", ("a"."異動單價" - "夾鏈費") AS "庫存米數", "a"."合併編號", "a"."異動單價" AS "合併米數", "a"."異動金額" AS "印刷色數", "c"."包裝單位" AS "機台選擇", CASE WHEN "c"."包裝單位" = 'A' THEN '十色' WHEN "c"."包裝單位" = 'B' THEN '七色' WHEN "c"."包裝單位" = 'C' THEN '六色' WHEN "c"."包裝單位" = 'D' THEN '積層' WHEN "c"."包裝單位" = 'E' THEN '淋膜' ELSE '選擇' END AS "機台名稱", REPLACE('□十色 □七色 □六色 □積層 □淋膜', TRIM(CONCAT('□', CASE WHEN "c"."包裝單位" = 'A' THEN '十色' WHEN "c"."包裝單位" = 'B' THEN '七色' WHEN "c"."包裝單位" = 'C' THEN '六色' WHEN "c"."包裝單位" = 'D' THEN '積層' WHEN "c"."包裝單位" = 'E' THEN '淋膜' ELSE '選擇' END)), TRIM(CONCAT('■', CASE WHEN "c"."包裝單位" = 'A' THEN '十色' WHEN "c"."包裝單位" = 'B' THEN '七色' WHEN "c"."包裝單位" = 'C' THEN '六色' WHEN "c"."包裝單位" = 'D' THEN '積層' WHEN "c"."包裝單位" = 'E' THEN '淋膜' ELSE '選擇' END))) AS "機台名稱串", "a"."logical1" AS "是否符合", "a"."結案碼" AS "字圖清晰度", "a"."折扣率" AS "接頭數量", "a"."雷射費" AS "線外不良剔除", "a"."夾鏈費" AS "線內不良剔除", "a"."毛重" AS "不良剔除米數", "a"."燙金費" AS "合理剔除數", "c"."標籤列印次數二", "c"."文數字4" AS "前製程條碼", "a"."備註說明", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日", "a"."其它日期" AS "plc抓取日期", "a"."time1" AS "plc抓取時間" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0030" AS "m" ON "a"."單據類別" = "m"."單據類別" AND "a"."單據編號" = "m"."單據編號" /* 製令 */ INNER JOIN "viewfil4030" AS "d" ON "a"."前置單別" = "d"."製令單別" AND "a"."前置單號" = "d"."製令單號" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31H');

-- Home #1978 ViewFIL404H3.印檢製令日報
CREATE OR REPLACE VIEW "viewfil404h3" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "d"."單據序號" AS "序號", "a"."單據日期" AS "作業日期", "b"."機台代碼", COALESCE("c"."名稱", ' ') AS "機台名稱", "e"."time1" AS "開始時間", "e"."time2" AS "結束時間", "d"."前置單別" AS "製令單別", "d"."前置單號" AS "製令單號", "e"."包裝單位" AS "機台選擇", CASE WHEN "e"."包裝單位" = 'A' THEN '十色' WHEN "e"."包裝單位" = 'B' THEN '七色' WHEN "e"."包裝單位" = 'C' THEN '六色' WHEN "e"."包裝單位" = 'D' THEN '積層' WHEN "e"."包裝單位" = 'E' THEN '淋膜' ELSE '選擇' END AS "選擇名稱", REPLACE('□十色 □七色 □六色 □積層 □淋膜', TRIM(CONCAT('□', CASE WHEN "e"."包裝單位" = 'A' THEN '十色' WHEN "e"."包裝單位" = 'B' THEN '七色' WHEN "e"."包裝單位" = 'C' THEN '六色' WHEN "e"."包裝單位" = 'D' THEN '積層' WHEN "e"."包裝單位" = 'E' THEN '淋膜' ELSE '選擇' END)), TRIM(CONCAT('■', CASE WHEN "e"."包裝單位" = 'A' THEN '十色' WHEN "e"."包裝單位" = 'B' THEN '七色' WHEN "e"."包裝單位" = 'C' THEN '六色' WHEN "e"."包裝單位" = 'D' THEN '積層' WHEN "e"."包裝單位" = 'E' THEN '淋膜' ELSE '選擇' END))) AS "機台名稱串" FROM "fil0030" AS "a" /* 特殊欄位 */ INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" /* */ LEFT JOIN "viewfil310p" AS "c" ON "b"."機台代碼" = "c"."代碼" /* 檢品明細 */ LEFT JOIN "fil0040" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" AND "d"."異動類別" = 'A' LEFT JOIN "fil0041" AS "e" ON "a"."單據類別" = "e"."單別" AND "a"."單據編號" = "e"."單號" AND "d"."單據序號" = "e"."序號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31H');

-- Home #1979 ViewFIL404I1.裁檢日報主檔.C41
CREATE OR REPLACE VIEW "viewfil404i1" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期" AS "作業日期", "a"."公司代碼", COALESCE("e"."名稱", ' ') AS "公司名稱", "b"."機台代碼", COALESCE("d"."名稱", ' ') AS "機台名稱", "a"."備註", "a"."業務員" AS "作業人員", COALESCE("c"."員工姓名", ' ') AS "作業人員姓名", "a"."確認碼", "b"."貿易條件" AS "標籤機代碼", "a"."簽核系統", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態", CONCAT("a"."單據編號", '(', TRIM("a"."單據類別"), ')') AS "主旨", "d"."單位主管流水編號", COALESCE("z1"."serial_num", ' ') AS "員工流水編號", "a"."流水編號", "a"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "a"."填表日", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日", "b"."時間一" AS "起始時間", "b"."時間五" AS "結束時間", CASE WHEN "b"."時間五" = '000000' THEN 0 ELSE (TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間五" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間五"), 'yyyymmddhh24miss') - TO_DATE(CONCAT(TRIM("a"."單據日期"), "b"."時間一"), 'yyyymmddhh24miss')) * 24 END AS "總耗時", "b"."logical6" AS "改件調整" FROM "fil0030" AS "a" /* 特殊欄位 */ INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" /* */ LEFT JOIN "fil0010" AS "c" ON "a"."業務員" = "c"."員工編號" LEFT JOIN "viewfil310p" AS "d" ON "b"."機台代碼" = "d"."代碼" LEFT JOIN "viewfil0011" AS "e" ON "a"."公司代碼" = "e"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewofobjproperties" AS "z3" ON "a"."流水編號" = "z3"."單據流水號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31K');

-- Home #1980 ViewFIL404I2.裁檢日報明細_C31K
