-- Home #1993 ViewFIL404Z3.機台材料領用明細
CREATE OR REPLACE VIEW "viewfil404z3" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."產品編號" AS "料號", COALESCE("c"."品名", ' ') AS "品名", COALESCE("c"."規格", ' ') AS "規格", COALESCE("b"."批號", ' ') AS "批號", "a"."異動日期" AS "領用日期", "a"."異動數量" AS "領用數量", "a"."數值1" AS "庫存數", "a"."單位代碼", "a"."倉庫代碼" AS "庫別代碼", COALESCE("d"."名稱", ' ') AS "庫別名稱", "a"."預交日" AS "回庫日期", "a"."贈品數量" AS "回庫數量", "a"."前置單別" AS "回庫庫別", "a"."毛重" AS "報廢數量", COALESCE("e"."名稱", ' ') AS "回庫名稱", "a"."qrno" AS "主檔序號", "a"."備註說明", "a"."logical1" AS "沿用", "a"."logical1" AS "使用廢料", "a"."數值2" AS "接頭數", "b"."標籤列印次數", "b"."標籤列印日期一", "b"."標籤列印時間一", CASE WHEN "b"."檢驗外觀" = 'A' THEN '正式料' WHEN "b"."檢驗外觀" = 'B' THEN '試刷料' WHEN "b"."檢驗外觀" = 'C' THEN '廢料' ELSE ' ' END AS "狀態", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" LEFT JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" LEFT JOIN "fil0012" AS "c" ON "a"."產品編號" = "c"."產品編號" LEFT JOIN "viewfil3106" AS "d" ON "a"."倉庫代碼" = "d"."代碼" LEFT JOIN "viewfil310n" AS "e" ON "a"."前置單別" = "e"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'C');

