CREATE OR REPLACE VIEW "viewfil404z7" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."產品編號" AS "料號", COALESCE("c"."品名", ' ') AS "品名", COALESCE("c"."規格", ' ') AS "規格", "b"."批號", "a"."異動日期" AS "報廢日期", "a"."異動數量" AS "報廢數量", "a"."單位代碼", "a"."倉庫代碼" AS "庫別代碼", COALESCE("d"."名稱", ' ') AS "庫別名稱", "a"."備註說明", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" LEFT JOIN "fil0012" AS "c" ON "a"."產品編號" = "c"."產品編號" LEFT JOIN "viewfil3106" AS "d" ON "a"."倉庫代碼" = "d"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'D');

-- Home #1998 ViewFIL404Z9.印刷油墨領用明細
CREATE OR REPLACE VIEW "viewfil404z9" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."產品編號" AS "料號", COALESCE("c"."品名", ' ') AS "品名", COALESCE("c"."規格", ' ') AS "規格", "b"."批號", "a"."異動日期" AS "領用日期", "a"."異動數量" AS "領用數量", "a"."單位代碼", "a"."倉庫代碼" AS "庫別代碼", COALESCE("d"."名稱", ' ') AS "庫別名稱", "a"."預交日" AS "回庫日期", "a"."贈品數量" AS "回庫數量", "a"."前置單別" AS "回庫庫別", COALESCE("e"."名稱", ' ') AS "回庫名稱", CONCAT(TRIM("b"."批號"), ' ', TRIM(COALESCE("c"."品名", ' ')), '/', COALESCE("c"."規格", ' ')) AS "品名規格", "a"."備註說明", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" LEFT JOIN "fil0012" AS "c" ON "a"."產品編號" = "c"."產品編號" LEFT JOIN "viewfil3106" AS "d" ON "a"."倉庫代碼" = "d"."代碼" LEFT JOIN "viewfil3106" AS "e" ON "a"."前置單別" = "e"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'E');

-- Home #2009 ViewFIL404ZI.製令起迄耗時
CREATE OR REPLACE VIEW "viewfil404zi" AS (/* 印刷~積層 */ SELECT CAST(CASE WHEN "b"."製程代碼" = 'C31A' THEN '印刷' WHEN "b"."製程代碼" = 'C32D' THEN '上臘' WHEN "b"."製程代碼" = 'C31B' THEN '淋膜' ELSE '積層' END AS TEXT) AS "製程", "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."歸屬類別" AS "製令單別", "a"."歸屬編號" AS "製令單號", CASE WHEN "b"."交貨日期_次批" = 'A' THEN 'A材' WHEN "b"."交貨日期_次批" = 'B' THEN 'B材' WHEN "b"."交貨日期_次批" = 'C' THEN '底邊' WHEN "b"."交貨日期_次批" = 'D' THEN 'A側' WHEN "b"."交貨日期_次批" = 'E' THEN 'B側' ELSE ' ' END AS "加工別", TO_DATE(CONCAT(TRIM("a"."單據日期"), "b"."時間一"), 'yyyymmddhh24miss') AS "開始時間", TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間五" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間五"), 'yyyymmddhh24miss') AS "結束時間", CASE WHEN "b"."時間五" = '000000' THEN 0 ELSE (TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間五" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間五"), 'yyyymmddhh24miss') - TO_DATE(CONCAT(TRIM("a"."單據日期"), "b"."時間一"), 'yyyymmddhh24miss')) * 24 END AS "總耗時" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "viewfil4030" AS "c" ON "a"."歸屬類別" = "c"."製令單別" AND "a"."歸屬編號" = "c"."製令單號" WHERE "a"."單據類別" = 'C41' AND ("b"."製程代碼" BETWEEN 'C31A' AND 'C31D' OR "b"."製程代碼" = 'C32D') AND ("b"."時間一" BETWEEN '000000' AND '235959') AND ("b"."時間五" BETWEEN '000000' AND '235959') UNION ALL /* 裁切~成捲 */ SELECT CAST(CASE WHEN "b"."製程代碼" = 'C31D' THEN '裁切' WHEN "b"."製程代碼" = 'C31E' THEN '製袋' WHEN "b"."製程代碼" = 'C31F' THEN '氣閥' WHEN "b"."製程代碼" = 'C31G' THEN '鐵條' ELSE '成捲' END AS TEXT) AS "製程", "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."歸屬類別" AS "製令單別", "a"."歸屬編號" AS "製令單號", CASE WHEN "b"."交貨日期_次批" = 'A' THEN 'A材' WHEN "b"."交貨日期_次批" = 'B' THEN 'B材' WHEN "b"."交貨日期_次批" = 'C' THEN '底邊' WHEN "b"."交貨日期_次批" = 'D' THEN 'A側' WHEN "b"."交貨日期_次批" = 'E' THEN 'B側' ELSE ' ' END AS "加工別", TO_DATE(CONCAT(TRIM("a"."單據日期"), "b"."時間一"), 'yyyymmddhh24miss') AS "起始時間", TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間二" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間二"), 'yyyymmddhh24miss') AS "結束時間", CASE WHEN "b"."時間二" = '000000' THEN 0 ELSE (TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間二" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間二"), 'yyyymmddhh24miss') - TO_DATE(CONCAT(TRIM("a"."單據日期"), "b"."時間一"), 'yyyymmddhh24miss')) * 24 END AS "總耗時" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "viewfil4030_a" AS "c" ON "a"."歸屬類別" = "c"."製令單別" AND "a"."歸屬編號" = "c"."製令單號" WHERE "a"."單據類別" = 'C41' AND ("b"."製程代碼" BETWEEN 'C31D' AND 'C31G' OR "b"."製程代碼" = 'C31I') AND ("b"."時間一" BETWEEN '000000' AND '235959') AND ("b"."時間二" BETWEEN '000000' AND '235959'));

-- Home #2010 ViewFIL404ZJ.製令起迄耗時彙總
CREATE OR REPLACE VIEW "viewfil404zj" AS (SELECT "a"."製令單別", "a"."製令單號", MIN("a"."開始時間") AS "開始時間", MAX("a"."結束時間") AS "結束時間" FROM (SELECT "a"."歸屬類別" AS "製令單別", "a"."歸屬編號" AS "製令單號", MIN(TO_DATE(CONCAT(TRIM("a"."單據日期"), "b"."時間一"), 'yyyymmddhh24miss')) AS "開始時間", MAX(TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間五" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間五"), 'yyyymmddhh24miss')) AS "結束時間" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "viewfil4030" AS "c" ON "a"."歸屬類別" = "c"."製令單別" AND "a"."歸屬編號" = "c"."製令單號" WHERE "a"."單據類別" = 'C41' AND ("b"."製程代碼" BETWEEN 'C31A' AND 'C31D' OR "b"."製程代碼" = 'C32D') AND ("b"."時間一" BETWEEN '000000' AND '235959') AND ("b"."時間五" BETWEEN '000000' AND '235959') GROUP BY CAST(CASE WHEN "b"."製程代碼" = 'C31A' THEN '1.印刷' WHEN "b"."製程代碼" = 'C32D' THEN '2.上臘' WHEN "b"."製程代碼" = 'C31B' THEN '3.淋膜' ELSE '4.積層' END AS TEXT), "a"."歸屬類別", "a"."歸屬編號" /* 印刷~積層 */ UNION ALL /* 裁切~成捲 */ SELECT "a"."歸屬類別" AS "製令單別", "a"."歸屬編號" AS "製令單號", MIN(TO_DATE(CONCAT(TRIM("a"."單據日期"), "b"."時間一"), 'yyyymmddhh24miss')) AS "起始時間", MAX(TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間二" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間二"), 'yyyymmddhh24miss')) AS "結束時間" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "viewfil4030_a" AS "c" ON "a"."歸屬類別" = "c"."製令單別" AND "a"."歸屬編號" = "c"."製令單號" WHERE "a"."單據類別" = 'C41' AND ("b"."製程代碼" BETWEEN 'C31D' AND 'C31G' OR "b"."製程代碼" = 'C31I') AND ("b"."時間一" BETWEEN '000000' AND '235959') AND ("b"."時間二" BETWEEN '000000' AND '235959') GROUP BY CAST(CASE WHEN "b"."製程代碼" = 'C31D' THEN '5.裁切' WHEN "b"."製程代碼" = 'C31E' THEN '6.製袋' WHEN "b"."製程代碼" = 'C31F' THEN '7.氣閥' WHEN "b"."製程代碼" = 'C31G' THEN '8.鐵條' ELSE '9.成捲' END AS TEXT), "a"."歸屬類別", "a"."歸屬編號") AS "a" GROUP BY "a"."製令單別", "a"."製令單號");

-- Home #2013 ViewFIL404ZM,後製程產量彙總
CREATE OR REPLACE VIEW "viewfil404zm" AS (SELECT "a"."歸屬類別" AS "製令單別", "a"."歸屬編號" AS "製令單號", MIN(TO_DATE(CONCAT(TRIM("a"."單據日期"), "b"."時間一"), 'yyyymmddhh24miss')) AS "起始時間", MAX(TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間二" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間二"), 'yyyymmddhh24miss')) AS "結束時間" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "viewfil4030_a" AS "c" ON "a"."歸屬類別" = "c"."製令單別" AND "a"."歸屬編號" = "c"."製令單號" WHERE "a"."單據類別" = 'C41' AND ("b"."製程代碼" BETWEEN 'C31E' AND 'C31G' OR "b"."製程代碼" = 'C31I') AND ("b"."時間一" BETWEEN '000000' AND '235959') AND ("b"."時間二" BETWEEN '000000' AND '235959') GROUP BY "a"."歸屬類別", "a"."歸屬編號");

-- Home #2015 ViewFil404ZO.製令日報人員費用
CREATE OR REPLACE VIEW "viewfil404zo" AS (SELECT "a"."單別", "a"."單號", "a"."單據日期", "e"."名稱" AS "製程", "a"."作業人員", "d"."員工姓名" AS "作業人員姓名", COALESCE("a"."總耗時", 0) AS "總耗時", COALESCE("a"."時薪" * "a"."總耗時", 0) AS "直接人工" FROM (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期", "b"."製程代碼", CAST(ORA_SUBSTR("a"."業務員", 1, 10) AS TEXT) AS "作業人員", CASE WHEN "b"."時間五" = '000000' THEN 0 ELSE (TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間五" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間五"), 'yyyymmddhh24miss') - TO_DATE(CONCAT(TRIM("a"."單據日期"), "b"."時間一"), 'yyyymmddhh24miss')) * 24 END AS "總耗時", (CAST(("f"."本月應發金額" - "f"."遲到早退扣支" - "f"."調補扣支") AS DOUBLE PRECISION) / (30 * 8)) AS "時薪" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0010" AS "e" ON "a"."業務員" = "e"."員工編號" LEFT JOIN "viewfilhs02" AS "f" ON ORA_SUBSTR("f"."年月", 1, 6) = ORA_SUBSTR("a"."單據日期", 1, 6) AND "f"."員工編號" = CAST(ORA_SUBSTR("a"."業務員", 1, 10) AS TEXT) WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" IN ('C31A', 'C31E', 'C31B', 'C31C', 'C31F', 'C31G', 'C31I', 'C32D') AND "a"."業務員" <> ' ' AND "a"."單據日期" > '2025' UNION SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期", "b"."製程代碼", CAST(ORA_SUBSTR("b"."文數字10", 1, 10) AS TEXT) AS "作業人員", CASE WHEN "b"."時間五" = '000000' THEN 0 ELSE (TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間五" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間五"), 'yyyymmddhh24miss') - TO_DATE(CONCAT(TRIM("a"."單據日期"), "b"."時間一"), 'yyyymmddhh24miss')) * 24 END AS "總耗時", (CAST(("f"."本月應發金額" - "f"."遲到早退扣支" - "f"."調補扣支") AS DOUBLE PRECISION) / (30 * 8)) AS "時薪" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0010" AS "e" ON "b"."文數字10" = "e"."員工編號" LEFT JOIN "viewfilhs02" AS "f" ON ORA_SUBSTR("f"."年月", 1, 6) = ORA_SUBSTR("a"."單據日期", 1, 6) AND "f"."員工編號" = CAST(ORA_SUBSTR("b"."文數字10", 1, 10) AS TEXT) WHERE "a"."單據類別" = 'C41' AND ("b"."製程代碼" = 'C31A' OR "b"."製程代碼" = 'C31B' OR "b"."製程代碼" = 'C31C' OR "b"."製程代碼" = 'C31E') AND "b"."文數字10" <> ' ' AND "a"."單據日期" > '2025' UNION SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期", "b"."製程代碼", CAST(ORA_SUBSTR("b"."文數字11", 1, 10) AS TEXT) AS "作業人員", CASE WHEN "b"."時間五" = '000000' THEN 0 ELSE (TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間五" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間五"), 'yyyymmddhh24miss') - TO_DATE(CONCAT(TRIM("a"."單據日期"), "b"."時間一"), 'yyyymmddhh24miss')) * 24 END AS "總耗時", (CAST(("f"."本月應發金額" - "f"."遲到早退扣支" - "f"."調補扣支") AS DOUBLE PRECISION) / (30 * 8)) AS "時薪" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0010" AS "e" ON "b"."文數字11" = "e"."員工編號" LEFT JOIN "viewfilhs02" AS "f" ON ORA_SUBSTR("f"."年月", 1, 6) = ORA_SUBSTR("a"."單據日期", 1, 6) AND "f"."員工編號" = CAST(ORA_SUBSTR("b"."文數字11", 1, 10) AS TEXT) WHERE "a"."單據類別" = 'C41' AND ("b"."製程代碼" = 'C31A' OR "b"."製程代碼" = 'C31B' OR "b"."製程代碼" = 'C31C' OR "b"."製程代碼" = 'C31E') AND "b"."文數字11" <> ' ' AND "a"."單據日期" > '2025' UNION SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期", "b"."製程代碼", CAST(ORA_SUBSTR("b"."文數字12", 1, 10) AS TEXT) AS "作業人員", CASE WHEN "b"."時間五" = '000000' THEN 0 ELSE (TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間五" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間五"), 'yyyymmddhh24miss') - TO_DATE(CONCAT(TRIM("a"."單據日期"), "b"."時間一"), 'yyyymmddhh24miss')) * 24 END AS "總耗時", (CAST(("f"."本月應發金額" - "f"."遲到早退扣支" - "f"."調補扣支") AS DOUBLE PRECISION) / (30 * 8)) AS "時薪" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0010" AS "e" ON "b"."文數字11" = "e"."員工編號" LEFT JOIN "viewfilhs02" AS "f" ON ORA_SUBSTR("f"."年月", 1, 6) = ORA_SUBSTR("a"."單據日期", 1, 6) AND "f"."員工編號" = CAST(ORA_SUBSTR("b"."文數字12", 1, 10) AS TEXT) WHERE "a"."單據類別" = 'C41' AND ("b"."製程代碼" = 'C31B' OR "b"."製程代碼" = 'C31C') AND "b"."文數字12" <> ' ' AND "a"."單據日期" > '2025' UNION SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期", "b"."製程代碼", CAST(ORA_SUBSTR("a"."填表人", 1, 10) AS TEXT) AS "作業人員", CASE WHEN "b"."時間五" = '000000' THEN 0 ELSE (TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間五" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間五"), 'yyyymmddhh24miss') - TO_DATE(CONCAT(TRIM("a"."單據日期"), "b"."時間一"), 'yyyymmddhh24miss')) * 24 END AS "總耗時", (CAST(("f"."本月應發金額" - "f"."遲到早退扣支" - "f"."調補扣支") AS DOUBLE PRECISION) / (30 * 8)) AS "時薪" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0010" AS "e" ON "a"."填表人" = "e"."員工編號" LEFT JOIN "viewfilhs02" AS "f" ON ORA_SUBSTR("f"."年月", 1, 6) = ORA_SUBSTR("a"."單據日期", 1, 6) AND "f"."員工編號" = CAST(ORA_SUBSTR("a"."填表人", 1, 10) AS TEXT) WHERE "a"."單據類別" = 'C41' AND ("b"."製程代碼" = 'C31H' OR "b"."製程代碼" = 'C31K') AND "a"."填表人" <> ' ' AND "a"."單據日期" > '2025') AS "a" INNER JOIN "fil0010" AS "d" ON "a"."作業人員" = "d"."員工編號" INNER JOIN "viewfil310n" AS "e" ON "e"."代碼" = "a"."製程代碼");

-- Home #2016 ViewFil404ZP.製令日報費用
CREATE OR REPLACE VIEW "viewfil404zp" AS (SELECT "a"."單別", "a"."單號", "a"."單據日期", "a"."製程", SUM("a"."總耗時") AS "總耗時", SUM("a"."直接人工") AS "直接人工" FROM "viewfil404zo" AS "a" GROUP BY "a"."單別", "a"."單號", "a"."單據日期", "a"."製程");

-- Home #2025 ViewFIL4061.原物料領料明細
CREATE OR REPLACE VIEW "viewfil4061" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."產品編號" AS "料號", "b"."歸屬類別" AS "請領單別", "b"."歸屬編號" AS "請領單號", "a"."文數字1" AS "請領料號", "c"."批號", COALESCE("d"."品名", ' ') AS "品名", COALESCE("d"."規格", ' ') AS "規格", "a"."異動日期" AS "發料日期", "a"."異動數量" AS "發料數量", "a"."單位代碼", COALESCE("f"."名稱", ' ') AS "單位名稱", "a"."倉庫代碼", COALESCE("e"."名稱", ' ') AS "倉庫名稱", COALESCE("g"."製程代碼", ' ') AS "製程代碼", "a"."備註說明", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" INNER JOIN "fil0031" AS "g" ON "a"."單據類別" = "g"."單別" AND "a"."單據編號" = "g"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN "fil0012" AS "d" ON "a"."產品編號" = "d"."產品編號" LEFT JOIN "viewfil3106" AS "e" ON "a"."倉庫代碼" = "e"."代碼" LEFT JOIN "viewfil3103" AS "f" ON "a"."單位代碼" = "f"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."單據類別" = 'C4M');

-- Home #2027 ViewFIL408B.請領發料合計
CREATE OR REPLACE VIEW "viewfil408b" AS (SELECT "a"."請領單別", "a"."請領單號", "b"."單據日期" AS "排程日期", "c"."製程代碼", COALESCE("d"."名稱", ' ') AS "製程名稱", "c"."工站代碼", COALESCE("e"."名稱", ' ') AS "工站名稱", "a"."機台代碼", COALESCE("f"."名稱", ' ') AS "機台名稱", "a"."料號", COALESCE("g"."品名", ' ') AS "品名", COALESCE("g"."規格", ' ') AS "規格", "b"."公司代碼", COALESCE("h"."名稱", ' ') AS "公司名稱", "a"."請領數量", "a"."核准數量", "a"."發料數量", GREATEST(0, "a"."核准數量" - "a"."發料數量") AS "未發料數" FROM (SELECT "a"."請領單別", "a"."請領單號", "a"."機台代碼", "a"."料號", SUM("a"."請領數量") AS "請領數量", SUM("a"."核准數量") AS "核准數量", SUM("a"."發料數量") AS "發料數量" FROM (SELECT CASE WHEN "a"."單據類別" = 'C4L' THEN "a"."單據類別" ELSE "b"."歸屬類別" END AS "請領單別", CASE WHEN "a"."單據類別" = 'C4L' THEN "a"."單據編號" ELSE "b"."歸屬編號" END AS "請領單號", "c"."機台代碼", CASE WHEN "a"."單據類別" = 'C4L' THEN "a"."產品編號" ELSE "a"."文數字1" END AS "料號", CASE WHEN "a"."單據類別" = 'C4L' THEN "a"."異動數量" ELSE 0 END AS "請領數量", CASE WHEN "a"."單據類別" = 'C4L' THEN "a"."異動數量" ELSE 0 END * "b"."邏輯值一" AS "核准數量", CASE WHEN "a"."單據類別" = 'C4M' THEN "a"."異動數量" ELSE 0 END AS "發料數量" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" WHERE "a"."單據類別" BETWEEN 'C4L' AND 'C4M') AS "a" GROUP BY "a"."請領單別", "a"."請領單號", "a"."機台代碼", "a"."料號") AS "a" INNER JOIN "fil0030" AS "b" ON "a"."請領單別" = "b"."單據類別" AND "a"."請領單號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0031" AS "c" ON "a"."請領單別" = "c"."單別" AND "a"."請領單號" = "c"."單號" /* 製程 */ LEFT JOIN "viewfil310n" AS "d" ON "c"."製程代碼" = "d"."代碼" /* 工站 */ LEFT JOIN "viewfil310o" AS "e" ON "c"."工站代碼" = "e"."代碼" /* 機台 */ LEFT JOIN "viewfil310p" AS "f" ON "a"."機台代碼" = "f"."代碼" /* 料號 */ LEFT JOIN "fil0012" AS "g" ON "a"."料號" = "g"."產品編號" /* 公司別 */ LEFT JOIN "viewfil0011" AS "h" ON "b"."公司代碼" = "h"."代碼" WHERE "a"."請領數量" > 0);

-- Home #2034 ViewFIL4101.製袋巡檢表.C47
CREATE OR REPLACE VIEW "viewfil4101" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "c"."機台代碼" AS "作業區域", "d"."名稱" AS "機台名稱", "a"."單據日期" AS "巡檢日期", "a"."歸屬類別" AS "製令單別", "a"."歸屬編號" AS "製令單號", "a"."簽核系統", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態", "b"."公司代碼", "b"."公司名稱", "b"."訂單單別", "b"."訂單單號", "b"."客戶編號", "b"."客戶名稱", "b"."產品編號", "b"."產品名稱", "b"."產品規格" AS "成品尺寸", "b"."訂購數量" AS "訂單數量", "c"."作業速率", "c"."檢驗時間", "c"."箱號", "a"."備註" AS "缺失說明", "c"."備註", "a"."流水編號", "a"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "a"."填表日", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日", "c"."機台狀態" FROM "fil0030" AS "a" INNER JOIN "fil003g" AS "c" ON "a"."流水編號" = "c"."主檔流水編號" INNER JOIN "viewfil310p" AS "d" ON "c"."機台代碼" = "d"."代碼" LEFT JOIN "viewfil4030" AS "b" ON "a"."歸屬類別" = "b"."製令單別" AND "a"."歸屬編號" = "b"."製令單號" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewfil0030" AS "z3" ON "a"."簽核系統" = "z3"."簽核系統" AND "a"."單據編號" = "z3"."單號" WHERE "a"."單據類別" = 'C47');

-- Home #2036 ViewFIL4111.氣閥巡檢表.C45
