-- Home #2038 ViewFIL4121.鐵條巡檢表.C46
CREATE OR REPLACE VIEW "viewfil4121" AS (SELECT "b"."單據類別" AS "單別", "b"."單據編號" AS "單號", "a"."機台代碼", "c"."名稱" AS "機台名稱", "a"."作業位置", "a"."出袋距離_左", "a"."出袋距離_右", "b"."單據日期" AS "巡檢日期", "b"."歸屬類別" AS "製令單別", "b"."歸屬編號" AS "製令單號", "b"."簽核系統", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態", "d"."公司代碼", "d"."公司名稱", "d"."訂單單別", "d"."訂單單號", "d"."客戶編號", "d"."客戶名稱", "d"."產品編號", "d"."產品名稱", "d"."產品規格" AS "成品尺寸", "d"."訂購數量" AS "訂單數量", "a"."檢驗時間", "a"."箱號", "a"."y牢固完整度", "a"."n牢固完整度", "a"."作業員", COALESCE("e"."員工姓名", ' ') AS "作業員姓名", "a"."備註", "a"."主檔流水編號" AS "流水編號", "b"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "b"."填表日", "b"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "b"."最後更新日", "a"."機台狀態" FROM "fil003h" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."主檔流水編號" = "b"."流水編號" INNER JOIN "viewfil310p" AS "c" ON "a"."機台代碼" = "c"."代碼" LEFT JOIN "viewfil4030" AS "d" ON "b"."歸屬類別" = "d"."製令單別" AND "b"."歸屬編號" = "d"."製令單號" LEFT JOIN "fil0010" AS "e" ON "a"."作業員" = "e"."員工編號" LEFT JOIN "fil0010" AS "z1" ON "b"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "b"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewfil0030" AS "z3" ON "b"."簽核系統" = "z3"."簽核系統" AND "b"."單據編號" = "z3"."單號" WHERE "a"."巡檢項目" = 'C31G');

-- Home #2040 ViewFIL4201.成品檢驗記錄表.C48
CREATE OR REPLACE VIEW "viewfil4201" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期" AS "檢驗日期", "a"."歸屬類別" AS "巡檢單別", "a"."歸屬編號" AS "巡檢單號", "d"."製令單別" AS "製令單別", "d"."製令單號", COALESCE("d1"."箱號", 0) AS "箱號", "a"."簽核系統", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態", "b"."公司代碼", "b"."公司名稱", "b"."訂單單別", "b"."訂單單號", "b"."客戶編號", "b"."客戶名稱", CASE WHEN "a"."廠客單號" = ' ' THEN "e"."成品編號" ELSE "a"."廠客單號" END AS "產品編號", "f"."品名" AS "產品名稱", "f"."規格" AS "產品規格", "b"."預交日" AS "預計交期", "d"."生產數量" AS "生產數量", "d"."製造日期", COALESCE("d"."檢驗數量", 0) AS "檢驗數量", COALESCE("d"."不良數量", 0) AS "不良數量", COALESCE("d"."交貨日期", '00000000') AS "交貨日期", COALESCE("d"."交貨數量", 0) AS "交貨數量", COALESCE("d"."判定", ' ') AS "判定", COALESCE("d"."判定其他說明", ' ') AS "判定其他說明", COALESCE("d"."作業人員1", ' ') AS "作業人員1", COALESCE("y1"."員工姓名", ' ') AS "作業員1姓名", COALESCE("d"."作業人員2", ' ') AS "作業人員2", COALESCE("y2"."員工姓名", ' ') AS "作業員2姓名", COALESCE("d"."作業人員3", ' ') AS "作業人員3", COALESCE("y3"."員工姓名", ' ') AS "作業員3姓名", "d"."標籤類別", "a"."備註", "a"."流水編號", "a"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "a"."填表日", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0030" AS "a" INNER JOIN "fil003e" AS "d" ON "a"."流水編號" = "d"."主檔流水編號" /* 檢驗記錄表 */ LEFT JOIN "viewfil4030_a" AS "b" ON "d"."製令單別" = "b"."製令單別" AND "d"."製令單號" = "b"."製令單號" /* 製令主檔 */ LEFT JOIN "fil0032" AS "c" ON "d"."製令單別" = "c"."製令單別" AND "d"."製令單號" = "c"."製令單號" /* 產品條件主檔 */ LEFT JOIN "viewfil4101" AS "d1" ON "a"."歸屬類別" = "d1"."單別" AND "a"."歸屬編號" = "d1"."單號" /* 製袋巡檢記錄表 */ LEFT JOIN "fil004b" AS "e" ON "e"."製令單號" = "d"."製令單號" AND "e"."箱號" = COALESCE("d1"."箱號", 0) /* 製成品屬性 */ LEFT JOIN "fil0012" AS "f" ON "f"."產品編號" = CASE WHEN "a"."廠客單號" = ' ' THEN "e"."成品編號" ELSE "a"."廠客單號" END LEFT JOIN "fil0010" AS "y1" ON "d"."作業人員1" = "y1"."員工編號" LEFT JOIN "fil0010" AS "y2" ON "d"."作業人員2" = "y2"."員工編號" LEFT JOIN "fil0010" AS "y3" ON "d"."作業人員3" = "y3"."員工編號" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2".