CREATE OR REPLACE VIEW "viewfil4a1e" AS WITH "tmp1" /* 採購單明細 */ AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."單位代碼", "a"."異動數量" AS "採購單數量", "a"."數值4" AS "採購單庫存異動數" FROM "fil0040" AS "a" LEFT JOIN "viewofobjproperties" AS "z3" ON "a"."流水編號" = "z3"."單據流水號" WHERE "a"."單據類別" = 'D11' AND COALESCE("z3"."簽核狀態", '0') <> 'A'), "tmp2" /* 廠商出貨明細 */ AS (SELECT "a"."單別", "a"."單號", "a"."序號", SUM("a"."數字四") AS "廠商出貨採購數", SUM("a"."數字二") AS "廠商出貨庫存異動數", SUM("a"."數字一") AS "廠商出貨支數", COUNT("a"."細分") AS "廠商條碼筆數" FROM "fil00401" AS "a" WHERE "a"."單別" = 'D11' AND "a"."邏輯一" = 1 GROUP BY "a"."單別", "a"."單號", "a"."序號"), "tmp3" /* 喜美收料 */ AS (SELECT "a"."單別", "a"."單號", "a"."序號", SUM("a"."庫存異動數") AS "喜美收料庫存異動數" FROM "fil0043" AS "a" WHERE "a"."單別" = 'D11' GROUP BY "a"."單別", "a"."單號", "a"."序號") SELECT "a"."單別", "a"."單號", "a"."序號", "a"."採購單數量", "a"."採購單庫存異動數", COALESCE("n"."廠商出貨採購數", 0) AS "廠商出貨採購數", COALESCE("n"."廠商出貨庫存異動數", 0) AS "廠商出貨庫存異動數", COALESCE("n"."廠商出貨支數", 0) AS "廠商出貨支數", COALESCE("p"."喜美收料庫存異動數", 0) AS "喜美收料庫存異動數", COALESCE("n"."廠商條碼筆數", 0) AS "廠商條碼筆數", CAST(COALESCE("p"."喜美收料庫存異動數", 0) AS DOUBLE PRECISION) / CASE WHEN "d"."庫存乘數" = 0 THEN 1 ELSE "d"."庫存乘數" END AS "喜美收料採購數", CASE WHEN "a"."採購單數量" >= COALESCE("n"."廠商出貨採購數", 0) THEN "a"."採購單數量" - COALESCE("n"."廠商出貨採購數", 0) ELSE 0 END AS "未交貨採購數", CASE WHEN "a"."採購單庫存異動數" >= COALESCE("n"."廠商出貨庫存異動數", 0) THEN "a"."採購單庫存異動數" - COALESCE("n"."廠商出貨庫存異動數", 0) ELSE 0 END AS "廠商未交貨庫存異動數" FROM "tmp1" AS "a" LEFT JOIN "tmp2" AS "n" ON "n"."單別" = "a"."單別" AND "n"."單號" = "a"."單號" AND "n"."序號" = "a"."序號" LEFT JOIN "tmp3" AS "p" ON "p"."單別" = "a"."單別" AND "p"."單號" = "a"."單號" AND "p"."序號" = "a"."序號" LEFT JOIN "viewfil3103" AS "d" ON "a"."單位代碼" = "d"."代碼";

-- Home #2159 ViewFIL4A1EA.採購平台廠商出貨
CREATE OR REPLACE VIEW "viewfil4a1ea" AS WITH "tmp1" /* 採購單明細 */ AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."產品編號" AS "料號", CASE WHEN COALESCE("b"."手動品名", ' ') = ' ' THEN COALESCE("c"."品名", ' ') ELSE COALESCE("b"."手動品名", ' ') END AS "品名", CASE WHEN COALESCE("b"."手動規格", ' ') = ' ' THEN COALESCE("c"."規格", ' ') ELSE COALESCE("b"."手動規格", ' ') END AS "規格", "a"."異動單價" AS "單價", "a"."預交日", "a"."備註說明" AS "備註", CONCAT(TRIM("a"."單據類別"), '-', TRIM("a"."單據編號"), '-', TRIM(TO_CHAR("a"."單據序號", '0000'))) AS "批號", "a"."數值2" AS "收貨量", "a"."相關代碼1" AS "收貨單位", "a"."數值3" AS "收貨規格", CASE WHEN COALESCE("c"."採購單位", ' ') = ' ' THEN 1 ELSE 0 END AS "庶物用品", "b"."logical1" AS "急用", "m"."流水編號", "m"."單據日期", "m"."廠客編號" AS "廠商編號", COALESCE("z2"."簡稱", ' ') AS "廠商簡稱", "m"."簽核系統", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態", "q"."價格條件" AS "送貨地址", "q"."logical1" AS "廠商已讀", "d"."庫存乘數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "m" ON "a"."單據類別" = "m"."單據類別" AND "a"."單據編號" = "m"."單據編號" INNER JOIN "fil0031" AS "q" ON "a"."單據類別" = "q"."單別" AND "a"."單據編號" = "q"."單號" LEFT JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" LEFT JOIN "fil0012" AS "c" ON "a"."產品編號" = "c"."產品編號" LEFT JOIN "viewfil3103" AS "d" ON "a"."單位代碼" = "d"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" LEFT JOIN "fil0011" AS "z2" ON "m"."廠客編號" = "z2"."編號" LEFT JOIN "viewofobjproperties" AS "z3" ON "m"."流水編號" = "z3"."單據流水號" WHERE "a"."單據類別" = 'D11' AND COALESCE("z3"."簽核狀態", '0') <> 'A') SELECT "a"."單別", "a"."單號", "a"."序號", "a"."料號", "a"."品名", "a"."規格", "a"."單價", "a"."預交日", "a"."備註", "a"."批號", "a"."收貨量", "a"."收貨單位", "a"."收貨規格", "a"."庶物用品", "a"."急用", "a"."流水編號", "n"."採購單數量", "n"."採購單庫存異動數", "n"."廠商出貨採購數", "n"."廠商出貨庫存異動數", "n"."廠商出貨支數", "n"."廠商條碼筆數", "n"."喜美收料採購數", "n"."喜美收料庫存異動數", "n"."未交貨採購數", "n"."廠商未交貨庫存異動數", "a"."單據日期", "a"."廠商編號", "a"."廠商簡稱", "a"."簽核系統", "a"."簽核狀態", "a"."送貨地址", "a"."廠商已讀" FROM "tmp1" AS "a" INNER JOIN "viewfil4a1e" AS "n" ON "n"."單別" = "a"."單別" AND "n"."單號" = "a"."單號" AND "n"."序號" = "a"."序號";

