-- Home #2161 ViewFIL4A1F.採購預交日單號
CREATE OR REPLACE VIEW "viewfil4a1f" AS (SELECT "a"."廠客編號", "a"."預交日", CASE WHEN "c"."筆數" > 0 AND COALESCE("b"."確認碼", ' ') = ' ' THEN 'A' ELSE COALESCE("b"."確認碼", ' ') END AS "狀態", COALESCE("b"."簽核系統_結案", ' ') AS "補件說明", STRING_AGG(CAST(COALESCE(TRIM("a"."單據編號"), ' ') AS TEXT), ',' ORDER BY "a"."廠客編號") AS "採購單號" FROM (SELECT "a"."廠客編號", "a"."單據編號", STRING_AGG(CAST(COALESCE(TO_CHAR(TO_DATE("a"."預交日", 'yyyy/mm/dd'), 'yyyy/mm/dd'), ' ') AS TEXT), ',' ORDER BY "a"."廠客編號") AS "預交日" FROM (SELECT DISTINCT "b"."廠客編號", "a"."單據編號", "a"."預交日" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" LEFT JOIN "viewofobjproperties" AS "z3" ON "b"."流水編號" = "z3"."單據流水號" WHERE "a"."單據類別" = 'D11' AND "z3"."簽核狀態" = 'E' GROUP BY "b"."廠客編號", "a"."單據編號", "a"."預交日") AS "a" GROUP BY "a"."廠客編號", "a"."單據編號") AS "a" LEFT JOIN "fil0030" AS "b" ON "b"."單據類別" = 'COA' AND "b"."單據編號" = CONCAT(TRIM("a"."廠客編號"), '-', REPLACE(REGEXP_SUBSTR("a"."預交日", '[^,]+'), '/', '')) LEFT JOIN "viewfil0054" AS "c" ON "c"."簽核系統" = 'COA' AND "c"."單號" = CONCAT(TRIM("a"."廠客編號"), '-', REPLACE(REGEXP_SUBSTR("a"."預交日", '[^,]+'), '/', '')) GROUP BY "a"."廠客編號", "a"."預交日", CASE WHEN "c"."筆數" > 0 AND COALESCE("b"."確認碼", ' ') = ' ' THEN 'A' ELSE COALESCE("b"."確認碼", ' ') END, COALESCE("b"."簽核系統_結案", ' '));

