-- Home #2186 ViewFILA001.訂單進度表
CREATE OR REPLACE VIEW "viewfila001" AS (SELECT "b"."訂單號碼", "a"."產品編號", "b"."單據日期", ' ' AS "父階", ' ' AS "父階單別", ' ' AS "父階單號", CONCAT(TRIM("a"."單據類別"), '.', "a"."單據編號") AS "子階", "a"."單據類別" AS "子階單別", "a"."單據編號" AS "子階單號", CONCAT(TRIM("a"."單據類別"), '.', "a"."單據編號") AS "排序" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" WHERE "a"."單據類別" = 'B31' /* 客戶訂單 */ UNION SELECT "b"."訂單號碼", "a"."產品編號", "b"."單據日期", CONCAT(TRIM("b"."歸屬類別"), '.', "b"."歸屬編號") AS "父階", "b"."歸屬類別" AS "父階單別", "b"."歸屬編號" AS "父階單號", CONCAT(TRIM("a"."製令單別"), '.', "a"."製令單號") AS "子階", "a"."製令單別" AS "子階單別", "a"."製令單號" AS "子階單號", CONCAT(TRIM("a"."製令單別"), '.', "a"."製令單號") AS "排序" FROM "fil0032" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."製令單別" = "b"."單據類別" AND "a"."製令單號" = "b"."單據編號" /* 生產條件單 */ UNION SELECT "b"."訂單號碼", COALESCE("c"."產品編號", ' ') AS "產品編號", "b"."單據日期", CONCAT(TRIM("b"."歸屬類別"), '.', "b"."歸屬編號") AS "父階", "b"."歸屬類別" AS "父階單別", "b"."歸屬編號" AS "父階單號", CONCAT(TRIM("a"."單別"), '.', "a"."單號") AS "子階", "a"."單別" AS "子階單別", "a"."單號" AS "子階單號", CONCAT(TRIM("a"."單別"), '.', "a"."單號") AS "排序" FROM "fil0035" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單別" = "b"."單據類別" AND "a"."單號" = "b"."單據編號" LEFT JOIN "fil0032" AS "c" ON "b"."歸屬類別" = "c"."製令單別" AND "b"."歸屬編號" = "c"."製令單號" /* 條件變更單 */ /*
UNION

SELECT
	B.訂單號碼,
	nvl(C.產品編號, ' ') 產品編號,
	B.單據日期,
	trim(B.歸屬類別) || '.' || B.歸屬編號 父階,
	B.歸屬類別 父階單別,
	B.歸屬編號 父階單號,
	trim(A.單別) || '.' || A.單號 子階,
	A.單別 子階單別,
	A.單號 子階單號,
	trim(A.單別) || '.' || A.單號 排序
FROM
	FIL0036 A
	INNER JOIN FIL0030 B ON A.單別 = B.單據類別 AND A.單號 = B.單據編號
	LEFT JOIN FIL0032 C ON B.歸屬類別 = C.製令單別 AND B.歸屬編號 = C.製令單號
製稿工作指示單 */ UNION SELECT "c"."訂單單號" AS "訂單號碼", "c"."產品編號", "b"."單據日期", CONCAT(TRIM("a"."前置單別"), '.', "a"."前置單號") AS "父階", "a"."前置單別" AS "父階單別", "a"."前置單號" AS "父階單號", CONCAT(TRIM("a"."單據類別"), '.', "a"."單據編號") AS "子階", "a"."單據類別" AS "子階單別", "a"."單據編號" AS "子階單號", CONCAT(TRIM("a"."單據類別"), '.', "a"."單據編號") AS "排序" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" INNER JOIN "viewfil4030" AS "c" ON "a"."前置單別" = "c"."製令單別" AND "a"."前置單號" = "c"."製令單號" WHERE "a"."單據類別" = 'D11' AND "a"."前置單號" <> ' ' /* 採購單 */ UNION SELECT "b"."訂單號碼", "c"."產品編號", "b"."單據日期", CONCAT(TRIM("b"."歸屬類別"), '.', "b"."歸屬編號") AS "父階", "b"."歸屬類別" AS "父階單別", "b"."歸屬編號" AS "父階單號", CONCAT(TRIM("a"."單別"), '.', "a"."單號") AS "子階", "a"."單別" AS "子階單別", "a"."單號" AS "子階單號", CONCAT(TRIM("a"."製程代碼"), ' ', TRIM("a"."機台代碼"), ' ', TO_CHAR("a"."聯絡人序號", '0000')) AS "排序" FROM "fil0031" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單別" = "b"."單據類別" AND "a"."單號" = "b"."單據編號" INNER JOIN "fil0032" AS "c" ON "b"."歸屬類別" = "c"."製令單別" AND "b"."歸屬編號" = "c"."製令單號" WHERE "a"."單別" = 'C31' /* 生產排程 */ UNION SELECT "b"."訂單號碼", "c"."產品編號", "b"."單據日期", CONCAT(TRIM("b"."歸屬類別"), '.', "b"."歸屬編號") AS "父階", "b"."歸屬類別" AS "父階單別", "b"."歸屬編號" AS "父階單號", CONCAT(TRIM("a"."單別"), '.', "a"."單號") AS "子階", "a"."單別" AS "子階單別", "a"."單號" AS "子階單號", CONCAT(TRIM("a"."製程代碼"), ' ', TRIM("a"."機台代碼"), ' ', TO_CHAR("a"."交貨日期_天", '0000')) AS "排序" FROM "fil0031" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單別" = "b"."單據類別" AND "a"."單號" = "b"."單據編號" INNER JOIN "fil0032" AS "c" ON "b"."歸屬類別" = "c"."製令單別" AND "b"."歸屬編號" = "c"."製令單號" WHERE "a"."單別" = 'C41') /* 日報表 */;

