CREATE OR REPLACE VIEW "viewfile025" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."公司代碼", COALESCE("e"."全名", ' ') AS "公司名稱", "a"."廠客編號", "a"."單據日期", "a"."簽核系統", "a"."備註", "a"."業務員" AS "倉管員", COALESCE("d"."員工姓名", ' ') AS "倉管員姓名", "b"."機台代碼", "z3"."名稱" AS "機台名稱", "a"."流水編號", "a"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "a"."填表日", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日", COALESCE("f"."簽核狀態", '0') AS "簽核狀態" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0010" AS "d" ON "a"."業務員" = "d"."員工編號" LEFT JOIN "viewfil0011" AS "e" ON "a"."公司代碼" = "e"."代碼" LEFT JOIN "viewofobjproperties" AS "f" ON "a"."流水編號" = "f"."單據流水號" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewfil310p" AS "z3" ON "z3"."代碼" = "b"."機台代碼" WHERE "a"."單據類別" = 'E13');

-- Home #2201 ViewFILE02B.裁切調整主檔.E22
CREATE OR REPLACE VIEW "viewfile02b" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."公司代碼", COALESCE("e"."全名", ' ') AS "公司名稱", "a"."單據日期", "a"."簽核系統", "a"."備註", "a"."業務員" AS "倉管員", COALESCE("d"."員工姓名", ' ') AS "倉管員姓名", "a"."歸屬類別" AS "製令類別", "a"."歸屬編號" AS "製令單號", "a"."廠客單號" AS "裁切單號", "m"."分條號", CONCAT("a"."單據編號", '(', TRIM("a"."單據類別"), ')', '/製令:', COALESCE("a"."歸屬編號", ' ')) AS "主旨", COALESCE("z1"."serial_num", ' ') AS "員工流水編號", "a"."流水編號", "a"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "a"."填表日", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日", COALESCE("f"."簽核狀態", '0') AS "簽核狀態" FROM "fil0030" AS "a" /*
	INNER JOIN FIL0031 B ON A.單據類別 = B.單別 AND A.單據編號 = B.單號
	*/ LEFT JOIN "fil0010" AS "d" ON "a"."業務員" = "d"."員工編號" LEFT JOIN "viewfil0011" AS "e" ON "a"."公司代碼" = "e"."代碼" LEFT JOIN "viewofobjproperties" AS "f" ON "a"."流水編號" = "f"."單據流水號" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", STRING_AGG(CAST(REGEXP_SUBSTR("a"."產品編號", '[^_]+', 1, 2) AS TEXT), ',' ORDER BY "a"."單據類別", "a"."單據編號") AS "分條號" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'E22' AND "a"."異動類別" = 'A' GROUP BY "a"."單據類別", "a"."單據編號") AS "m" ON "m"."單別" = "a"."單據類別" AND "m"."單號" = "a"."單據編號" WHERE "a"."單據類別" = 'E22');

-- Home #2204 ViewFILE02H.裁切入庫主檔.E23
CREATE OR REPLACE VIEW "viewfile02h" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."公司代碼", COALESCE("e"."全名", ' ') AS "公司名稱", "a"."歸屬類別" AS "製令類別", "a"."歸屬編號" AS "製令單號", "a"."單據日期", "a"."簽核系統", "a"."備註", "a"."業務員" AS "倉管員", COALESCE("d"."員工姓名", ' ') AS "倉管員姓名", "m"."分條號", "a"."流水編號", "a"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "a"."填表日", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日", COALESCE("f"."簽核狀態", '0') AS "簽核狀態" FROM "fil0030" AS "a" /*
	INNER JOIN FIL0031 B ON A.單據類別 = B.單別 AND A.單據編號 = B.單號
	*/ LEFT JOIN "fil0010" AS "d" ON "a"."業務員" = "d"."員工編號" LEFT JOIN "viewfil0011" AS "e" ON "a"."公司代碼" = "e"."代碼" LEFT JOIN "viewofobjproperties" AS "f" ON "a"."流水編號" = "f"."單據流水號" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", STRING_AGG(CAST(REGEXP_SUBSTR("a"."產品編號", '[^_]+', 1, 2) AS TEXT), ',' ORDER BY "a"."單據類別", "a"."單據編號") AS "分條號" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'E23' AND "a"."異動類別" = 'A' GROUP BY "a"."單據類別", "a"."單據編號") AS "m" ON "m"."單別" = "a"."單據類別" AND "m"."單號" = "a"."單據編號" WHERE "a"."單據類別" = 'E23');

-- Home #2219 ViewFILE02K.半成品入庫主檔.E24
CREATE OR REPLACE VIEW "viewfile02k" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."公司代碼", COALESCE("e"."全名", ' ') AS "公司名稱", "a"."單據日期", "a"."簽核系統", "a"."備註", "a"."業務員" AS "倉管員", COALESCE("d"."員工姓名", ' ') AS "倉管員姓名", "a"."流水編號", "a"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "a"."填表日", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日", COALESCE("f"."簽核狀態", '0') AS "簽核狀態" FROM "fil0030" AS "a" /*
	INNER JOIN FIL0031 B ON A.單據類別 = B.單別 AND A.單據編號 = B.單號
	*/ LEFT JOIN "fil0010" AS "d" ON "a"."業務員" = "d"."員工編號" LEFT JOIN "viewfil0011" AS "e" ON "a"."公司代碼" = "e"."代碼" LEFT JOIN "viewofobjproperties" AS "f" ON "a"."流水編號" = "f"."單據流水號" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" WHERE "a"."單據類別" = 'E24');

-- Home #2087 ViewFILE039.成品品檢主檔.E37
CREATE OR REPLACE VIEW "viewfile039" ("單別", "單號", "裝櫃單別", "貨櫃號碼", "嘜頭序號", "公司代碼", "公司名稱", "單據日期", "簽核系統", "備註", "品檢員", "品檢員姓名", "流水編號", "填表人", "填表人姓名", "填表日", "最後更新者", "更新者姓名", "製程代碼", "工站代碼", "機台代碼", "機台名稱", "工站名稱", "製程名稱", "最後更新日", "簽核狀態", "品檢簽收") AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."歸屬類別" AS "裝櫃單別", "a"."歸屬編號" AS "貨櫃號碼", "a"."歸屬序號" AS "嘜頭序號" /* 棧板單號與嘜頭序號一對一 */, "a"."公司代碼", COALESCE("e"."全名", ' ') AS "公司名稱", "a"."單據日期", "a"."簽核系統", "a"."備註", "a"."業務員" AS "品檢員", COALESCE("d"."員工姓名", ' ') AS "品檢員姓名", "a"."流水編號", "a"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "a"."填表日", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "b"."製程代碼", "b"."工站代碼", "b"."機台代碼", COALESCE("h"."名稱", ' ') AS "機台名稱", COALESCE("i"."名稱", ' ') AS "工站名稱", COALESCE("i"."製程名稱", ' ') AS "製程名稱", "a"."最後更新日", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態", CASE WHEN COALESCE("dbms_lob".getlength("g"."圖檔"), 0) = 0 THEN 0 ELSE 1 END AS "品檢簽收" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0010" AS "d" ON "a"."業務員" = "d"."員工編號" LEFT JOIN "viewfil0011" AS "e" ON "a"."公司代碼" = "e"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN "fil0037" AS "g" ON "a"."單據類別" = "g"."製令單別" AND "a"."單據編號" = "g"."製令單號" AND "g"."材料序號" = 0 LEFT JOIN "viewfil310p" AS "h" ON "b"."機台代碼" = "h"."代碼" LEFT JOIN "viewfil310o" AS "i" ON "b"."工站代碼" = "i"."代碼" LEFT JOIN "viewofobjproperties" AS "z3" ON "a"."流水編號" = "z3"."單據流水號" WHERE "a"."單據類別" = 'E37');

-- Home #2089 ViewFILE03A.成品品檢明細
CREATE OR REPLACE VIEW "viewfile03a" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."產品編號" AS "料號", COALESCE("e"."英文品名", ' ') AS "品名", COALESCE("e"."規格", ' ') AS "規格", COALESCE("e"."英文品名", ' ') AS "英文品名", "b"."單據日期" AS "異動日期", "a"."預交日", "a"."倉庫代碼" AS "庫別代碼", COALESCE("g"."名稱", ' ') AS "庫別名稱", COALESCE("c"."數值1", 0) AS "原庫存數", "a"."異動數量" AS "箱號", "a"."贈品數量" AS "包裝數量", "c"."數值5" * -1 AS "差異數量", "a"."毛重" AS "重量", COALESCE("e"."單位代碼", ' ') AS "庫存單位代碼", COALESCE("f1"."名稱", ' ') AS "庫存單位名稱", COALESCE("e"."銷售單位", ' ') AS "包裝單位代碼", COALESCE("f2"."名稱", ' ') AS "包裝單位名稱", "a"."數值1" AS "箱數", "c"."批號", "a"."廠客品號" AS "製令單號", "z2"."廠客編號" AS "客戶編號", "a"."qrno" /* C.數值1 棧板序號, 依櫃號+製令編製 */, "c"."標籤類別", "a"."備註說明" AS "備註", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" LEFT JOIN "fil0012" AS "e" ON "a"."產品編號" = "e"."產品編號" LEFT JOIN "viewfil3103" AS "f1" ON "e"."單位代碼" = "f1"."代碼" LEFT JOIN "viewfil3103" AS "f2" ON "e"."銷售單位" = "f2"."代碼" LEFT JOIN "viewfil3106" AS "g" ON "a"."倉庫代碼" = "g"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" LEFT JOIN "fil0030" AS "z2" ON "z2"."單據類別" = 'C11' AND "a"."廠客品號" = "z2"."單據編號" WHERE "a"."單據類別" = 'E37');

-- Home #2095 ViewFILE040.貨櫃號碼主檔.E38
CREATE OR REPLACE VIEW "viewfile040" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."公司代碼", COALESCE("d"."全名", ' ') AS "公司名稱", "a"."單據日期", "a"."簽核系統", "a"."廠客編號" AS "客戶編號", "a"."廠客單號" AS "貨櫃號碼", COALESCE("c"."全名", ' ') AS "客戶名稱", "b"."文數字7" AS "attn", "b"."文數字8" AS "tel", "b"."文數字9" AS "fax", "b"."文字1" AS "address", "b"."文字2" AS "價格條件", "b"."文字3" AS "目的地", "b"."文數字1" AS "封條號碼", "b"."文數字2" AS "車架號碼", "b"."文數字3" AS "so", "b"."文數字4" AS "貨櫃尺寸", "b"."文數字5" AS "運送方式", "b"."文數字6" AS "vesselno", "b"."交貨日期" AS "onboarddate", "a"."匯率日期" AS "eta", COALESCE("e"."名稱", ' ') AS "運送方式名稱", "a"."幣別代碼", "a"."備註", "a"."業務員" AS "作業員", COALESCE("z3"."員工姓名", ' ') AS "作業員姓名", "a"."流水編號", "a"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "a"."填表日", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日", COALESCE("z4"."簽核狀態", '0') AS "簽核狀態", CASE WHEN COALESCE("dbms_lob".getlength("z5"."圖檔"), 0) = 0 THEN 0 ELSE 1 END AS "裝櫃簽收" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0011" AS "c" ON "a"."廠客編號" = "c"."編號" LEFT JOIN "viewfil0011" AS "d" ON "a"."公司代碼" = "d"."代碼" LEFT JOIN "viewfil3111" AS "e" ON "b"."文數字5" = "e"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN "fil0010" AS "z3" ON "a"."業務員" = "z3"."員工編號" LEFT JOIN "viewofobjproperties" AS "z4" ON "a"."流水編號" = "z4"."單據流水號" LEFT JOIN "fil0037" AS "z5" ON "a"."單據類別" = "z5"."製令單別" AND "a"."單據編號" = "z5"."製令單號" AND "z5"."材料序號" = 0 WHERE "a"."單據類別" = 'E38');

-- Home #2096 ViewFILE041.貨櫃號碼明細
CREATE OR REPLACE VIEW "viewfile041" AS (SELECT "b"."歸屬類別" AS "裝櫃單別", "b"."歸屬編號" AS "貨櫃號碼", "b"."歸屬序號" AS "嘜頭序號", "a"."單據類別" AS "品檢單別", "a"."單據編號" AS "品檢單號", "a"."單據序號" AS "品檢序號", "a"."產品編號" AS "料號", COALESCE("e"."英文品名", ' ') AS "品名", COALESCE("e"."規格", ' ') AS "規格", "a"."異動日期", "a"."倉庫代碼" AS "庫別代碼", COALESCE("g"."名稱", ' ') AS "庫別名稱", "a"."異動數量" AS "箱號", "a"."贈品數量" AS "包裝數量", "a"."毛重" AS "重量", COALESCE("e"."單位代碼", ' ') AS "庫存單位代碼", COALESCE("f1"."名稱", ' ') AS "庫存單位名稱", COALESCE("e"."銷售單位", ' ') AS "包裝單位代碼", COALESCE("f2"."名稱", ' ') AS "包裝單位名稱", "a"."數值1" AS "箱數", "c"."批號", "a"."廠客品號" AS "製令單號", "a"."備註說明" AS "備註" /* C.數值1 棧板序號, 依櫃號+製令編製 */, "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" /* 貨櫃號碼 */ INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" AND "b"."歸屬類別" = 'E38' /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN "fil0012" AS "e" ON "a"."產品編號" = "e"."產品編號" LEFT JOIN "viewfil3103" AS "f1" ON "e"."單位代碼" = "f1"."代碼" LEFT JOIN "viewfil3103" AS "f2" ON "e"."銷售單位" = "f2"."代碼" LEFT JOIN "viewfil3106" AS "g" ON "a"."倉庫代碼" = "g"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."單據類別" = 'E37');

-- Home #2104 ViewFILF010.委外加工主檔.F11
CREATE OR REPLACE VIEW "viewfilf010" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."公司代碼", COALESCE("e"."全名", ' ') AS "公司名稱", "a"."單據日期", "a"."簽核系統", "a"."備註", "a"."業務員" AS "倉管員", COALESCE("d"."員工姓名", ' ') AS "倉管員姓名", "a"."流水編號", "a"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "a"."填表日", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "b"."製程代碼", "b"."工站代碼", "b"."機台代碼", COALESCE("h"."名稱", ' ') AS "機台名稱", COALESCE("i"."名稱", ' ') AS "工站名稱", COALESCE("i"."製程名稱", ' ') AS "製程名稱", "a"."最後更新日", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態", CASE WHEN COALESCE("dbms_lob".getlength("g"."圖檔"), 0) = 0 THEN 0 ELSE 1 END AS "廠商簽收" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0010" AS "d" ON "a"."業務員" = "d"."員工編號" LEFT JOIN "viewfil0011" AS "e" ON "a"."公司代碼" = "e"."代碼" LEFT JOIN "fil0037" AS "g" ON "a"."單據類別" = "g"."製令單別" AND "a"."單據編號" = "g"."製令單號" AND "g"."材料序號" = 0 LEFT JOIN "viewfil310p" AS "h" ON "b"."機台代碼" = "h"."代碼" LEFT JOIN "viewfil310o" AS "i" ON "b"."工站代碼" = "i"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewofobjproperties" AS "z3" ON "a"."流水編號" = "z3"."單據流水號" WHERE "a"."單據類別" = 'F11');

-- Home #2108 ViewFILF014.委外加工生產數
CREATE OR REPLACE VIEW "viewfilf014" AS (SELECT "b"."製程代碼", "b"."工站代碼", "c"."歸屬編號" AS "製令單號", SUM("a"."贈品數量") AS "生產數量", SUM("a"."燙金費") AS "合理剔除數", SUM("d"."數值5") AS "報廢數量" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "d" ON "d"."單別" = "a"."單據類別" AND "d"."單號" = "a"."單據編號" AND "d"."序號" = "a"."單據序號" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" INNER JOIN "viewfilf015" AS "e" ON "b"."工站代碼" = "e"."工站代碼" AND "c"."歸屬編號" = "e"."製令單號" AND "c"."填表日" >= "e"."填表日" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" BETWEEN 'C31F' AND 'C31G' GROUP BY "b"."製程代碼", "b"."工站代碼", "c"."歸屬編號");

