CREATE OR REPLACE VIEW "viewfilf061" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."稅別" AS "類別代碼", CASE WHEN "a"."稅別" = 'A' THEN '委外' ELSE '廠內' END AS "類別說明", "a"."公司代碼", COALESCE("e"."全名", ' ') AS "公司名稱", "a"."單據日期", "a"."簽核系統", "a"."備註", "a"."業務員" AS "倉管員", COALESCE("d"."員工姓名", ' ') AS "倉管員姓名", "a"."流水編號", "a"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "a"."填表日", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "b"."製程代碼", CASE WHEN "a"."稅別" = 'A' THEN COALESCE("i"."製程名稱", ' ') ELSE CASE WHEN "b"."製程代碼" = 'M' THEN '原料' WHEN "b"."製程代碼" = 'N' THEN '物料' WHEN "b"."製程代碼" = 'O' THEN '其他' WHEN "b"."製程代碼" = 'S' THEN '半成品' WHEN "b"."製程代碼" = 'P' THEN '版銅' ELSE '錯誤' END END AS "製程名稱", "b"."工站代碼", CASE WHEN "a"."稅別" = 'A' THEN COALESCE("i"."名稱", ' ') ELSE COALESCE("j"."名稱", ' ') END AS "工站名稱", CASE WHEN "a"."稅別" = 'A' THEN COALESCE("i"."製程工站", ' ') ELSE CONCAT(COALESCE("j"."名稱", ' '), '(', CASE WHEN "b"."製程代碼" = 'M' THEN '原料' WHEN "b"."製程代碼" = 'N' THEN '物料' WHEN "b"."製程代碼" = 'O' THEN '其他' WHEN "b"."製程代碼" = 'S' THEN '半成品' WHEN "b"."製程代碼" = 'P' THEN '版銅' ELSE '錯誤' END, ')') END AS "製程工站", "b"."機台代碼", COALESCE("h"."名稱", ' ') AS "機台名稱", "a"."最後更新日", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0010" AS "d" ON "a"."業務員" = "d"."員工編號" LEFT JOIN "viewfil0011" AS "e" ON "a"."公司代碼" = "e"."代碼" LEFT JOIN "fil0037" AS "g" ON "a"."單據類別" = "g"."製令單別" AND "a"."單據編號" = "g"."製令單號" AND "g"."材料序號" = 0 /* 委外盤點.工站 */ LEFT JOIN "viewfil310p" AS "h" ON "b"."機台代碼" = "h"."代碼" LEFT JOIN "viewfil310o" AS "i" ON "b"."工站代碼" = "i"."代碼" /* 廠內盤點.物料大類 */ LEFT JOIN "viewfil310b" AS "j" ON "b"."工站代碼" = "j"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewofobjproperties" AS "z3" ON "a"."流水編號" = "z3"."單據流水號" WHERE "a"."單據類別" = 'F35');

-- Home #2130 ViewFILF0W0.委外半成品結存檔
CREATE OR REPLACE VIEW "viewfilf0w0" AS (SELECT "a"."製程代碼", "d"."製程名稱", "a"."工站代碼", "d"."名稱" AS "工站名稱", "d"."製程工站", "c"."產品編號", "c"."產品名稱" AS "品名", "c"."展開尺寸" AS "規格", "c"."加工項目_氣閥代碼" AS "氣閥代碼", "a"."製令單號", "a"."填表日" AS "製造日期", "a"."加工數量", "a"."回廠數量", "a"."退回數量", "a"."調整數量", COALESCE("b"."生產數量", 0) AS "生產數量", COALESCE("b"."報廢數量", 0) AS "報廢數量", COALESCE("b"."合理剔除數", 0) AS "合理剔除數", "a"."加工數量" - "a"."回廠數量" - "a"."退回數量" + "a"."調整數量" - COALESCE("b"."報廢數量", 0) - COALESCE("b"."合理剔除數", 0) AS "結存數量", CASE WHEN ("a"."加工數量" - "a"."回廠數量" - "a"."退回數量" + "a"."調整數量" - COALESCE("b"."報廢數量", 0) - COALESCE("b"."合理剔除數", 0)) = 0 THEN 0 ELSE "a"."加工數量" - "a"."退回數量" - COALESCE("b"."生產數量", 0) - COALESCE("b"."報廢數量", 0) - COALESCE("b"."合理剔除數", 0) END AS "待生產數量", CASE WHEN ("a"."加工數量" - "a"."回廠數量" - "a"."退回數量" + "a"."調整數量" - COALESCE("b"."報廢數量", 0) - COALESCE("b"."合理剔除數", 0)) = 0 THEN 0 ELSE COALESCE("b"."生產數量", 0) - "a"."回廠數量" END AS "待回廠數量", CASE WHEN ("a"."加工數量" - "a"."退回數量") = (COALESCE("b"."報廢數量", 0) + COALESCE("b"."生產數量", 0) + COALESCE("b"."合理剔除數", 0)) OR (("a"."加工數量" - "a"."退回數量") IS NULL AND (COALESCE("b"."報廢數量", 0) + COALESCE("b"."生產數量", 0) + COALESCE("b"."合理剔除數", 0)) IS NULL) THEN 1 ELSE 0 END AS "結案" FROM (SELECT "b"."製程代碼", "b"."工站代碼", "a"."廠客品號" AS "製令單號", MIN(COALESCE("d"."填表日", "e"."填表日")) AS "填表日", SUM(CASE WHEN "a"."單據類別" = 'F11' THEN "a"."贈品數量" ELSE 0 END) AS "加工數量", SUM(CASE WHEN "a"."單據類別" = 'F21' THEN "a"."贈品數量" * CASE WHEN "a"."logical1" = 0 THEN 1 ELSE 0 END ELSE 0 END) AS "回廠數量", SUM(CASE WHEN "a"."單據類別" = 'F21' THEN "a"."贈品數量" * CASE WHEN "a"."logical1" = 0 THEN 0 ELSE 1 END ELSE 0 END) AS "退回數量", SUM(CASE WHEN "a"."單據類別" = 'F32' THEN "a"."贈品數量" ELSE 0 END) AS "調整數量" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0037" AS "c" ON "a"."單據類別" = "c"."製令單別" AND "a"."單據編號" = "c"."製令單號" AND "c"."材料序號" = 0 AND ((COALESCE("dbms_lob".getlength("c"."圖檔"), 0) > 0) OR "a"."單據類別" = 'F32') LEFT JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" AND "d"."單據類別" = 'F11' LEFT JOIN "fil0030" AS "e" ON "a"."單據類別" = "e"."單據類別" AND "a"."單據編號" = "e"."單據編號" WHERE "a"."單據類別" BETWEEN 'F11' AND 'F32' AND "a"."單據類別" <> 'F31' GROUP BY "b"."製程代碼", "b"."工站代碼", "a"."廠客品號") AS "a" INNER JOIN "viewfil310o" AS "d" ON "a"."工站代碼" = "d"."代碼" INNER JOIN "fil0032" AS "c" ON "c"."製令單別" = 'C11' AND "c"."製令單號" = "a"."製令單號" LEFT JOIN "viewfilf014" AS "b" ON "a"."工站代碼" = "b"."工站代碼" AND "a"."製令單號" = "b"."製令單號");

-- Home #2136 ViewFILF0W3D.委外原物料預估檔
CREATE OR REPLACE VIEW "viewfilf0w3d" AS (SELECT "a"."氣閥代碼" AS "料號", "a"."工站代碼", SUM("a"."待生產數量") AS "預估用量" FROM (SELECT "a"."工站代碼", "c"."加工項目_氣閥代碼" AS "氣閥代碼", CASE WHEN ("a"."加工數量" - "a"."回廠數量" - "a"."退回數量" + "a"."調整數量" - COALESCE("b"."報廢數量", 0)) = 0 THEN 0 ELSE "a"."加工數量" - "a"."退回數量" - COALESCE("b"."生產數量", 0) - COALESCE("b"."報廢數量", 0) END AS "待生產數量" FROM (SELECT "b"."製程代碼", "b"."工站代碼", "a"."廠客品號" AS "製令單號", SUM(CASE WHEN "a"."單據類別" = 'F11' THEN "a"."贈品數量" ELSE 0 END) AS "加工數量", SUM(CASE WHEN "a"."單據類別" = 'F21' THEN "a"."贈品數量" * CASE WHEN "a"."logical1" = 0 THEN 1 ELSE 0 END ELSE 0 END) AS "回廠數量", SUM(CASE WHEN "a"."單據類別" = 'F21' THEN "a"."贈品數量" * CASE WHEN "a"."logical1" = 0 THEN 0 ELSE 1 END ELSE 0 END) AS "退回數量", SUM(CASE WHEN "a"."單據類別" = 'F32' THEN "a"."贈品數量" ELSE 0 END) AS "調整數量" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0037" AS "c" ON "a"."單據類別" = "c"."製令單別" AND "a"."單據編號" = "c"."製令單號" AND "c"."材料序號" = 0 AND ((COALESCE("dbms_lob".getlength("c"."圖檔"), 0) > 0) OR "a"."單據類別" = 'F32') INNER JOIN "fil1014" AS "i" ON "i"."代碼類別" = '工站代碼' AND "b"."工站代碼" = "i"."系統代碼" WHERE "a"."單據類別" BETWEEN 'F11' AND 'F32' AND "a"."單據類別" <> 'F31' AND "a"."異動日期" >= "i"."日期一" GROUP BY "b"."製程代碼", "b"."工站代碼", "a"."廠客品號") AS "a" INNER JOIN "fil0032" AS "c" ON "c"."製令單別" = 'C11' AND "c"."製令單號" = "a"."製令單號" LEFT JOIN "viewfilf014" AS "b" ON "a"."工站代碼" = "b"."工站代碼" AND "a"."製令單號" = "b"."製令單號") AS "a" GROUP BY "a"."氣閥代碼", "a"."工站代碼");

-- Home #2140 ViewFILF0W4B1.委外原物料結存檔
CREATE OR REPLACE VIEW "viewfilf0w4b_1" AS (SELECT "a"."產品編號" AS "料號", "b"."製程代碼", "b"."工站代碼", SUM(CASE WHEN "a"."單據類別" = 'F11' THEN "a"."贈品數量" ELSE 0 END) AS "加工數量", SUM(CASE WHEN "a"."單據類別" = 'F21' THEN "a"."贈品數量" ELSE 0 END) AS "回廠數量", 0 AS "耗用數量", 0 AS "報廢數量", SUM(CASE WHEN "a"."單據類別" = 'F32' THEN "a"."贈品數量" ELSE 0 END) AS "調整數量", SUM("a"."贈品數量" * CASE WHEN "a"."單據類別" = 'F11' THEN 1 WHEN "a"."單據類別" = 'F21' THEN -1 WHEN "a"."單據類別" = 'F32' THEN 1 ELSE -1 END) AS "結存數量" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" LEFT JOIN "viewofobjproperties" AS "d1" ON "d"."流水編號" = "d1"."單據流水號" /* 料號 */ INNER JOIN "fil0012" AS "e" ON "a"."產品編號" = "e"."產品編號" AND "e"."產品類別" BETWEEN 'M' AND 'P' INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" /* 簽收 */ INNER JOIN "fil0037" AS "f" ON "a"."單據類別" = "f"."製令單別" AND "a"."單據編號" = "f"."製令單號" AND "f"."材料序號" = 0 AND ((COALESCE("dbms_lob".getlength("f"."圖檔"), 0) > 0) OR "a"."單據類別" = 'F32') /* 填單日 */ INNER JOIN "viewfilf013" AS "h" ON "h"."工站代碼" = "b"."工站代碼" AND "h"."批號" = "c"."批號" AND CASE WHEN "d1"."送簽日時" IS NULL THEN "d"."填表日" ELSE "d1"."送簽日時" END >= "h"."填表日" INNER JOIN "fil1014" AS "i" ON "i"."代碼類別" = '工站代碼' AND "b"."工站代碼" = "i"."系統代碼" WHERE "a"."單據類別" BETWEEN 'F11' AND 'F32' AND "a"."單據類別" <> 'F31' AND "a"."異動日期" >= "i"."日期" GROUP BY "a"."產品編號", "b"."製程代碼", "b"."工站代碼");

-- Home #2143 ViewFILF0W4B4.委外原物料結存檔
CREATE OR REPLACE VIEW "viewfilf0w4b_4" AS (/* 材料耗用.氣閥.鐵條 */ /* 報廢 */ SELECT "a"."產品編號" AS "料號", "c"."製程代碼", "c"."工站代碼", 0 AS "加工數量", 0 AS "回廠數量", 0 AS "耗用數量", SUM("a"."異動數量") AS "報廢數量", 0 AS "調整數量", SUM("a"."異動數量" * CASE WHEN "a"."單據類別" = 'F11' THEN 1 WHEN "a"."單據類別" = 'F21' THEN -1 WHEN "a"."單據類別" = 'F32' THEN 1 ELSE -1 END) AS "結存數量" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "g" ON "a"."單據類別" = "g"."單據類別" AND "a"."單據編號" = "g"."單據編號" LEFT JOIN "viewofobjproperties" AS "d1" ON "g"."流水編號" = "d1"."單據流水號" /* 填單日 */ INNER JOIN "viewfilf013" AS "h" ON "h"."工站代碼" = "c"."工站代碼" AND "h"."批號" = "b"."批號" AND CASE WHEN "d1"."送簽日時" IS NULL THEN "g"."填表日" ELSE "d1"."送簽日時" END >= "h"."填表日" INNER JOIN "fil1014" AS "i" ON "i"."代碼類別" = '工站代碼' AND "c"."工站代碼" = "i"."系統代碼" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'D' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "a"."產品編號" <> ' ' AND "a"."異動日期" >= "i"."日期" GROUP BY "a"."產品編號", "c"."製程代碼", "c"."工站代碼");

-- Home #2276 ViewFILH001.請假申請單.H01
CREATE OR REPLACE VIEW "viewfilh001" AS (SELECT 'H01' AS "單別", "a"."單號", "b"."單據日期", CONCAT("a"."單號", '(', 'H01', ')') AS "主旨", "a"."填寫人", COALESCE("c"."員工姓名", ' ') AS "填寫人姓名", "a"."申請人", COALESCE("f"."員工姓名", ' ') AS "申請人姓名", "a"."填寫日期", "a"."假別", COALESCE("d"."名稱", ' ') AS "假別名稱", CASE WHEN "a"."請假假別" = ' ' THEN "a"."假別" ELSE "a"."請假假別" END AS "請假假別", COALESCE(CASE WHEN "a"."請假假別" = ' ' THEN "d"."名稱" ELSE "d1"."名稱" END, ' ') AS "請假假別名稱", "a"."起始日期", "a"."起始時間", "a"."截止日期", "a"."截止時間", "a"."天數", "a"."時數", ("a"."天數" * 8 + "a"."時數") AS "請假時數", "a"."代理人", COALESCE("e"."員工姓名", ' ') AS "代理人姓名", "b"."部門編號", COALESCE("z3"."guname", ' ') AS "部門名稱", COALESCE("z2"."簽核狀態", '0') AS "簽核狀態", CASE WHEN COALESCE("z2"."簽核狀態", ' ') = ' ' THEN ' ' WHEN COALESCE("z2"."簽核狀態", ' ') = '0' THEN ' ' WHEN COALESCE("z2"."簽核狀態", ' ') = 'I' THEN '1' WHEN COALESCE("z2"."簽核狀態", ' ') = 'D' THEN '2' WHEN COALESCE("z2"."簽核狀態", ' ') = 'E' THEN '3' WHEN COALESCE("z2"."簽核狀態", ' ') = 'A' THEN 'Z' ELSE ' ' END AS "簽核排序", "b"."簽核系統", COALESCE("g"."每日時數合計", 0) AS "每日時數合計", "a"."流水編號", "a"."請假事由", "b"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", COALESCE("c"."serial_num", ' ') AS "員工流水編號", "b"."最後更新日" FROM "hrfil1031" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."流水編號" = "b"."流水編號" LEFT JOIN "fil0010" AS "c" ON "a"."填寫人" = "c"."員工編號" LEFT JOIN "viewfil3801" AS "d" ON "a"."假別" = "d"."代碼" LEFT JOIN "viewfil3801" AS "d1" ON "a"."請假假別" = "d1"."代碼" LEFT JOIN "fil0010" AS "e" ON "a"."代理人" = "e"."員工編號" LEFT JOIN "fil0010" AS "f" ON "a"."申請人" = "f"."員工編號" LEFT JOIN "fil0010" AS "z1" ON "b"."最後更新者" = "z1"."員工編號" LEFT JOIN "viewofobjproperties" AS "z2" ON "a"."流水編號" = "z2"."單據流水號" LEFT JOIN "a30" AS "z3" ON "b"."部門編號" = "z3"."groupid" LEFT JOIN (SELECT "a"."單據類別", "a"."單據編號", SUM("a"."異動數量") AS "每日時數合計" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'H01' GROUP BY "a"."單據類別", "a"."單據編號") AS "g" ON "g"."單據類別" = "a"."單別" AND "g"."單據編號" = "a"."單號" WHERE "b"."單據類別" = 'H01');

-- Home #2277 ViewFILH002.特休排定表.H02
CREATE OR REPLACE VIEW "viewfilh002" AS (SELECT 'H02' AS "單別", "a"."單號", "b"."單據日期", CONCAT("a"."單號", '(', 'H02', ')') AS "主旨", CASE WHEN "b"."稅別" = 'T' THEN 1 ELSE 0 END AS "類別", "a"."填寫人", COALESCE("c"."員工姓名", ' ') AS "填寫人姓名", "a"."申請人", COALESCE("d"."員工姓名", ' ') AS "申請人姓名", "a"."填寫日期", "a"."年度", "a"."應休天數", "a"."生效日期", "a"."一月", "a"."二月", "a"."三月", "a"."四月", "a"."五月", "a"."六月", "a"."七月", "a"."八月", "a"."九月", "a"."十月", "a"."十一月", "a"."十二月", "a"."一月" + "a"."二月" + "a"."三月" + "a"."四月" + "a"."五月" + "a"."六月" + "a"."七月" + "a"."八月" + "a"."九月" + "a"."十月" + "a"."十一月" + "a"."十二月" AS "合計", "b"."部門編號", COALESCE("z3"."guname", ' ') AS "部門名稱", COALESCE("z2"."簽核狀態", '0') AS "簽核狀態", "b"."簽核系統", "a"."流水編號", "a"."事由", "b"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", COALESCE("c"."serial_num", ' ') AS "員工流水編號", "b"."最後更新日" FROM "hrfil1032" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."流水編號" = "b"."流水編號" LEFT JOIN "fil0010" AS "c" ON "a"."填寫人" = "c"."員工編號" LEFT JOIN "fil0010" AS "d" ON "a"."申請人" = "d"."員工編號" LEFT JOIN "fil0010" AS "z1" ON "b"."最後更新者" = "z1"."員工編號" LEFT JOIN "viewofobjproperties" AS "z2" ON "a"."流水編號" = "z2"."單據流水號" LEFT JOIN "a30" AS "z3" ON "b"."部門編號" = "z3"."groupid");

-- Home #2279 ViewFILH004.加班費主檔.H03
CREATE OR REPLACE VIEW "viewfilh004" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", CONCAT("a"."單據編號", '(', "a"."單據類別", ')') AS "主旨", "a"."公司代碼", COALESCE("e"."全名", ' ') AS "公司名稱", "a"."單據日期" AS "加班日期", '000000' AS "計薪日期", "a"."部門編號", COALESCE("b"."guname", ' ') AS "部門名稱", "a"."簽核系統", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態", CASE WHEN COALESCE("z3"."簽核狀態", ' ') = ' ' THEN ' .未送簽' WHEN COALESCE("z3"."簽核狀態", ' ') = 'I' THEN '1.簽核中' WHEN COALESCE("z3"."簽核狀態", ' ') = 'D' THEN '2.退回' WHEN COALESCE("z3"."簽核狀態", ' ') = 'A' THEN '3.作廢' WHEN COALESCE("z3"."簽核狀態", ' ') = 'E' THEN '9.已簽' ELSE ' .草稿' END AS "簽核排序", "a"."備註", "a"."流水編號", "a"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", COALESCE("z4"."guname", ' ') AS "填表人職稱", "a"."填表日", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", COALESCE("z1"."serial_num", ' ') AS "員工流水編號", "a"."最後更新日" FROM "fil0030" AS "a" LEFT JOIN "a30" AS "b" ON "a"."部門編號" = "b"."groupid" LEFT JOIN "viewfil0011" AS "e" ON "a"."公司代碼" = "e"."代碼" LEFT JOIN "viewfil0030" AS "f" ON "a"."簽核系統" = "f"."簽核系統" AND "a"."單據編號" = "f"."單號" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewofobjproperties" AS "z3" ON "a"."流水編號" = "z3"."單據流水號" LEFT JOIN "a40" AS "z4" ON "z1"."flowposi" = "z4"."serial_num" WHERE "a"."單據類別" = 'H03');

-- Home #2280 ViewFILH005.加班費明細
CREATE OR REPLACE VIEW "viewfilh005" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."產品編號" AS "申請人", CASE WHEN "a"."異動日期" = '00000000' THEN "b"."單據日期" ELSE "a"."異動日期" END AS "加班日期", COALESCE("e"."員工姓名", ' ') AS "申請人姓名", COALESCE("e"."部門編號", ' ') AS "部門編號", COALESCE("f"."guname", ' ') AS "部門名稱", COALESCE("g"."工作內容", ' ') AS "工作內容", "a"."異動數量" AS "數量", "a"."單位代碼", COALESCE("d"."名稱", ' ') AS "單位名稱", "c"."time1" AS "時間起", "c"."time2" AS "時間訖", "c"."time3" AS "休息起1", "c"."time4" AS "休息迄1", "c"."time5" AS "休息起2", "c"."time6" AS "休息迄2", "a"."贈品數量" AS "時數", "a"."異動單價" AS "休息1", "a"."異動金額" AS "休息2", "a"."贈品數量" - "a"."異動單價" - "a"."異動金額" AS "小計", "a"."logical1" AS "計件", "a"."logical2" AS "調補", "a"."logical3" AS "教育", "a"."logical4" AS "計時", "a"."備註說明" AS "備註", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日", COALESCE("z3"."簽核狀態", ' ') AS "簽核狀態" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN "viewfil3103" AS "d" ON "a"."單位代碼" = "d"."代碼" LEFT JOIN "fil0010" AS "e" ON "a"."產品編號" = "e"."員工編號" LEFT JOIN "a30" AS "f" ON "e"."部門編號" = "f"."groupid" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" LEFT JOIN "viewofobjproperties" AS "z3" ON "b"."流水編號" = "z3"."單據流水號" LEFT JOIN (SELECT "a"."製令單別", "a"."製令單號", "a"."材料序號" AS "序號", "utl_raw".cast_to_nvarchar2(STRING_AGG(CAST(CONCAT("utl_raw".cast_to_raw(CONCAT("a"."備註", (CASE WHEN "a"."相關單號" <> ' ' THEN CONCAT('|', "a"."相關單號") END), '/')), "utl_raw".cast_to_raw(TO_NCHAR(ROUND("a"."數字一"))), "utl_raw".cast_to_raw(COALESCE("b"."名稱", ' '))) AS TEXT), "utl_raw".cast_to_raw(N'　') ORDER BY "a"."製令單別", "a"."製令單號", "a"."材料序號", "a"."序號")) AS "工作內容" FROM "fil0037" AS "a" LEFT JOIN "viewfil3103" AS "b" ON "a"."代碼" = "b"."代碼" WHERE "a"."製令單別" = 'H03' GROUP BY "a"."製令單別", "a"."製令單號", "a"."材料序號") AS "g" ON "a"."單據類別" = "g"."製令單別" AND "a"."單據編號" = "g"."製令單號" AND "a"."單據序號" = "g"."序號" WHERE "a"."單據類別" = 'H03');

-- Home #2281 ViewFILH005A.每日加班費(已簽)
CREATE OR REPLACE VIEW "viewfilh005a" AS (SELECT "a"."產品編號" AS "申請人", CASE WHEN "a"."異動日期" = '00000000' THEN "b"."單據日期" ELSE "a"."異動日期" END AS "加班日期", "a"."logical2" AS "調補", SUM("a"."贈品數量" - "a"."異動單價" - "a"."異動金額") AS "小計" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" LEFT JOIN "viewofobjproperties" AS "z3" ON "b"."流水編號" = "z3"."單據流水號" WHERE "a"."單據類別" = 'H03' AND "z3"."簽核狀態" = 'E' AND "a"."logical1" = 0 GROUP BY "a"."產品編號", CASE WHEN "a"."異動日期" = '00000000' THEN "b"."單據日期" ELSE "a"."異動日期" END, "a"."logical2");

-- Home #2282 ViewFILH005B.每日加班費(教育)
CREATE OR REPLACE VIEW "viewfilh005b" AS (SELECT "a"."產品編號" AS "申請人", CASE WHEN "a"."異動日期" = '00000000' THEN "b"."單據日期" ELSE "a"."異動日期" END AS "加班日期", "a"."logical2" AS "調補", "a"."logical3" AS "教育", SUM("a"."贈品數量" - "a"."異動單價" - "a"."異動金額") AS "小計" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" LEFT JOIN "viewofobjproperties" AS "z3" ON "b"."流水編號" = "z3"."單據流水號" WHERE "a"."單據類別" = 'H03' AND "z3"."簽核狀態" = 'E' AND "a"."logical1" = 0 GROUP BY "a"."產品編號", CASE WHEN "a"."異動日期" = '00000000' THEN "b"."單據日期" ELSE "a"."異動日期" END, "a"."logical2", "a"."logical3");

-- Home #2288 ViewFILH009.加班說明
CREATE OR REPLACE VIEW "viewfilh009" AS (SELECT "m"."製令單別" AS "單別", "m"."製令單號" AS "單號", "m"."材料序號" AS "單據序號", "m"."序號" AS "序號", "a"."產品編號" AS "申請人", "b"."單據日期" AS "加班日期", COALESCE("e"."員工姓名", ' ') AS "申請人姓名", COALESCE("e"."部門編號", ' ') AS "部門編號", COALESCE("f"."guname", ' ') AS "部門名稱", COALESCE("m"."備註", ' ') AS "工作內容", "m"."數字一" AS "數量", "m"."代碼" AS "單位代碼", COALESCE("d"."名稱", ' ') AS "單位名稱", "a"."logical1" AS "計件", "m"."相關單號", COALESCE("z3"."簽核狀態", ' ') AS "簽核狀態" FROM "fil0037" AS "m" INNER JOIN "fil0040" AS "a" ON "a"."單據類別" = "m"."製令單別" AND "a"."單據編號" = "m"."製令單號" AND "a"."單據序號" = "m"."材料序號" INNER JOIN "fil0030" AS "b" ON "m"."製令單別" = "b"."單據類別" AND "m"."製令單號" = "b"."單據編號" INNER JOIN "fil0041" AS "c" ON "m"."製令單別" = "c"."單別" AND "m"."製令單號" = "c"."單號" AND "m"."材料序號" = "c"."序號" LEFT JOIN "viewfil3103" AS "d" ON "m"."代碼" = "d"."代碼" LEFT JOIN "fil0010" AS "e" ON "a"."產品編號" = "e"."員工編號" LEFT JOIN "a30" AS "f" ON "e"."部門編號" = "f"."groupid" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" LEFT JOIN "viewofobjproperties" AS "z3" ON "b"."流水編號" = "z3"."單據流水號" WHERE "m"."製令單別" = 'H03' AND "m"."屬性" = '4');

-- Home #2297 ViewFILH017.員工每月加班
CREATE OR REPLACE VIEW "viewfilh017" AS (SELECT "a"."申請人", ORA_SUBSTR("a"."加班日期", 1, 6) AS "加班年月", SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) <= 1 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" >= 2 THEN 2 ELSE "a"."小計" END) ELSE 0 END, 0)) AS "平日前2小時" /* 平日、補班 */, SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) <= 1 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 2 AND "a"."小計" < 4 THEN "a"."小計" - 2 WHEN "a"."小計" >= 4 THEN 2 ELSE 0 END) ELSE 0 END, 0)) AS "平日前4小時", SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) <= 1 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 4 THEN "a"."小計" - 4 ELSE 0 END) ELSE 0 END, 0)) AS "平日大於4小時", SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 2 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" >= 2 THEN 2 ELSE "a"."小計" END) ELSE 0 END, 0)) AS "休息日前2小時" /* 休息日 */, SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 2 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 2 AND "a"."小計" < 8 THEN "a"."小計" - 2 WHEN "a"."小計" >= 8 THEN 6 ELSE 0 END) ELSE 0 END, 0)) AS "休息日前8小時", SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 2 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 8 THEN "a"."小計" - 8 ELSE 0 END) ELSE 0 END, 0)) AS "休息日大於8小時", SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 3 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 0 THEN (CASE WHEN "a"."小計" > 8 THEN 8 ELSE "a"."小計" END) ELSE 0 END) ELSE 0 END, 0)) AS "例假日前8小時" /* 例假日 */, SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 3 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 8 AND "a"."小計" < 10 THEN "a"."小計" - 8 WHEN "a"."小計" >= 10 THEN 2 ELSE 0 END) ELSE 0 END, 0)) AS "例假日大於8小時", SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 3 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 10 THEN "a"."小計" - 10 ELSE 0 END) ELSE 0 END, 0)) AS "例假日大於10小時", SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 3 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 8 THEN 8 ELSE "a"."小計" END) ELSE 0 END, 0)) AS "例假日補休小時", SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 4 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 0 THEN (CASE WHEN "a"."小計" > 8 THEN 8 ELSE "a"."小計" END) ELSE 0 END) ELSE 0 END, 0)) AS "國定假日前8小時" /* 國定假日 */, SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 4 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 8 AND "a"."小計" < 10 THEN "a"."小計" - 8 WHEN "a"."小計" >= 10 THEN 2 ELSE 0 END) ELSE 0 END, 0)) AS "國定假日大於8小時", SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 4 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 10 THEN "a"."小計" - 10 ELSE 0 END) ELSE 0 END, 0)) AS "國定假日大於10小時", SUM(COALESCE(CASE WHEN "a"."調補" = 1 THEN "a"."小計" ELSE 0 END, 0)) AS "調補時數" /* 調補 */ FROM "viewfilh005a" AS "a" LEFT JOIN "viewfil3805" AS "c" ON "a"."加班日期" = "c"."日期" GROUP BY "a"."申請人", ORA_SUBSTR("a"."加班日期", 1, 6));

-- Home #2298 ViewFILH018.出勤調整單.H05
CREATE OR REPLACE VIEW "viewfilh018" AS (SELECT 'H05' AS "單別", "a"."單號", "b"."單據日期", CONCAT("a"."單號", '(', 'H01', ')') AS "主旨", "a"."填寫人", COALESCE("c"."員工姓名", ' ') AS "填寫人姓名", "a"."申請人", COALESCE("f"."員工姓名", ' ') AS "申請人姓名", "a"."填寫日期", "a"."假別", COALESCE("d"."名稱", ' ') AS "假別名稱", CASE WHEN "a"."請假假別" = ' ' THEN "a"."假別" ELSE "a"."請假假別" END AS "請假假別", COALESCE(CASE WHEN "a"."請假假別" = ' ' THEN "d"."名稱" ELSE "d1"."名稱" END, ' ') AS "請假假別名稱", "a"."起始日期", "a"."起始時間", "a"."截止日期", "a"."截止時間", "a"."天數", "a"."時數", "a"."代理人", COALESCE("e"."員工姓名", ' ') AS "代理人姓名", "b"."部門編號", COALESCE("z3"."guname", ' ') AS "部門名稱", COALESCE("z2"."簽核狀態", ' ') AS "簽核狀態", "b"."簽核系統", "a"."流水編號", "a"."請假事由", "b"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", COALESCE("c"."serial_num", ' ') AS "員工流水編號", "b"."最後更新日" FROM "hrfil1031" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."流水編號" = "b"."流水編號" LEFT JOIN "fil0010" AS "c" ON "a"."填寫人" = "c"."員工編號" LEFT JOIN "viewfil3801" AS "d" ON "a"."假別" = "d"."代碼" LEFT JOIN "viewfil3801" AS "d1" ON "a"."請假假別" = "d1"."代碼" LEFT JOIN "fil0010" AS "e" ON "a"."代理人" = "e"."員工編號" LEFT JOIN "fil0010" AS "f" ON "a"."申請人" = "f"."員工編號" LEFT JOIN "fil0010" AS "z1" ON "b"."最後更新者" = "z1"."員工編號" LEFT JOIN "viewofobjproperties" AS "z2" ON "a"."流水編號" = "z2"."單據流水號" LEFT JOIN "a30" AS "z3" ON "b"."部門編號" = "z3"."groupid" WHERE "b"."單據類別" = 'H05');

-- Home #2299 ViewFILH019.每日請假清單
CREATE OR REPLACE VIEW "viewfilh019" AS (SELECT "a"."申請人", "m"."異動日期" AS "起始日期", "utl_raw".cast_to_nvarchar2(STRING_AGG(CAST(CONCAT("utl_raw".cast_to_raw(CONCAT("a"."假別名稱", ORA_SUBSTR("m"."time1", 1, 2), ':', ORA_SUBSTR("m"."time1", 3, 2), '[')), "utl_raw".cast_to_raw(TRIM(TO_NCHAR(ROUND("m"."異動數量", 1), '90D9'))), "utl_raw".cast_to_raw(CONCAT(N'小時]', TRIM(CASE WHEN "a"."簽核狀態" = 'E' THEN ' ' ELSE '(未)' END)))) AS TEXT), "utl_raw".cast_to_raw(N' ') ORDER BY "a"."申請人")) AS "假別" FROM "fil0040" AS "m" INNER JOIN "viewfilh001" AS "a" ON "a"."單別" = "m"."單據類別" AND "a"."單號" = "m"."單據編號" WHERE "m"."單據類別" = 'H01' GROUP BY "a"."申請人", "m"."異動日期");

-- Home #2303 ViewFILH023.費用申請主檔.H11
CREATE OR REPLACE VIEW "viewfilh023" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", CONCAT("a"."單據編號", '(', "a"."單據類別", ')') AS "主旨", "a"."公司代碼", COALESCE("e"."全名", ' ') AS "公司名稱", "a"."單據日期" AS "申請日期", "a"."匯率日期" AS "帳款年月", "a"."部門編號", COALESCE("b"."guname", ' ') AS "部門名稱", "a"."簽核系統", "a"."稅別" AS "費用類別", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態", CASE WHEN COALESCE("z3"."簽核狀態", ' ') = ' ' THEN ' .未送簽' WHEN COALESCE("z3"."簽核狀態", ' ') = 'I' THEN '1.簽核中' WHEN COALESCE("z3"."簽核狀態", ' ') = 'D' THEN '2.退回' WHEN COALESCE("z3"."簽核狀態", ' ') = 'A' THEN '3.作廢' WHEN COALESCE("z3"."簽核狀態", ' ') = 'E' THEN '9.已簽' ELSE ' .草稿' END AS "簽核排序", "a"."備註", "a"."流水編號", "a"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", COALESCE("z4"."guname", ' ') AS "填表人職稱", "a"."填表日", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", COALESCE("z1"."serial_num", ' ') AS "員工流水編號", "a"."最後更新日" FROM "fil0030" AS "a" LEFT JOIN "a30" AS "b" ON "a"."部門編號" = "b"."groupid" LEFT JOIN "viewfil0011" AS "e" ON "a"."公司代碼" = "e"."代碼" LEFT JOIN "viewfil0030" AS "f" ON "a"."簽核系統" = "f"."簽核系統" AND "a"."單據編號" = "f"."單號" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewofobjproperties" AS "z3" ON "a"."流水編號" = "z3"."單據流水號" LEFT JOIN "a40" AS "z4" ON "z1"."flowposi" = "z4"."serial_num" WHERE "a"."單據類別" = 'H11');

-- Home #2304 ViewFILH024.費用申請明細
CREATE OR REPLACE VIEW "viewfilh024" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."產品編號" AS "申請人", COALESCE("e"."員工姓名", ' ') AS "申請人姓名", COALESCE("e"."部門編號", ' ') AS "部門編號", COALESCE("f"."guname", ' ') AS "部門名稱", "a"."異動數量" AS "金額", "a"."備註說明" AS "備註", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日", COALESCE("z3"."簽核狀態", ' ') AS "簽核狀態" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" LEFT JOIN "viewfil3103" AS "d" ON "a"."單位代碼" = "d"."代碼" LEFT JOIN "fil0010" AS "e" ON "a"."產品編號" = "e"."員工編號" LEFT JOIN "a30" AS "f" ON "e"."部門編號" = "f"."groupid" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" LEFT JOIN "viewofobjproperties" AS "z3" ON "b"."流水編號" = "z3"."單據流水號" WHERE "a"."單據類別" = 'H11');

