CREATE OR REPLACE VIEW "viewfilh030" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", CONCAT("a"."單據編號", '(', "a"."單據類別", '):', ORA_SUBSTR("a"."匯率日期", 6)) AS "主旨", "a"."公司代碼", COALESCE("e"."全名", ' ') AS "公司名稱", "a"."單據日期" AS "申請日期", "a"."匯率日期" AS "帳款年月", "a"."簽核系統", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態", CASE WHEN COALESCE("z3"."簽核狀態", ' ') = ' ' THEN ' .未送簽' WHEN COALESCE("z3"."簽核狀態", ' ') = 'I' THEN '1.簽核中' WHEN COALESCE("z3"."簽核狀態", ' ') = 'D' THEN '2.退回' WHEN COALESCE("z3"."簽核狀態", ' ') = 'A' THEN '3.作廢' WHEN COALESCE("z3"."簽核狀態", ' ') = 'E' THEN '9.已簽' ELSE ' .草稿' END AS "簽核排序", "a"."稅別" AS "費用類別", "a"."備註", "a"."流水編號", "a"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "a"."填表日", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", COALESCE("z1"."serial_num", ' ') AS "員工流水編號", "a"."最後更新日" FROM "fil0030" AS "a" LEFT JOIN "viewfil0011" AS "e" ON "a"."公司代碼" = "e"."代碼" LEFT JOIN "viewfil0030" AS "f" ON "a"."簽核系統" = "f"."簽核系統" AND "a"."單據編號" = "f"."單號" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewofobjproperties" AS "z3" ON "a"."流水編號" = "z3"."單據流水號" LEFT JOIN "a40" AS "z4" ON "z1"."flowposi" = "z4"."serial_num" WHERE "a"."單據類別" = 'H21');

