-- Home #2310 ViewFILH032.加班2及計件.H23
CREATE OR REPLACE VIEW "viewfilh032" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", CONCAT("a"."單據編號", '(', "a"."單據類別", '):', ORA_SUBSTR("a"."匯率日期", 6)) AS "主旨", "a"."公司代碼", COALESCE("e"."全名", ' ') AS "公司名稱", "a"."單據日期" AS "申請日期", "a"."匯率日期" AS "帳款年月", "a"."簽核系統", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態", CASE WHEN COALESCE("z3"."簽核狀態", ' ') = ' ' THEN ' .未送簽' WHEN COALESCE("z3"."簽核狀態", ' ') = 'I' THEN '1.簽核中' WHEN COALESCE("z3"."簽核狀態", ' ') = 'D' THEN '2.退回' WHEN COALESCE("z3"."簽核狀態", ' ') = 'A' THEN '3.作廢' WHEN COALESCE("z3"."簽核狀態", ' ') = 'E' THEN '9.已簽' ELSE ' .草稿' END AS "簽核排序", "a"."稅別" AS "費用類別", "a"."備註", "a"."流水編號", "a"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "a"."填表日", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", COALESCE("z1"."serial_num", ' ') AS "員工流水編號", "a"."最後更新日" FROM "fil0030" AS "a" LEFT JOIN "viewfil0011" AS "e" ON "a"."公司代碼" = "e"."代碼" LEFT JOIN "viewfil0030" AS "f" ON "a"."簽核系統" = "f"."簽核系統" AND "a"."單據編號" = "f"."單號" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewofobjproperties" AS "z3" ON "a"."流水編號" = "z3"."單據流水號" LEFT JOIN "a40" AS "z4" ON "z1"."flowposi" = "z4"."serial_num" WHERE "a"."單據類別" = 'H23');

-- Home #2226 ViewFILM007.不分月庫存數_WK
CREATE OR REPLACE VIEW "viewfilm007_wk" AS (SELECT "a"."材料編號", "a"."庫別代碼", COALESCE("b"."名稱", ' ') AS "庫別名稱", COALESCE("b"."倉別代碼", ' ') AS "倉別代碼", COALESCE("c"."名稱", ' ') AS "倉別名稱", "a"."庫存數" FROM (SELECT "a"."材料編號", "a"."倉庫代碼" AS "庫別代碼", SUM("a"."異動數") AS "庫存數" FROM "wkfil2022" AS "a" GROUP BY "a"."材料編號", "a"."倉庫代碼") AS "a" LEFT JOIN "viewfil3106" AS "b" ON "a"."庫別代碼" = "b"."代碼" LEFT JOIN "viewfil310r" AS "c" ON "b"."倉別代碼" = "c"."代碼");

-- Home #2262 ViewFILM201.日報人員耗時
CREATE OR REPLACE VIEW "viewfilm201" AS WITH "temp1" AS (/* 前製程 */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期" AS "作業日期", "b"."logical4" AS "結束", "b"."logical5" AS "待補", "b"."logical6" AS "改件調機", (COALESCE("w"."實際直接人工時薪", 0) + COALESCE("x"."實際直接人工時薪", 0) + COALESCE("y"."實際直接人工時薪", 0) + COALESCE("z"."實際直接人工時薪", 0)) AS "員工實際時薪", (CASE WHEN "a"."業務員" = ' ' THEN 0 ELSE 1 END + CASE WHEN "b"."文數字10" = ' ' THEN 0 ELSE 1 END + CASE WHEN "b"."文數字11" = ' ' THEN 0 ELSE 1 END + CASE WHEN "b"."製程代碼" = 'C31E' THEN 0 ELSE CASE WHEN "b"."文數字12" = ' ' THEN 0 ELSE 1 END END) AS "加工人數", CASE WHEN "b"."時間五" = '000000' THEN 0 ELSE (TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間五" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間五"), 'yyyymmddhh24miss') - TO_DATE(CONCAT(TRIM("a"."單據日期"), "b"."時間一"), 'yyyymmddhh24miss')) * 24 END AS "總耗時", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態", "b"."製程代碼", ORA_SUBSTR("a"."單據日期", 1, 6) AS "年月" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "viewofobjproperties" AS "z3" ON "a"."流水編號" = "z3"."單據流水號" LEFT JOIN "viewfilhs02" AS "w" ON ORA_SUBSTR("w"."年月", 1, 6) = ORA_SUBSTR("a"."單據日期", 1, 6) AND "w"."員工編號" = "a"."業務員" LEFT JOIN "viewfilhs02" AS "x" ON ORA_SUBSTR("x"."年月", 1, 6) = ORA_SUBSTR("a"."單據日期", 1, 6) AND "x"."員工編號" = "b"."文數字10" LEFT JOIN "viewfilhs02" AS "y" ON ORA_SUBSTR("y"."年月", 1, 6) = ORA_SUBSTR("a"."單據日期", 1, 6) AND "y"."員工編號" = "b"."文數字11" LEFT JOIN "viewfilhs02" AS "z" ON ORA_SUBSTR("z"."年月", 1, 6) = ORA_SUBSTR("a"."單據日期", 1, 6) AND "z"."員工編號" = CASE WHEN "b"."製程代碼" = 'C31E' THEN ' ' ELSE "b"."文數字12" END WHERE "a"."單據類別" = 'C41' AND "a"."單據日期" > '2025' AND ("b"."製程代碼" BETWEEN 'C31A' AND 'C31G' OR "b"."製程代碼" = 'C32D' OR "b"."製程代碼" = 'C31I') UNION ALL /* 檢品 */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期" AS "作業日期", "b"."logical4" AS "結束", "b"."logical5" AS "待補", "b"."logical6" AS "改件調機", (COALESCE("w"."實際直接人工時薪", 0) + COALESCE("x"."實際直接人工時薪", 0) + COALESCE("y"."實際直接人工時薪", 0) + COALESCE("z"."實際直接人工時薪", 0)) AS "員工實際時薪", (CASE WHEN "a"."業務員" = ' ' THEN 0 ELSE 1 END + CASE WHEN "b"."文數字10" = ' ' THEN 0 ELSE 1 END + CASE WHEN "b"."文數字11" = ' ' THEN 0 ELSE 1 END + CASE WHEN "b"."文數字12" = ' ' THEN 0 ELSE 1 END) AS "加工人數", CASE WHEN "b"."時間五" = '000000' THEN 0 ELSE (TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間五" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間五"), 'yyyymmddhh24miss') - TO_DATE(CONCAT(TRIM("a"."單據日期"), "b"."時間一"), 'yyyymmddhh24miss')) * 24 END AS "總耗時", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態", "b"."製程代碼", ORA_SUBSTR("a"."單據日期", 1, 6) AS "年月" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "viewofobjproperties" AS "z3" ON "a"."流水編號" = "z3"."單據流水號" LEFT JOIN "viewfilhs02" AS "w" ON ORA_SUBSTR("w"."年月", 1, 6) = ORA_SUBSTR("a"."單據日期", 1, 6) AND "w"."員工編號" = "a"."業務員" LEFT JOIN "viewfilhs02" AS "x" ON ORA_SUBSTR("x"."年月", 1, 6) = ORA_SUBSTR("a"."單據日期", 1, 6) AND "x"."員工編號" = "b"."文數字10" LEFT JOIN "viewfilhs02" AS "y" ON ORA_SUBSTR("y"."年月", 1, 6) = ORA_SUBSTR("a"."單據日期", 1, 6) AND "y"."員工編號" = "b"."文數字11" LEFT JOIN "viewfilhs02" AS "z" ON ORA_SUBSTR("z"."年月", 1, 6) = ORA_SUBSTR("a"."單據日期", 1, 6) AND "z"."員工編號" = "b"."文數字12" WHERE "a"."單據類別" = 'C41' AND "a"."單據日期" > '2025' AND ("b"."製程代碼" = 'C31H' OR "b"."製程代碼" = 'C31K')) SELECT * FROM "temp1";

-- Home #2264 ViewFILM203.日報人員製令
CREATE OR REPLACE VIEW "viewfilm203" AS WITH "temp1" AS (/* 前製程 */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期" AS "作業日期", "a"."歸屬編號" AS "製令單號", "c"."訂單單號", "c"."產品編號", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態", "b"."製程代碼", ORA_SUBSTR("a"."單據日期", 1, 6) AS "年月" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "viewfil4030" AS "c" ON "a"."歸屬類別" = "c"."製令單別" AND "a"."歸屬編號" = "c"."製令單號" LEFT JOIN "viewofobjproperties" AS "z3" ON "a"."流水編號" = "z3"."單據流水號" LEFT JOIN "viewfilhs02" AS "w" ON ORA_SUBSTR("w"."年月", 1, 6) = ORA_SUBSTR("a"."單據日期", 1, 6) AND "w"."員工編號" = "a"."業務員" LEFT JOIN "viewfilhs02" AS "x" ON ORA_SUBSTR("x"."年月", 1, 6) = ORA_SUBSTR("a"."單據日期", 1, 6) AND "x"."員工編號" = "b"."文數字10" LEFT JOIN "viewfilhs02" AS "y" ON ORA_SUBSTR("y"."年月", 1, 6) = ORA_SUBSTR("a"."單據日期", 1, 6) AND "y"."員工編號" = "b"."文數字11" LEFT JOIN "viewfilhs02" AS "z" ON ORA_SUBSTR("z"."年月", 1, 6) = ORA_SUBSTR("a"."單據日期", 1, 6) AND "z"."員工編號" = CASE WHEN "b"."製程代碼" = 'C31E' THEN ' ' ELSE "b"."文數字12" END WHERE "a"."單據類別" = 'C41' AND "a"."單據日期" > '2025' AND ("b"."製程代碼" BETWEEN 'C31A' AND 'C31G' OR "b"."製程代碼" = 'C32D' OR "b"."製程代碼" = 'C31I') UNION ALL /* 檢品 */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期" AS "作業日期", CAST("m"."前置單號" AS TEXT) AS "製令單號", "c"."訂單單號", "c"."產品編號", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態", "b"."製程代碼", ORA_SUBSTR("a"."單據日期", 1, 6) AS "年月" FROM "fil0040" AS "m" INNER JOIN "fil0030" AS "a" ON "a"."單據類別" = "m"."單據類別" AND "a"."單據編號" = "m"."單據編號" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "viewfil4030" AS "c" ON "m"."前置單別" = "c"."製令單別" AND "m"."前置單號" = "c"."製令單號" LEFT JOIN "viewofobjproperties" AS "z3" ON "a"."流水編號" = "z3"."單據流水號" LEFT JOIN "viewfilhs02" AS "w" ON ORA_SUBSTR("w"."年月", 1, 6) = ORA_SUBSTR("a"."單據日期", 1, 6) AND "w"."員工編號" = "a"."業務員" LEFT JOIN "viewfilhs02" AS "x" ON ORA_SUBSTR("x"."年月", 1, 6) = ORA_SUBSTR("a"."單據日期", 1, 6) AND "x"."員工編號" = "b"."文數字10" LEFT JOIN "viewfilhs02" AS "y" ON ORA_SUBSTR("y"."年月", 1, 6) = ORA_SUBSTR("a"."單據日期", 1, 6) AND "y"."員工編號" = "b"."文數字11" LEFT JOIN "viewfilhs02" AS "z" ON ORA_SUBSTR("z"."年月", 1, 6) = ORA_SUBSTR("a"."單據日期", 1, 6) AND "z"."員工編號" = "b"."文數字12" WHERE "a"."單據類別" = 'C41' AND "a"."單據日期" > '2025' AND ("b"."製程代碼" = 'C31H' OR "b"."製程代碼" = 'C31K')) SELECT * FROM "temp1";

-- Home #2316 ViewFILR001.客訴單主檔.R01
CREATE OR REPLACE VIEW "viewfilr001" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期", "a"."歸屬類別" AS "品質異常單別", "a"."歸屬編號" AS "品質異常單號", "a"."業務員" AS "品管課填表人", COALESCE("c"."員工姓名", ' ') AS "品管課填表人姓名", "a"."公司代碼", COALESCE("k"."全名", ' ') AS "公司名稱", "a"."簽核系統", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態", "a"."簽核系統_結案", "a"."廠客編號" AS "客戶編號", COALESCE("e"."簡稱", ' ') AS "客戶簡稱", COALESCE("e"."全名", ' ') AS "客戶名稱", "b"."摘要", "b"."異常別權責單位", "a"."流水編號", COALESCE("z1"."serial_num", ' ') AS "員工流水編號", COALESCE("z1"."部門編號", ' ') AS "填表人部門編號", "a"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "a"."填表日", COALESCE("z4"."標籤數", 0) AS "標籤數", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0030" AS "a" INNER JOIN "fil003k1" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0010" AS "c" ON "a"."業務員" = "c"."員工編號" LEFT JOIN "fil0011" AS "e" ON "a"."廠客編號" = "e"."編號" LEFT JOIN "viewfil0011" AS "k" ON "a"."公司代碼" = "k"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewofobjproperties" AS "z3" ON "a"."流水編號" = "z3"."單據流水號" LEFT JOIN (SELECT "單別", "單號", COUNT("序號") AS "標籤數" FROM "fil0041" WHERE "單別" = 'R01' AND "標籤列印次數" > 0 GROUP BY "單別", "單號") AS "z4" ON "z4"."單別" = "a"."單據類別" AND "z4"."單號" = "a"."單據編號" WHERE "a"."單據類別" = 'R01');

-- Home #2319 ViewFILR010.品質異常單主檔.R02
CREATE OR REPLACE VIEW "viewfilr010" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期", "a"."廠客編號" AS "客戶編號", COALESCE("g"."全名", ' ') AS "客戶名稱", "a"."歸屬類別" AS "客訴單別", "a"."歸屬編號" AS "客訴單號", "a"."公司代碼", COALESCE("z3"."全名", ' ') AS "公司名稱", "a"."簽核系統", COALESCE("z4"."簽核狀態", '0') AS "簽核狀態", "a"."簽核系統_結案", "b"."異常大類", COALESCE("c"."名稱", ' ') AS "異常大類名稱", "b"."異常原因分類", COALESCE("d"."名稱", ' ') AS "異常原因分類名稱", "b"."異常單位", COALESCE("e"."部門名稱", ' ') AS "異常單位名稱", "b"."異常現象_作業者", "b"."異常現象_作業者姓名", "b"."異常現象_摘要", "b"."異常現象_詳述", "b"."異常原因分析", "b"."矯正措施_摘要1", "b"."矯正措施_摘要2", "b"."再發防止措施", "b"."追蹤確認", "b"."異常現象_填表人", COALESCE("f"."員工姓名", ' ') AS "異常現象_填表人姓名", "a"."業務員" AS "業務擔當", COALESCE("z6"."員工姓名", ' ') AS "業務擔當姓名", "a"."流水編號", COALESCE("z1"."serial_num", ' ') AS "員工流水編號", COALESCE("z5"."serial_num", ' ') AS "矯正人流水編號", COALESCE("z5"."員工姓名", ' ') AS "矯正人姓名", "a"."填表人", COALESCE("z1"."部門編號", ' ') AS "填表人部門編號", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", CONCAT("b"."異常單位", ORA_SUBSTR("a"."單據日期", 1, 6)) AS "單位年月", "a"."填表日", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0030" AS "a" INNER JOIN "fil003l1" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "viewfil3114" AS "c" ON "b"."異常大類" = "c"."代碼" LEFT JOIN "viewfil3115" AS "d" ON "b"."異常原因分類" = "d"."代碼" LEFT JOIN "fil0020" AS "e" ON "b"."異常單位" = "e"."部門編號" LEFT JOIN "fil0010" AS "f" ON "b"."異常現象_填表人" = "f"."員工編號" LEFT JOIN "fil0011" AS "g" ON "a"."廠客編號" = "g"."編號" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewfil0011" AS "z3" ON "a"."公司代碼" = "z3"."代碼" LEFT JOIN "viewofobjproperties" AS "z4" ON "a"."流水編號" = "z4"."單據流水號" LEFT JOIN "fil0010" AS "z5" ON "b"."矯正措施_填表人" = "z5"."員工編號" LEFT JOIN "fil0010" AS "z6" ON "a"."業務員" = "z6"."員工編號" WHERE "a"."單據類別" = 'R02');

-- Home #2317 ViewFILR011.客訴單主檔.R11
CREATE OR REPLACE VIEW "viewfilr011" AS (SELECT "m"."單據類別" AS "單別", "m"."單據編號" AS "單號", "a"."單據日期", "a"."歸屬類別" AS "品質異常單別", "a"."歸屬編號" AS "品質異常單號", "a"."業務員" AS "品管課填表人", COALESCE("c"."員工姓名", ' ') AS "品管課填表人姓名", "a"."公司代碼", COALESCE("k"."全名", ' ') AS "公司名稱", "a"."簽核系統", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態", "a"."簽核系統_結案", "a"."廠客編號" AS "客戶編號", COALESCE("e"."簡稱", ' ') AS "客戶簡稱", COALESCE("e"."全名", ' ') AS "客戶名稱", "b"."摘要", "b"."異常別權責單位", "m"."流水編號", COALESCE("z1"."serial_num", ' ') AS "員工流水編號", COALESCE("z1"."部門編號", ' ') AS "填表人部門編號", "m"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "m"."填表日", "m"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "m"."最後更新日" FROM "fil0030" AS "m" INNER JOIN "fil0030" AS "a" ON "a"."流水編號" = CONCAT('R01', ORA_SUBSTR("m"."流水編號", 4, 60)) INNER JOIN "fil003k1" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "viewofobjproperties" AS "z5" ON "z5"."單據流水號" = CONCAT('R01', ORA_SUBSTR("m"."流水編號", 4, 60)) AND "z5"."簽核狀態" = 'E' LEFT JOIN "fil0010" AS "c" ON "a"."業務員" = "c"."員工編號" LEFT JOIN "fil0011" AS "e" ON "a"."廠客編號" = "e"."編號" LEFT JOIN "viewfil0011" AS "k" ON "a"."公司代碼" = "k"."代碼" LEFT JOIN "fil0010" AS "z1" ON "m"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "m"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewofobjproperties" AS "z3" ON "m"."流水編號" = "z3"."單據流水號" WHERE "m"."單據類別" = 'R11');

-- Home #2328 ViewFILR031.銷退處理記錄表.R31
CREATE OR REPLACE VIEW "viewfilr031" AS (SELECT "m"."單據類別" AS "單別", "m"."單據編號" AS "單號", "a"."單據日期", "a"."廠客編號" AS "客戶編號", COALESCE("g"."全名", ' ') AS "客戶名稱", "a"."公司代碼", COALESCE("z3"."全名", ' ') AS "公司名稱", "a"."簽核系統", COALESCE("z6"."簽核狀態", '0') AS "簽核狀態", "a"."簽核系統_結案", "b"."退貨日期", "b"."退貨方式", "b"."退貨件數", "b"."退貨方式說明", "b"."退貨原因", "b"."處理數量_入庫", "b"."處理數量_銷毀", "b"."處理數量_其他", "b"."後續處理", COALESCE("z4"."員工姓名", ' ') AS "品管課負責人姓名", "m"."流水編號", COALESCE("z1"."serial_num", ' ') AS "員工流水編號", COALESCE("z1"."部門編號", ' ') AS "填表人部門編號", "m"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "m"."收付方式" AS "擔當業務", COALESCE("z7"."serial_num", ' ') AS "擔當業務流水編號", COALESCE("z7"."員工姓名", ' ') AS "擔當業務姓名", "m"."填表日", "m"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "m"."最後更新日" FROM "fil0030" AS "m" INNER JOIN "fil0030" AS "a" ON "a"."流水編號" = CONCAT('R03', ORA_SUBSTR("m"."流水編號", 4, 60)) INNER JOIN "fil003m1" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "viewofobjproperties" AS "z5" ON "z5"."單據流水號" = CONCAT('R03', ORA_SUBSTR("m"."流水編號", 4, 60)) AND "z5"."簽核狀態" = 'E' LEFT JOIN "fil0011" AS "g" ON "a"."廠客編號" = "g"."編號" LEFT JOIN "fil0010" AS "z1" ON "m"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "m"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewfil0011" AS "z3" ON "a"."公司代碼" = "z3"."代碼" LEFT JOIN "fil0010" AS "z4" ON "b"."品管課負責人" = "z4"."員工編號" LEFT JOIN "viewofobjproperties" AS "z6" ON "m"."流水編號" = "z6"."單據流水號" LEFT JOIN "fil0010" AS "z7" ON "a"."收付方式" = "z7"."員工編號" WHERE "m"."單據類別" = 'R31');

-- Home #2324 ViewFILR210.品質異常單主檔.R21
CREATE OR REPLACE VIEW "viewfilr210" AS (SELECT "m"."單據類別" AS "單別", "m"."單據編號" AS "單號", "a"."單據日期", "a"."廠客編號" AS "客戶編號", COALESCE("g"."全名", ' ') AS "客戶名稱", "a"."歸屬類別" AS "客訴單別", "a"."歸屬編號" AS "客訴單號", "a"."公司代碼", COALESCE("z3"."全名", ' ') AS "公司名稱", "a"."簽核系統", COALESCE("z4"."簽核狀態", '0') AS "簽核狀態", "a"."簽核系統_結案", "b"."異常大類", COALESCE("c"."名稱", ' ') AS "異常大類名稱", "b"."異常原因分類", COALESCE("d"."名稱", ' ') AS "異常原因分類名稱", "b"."異常單位", COALESCE("e"."部門名稱", ' ') AS "異常單位名稱", "b"."異常現象_作業者", "b"."異常現象_作業者姓名", "b"."異常現象_摘要", "b"."異常現象_詳述", "b"."異常現象_填表人", "b"."異常原因_摘要", "b"."異常原因分析", "b"."再發防止措施_摘要", "b"."再發防止措施", "b"."矯正措施_填表人", COALESCE("f"."員工姓名", ' ') AS "異常現象_填表人姓名", "m"."流水編號", "m"."填表人", COALESCE("z1"."serial_num", ' ') AS "員工流水編號", COALESCE("z1"."部門編號", ' ') AS "填表人部門編號", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "m"."填表日", "m"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "m"."最後更新日" FROM "fil0030" AS "m" INNER JOIN "fil0030" AS "a" ON "a"."流水編號" = CONCAT('R02', ORA_SUBSTR("m"."流水編號", 4, 60)) INNER JOIN "fil003l1" AS "b" ON "b"."單別" = 'R02' AND "a"."單據編號" = "b"."單號" INNER JOIN "viewofobjproperties" AS "z5" ON "a"."流水編號" = "z5"."單據流水號" AND "z5"."簽核狀態" = 'E' LEFT JOIN "viewfil3114" AS "c" ON "b"."異常大類" = "c"."代碼" LEFT JOIN "viewfil3115" AS "d" ON "b"."異常原因分類" = "d"."代碼" LEFT JOIN "fil0020" AS "e" ON "b"."異常單位" = "e"."部門編號" LEFT JOIN "fil0010" AS "f" ON "b"."異常現象_填表人" = "f"."員工編號" LEFT JOIN "fil0011" AS "g" ON "a"."廠客編號" = "g"."編號" LEFT JOIN "fil0010" AS "z1" ON "m"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "m"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewfil0011" AS "z3" ON "a"."公司代碼" = "z3"."代碼" LEFT JOIN "viewofobjproperties" AS "z4" ON "m"."流水編號" = "z4"."單據流水號" WHERE "m"."單據類別" = 'R21');

-- Home #2326 ViewFILR230.品質異常單主檔.R23
CREATE OR REPLACE VIEW "viewfilr230" AS (SELECT "m"."單據類別" AS "單別", "m"."單據編號" AS "單號", "a"."單據日期", "a"."廠客編號" AS "客戶編號", COALESCE("g"."全名", ' ') AS "客戶名稱", "a"."歸屬類別" AS "客訴單別", "a"."歸屬編號" AS "客訴單號", "a"."公司代碼", COALESCE("z3"."全名", ' ') AS "公司名稱", "a"."簽核系統", COALESCE("z4"."簽核狀態", '0') AS "簽核狀態", "a"."簽核系統_結案", "b"."異常大類", COALESCE("c"."名稱", ' ') AS "異常大類名稱", "b"."異常原因分類", COALESCE("d"."名稱", ' ') AS "異常原因分類名稱", "b"."異常單位", COALESCE("e"."部門名稱", ' ') AS "異常單位名稱", "b"."異常現象_作業者", "b"."異常現象_作業者姓名", "b"."異常現象_摘要", "b"."異常現象_詳述", "b"."異常現象_填表人", "b"."追蹤確認", COALESCE("f"."員工姓名", ' ') AS "異常現象_填表人姓名", "m"."流水編號", "m"."填表人", COALESCE("z1"."serial_num", ' ') AS "員工流水編號", COALESCE("z1"."部門編號", ' ') AS "填表人部門編號", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "m"."填表日", "m"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "m"."最後更新日" FROM "fil0030" AS "m" INNER JOIN "fil0030" AS "a" ON "a"."流水編號" = CONCAT('R02', ORA_SUBSTR("m"."流水編號", 4, 60)) INNER JOIN "fil003l1" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "viewofobjproperties" AS "z5" ON "z5"."單據流水號" = CONCAT('R22', ORA_SUBSTR("m"."流水編號", 4, 60)) AND "z5"."簽核狀態" = 'E' LEFT JOIN "viewfil3114" AS "c" ON "b"."異常大類" = "c"."代碼" LEFT JOIN "viewfil3115" AS "d" ON "b"."異常原因分類" = "d"."代碼" LEFT JOIN "fil0020" AS "e" ON "b"."異常單位" = "e"."部門編號" LEFT JOIN "fil0010" AS "f" ON "b"."異常現象_填表人" = "f"."員工編號" LEFT JOIN "fil0011" AS "g" ON "a"."廠客編號" = "g"."編號" LEFT JOIN "fil0010" AS "z1" ON "m"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "m"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewfil0011" AS "z3" ON "a"."公司代碼" = "z3"."代碼" LEFT JOIN "viewofobjproperties" AS "z4" ON "m"."流水編號" = "z4"."單據流水號" WHERE "m"."單據類別" = 'R23');

-- Home #2357 Create ViewOfEmp
CREATE OR REPLACE VIEW "viewofemp" ("serialno", "empid", "empname", "position", "salaryposi", "flowposi", "entryid", "entrypsw", "nickname", "language", "empemail", "compserial", "depserial", "assignee", "replaceby", "imheader", "imstatus", "hiredate", "termdate", "closed", "salarytype", "salary", "displayname", "supervisor") AS SELECT "a"."serial_num", "a"."員工編號", "a"."員工姓名", "a"."職稱代碼", "a"."salaryposi", "a"."flowposi", "a"."entryid", "a"."個人密碼", "a"."英文姓名", "a"."language", "a"."emailaddress", "a"."compserial", "a"."depserial", COALESCE("viewofvalidassignee"."asignee", ' '), "a"."replaceby", "a"."imheader", "a"."imstatus", "a"."就職日期", "a"."離職日期", "a"."停止使用", ' ', 0, CONCAT(RTRIM("a50"."guname"), '.', RTRIM("a30"."groupname"), '.', RTRIM("a40"."guname"), '.', RTRIM("a"."員工姓名")), 0 FROM "fil0010" AS "a" LEFT JOIN "viewofvalidassignee" ON "a"."serial_num" = "viewofvalidassignee"."serial_num" LEFT JOIN "a50" ON "a"."compserial" = "a50"."serial_num" LEFT JOIN "a30" ON "a"."depserial" = "a30"."serial_num" LEFT JOIN "a40" ON "a"."salaryposi" = "a40"."serial_num" LEFT JOIN "a01" ON "a"."serial_num" = "a01"."serial_num";

