CREATE OR REPLACE VIEW "viewofflow" AS SELECT DISTINCT "a"."serial_num" AS "流水編號", "a"."compid" AS "公司流水號", "a"."level_" AS "父階序號", "a"."serial_num_seq" AS "表身序號", "a"."指定人員" AS "指定人員流水號", "a"."posiid" AS "職稱流水號", "a"."signorcc" AS "正副本", "a"."flowdept" AS "簽核部門流水號", "a"."會簽判定", "a"."會簽方式", COALESCE("b"."guname", ' ') AS "職稱", COALESCE("c"."empname", ' ') AS "指定人員", "a"."cndfield" AS "條件欄位", "a"."cndexpression" AS "條件式", "a"."cndcontent" AS "條件內容" FROM "a20_1" AS "a" LEFT JOIN "a40" AS "b" ON "a"."serial_num" = "b"."serial_num" AND "b"."positype" = '2' LEFT JOIN "viewofemp" AS "c" ON "a"."指定人員" = "c"."serialno";

