-- Home #1750 ViewFIL1012.品號資料檔
CREATE OR REPLACE VIEW "viewfil1012" AS (SELECT "a"."產品編號", "a"."產品類別", CASE WHEN "a"."產品類別" = 'F' THEN '成品' WHEN "a"."產品類別" = 'M' THEN '原料' WHEN "a"."產品類別" = 'N' THEN '物料' WHEN "a"."產品類別" = 'O' THEN '其他' ELSE '空白' END AS "類別名稱", "a"."物料大類", COALESCE("d"."名稱", ' ') AS "大類名稱", COALESCE("d"."批號管理", 0) AS "批號管理", "a"."品名", "a"."規格", "a"."貨號", "a"."版次", "a"."單位代碼", COALESCE("h1"."名稱", ' ') AS "單位名稱", "a"."包裝數量", "a"."包裝單位", COALESCE("m"."員工姓名", ' ') AS "代理人姓名", "a"."新品號核准日期", "a"."修改品名規格", "a"."財務", "a"."主要庫別", COALESCE("i"."名稱", ' ') AS "庫別名稱", "a"."採購單位", COALESCE("h2"."名稱", ' ') AS "採購單位名稱", "a"."銷售單位", COALESCE("h3"."名稱", ' ') AS "銷售單位名稱", "a"."稅則", "a"."條碼編號", "a"."庫存管理", "a"."進價管制", "a"."單價上限率", "a"."售價管制", "a"."單價下限率" AS "重量", "a"."超交管理", "a"."超交率", "a"."品號屬性", CASE WHEN "a"."品號屬性" = 'M' THEN '自製件' WHEN "a"."品號屬性" = 'P' THEN '採購件' ELSE '空白' END AS "品號屬性名稱", "a"."低階碼", "a"."備註", "a"."標準途程品號", COALESCE("l"."全名", ' ') AS "次要供應商名稱", "a"."採購人", COALESCE("j"."員工姓名", ' ') AS "採購人姓名", "a"."主供應商", COALESCE("k"."全名", ' ') AS "主供應商名稱", "a"."補貨政策", CASE WHEN "a"."補貨政策" = 'L' THEN '依LRPM需求' WHEN "a"."補貨政策" = 'R' THEN '依補貨點' ELSE '空白' END AS "補貨政策名稱", "a"."固定前置天數", "a"."變動前置天數", "a"."批量", "a"."承認碼", "a"."最低補量", "a"."補貨倍量", "a"."領用倍量", "a"."轉撥倍量", "a"."檢驗方式", CASE WHEN "a"."檢驗方式" = '0' THEN '免檢' WHEN "a"."檢驗方式" = '2' THEN '抽檢(正常)' WHEN "a"."檢驗方式" = '4' THEN '全檢' ELSE '空白' END AS "檢驗方式名稱", "a"."領料代碼", CASE WHEN "a"."領料代碼" = '1' THEN '逐批領料' ELSE '空白' END AS "領料代碼名稱", "a"."超收率", "a"."標準進價", "a"."標準售價", "a"."零售價", "a"."售價定價一", "a"."營業稅率", "a"."重量單位", COALESCE("h4"."名稱", ' ') AS "重量單位名稱", "a"."熟成溫度1", "a"."熟成時間1", "a"."熟成溫度2", "a"."熟成時間2", "a"."英文品名", "a"."材質結構1", "a"."材質結構2", "a"."材質結構3", CONCAT(TRIM(COALESCE("e"."品名", ' ')), CASE WHEN "a"."材質結構2" = ' ' THEN ' ' ELSE CONCAT('/', TRIM(COALESCE("f"."品名", ' '))) END, CASE WHEN "a"."材質結構3" = ' ' THEN ' ' ELSE CONCAT('/', TRIM(COALESCE("g"."品名", ' '))) END) AS "材質結構", "a"."失效日期", "a"."客戶成品尺寸", "a"."客戶最終名稱", "a"."安全存量", "n"."密度", "n"."名稱" AS "進貨報價類別", "a"."盤點日期", "a"."盤存數量", "a"."流水編號", "a"."建立員工", COALESCE("b"."員工姓名", ' ') AS "建立姓名", "a"."建立日期", "a"."最後更新者", COALESCE("c"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0012" AS "a" LEFT JOIN "fil0010" AS "b" ON "a"."建立員工" = "b"."員工編號" LEFT JOIN "fil0010" AS "c" ON "a"."最後更新者" = "c"."員工編號" LEFT JOIN "viewfil310b" AS "d" ON "a"."物料大類" = "d"."代碼" LEFT JOIN "fil0012" AS "e" ON "a"."材質結構1" = "e"."產品編號" LEFT JOIN "fil0012" AS "f" ON "a"."材質結構2" = "f"."產品編號" LEFT JOIN "fil0012" AS "g" ON "a"."材質結構3" = "g"."產品編號" LEFT JOIN "viewfil3103" AS "h1" ON "a"."單位代碼" = "h1"."代碼" LEFT JOIN "viewfil3103" AS "h2" ON "a"."採購單位" = "h2"."代碼" LEFT JOIN "viewfil3103" AS "h3" ON "a"."銷售單位" = "h3"."代碼" LEFT JOIN "viewfil3103" AS "h4" ON "a"."重量單位" = "h4"."代碼" LEFT JOIN "viewfil3106" AS "i" ON "a"."主要庫別" = "i"."代碼" LEFT JOIN "fil0010" AS "j" ON "a"."採購人" = "j"."員工編號" LEFT JOIN "fil0011" AS "k" ON "a"."主供應商" = "k"."編號" LEFT JOIN "fil0011" AS "l" ON "a"."標準途程品號" = "l"."編號" LEFT JOIN "fil0010" AS "m" ON "a"."包裝單位" = "m"."員工編號" LEFT JOIN "viewfil3117" AS "n" ON "n"."代碼" = "a"."進貨報價類別");

