-- Home #1828 ViewFIL4021.客戶訂單明細
CREATE OR REPLACE VIEW "viewfil4021" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."產品編號", COALESCE("a1"."手動品名", ' ') AS "品名", COALESCE("a1"."手動規格", ' ') AS "規格", CONCAT(TRIM(CONCAT(COALESCE("h"."品名", ' '), COALESCE("h"."規格", ' '))), CASE WHEN "a1"."客戶報價材質結構2" = ' ' THEN ' ' ELSE CONCAT('/', TRIM(COALESCE(CONCAT("i"."品名", COALESCE("i"."規格", ' ')), ' '))) END, CASE WHEN "a1"."客戶報價材質結構3" = ' ' THEN ' ' ELSE CONCAT('/', TRIM(COALESCE(CONCAT("j"."品名", COALESCE("j"."規格", ' ')), ' '))) END) AS "材質", "a"."異動日期", "a"."廠客品號" AS "客戶品號", "a"."異動數量" AS "訂單數量", (COALESCE("k"."交貨數量", 0) - COALESCE("l"."退貨數量", 0)) AS "已交數量", "a"."贈品數量" AS "贈品量", (COALESCE("k"."交貨贈品數", 0) - COALESCE("l"."退貨贈品數", 0)) AS "贈品已交量", "a"."單位代碼", COALESCE("d"."名稱", ' ') AS "單位名稱", "a1"."小單位", COALESCE("e"."名稱", ' ') AS "小單位名稱", "a"."折扣率", "a1"."包裝數量", "a1"."包裝單位", COALESCE("f"."名稱", ' ') AS "包裝單位名稱", "a"."異動單價" AS "單價", "a"."異動金額" AS "金額", "a"."毛重", "a"."材積", "a"."製版費", "a"."預交日", "a"."倉庫代碼" AS "交貨庫別", COALESCE("g"."名稱", ' ') AS "庫別名稱", "a"."前置單別", "a"."前置單號", "a1"."文數字1" AS "報價單別", "a1"."文數字2" AS "報價單號", "a1"."數值1" AS "報價單序號", "a1"."專案代號", "a"."備註說明" AS "備註", "a"."結案碼", "a"."數值1" AS "參考尺寸", "a"."數值2" AS "米平方單價", "a"."流水編號", "a"."最後更新者", COALESCE("b"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "a1" ON "a"."單據類別" = "a1"."單別" AND "a"."單據編號" = "a1"."單號" AND "a"."單據序號" = "a1"."序號" LEFT JOIN "fil0010" AS "b" ON "a"."最後更新者" = "b"."員工編號" LEFT JOIN "viewfil1012" AS "c" ON "a"."產品編號" = "c"."產品編號" LEFT JOIN "viewfil3103" AS "d" ON "a"."單位代碼" = "d"."代碼" LEFT JOIN "viewfil3103" AS "e" ON "a1"."小單位" = "e"."代碼" LEFT JOIN "viewfil3103" AS "f" ON "a1"."包裝單位" = "f"."代碼" LEFT JOIN "viewfil3106" AS "g" ON "a"."倉庫代碼" = "g"."代碼" LEFT JOIN "fil0012" AS "h" ON "a1"."客戶報價材質結構1" = "h"."產品編號" LEFT JOIN "fil0012" AS "i" ON "a1"."客戶報價材質結構2" = "i"."產品編號" LEFT JOIN "fil0012" AS "j" ON "a1"."客戶報價材質結構3" = "j"."產品編號" LEFT JOIN (SELECT "a1"."文數字1" AS "訂單單別", "a1"."文數字2" AS "訂單單號", "a1"."數值1" AS "訂單序號", SUM("a"."異動數量") AS "交貨數量", SUM("a"."贈品數量") AS "交貨贈品數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "m" ON "m"."單據類別" = "a"."單據類別" AND "m"."單據編號" = "a"."單據編號" INNER JOIN "fil0041" AS "a1" ON "a"."單據類別" = "a1"."單別" AND "a"."單據編號" = "a1"."單號" AND "a"."單據序號" = "a1"."序號" LEFT JOIN "viewofobjproperties" AS "z3" ON "m"."流水編號" = "z3"."單據流水號" WHERE "a"."單據類別" = 'B42' AND COALESCE("z3"."簽核狀態", ' ') <> 'A' GROUP BY "a1"."文數字1", "a1"."文數字2", "a1"."數值1") AS "k" ON "k"."訂單單別" = "a"."單據類別" AND "k"."訂單單號" = "a"."單據編號" AND "k"."訂單序號" = "a"."單據序號" LEFT JOIN (SELECT "a1"."文數字1" AS "訂單單別", "a1"."文數字2" AS "訂單單號", "a1"."數值1" AS "訂單序號", SUM("a"."異動數量" * -1) AS "退貨數量", SUM("a"."贈品數量" * -1) AS "退貨贈品數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "m" ON "m"."單據類別" = "a"."單據類別" AND "m"."單據編號" = "a"."單據編號" INNER JOIN "fil0041" AS "a1" ON "a"."單據類別" = "a1"."單別" AND "a"."單據編號" = "a1"."單號" AND "a"."單據序號" = "a1"."序號" LEFT JOIN "viewofobjproperties" AS "z3" ON "m"."流水編號" = "z3"."單據流水號" WHERE "a"."單據類別" = 'B51' AND COALESCE("z3"."簽核狀態", ' ') <> 'A' GROUP BY "a1"."文數字1", "a1"."文數字2", "a1"."數值1") AS "l" ON "l"."訂單單別" = "a"."單據類別" AND "l"."訂單單號" = "a"."單據編號" AND "l"."訂單序號" = "a"."單據序號" WHERE "a"."單據類別" = 'B31');

-- Home #1834 ViewFIL402E.訂單明細選擇表
CREATE OR REPLACE VIEW "viewfil402e" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."備註說明" AS "備註", "a"."產品編號", "d"."品名", "d"."規格", "c"."手動品名", "c"."手動規格", "a"."異動金額" AS "總價", "a"."製版費", "m"."流水編號", "m"."單據日期", "m"."廠客編號", "e"."全名" AS "廠客全名", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態", "a"."異動數量" AS "訂單數量", (COALESCE("k"."交貨數量", 0) - COALESCE("l"."退貨數量", 0)) AS "已交數量", "a"."贈品數量" AS "贈品量", (COALESCE("k"."交貨贈品數", 0) - COALESCE("l"."退貨贈品數", 0)) AS "贈品已交量", GREATEST(("a"."異動數量" + "a"."贈品數量") - (COALESCE("k"."交貨數量", 0) - COALESCE("l"."退貨數量", 0)) - (COALESCE("k"."交貨贈品數", 0) - COALESCE("l"."退貨贈品數", 0)), 0) AS "待交數量" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "m" ON "m"."單據類別" = "a"."單據類別" AND "m"."單據編號" = "a"."單據編號" INNER JOIN "fil0041" AS "c" ON "c"."單別" = "a"."單據類別" AND "c"."單號" = "a"."單據編號" AND "c"."序號" = "a"."單據序號" INNER JOIN "viewofobjproperties" AS "z3" ON "m"."流水編號" = "z3"."單據流水號" AND "z3"."簽核狀態" = 'E' INNER JOIN "viewfil1012" AS "d" ON "a"."產品編號" = "d"."產品編號" LEFT JOIN "fil0011" AS "e" ON "m"."廠客編號" = "e"."編號" LEFT JOIN (SELECT "a1"."文數字1" AS "訂單單別", "a1"."文數字2" AS "訂單單號", "a1"."數值1" AS "訂單序號", SUM("a"."異動數量") AS "交貨數量", SUM("a"."贈品數量") AS "交貨贈品數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "m" ON "m"."單據類別" = "a"."單據類別" AND "m"."單據編號" = "a"."單據編號" INNER JOIN "fil0041" AS "a1" ON "a"."單據類別" = "a1"."單別" AND "a"."單據編號" = "a1"."單號" AND "a"."單據序號" = "a1"."序號" LEFT JOIN "viewofobjproperties" AS "z3" ON "m"."流水編號" = "z3"."單據流水號" WHERE "a"."單據類別" = 'B42' AND COALESCE("z3"."簽核狀態", ' ') <> 'A' GROUP BY "a1"."文數字1", "a1"."文數字2", "a1"."數值1") AS "k" ON "k"."訂單單別" = "a"."單據類別" AND "k"."訂單單號" = "a"."單據編號" AND "k"."訂單序號" = "a"."單據序號" LEFT JOIN (SELECT "a1"."文數字1" AS "訂單單別", "a1"."文數字2" AS "訂單單號", "a1"."數值1" AS "訂單序號", SUM("a"."異動數量" * -1) AS "退貨數量", SUM("a"."贈品數量" * -1) AS "退貨贈品數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "m" ON "m"."單據類別" = "a"."單據類別" AND "m"."單據編號" = "a"."單據編號" INNER JOIN "fil0041" AS "a1" ON "a"."單據類別" = "a1"."單別" AND "a"."單據編號" = "a1"."單號" AND "a"."單據序號" = "a1"."序號" LEFT JOIN "viewofobjproperties" AS "z3" ON "m"."流水編號" = "z3"."單據流水號" WHERE "a"."單據類別" = 'B51' AND COALESCE("z3"."簽核狀態", ' ') <> 'A' GROUP BY "a1"."文數字1", "a1"."文數字2", "a1"."數值1") AS "l" ON "l"."訂單單別" = "a"."單據類別" AND "l"."訂單單號" = "a"."單據編號" AND "l"."訂單序號" = "a"."單據序號" WHERE "a"."單據類別" = 'B31');

-- Home #1836 ViewFIL402G.送貨單明細
CREATE OR REPLACE VIEW "viewfil402g" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."產品編號", COALESCE("c"."品名", ' ') AS "品名", COALESCE("c"."規格", ' ') AS "規格", CONCAT(TRIM(CONCAT(COALESCE("h"."品名", ' '), COALESCE("h"."規格", ' '))), CASE WHEN "a1"."客戶報價材質結構2" = ' ' THEN ' ' ELSE CONCAT('/', TRIM(COALESCE(CONCAT("i"."品名", COALESCE("i"."規格", ' ')), ' '))) END, CASE WHEN "a1"."客戶報價材質結構3" = ' ' THEN ' ' ELSE CONCAT('/', TRIM(COALESCE(CONCAT("j"."品名", COALESCE("j"."規格", ' ')), ' '))) END) AS "材質", "a"."異動日期", "a"."廠客品號" AS "客戶品號", "a"."異動數量" AS "訂單數量", CASE WHEN "c"."產品類別" = 'O' THEN "a"."異動數量" ELSE COALESCE("k"."出庫數量", 0) END AS "出庫數量", "a"."贈品數量" AS "贈品量", "a"."數值3" AS "寄庫數量", GREATEST(CASE WHEN "c"."產品類別" = 'O' THEN "a"."異動數量" ELSE COALESCE("k"."出庫數量", 0) END - ("a"."異動數量" + "a"."贈品數量"), 0) AS "寄庫出貨", "a"."單位代碼", COALESCE("d"."名稱", ' ') AS "單位名稱", "a1"."小單位", COALESCE("e"."名稱", ' ') AS "小單位名稱", "a"."折扣率", "a1"."包裝數量", "a1"."包裝單位", COALESCE("f"."名稱", ' ') AS "包裝單位名稱", "a"."異動單價" AS "單價", "a"."異動金額" AS "金額", "a"."毛重", "a"."材積", "a"."製版費", "a"."預交日", "a"."倉庫代碼" AS "交貨庫別", COALESCE("g"."名稱", ' ') AS "庫別名稱", "a"."前置單別", "a"."前置單號", "a1"."文數字1" AS "訂單單別", "a1"."文數字2" AS "訂單單號", "a1"."數值1" AS "訂單序號", "a1"."專案代號", "a"."備註說明" AS "備註", "a"."結案碼", "a"."流水編號", "a"."最後更新者", COALESCE("b"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "a1" ON "a"."單據類別" = "a1"."單別" AND "a"."單據編號" = "a1"."單號" AND "a"."單據序號" = "a1"."序號" LEFT JOIN "fil0010" AS "b" ON "a"."最後更新者" = "b"."員工編號" LEFT JOIN "viewfil1012" AS "c" ON "a"."產品編號" = "c"."產品編號" LEFT JOIN "viewfil3103" AS "d" ON "a"."單位代碼" = "d"."代碼" LEFT JOIN "viewfil3103" AS "e" ON "a1"."小單位" = "e"."代碼" LEFT JOIN "viewfil3103" AS "f" ON "a1"."包裝單位" = "f"."代碼" LEFT JOIN "viewfil3106" AS "g" ON "a"."倉庫代碼" = "g"."代碼" LEFT JOIN "fil0012" AS "h" ON "a1"."客戶報價材質結構1" = "h"."產品編號" LEFT JOIN "fil0012" AS "i" ON "a1"."客戶報價材質結構2" = "i"."產品編號" LEFT JOIN "fil0012" AS "j" ON "a1"."客戶報價材質結構3" = "j"."產品編號" LEFT JOIN (SELECT "a"."單據類別", "a"."單據號碼", "a"."單據序號", SUM("a"."異動數量") * -1 AS "出庫數量" FROM "fil0044" AS "a" WHERE "a"."單據類別" = 'B42' GROUP BY "a"."單據類別", "a"."單據號碼", "a"."單據序號") AS "k" ON "a"."單據類別" = "k"."單據類別" AND "a"."單據編號" = "k"."單據號碼" AND "a"."單據序號" = "k"."單據序號" WHERE "a"."單據類別" = 'B42');

-- Home #1837 ViewFIL402G1.送貨單發貨數
CREATE OR REPLACE VIEW "viewfil402g1" AS (SELECT "a"."單據類別", "a"."單據編號" AS "單據號碼", "a"."單據序號", SUM(CASE WHEN "c"."產品類別" = 'O' THEN "a"."異動數量" ELSE COALESCE("k"."出庫數量", 0) END) AS "出庫數量" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "a1" ON "a"."單據類別" = "a1"."單別" AND "a"."單據編號" = "a1"."單號" AND "a"."單據序號" = "a1"."序號" LEFT JOIN "viewfil1012" AS "c" ON "a"."產品編號" = "c"."產品編號" LEFT JOIN (SELECT "a"."單據類別", "a"."單據號碼", "a"."單據序號", SUM("a"."異動數量") * -1 AS "出庫數量" FROM "fil0044" AS "a" WHERE "a"."單據類別" = 'B42' GROUP BY "a"."單據類別", "a"."單據號碼", "a"."單據序號") AS "k" ON "a"."單據類別" = "k"."單據類別" AND "a"."單據編號" = "k"."單據號碼" AND "a"."單據序號" = "k"."單據序號" WHERE "a"."單據類別" = 'B42' GROUP BY "a"."單據類別", "a"."單據編號", "a"."單據序號");

