E("z3"."簽核狀態", '0') AS "簽核狀態", "d"."單位主管流水編號" FROM "tmp1" AS "a" LEFT JOIN "viewfil310p" AS "d" ON "a"."機台代碼" = "d"."代碼" LEFT JOIN "fil0010" AS "e" ON "a"."作業人員" = "e"."員工編號" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewofobjproperties" AS "z3" ON "a"."流水編號" = "z3"."單據流水號" LEFT JOIN "viewfil1012" AS "z4" ON "z4"."產品編號" = "a"."紙箱編號" LEFT JOIN "viewfil1012" AS "z5" ON "z5"."產品編號" = "a"."尾數紙箱編號";

