CREATE OR REPLACE VIEW "viewfil4a1a" AS (SELECT "a"."單別", "a"."單號", "a"."數量", "a"."總價", "b"."稅率", ROUND(CAST("a"."總價" * "b"."稅率" AS DOUBLE PRECISION) / 100) AS "稅額", ROUND("a"."總價" * (1 + CAST("b"."稅率" AS DOUBLE PRECISION) / 100)) AS "含稅價", "a"."原幣總價", "原物料編號", "原物料名稱" FROM (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "數量", SUM("a"."異動金額") AS "總價", SUM(COALESCE("b"."數值2", 0)) AS "原幣總價", STRING_AGG(CAST(TRIM("a"."產品編號") AS TEXT), ' ' ORDER BY "a"."產品編號") AS "原物料編號", STRING_AGG(CAST(TRIM("c"."品名") AS TEXT), ' ' ORDER BY "c"."品名") AS "原物料名稱" FROM "fil0040" AS "a" LEFT JOIN "fil0041" AS "b" ON "b"."單別" = "a"."單據類別" AND "b"."單號" = "a"."單據編號" AND "b"."序號" = "a"."單據序號" LEFT JOIN "viewfil1012" AS "c" ON "a"."產品編號" = "c"."產品編號" WHERE "a"."單據類別" = 'D11' GROUP BY "a"."單據類別", "a"."單據編號") AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單別" = "b"."單據類別" AND "a"."單號" = "b"."單據編號");

-- Home #2163 ViewFIL4A21.進料單明細
CREATE OR REPLACE VIEW "viewfil4a21" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."前置單別" AS "採購單別", "a"."前置單號" AS "採購單號", "a"."qrno" AS "採購序號", "a"."產品編號" AS "料號", CASE WHEN COALESCE("c"."手動品名", ' ') = ' ' THEN COALESCE("e"."品名", ' ') ELSE COALESCE("c"."手動品名", ' ') END AS "品名", CASE WHEN COALESCE("c"."手動規格", ' ') = ' ' THEN COALESCE("e"."規格", ' ') ELSE COALESCE("c"."手動規格", ' ') END AS "規格", "a"."異動日期" AS "入庫日期", "a"."倉庫代碼", COALESCE("g"."名稱", ' ') AS "倉庫名稱", "a"."異動數量" AS "數量", "a"."贈品數量", "a"."單位代碼", COALESCE("f"."名稱", ' ') AS "單位名稱", "a"."異動單價" AS "單價", "a"."異動金額" AS "總價", "a"."數值4" AS "庫存異動數", COALESCE("c"."批號", ' ') AS "批號", CONCAT(COALESCE("c"."批號", ' '), ' (', "a"."產品編號", ') ', TRIM(COALESCE("e"."品名", ' ')), '/', COALESCE("e"."規格", ' ')) AS "批號規格", "a"."文數字1" AS "廠商批號", "a"."備註說明" AS "備註", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" /* 主檔 */ INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ LEFT JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN "viewfil1012" AS "e" ON "a"."產品編號" = "e"."產品編號" LEFT JOIN "viewfil3103" AS "f" ON "a"."單位代碼" = "f"."代碼" LEFT JOIN "viewfil3106" AS "g" ON "a"."倉庫代碼" = "g"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" LEFT JOIN "viewofobjproperties" AS "z3" ON "b"."流水編號" = "z3"."單據流水號" WHERE "a"."單據類別" = 'D21' AND "a"."異動類別" = 'A');

-- Home #2168 ViewFIL4A31.進料檢驗單明細
CREATE OR REPLACE VIEW "viewfil4a31" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."產品編號" AS "料號", COALESCE("e"."品名", ' ') AS "品名", COALESCE("e"."規格", ' ') AS "規格", COALESCE("d"."入庫日期", ' ') AS "進料日期", "a"."異動日期" AS "檢驗日期", "a"."倉庫代碼", COALESCE("g"."名稱", ' ') AS "倉庫名稱", "a"."異動數量" AS "數量", "a"."單位代碼", COALESCE("f"."名稱", ' ') AS "單位名稱", "d"."序號" AS "進料序號", "c"."批號", "c"."檢附coa", "c"."檢驗外觀", "c"."檢驗清潔度", "c"."檢驗顏色", "c"."檢驗尺寸", "c"."檢驗厚度", "c"."檢驗滑度", "c"."檢驗人員", COALESCE("h"."員工姓名", ' ') AS "檢驗姓名", "c"."檢驗判定" AS "判定", "c"."檢驗特採" AS "特採", "a"."備註說明" AS "不合格原因", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" /* 進料 */ LEFT JOIN "viewfil4a21" AS "d" ON "c"."批號" = "d"."批號" LEFT JOIN "viewfil1012" AS "e" ON "a"."產品編號" = "e"."產品編號" LEFT JOIN "viewfil3103" AS "f" ON "a"."單位代碼" = "f"."代碼" LEFT JOIN "viewfil3106" AS "g" ON "a"."倉庫代碼" = "g"."代碼" LEFT JOIN "fil0010" AS "h" ON "c"."檢驗人員" = "h"."員工編號" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."單據類別" = 'D31');

-- Home #2171 ViewFIL4A41.退料單明細
CREATE OR REPLACE VIEW "viewfil4a41" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."產品編號" AS "料號", COALESCE("e"."品名", ' ') AS "品名", COALESCE("e"."規格", ' ') AS "規格", "a"."異動日期" AS "退料日期", "a"."倉庫代碼", COALESCE("g"."名稱", ' ') AS "倉庫名稱", "a"."異動數量" AS "數量", "a"."異動金額" AS "金額", "a"."異動單價" AS "單價", "a"."數值4" AS "庫存異動數", "a"."單位代碼", COALESCE("f"."名稱", ' ') AS "單位名稱", "d"."序號" AS "進料序號", "c"."批號", "a"."備註說明" AS "備註", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" /* 進料 */ LEFT JOIN "viewfil4a21" AS "d" ON "c"."批號" = "d"."批號" LEFT JOIN "viewfil1012" AS "e" ON "a"."產品編號" = "e"."產品編號" LEFT JOIN "viewfil3103" AS "f" ON "a"."單位代碼" = "f"."代碼" LEFT JOIN "viewfil3106" AS "g" ON "a"."倉庫代碼" = "g"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."單據類別" = 'D41' AND "a"."異動類別" = 'S');

-- Home #2174 ViewFIL4A4C.批號退料數
CREATE OR REPLACE VIEW "viewfil4a4c" AS (SELECT COALESCE("a"."批號", "b"."批號") AS "批號", COALESCE("a"."進料數量", 0) AS "進料數量", COALESCE("a"."退料數量", 0) AS "退料數量", COALESCE("a"."未退料數", 0) AS "未退料數", COALESCE("b"."檢驗數量", 0) AS "檢驗數量", COALESCE("a"."進料數量", 0) - COALESCE("b"."檢驗數量", 0) AS "未檢驗數" FROM (SELECT COALESCE("a"."批號", "b"."批號") AS "批號", COALESCE("a"."數量", 0) AS "進料數量", COALESCE("b"."退料數", 0) AS "退料數量", COALESCE("a"."數量", 0) - COALESCE("b"."退料數", 0) AS "未退料數" FROM (/* 進料 */ SELECT "a"."批號", "a"."數量" FROM "viewfil4a21" AS "a") AS "a" FULL OUTER JOIN (/* 退料 */ SELECT "a"."批號", SUM("a"."數量") AS "退料數" FROM "viewfil4a41" AS "a" GROUP BY "a"."批號") AS "b" ON "a"."批號" = "b"."批號") AS "a" FULL OUTER JOIN (/* 檢驗 */ SELECT "a"."批號", SUM("a"."數量") AS "檢驗數量" FROM "viewfil4a31" AS "a" GROUP BY "a"."批號") AS "b" ON "a"."批號" = "b"."批號");

-- Home #2178 ViewFIL4A4G.客供品明細
CREATE OR REPLACE VIEW "viewfil4a4g" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "b"."單據日期", "b"."廠客編號" AS "客戶編號", COALESCE("z2"."簡稱", ' ') AS "客戶簡稱", "a"."產品編號" AS "料號", COALESCE("e"."品名", ' ') AS "品名", COALESCE("e"."規格", ' ') AS "規格", "a"."異動日期" AS "來料日期", "a"."倉庫代碼", CONCAT("a"."單據類別", '-', "a"."單據編號", '-', TO_CHAR("a"."單據序號", '0009')) AS "批號", COALESCE("g"."名稱", ' ') AS "倉庫名稱", "a"."異動數量" AS "數量", "a"."數值4" AS "庫存異動數", "a"."單位代碼", "a"."相關代碼1" AS "庫存單位", COALESCE("f"."名稱", ' ') AS "單位名稱", "a"."文數字1" AS "廠商批號", "a"."備註說明" AS "備註", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "a"."單據編號" LEFT JOIN "viewfil1012" AS "e" ON "a"."產品編號" = "e"."產品編號" LEFT JOIN "viewfil3103" AS "f" ON "a"."單位代碼" = "f"."代碼" LEFT JOIN "viewfil3106" AS "g" ON "a"."倉庫代碼" = "g"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" LEFT JOIN "fil0011" AS "z2" ON "b"."廠客編號" = "z2"."編號" WHERE "a"."單據類別" = 'D51' AND "a"."異動類別" = ' ');

-- Home #2181 ViewFIL4A4J.客供品退料明細
CREATE OR REPLACE VIEW "viewfil4a4j" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."產品編號" AS "料號", COALESCE("e"."品名", ' ') AS "品名", COALESCE("e"."規格", ' ') AS "規格", "a"."異動日期" AS "來料日期", "a"."倉庫代碼", COALESCE("g"."名稱", ' ') AS "倉庫名稱", "a"."異動數量" AS "數量", "a"."單位代碼", COALESCE("f"."名稱", ' ') AS "單位名稱", "d"."序號" AS "進料序號", "c"."批號", "a"."文數字1" AS "廠商批號", "a"."數值4" AS "庫存異動數", "a"."相關代碼1" AS "庫存單位", "a"."備註說明" AS "備註", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" /* 特殊欄位 */ LEFT JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" /* 進料 */ LEFT JOIN "viewfil4a21" AS "d" ON "c"."批號" = "d"."批號" LEFT JOIN "viewfil1012" AS "e" ON "a"."產品編號" = "e"."產品編號" LEFT JOIN "viewfil3103" AS "f" ON "a"."單位代碼" = "f"."代碼" LEFT JOIN "viewfil3106" AS "g" ON "a"."倉庫代碼" = "g"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."單據類別" = 'D52' AND "a"."異動類別" = 'S');

-- Home #2191 ViewFILE011.原物料入庫明細
CREATE OR REPLACE VIEW "viewfile011" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."產品編號" AS "料號", COALESCE("e"."品名", ' ') AS "品名", COALESCE("e"."規格", ' ') AS "規格", "a"."異動日期" AS "盤點日期", "a"."預交日" AS "進貨日期", "a"."其它日期" AS "有效日期", "c"."文數字4" AS "廠別代碼", "c"."文數字5" AS "倉別代碼", "a"."倉庫代碼" AS "庫別代碼", COALESCE("g"."名稱", ' ') AS "庫別名稱", "a"."異動數量" AS "庫存數量", "a"."異動單價" AS "包裝數量", "a"."單位代碼" AS "庫存單位代碼", COALESCE("f1"."名稱", ' ') AS "庫存單位名稱", "a"."文數字1" AS "包裝單位代碼", COALESCE("f2"."名稱", ' ') AS "包裝單位名稱", "c"."批號", "a"."廠客品號" AS "廠商批號", "a"."qrno", "a"."備註說明" AS "備註", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN "viewfil1012" AS "e" ON "a"."產品編號" = "e"."產品編號" LEFT JOIN "viewfil3103" AS "f1" ON "a"."單位代碼" = "f1"."代碼" LEFT JOIN "viewfil3103" AS "f2" ON "a"."文數字1" = "f2"."代碼" LEFT JOIN "viewfil3106" AS "g" ON "a"."倉庫代碼" = "g"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."單據類別" = 'E11');

-- Home #2194 ViewFILE01C.原物料入庫沖銷.E11
CREATE OR REPLACE VIEW "viewfile01c" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."產品編號" AS "料號", COALESCE("e"."品名", ' ') AS "品名", COALESCE("e"."規格", ' ') AS "規格", "b"."單據日期", "d"."名稱" AS "入庫原因", "f"."全名" AS "廠商名稱", ABS("a"."異動數量") AS "庫存異動數", COALESCE(ABS("c"."沖銷異動數"), 0) AS "沖銷異動數", GREATEST(ABS("a"."異動數量") - COALESCE(ABS("c"."沖銷異動數"), 0), 0) AS "待沖銷數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" INNER JOIN "viewfil3127" AS "d" ON "d"."代碼" = "b"."收付方式" INNER JOIN "fil0011" AS "f" ON "f"."編號" = "b"."廠客編號" LEFT JOIN "viewfil1012" AS "e" ON "a"."產品編號" = "e"."產品編號" LEFT JOIN (SELECT "前置單別", "前置單號", "圓周" AS "前置序號", SUM("異動數量") AS "沖銷異動數" FROM "fil0040" WHERE "單據類別" = 'E12' GROUP BY "前置單別", "前置單號", "圓周") AS "c" ON "c"."前置單別" = "a"."單據類別" AND "c"."前置單號" = "a"."單據編號" AND "c"."前置序號" = "a"."單據序號" WHERE "a"."單據類別" = 'E11' AND "b"."收付方式" <> ' ');

-- Home #2196 ViewFILE021.調整單明細
