-- Home #2081 ViewFILE034.成品重工明細
CREATE OR REPLACE VIEW "viewfile034" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "b"."單據日期", "a"."異動類別", "a"."數值1" AS "父項序號", "d"."產品編號" AS "料號", COALESCE("e"."品名", ' ') AS "品名", COALESCE("e"."規格", ' ') AS "規格", "a"."異動日期" AS "盤點日期", "a"."預交日" AS "進貨日期", "a"."倉庫代碼" AS "庫別代碼", COALESCE("g"."名稱", ' ') AS "庫別名稱", "a"."異動數量" AS "箱號", "a"."贈品數量" AS "包裝數量", CASE WHEN "a"."異動類別" = 'A' THEN 0 ELSE 0 END AS "報廢數量", "a"."毛重" AS "重量", "a"."單位代碼" AS "庫存單位代碼", COALESCE("f1"."名稱", ' ') AS "庫存單位名稱", "a"."文數字1" AS "包裝單位代碼", COALESCE("f2"."名稱", ' ') AS "包裝單位名稱", "c"."批號", "c"."數值1" AS "幾束一袋", "c"."數值2" AS "氣閥重量", "c"."數值3" AS "鐵條重量", "a"."毛重" AS "製袋重量", "b"."歸屬類別" AS "製令單別", "b"."歸屬編號" AS "製令單號", "a"."qrno", "a"."前置單號" AS "紙箱代碼", "a"."備註說明" AS "備註", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日", "b"."業務員" AS "倉管人員", "h"."文數字1" AS "重工人員1", "h"."文數字2" AS "重工人員2", "h"."文數字3" AS "重工人員3", "h"."文數字4" AS "重工人員4", "h"."文數字5" AS "品檢人員", COALESCE("z2"."員工姓名", ' ') AS "重工人員名稱1", COALESCE("z3"."員工姓名", ' ') AS "重工人員名稱2", COALESCE("z4"."員工姓名", ' ') AS "重工人員名稱3", COALESCE("z5"."員工姓名", ' ') AS "重工人員名稱4", COALESCE("z6"."員工姓名", ' ') AS "品檢人員名稱", COALESCE("z7"."員工姓名", ' ') AS "倉管人員名稱" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" LEFT JOIN "fil0031" AS "h" ON "a"."單據類別" = "h"."單別" AND "a"."單據編號" = "h"."單號" /* 特殊欄位 */ LEFT JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN "fil0032" AS "d" ON "d"."製令單別" = "b"."歸屬類別" AND "d"."製令單號" = "b"."歸屬編號" LEFT JOIN "viewfil1012" AS "e" ON "d"."產品編號" = "e"."產品編號" LEFT JOIN "viewfil3103" AS "f1" ON "a"."單位代碼" = "f1"."代碼" LEFT JOIN "viewfil3103" AS "f2" ON "a"."文數字1" = "f2"."代碼" LEFT JOIN "viewfil3106" AS "g" ON "a"."倉庫代碼" = "g"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "h"."文數字1" = "z2"."員工編號" LEFT JOIN "fil0010" AS "z3" ON "h"."文數字2" = "z3"."員工編號" LEFT JOIN "fil0010" AS "z4" ON "h"."文數字3" = "z4"."員工編號" LEFT JOIN "fil0010" AS "z5" ON "h"."文數字4" = "z5"."員工編號" LEFT JOIN "fil0010" AS "z6" ON "h"."文數字5" = "z6"."員工編號" LEFT JOIN "fil0010" AS "z7" ON "b"."業務員" = "z7"."員工編號" WHERE "a"."單據類別" = 'E33');

-- Home #2085 ViewFILE037.成品出廠明細
CREATE OR REPLACE VIEW "viewfile037" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."產品編號" AS "料號", COALESCE("e"."品名", ' ') AS "品名", COALESCE("e"."規格", ' ') AS "規格", "a"."異動日期", "a"."預交日", "a"."倉庫代碼" AS "庫別代碼", COALESCE("g"."名稱", ' ') AS "庫別名稱", "a"."異動數量" AS "箱號", "a"."贈品數量" AS "包裝數量", "a"."毛重" AS "重量", "a"."單位代碼" AS "庫存單位代碼", COALESCE("f1"."名稱", ' ') AS "庫存單位名稱", "a"."文數字1" AS "包裝單位代碼", COALESCE("f2"."名稱", ' ') AS "包裝單位名稱", "a"."數值1" AS "箱數", "c"."批號", "a"."廠客品號" AS "製令單號", "a"."qrno", "a"."備註說明" AS "備註", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" /* 特殊欄位 */ LEFT JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN "viewfil1012" AS "e" ON "a"."產品編號" = "e"."產品編號" LEFT JOIN "viewfil3103" AS "f1" ON "a"."單位代碼" = "f1"."代碼" LEFT JOIN "viewfil3103" AS "f2" ON "a"."文數字1" = "f2"."代碼" LEFT JOIN "viewfil3106" AS "g" ON "a"."倉庫代碼" = "g"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."單據類別" = 'E35');

-- Home #2289 ViewFILH010.員工假別月統計
CREATE OR REPLACE VIEW "viewfilh010" AS (SELECT ORA_SUBSTR("a"."異動日期", 1, 6) AS "年月", "b"."申請人", "b"."假別", SUM("a"."異動數量") AS "請假時數", SUM(CASE WHEN "d"."扣點" = 0 THEN "a"."異動數量" * (CAST("e"."本薪" AS DOUBLE PRECISION) / (30 * 8) * "d"."扣薪") ELSE "a"."異動數量" * (CAST("e"."本薪" AS DOUBLE PRECISION) / (30 * 8 * 2)) * "d"."扣點" + (CAST("a"."異動數量" AS DOUBLE PRECISION) / 8 * ("e"."出勤日支" * "d"."扣點")) END) AS "請假扣薪", SUM(CASE WHEN "b"."假別" <> "b"."請假假別" THEN "a"."異動數量" ELSE 0 END) AS "假別轉換" FROM "fil0040" AS "a" INNER JOIN "hrfil1031" AS "b" ON "b"."單號" = "a"."單據編號" AND "b"."單別" = "a"."單據類別" LEFT JOIN "hrfil2006" AS "c" ON "b"."申請人" = "c"."員工編號" AND ORA_SUBSTR("a"."異動日期", 1, 6) = ORA_SUBSTR("c"."年月", 1, 6) LEFT JOIN "viewfil3801" AS "d" ON "d"."代碼" = "b"."假別" LEFT JOIN "hrfil2001" AS "e" ON "e"."員工編號" = "b"."申請人" AND ORA_SUBSTR("a"."異動日期", 1, 6) = "e"."年月" LEFT JOIN "viewfilh001" AS "z" ON "z"."單別" = "a"."單據類別" AND "z"."單號" = "a"."單據編號" LEFT JOIN "viewfilh018" AS "z1" ON "z1"."單別" = "a"."單據類別" AND "z1"."單號" = "a"."單據編號" WHERE "a"."單據類別" = 'H01' AND "z"."簽核狀態" = 'E' OR "a"."單據類別" = 'H05' AND "z1"."簽核狀態" = 'E' GROUP BY ORA_SUBSTR("a"."異動日期", 1, 6), "b"."申請人", "b"."假別");

-- Home #2290 ViewFILH011.員工假別年統計
CREATE OR REPLACE VIEW "viewfilh011" AS (SELECT ORA_SUBSTR("a"."異動日期", 1, 4) AS "年度", "b"."申請人", "b"."假別", SUM("a"."異動數量") AS "請假時數" FROM "fil0040" AS "a" INNER JOIN "hrfil1031" AS "b" ON "b"."單號" = "a"."單據編號" AND "b"."單別" = "a"."單據類別" LEFT JOIN "viewfilh001" AS "z" ON "z"."單別" = "a"."單據類別" AND "z"."單號" = "a"."單據編號" LEFT JOIN "viewfilh018" AS "z1" ON "z1"."單別" = "a"."單據類別" AND "z1"."單號" = "a"."單據編號" WHERE "a"."單據類別" = 'H01' AND "z"."簽核狀態" = 'E' OR "a"."單據類別" = 'H05' AND "z1"."簽核狀態" = 'E' GROUP BY ORA_SUBSTR("a"."異動日期", 1, 4), "b"."申請人", "b"."假別");

-- Home #2291 ViewFILH012.員工每日請假時數
CREATE OR REPLACE VIEW "viewfilh012" AS (SELECT "a"."異動日期", CASE WHEN "a"."單據類別" = 'H01' THEN "b"."申請人" ELSE "b1"."申請人" END AS "申請人", SUM("a"."異動數量") AS "請假時數", SUM(COALESCE(CASE WHEN "a"."異動數量" BETWEEN 2 AND 4 THEN CASE WHEN CASE WHEN "a"."單據類別" = 'H01' THEN "b"."假別名稱" ELSE "b1"."假別名稱" END = '事假' THEN 2 ELSE 1 END * 0.5 WHEN "a"."異動數量" > 4 THEN CASE WHEN CASE WHEN "a"."單據類別" = 'H01' THEN "b"."假別名稱" ELSE "b1"."假別名稱" END = '事假' THEN 2 ELSE 1 END ELSE 0 END, 0)) AS "出勤扣點", SUM(COALESCE(CASE WHEN "a"."異動數量" BETWEEN 2 AND 4 THEN CASE WHEN CASE WHEN "a"."單據類別" = 'H01' THEN "b"."假別名稱" ELSE "b1"."假別名稱" END = '事假' THEN "c"."出勤日支" ELSE CAST("c"."出勤日支" AS DOUBLE PRECISION) / 2 END * 0.5 WHEN "a"."異動數量" > 4 THEN CASE WHEN CASE WHEN "a"."單據類別" = 'H01' THEN "b"."假別名稱" ELSE "b1"."假別名稱" END = '事假' THEN "c"."出勤日支" ELSE CAST("c"."出勤日支" AS DOUBLE PRECISION) / 2 END ELSE 0 END, 0)) AS "出勤扣支", SUM(COALESCE(CASE WHEN "a"."異動數量" BETWEEN 2 AND 4 THEN "c"."othfee1" * 0.5 WHEN "a"."異動數量" > 4 THEN "c"."othfee1" ELSE 0 END, 0)) AS "午餐扣支", SUM(COALESCE(CASE WHEN "a"."異動數量" BETWEEN 2 AND 4 THEN CAST("c"."伙食津貼" AS DOUBLE PRECISION) / 30 * 0.5 WHEN "a"."異動數量" > 4 THEN CAST("c"."伙食津貼" AS DOUBLE PRECISION) / 30 ELSE 0 END, 0)) AS "伙食扣支" FROM "fil0040" AS "a" LEFT JOIN "viewfilh001" AS "b" ON "b"."單別" = "a"."單據類別" AND "b"."單號" = "a"."單據編號" LEFT JOIN "viewfilh018" AS "b1" ON "b1"."單別" = "a"."單據類別" AND "b1"."單號" = "a"."單據編號" LEFT JOIN "hrfil2001" AS "c" ON "c"."員工編號" = CASE WHEN "a"."單據類別" = 'H01' THEN "b"."申請人" ELSE "b1"."申請人" END AND ORA_SUBSTR("a"."異動日期", 1, 6) = "c"."年月" WHERE "a"."單據類別" = 'H01' AND "b"."簽核狀態" = 'E' OR "a"."單據類別" = 'H05' AND "b1"."簽核狀態" = 'E' GROUP BY "a"."異動日期", CASE WHEN "a"."單據類別" = 'H01' THEN "b"."申請人" ELSE "b1"."申請人" END);

-- Home #2292 ViewFILH012A.員工日請假含未核
CREATE OR REPLACE VIEW "viewfilh012a" AS (SELECT "a"."異動日期", CASE WHEN "a"."單據類別" = 'H01' THEN "b"."申請人" ELSE "b1"."申請人" END AS "申請人", SUM("a"."異動數量") AS "請假時數" FROM "fil0040" AS "a" LEFT JOIN "viewfilh001" AS "b" ON "b"."單別" = "a"."單據類別" AND "b"."單號" = "a"."單據編號" LEFT JOIN "viewfilh018" AS "b1" ON "b1"."單別" = "a"."單據類別" AND "b1"."單號" = "a"."單據編號" WHERE "a"."單據類別" = 'H01' OR "a"."單據類別" = 'H05' GROUP BY "a"."異動日期", CASE WHEN "a"."單據類別" = 'H01' THEN "b"."申請人" ELSE "b1"."申請人" END);

-- Home #2294 ViewFILH014.員工伙食請假日數
CREATE OR REPLACE VIEW "viewfilh014" AS (SELECT ORA_SUBSTR("a"."異動日期", 1, 6) AS "年月", CASE WHEN "a"."單據類別" = 'H01' THEN "b"."申請人" ELSE "b1"."申請人" END AS "申請人", SUM("a"."異動數量") AS "請假時數合計", SUM(CASE WHEN "a"."異動數量" > 4 THEN 1 ELSE 0.5 END) AS "伙食扣假" FROM "fil0040" AS "a" LEFT JOIN "viewfilh001" AS "b" ON "b"."單別" = "a"."單據類別" AND "b"."單號" = "a"."單據編號" LEFT JOIN "viewfilh018" AS "b1" ON "b1"."單別" = "a"."單據類別" AND "b1"."單號" = "a"."單據編號" WHERE "a"."單據類別" = 'H01' AND "b"."簽核狀態" = 'E' OR "a"."單據類別" = 'H05' AND "b1"."簽核狀態" = 'E' GROUP BY ORA_SUBSTR("a"."異動日期", 1, 6), CASE WHEN "a"."單據類別" = 'H01' THEN "b"."申請人" ELSE "b1"."申請人" END);

-- Home #2295 ViewFILH015.員工每月請假扣支
CREATE OR REPLACE VIEW "viewfilh015" AS (SELECT ORA_SUBSTR("a"."異動日期", 1, 6) AS "年月", "a"."申請人", "f"."請假扣支" AS "請假扣支", SUM("a"."請假時數") AS "請假時數", SUM("a"."出勤扣點") AS "出勤扣點", SUM(CAST("a"."伙食扣支時數" * "c"."伙食津貼" AS DOUBLE PRECISION) / 30) AS "伙食扣支" FROM (SELECT "a"."異動日期", CASE WHEN "a"."單據類別" = 'H01' THEN "b"."申請人" ELSE "b1"."申請人" END AS "申請人", SUM("a"."異動數量") AS "請假時數", SUM(COALESCE(CASE WHEN "a"."異動數量" BETWEEN 2.01 AND 4 THEN CASE WHEN CASE WHEN "a"."單據類別" = 'H01' THEN "b"."假別名稱" ELSE "b1"."假別名稱" END = '事假' THEN 2 ELSE 1 END * 0.5 WHEN "a"."異動數量" > 4 THEN CASE WHEN CASE WHEN "a"."單據類別" = 'H01' THEN "b"."假別名稱" ELSE "b1"."假別名稱" END = '事假' THEN 2 ELSE 1 END ELSE 0 END, 0)) AS "出勤扣點", SUM(COALESCE(CASE WHEN "a"."異動數量" BETWEEN 2.01 AND 4 THEN 0.5 WHEN "a"."異動數量" > 4 THEN 1 ELSE 0 END, 0)) AS "伙食扣支時數" FROM "fil0040" AS "a" LEFT JOIN "viewfilh001" AS "b" ON "b"."單別" = "a"."單據類別" AND "b"."單號" = "a"."單據編號" LEFT JOIN "viewfilh018" AS "b1" ON "b1"."單別" = "a"."單據類別" AND "b1"."單號" = "a"."單據編號" WHERE ("a"."單據類別" = 'H01' AND "b"."簽核狀態" = 'E' OR "a"."單據類別" = 'H05' AND "b1"."簽核狀態" = 'E') GROUP BY "a"."異動日期", CASE WHEN "a"."單據類別" = 'H01' THEN "b"."申請人" ELSE "b1"."申請人" END) AS "a" LEFT JOIN "hrfil2001" AS "c" ON "c"."員工編號" = "a"."申請人" AND ORA_SUBSTR("a"."異動日期", 1, 6) = "c"."年月" LEFT JOIN "hrfil2006" AS "e" ON "a"."申請人" = "e"."員工編號" AND ORA_SUBSTR("a"."異動日期", 1, 6) = ORA_SUBSTR("e"."年月", 1, 6) LEFT JOIN (SELECT "a"."年月", "a"."申請人", SUM("a"."請假扣薪") AS "請假扣支" FROM "viewfilh010" AS "a" GROUP BY "a"."年月", "a"."申請人") AS "f" ON "f"."年月" = ORA_SUBSTR("a"."異動日期", 1, 6) AND "f"."申請人" = "a"."申請人" GROUP BY ORA_SUBSTR("a"."異動日期", 1, 6), "a"."申請人", "f"."請假扣支");

-- Home #2306 ViewFILH026.月計件彙總
CREATE OR REPLACE VIEW "viewfilh026" AS (SELECT "d"."產品編號" AS "作業人員", ORA_SUBSTR("c"."匯率日期", 1, 6) AS "年月", MAX("a"."數字一") AS "件數", SUM(ROUND("a"."數字一" * COALESCE(CASE WHEN "e"."製程代碼" = 'C31G' THEN "b"."鐵條加工單價" ELSE "b"."氣閥加工單價" END, 0), 0)) AS "加工費" FROM "fil0037" AS "a" INNER JOIN "fil0031" AS "e" ON "e"."單別" = "a"."相關單別" AND "e"."單號" = "a"."相關單號" INNER JOIN "fil0030" AS "g" ON "g"."單據類別" = "e"."單別" AND "g"."單據編號" = "e"."單號" INNER JOIN "fil0032" AS "b" ON "b"."製令單別" = "g"."歸屬類別" AND "b"."製令單號" = "g"."歸屬編號" INNER JOIN "fil0030" AS "c" ON "a"."製令單別" = "c"."單據類別" AND "a"."製令單號" = "c"."單據編號" INNER JOIN "fil0040" AS "d" ON "a"."製令單別" = "d"."單據類別" AND "a"."製令單號" = "d"."單據編號" AND "a"."材料序號" = "d"."單據序號" INNER JOIN "viewofobjproperties" AS "g_2" ON "c"."流水編號" = "g_2"."單據流水號" WHERE "a"."製令單別" = 'H03' AND "a"."屬性" = '4' AND "g_2"."簽核狀態" = 'E' AND "d"."logical1" = 1 GROUP BY "d"."產品編號", ORA_SUBSTR("c"."匯率日期", 1, 6));

-- Home #2307 ViewFILH027.年計件彙總
CREATE OR REPLACE VIEW "viewfilh027" AS (SELECT "d"."產品編號" AS "作業人員", ORA_SUBSTR("c"."匯率日期", 1, 4) AS "年度", MAX("a"."數字一") AS "件數", SUM(ROUND("a"."數字一" * COALESCE(CASE WHEN "e"."製程代碼" = 'C31G' THEN "b"."鐵條加工單價" ELSE "b"."氣閥加工單價" END, 0), 0)) AS "加工費" FROM "fil0037" AS "a" INNER JOIN "fil0031" AS "e" ON "e"."單別" = "a"."相關單別" AND "e"."單號" = "a"."相關單號" INNER JOIN "fil0030" AS "g" ON "g"."單據類別" = "e"."單別" AND "g"."單據編號" = "e"."單號" INNER JOIN "fil0032" AS "b" ON "b"."製令單別" = "g"."歸屬類別" AND "b"."製令單號" = "g"."歸屬編號" INNER JOIN "fil0030" AS "c" ON "a"."製令單別" = "c"."單據類別" AND "a"."製令單號" = "c"."單據編號" INNER JOIN "fil0040" AS "d" ON "a"."製令單別" = "d"."單據類別" AND "a"."製令單號" = "d"."單據編號" AND "a"."材料序號" = "d"."單據序號" INNER JOIN "viewofobjproperties" AS "g_2" ON "c"."流水編號" = "g_2"."單據流水號" WHERE "a"."製令單別" = 'H03' AND "a"."屬性" = '4' AND "g_2"."簽核狀態" = 'E' AND "d"."logical1" = 1 GROUP BY "d"."產品編號", ORA_SUBSTR("c"."匯率日期", 1, 4));

-- Home #2311 ViewFILH033.計件工資明細
CREATE OR REPLACE VIEW "viewfilh033" AS (SELECT "d"."產品編號" AS "員工編號", ORA_SUBSTR("c"."匯率日期", 1, 6) AS "年月", SUM(ROUND("a"."數字一" * COALESCE(CASE WHEN "e"."製程代碼" = 'C31G' THEN "b"."鐵條加工單價" ELSE "b"."氣閥加工單價" END, 0), 0)) AS "計件工資" FROM "fil0037" AS "a" INNER JOIN "fil0031" AS "e" ON "e"."單別" = "a"."相關單別" AND "e"."單號" = "a"."相關單號" INNER JOIN "fil0030" AS "g" ON "g"."單據類別" = "e"."單別" AND "g"."單據編號" = "e"."單號" INNER JOIN "fil0032" AS "b" ON "b"."製令單別" = "g"."歸屬類別" AND "b"."製令單號" = "g"."歸屬編號" INNER JOIN "fil0030" AS "c" ON "a"."製令單別" = "c"."單據類別" AND "a"."製令單號" = "c"."單據編號" INNER JOIN "fil0040" AS "d" ON "a"."製令單別" = "d"."單據類別" AND "a"."製令單號" = "d"."單據編號" AND "a"."材料序號" = "d"."單據序號" INNER JOIN "viewofobjproperties" AS "g_2" ON "c"."流水編號" = "g_2"."單據流水號" WHERE "a"."製令單別" = 'H03' AND "g_2"."簽核狀態" = 'E' AND "a"."屬性" = '4' AND "d"."logical1" = 1 GROUP BY "d"."產品編號", ORA_SUBSTR("c"."匯率日期", 1, 6));

-- Home #2236 ViewFILM017S.不分倉批號(S)
CREATE OR REPLACE VIEW "viewfilm017s" AS (SELECT "f"."料號" AS "材料編號", "e"."物料大類", "e"."品名", "e"."規格", "a"."批號", "f"."廠客" AS "廠客編號", GREATEST(SUM(COALESCE("a"."異動數", 0)), 0) AS "庫存數" FROM (SELECT "a"."條碼" AS "批號", "a"."庫存結算數" AS "異動數" FROM "fil0043" AS "a" UNION ALL /* 盤點調整 */ SELECT "c"."批號", ("a"."異動數量" + "a"."贈品數量") AS "異動數" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "c"."批號" WHERE "a"."單據類別" = 'F32' AND "c"."批號" <> ' ' AND "a"."異動日期" >= "f"."結算日期" UNION ALL /* 驗收/入庫/調整/退出 */ SELECT "c"."批號", CASE WHEN "a"."單據類別" = 'D21' THEN "a"."數值4" WHEN "a"."單據類別" = 'E12' THEN "a"."數值2" WHEN "a"."單據類別" = 'E13' THEN "a"."數值2" ELSE ("a"."異動數量" + "a"."贈品數量") END AS "異動數" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "c"."批號" LEFT JOIN "viewofobjproperties" AS "d" ON "d"."單據流水號" = "b"."流水編號" WHERE "a"."入料註記" = 1 AND "a"."產品編號" <> ' ' AND "c"."批號" <> ' ' AND COALESCE("d"."簽核狀態", ' ') <> 'A' AND "a"."異動日期" >= "f"."結算日期" UNION ALL /* 前製程日報領料 */ SELECT CAST("c"."文數字4" AS TEXT) AS "批號", ("a"."異動數量") * -1 AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = CAST("c"."文數字4" AS TEXT) WHERE "a"."單據類別" = 'C41' AND (("d"."製程代碼" BETWEEN 'C31A' AND 'C31C') OR "d"."製程代碼" = 'C32D' OR "d"."製程代碼" = 'C31H' OR "d"."製程代碼" = 'C31K') AND "c"."文數字4" <> ' ' AND "a"."異動數量" > 0 AND "b"."單據日期" >= "f"."結算日期" UNION ALL /* 前製程日報退庫 */ SELECT CAST("c"."文數字4" AS TEXT) AS "批號", "a"."退庫數量" AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = CAST("c"."文數字4" AS TEXT) WHERE "a"."單據類別" = 'C41' AND "a"."單據序號" < 500 AND ("d"."製程代碼" = 'C31B' OR "d"."製程代碼" = 'C31C' OR "d"."製程代碼" = 'C32D' OR "d"."製程代碼" = 'C31H' OR "d"."製程代碼" = 'C31K') AND "c"."文數字4" <> ' ' AND "a"."退庫數量" > 0 AND "b"."單據日期" >= "f"."結算日期" UNION ALL /* 前製程日報領用退庫 */ SELECT CAST("c"."文數字4" AS TEXT) AS "批號", "a"."退庫數量" AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = CAST("c"."文數字4" AS TEXT) WHERE "a"."單據類別" = 'C41' AND "a"."單據序號" >= 500 AND ("d"."製程代碼" = 'C31B' OR "d"."製程代碼" = 'C31C' OR "d"."製程代碼" = 'C32D' OR "d"."製程代碼" = 'C31H' OR "d"."製程代碼" = 'C31K') AND "c"."文數字4" <> ' ' AND "a"."logical1" = 0 AND "a"."退庫數量" > 0 AND "b"."單據日期" >= "f"."結算日期" UNION ALL /* 印刷日報退庫 */ SELECT CAST("c"."文數字4" AS TEXT) AS "批號", "a"."退庫數量" AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = CAST("c"."文數字4" AS TEXT) WHERE "a"."單據類別" = 'C41' AND "d"."製程代碼" = 'C31A' AND CAST("c"."文數字4" AS TEXT) <> ' ' AND "a"."退庫數量" > 0 AND "b"."單據日期" >= "f"."結算日期" UNION ALL /* 製袋主頁領料 */ SELECT "a"."批號", "a"."異動數" * -1 AS "異動數" FROM "viewfilm018a" AS "a" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "a"."批號" WHERE "a"."單據日期" >= "f"."結算日期" UNION ALL /* 退庫 */ SELECT "c"."批號", CASE WHEN "a"."單據類別" = 'D52' THEN "a"."數值4" ELSE ("a"."異動數量" + "a"."贈品數量") END * -1 AS "異動數" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "c"."批號" WHERE "a"."退料註記" = 1 AND "a"."產品編號" <> ' ' AND "c"."批號" <> ' ' AND "a"."異動日期" >= "f"."結算日期" UNION ALL /* 裁切材料領用 */ SELECT "a"."廠客單號" AS "批號", "a"."折讓" * -1 AS "異動數" FROM "fil0030" AS "a" /* 特殊欄位 */ INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" LEFT JOIN "viewofobjproperties" AS "d" ON "d"."單據流水號" = "a"."流水編號" WHERE "a"."單據類別" = 'E13' AND "a"."廠客單號" <> ' ' AND "a"."折讓" > 0 AND COALESCE("d"."簽核狀態", ' ') <> 'A' UNION ALL /* 裁切材料退庫 */ SELECT "a"."廠客單號" AS "批號", "c"."數值1" AS "異動數" FROM "fil0030" AS "a" /* 特殊欄位 */ INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" LEFT JOIN "viewofobjproperties" AS "d" ON "d"."單據流水號" = "a"."流水編號" WHERE "a"."單據類別" = 'E13' AND "a"."廠客單號" <> ' ' AND "c"."數值1" > 0 AND COALESCE("d"."簽核狀態", ' ') <> 'A' UNION ALL /* 氣閥鐵條領用1 */ SELECT "c"."文數字1" AS "批號", ("c"."數值1") * -1 AS "異動數" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "c"."文數字1" WHERE "a"."單據類別" = 'C41' AND "c"."數值1" > 0 AND "d"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "a"."異動類別" = 'A' AND "c"."文數字1" <> ' ' AND "a"."異動日期" >= "f"."結算日期" UNION ALL /* 氣閥鐵條領用2 */ SELECT "c"."文數字2" AS "批號", ("c"."數值2") * -1 AS "異動數" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "c"."文數字2" WHERE "a"."單據類別" = 'C41' AND "c"."數值2" > 0 AND "d"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "a"."異動類別" = 'A' AND "c"."文數字2" <> ' ' AND "a"."異動日期" >= "f"."結算日期" /* 期初庫存 */ UNION ALL /* 材料領用,報廢,油墨領用 */ SELECT "b"."批號", ("a"."異動數量" - "a"."退庫數量") * -1 FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "c1" ON "a"."單據類別" = "c1"."單據類別" AND "a"."單據編號" = "c1"."單據編號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "b"."批號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" BETWEEN 'C' AND 'E' AND "a"."異動數量" <> 0 AND "b"."批號" <> ' ' AND "c1"."單據日期" >= "f"."結算日期") AS "a" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "a"."批號" INNER JOIN "viewfil1012" AS "e" ON "f"."料號" = "e"."產品編號" GROUP BY "f"."料號", "e"."物料大類", "e"."品名", "e"."規格", "a"."批號", "f"."廠客");

-- Home #2237 ViewFILM017SA.條碼庫存
CREATE OR REPLACE VIEW "viewfilm017sa" AS (SELECT "a"."批號", SUM(COALESCE("a"."異動數", 0)) AS "庫存數" FROM (SELECT "a"."條碼" AS "批號", "a"."庫存結算數" AS "異動數" FROM "fil0043" AS "a" UNION ALL /* 盤點調整 */ SELECT "c"."批號", ("a"."異動數量" + "a"."贈品數量") AS "異動數" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "c"."批號" WHERE "a"."單據類別" = 'F32' AND "c"."批號" <> ' ' AND "a"."異動日期" >= "f"."結算日期" UNION ALL /* 驗收/入庫/調整/退出 */ SELECT "c"."批號", CASE WHEN "a"."單據類別" = 'D21' THEN "a"."數值4" WHEN "a"."單據類別" = 'E12' THEN "a"."數值2" WHEN "a"."單據類別" = 'E13' THEN "a"."數值2" ELSE ("a"."異動數量" + "a"."贈品數量") END AS "異動數" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "c"."批號" LEFT JOIN "viewofobjproperties" AS "d" ON "d"."單據流水號" = "b"."流水編號" WHERE "a"."入料註記" = 1 AND "a"."產品編號" <> ' ' AND "c"."批號" <> ' ' AND COALESCE("d"."簽核狀態", ' ') <> 'A' AND "a"."異動日期" >= "f"."結算日期" UNION ALL /* 前製程日報領料 */ SELECT CAST("c"."文數字4" AS TEXT) AS "批號", ("a"."異動數量") * -1 AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = CAST("c"."文數字4" AS TEXT) WHERE "a"."單據類別" = 'C41' AND (("d"."製程代碼" BETWEEN 'C31A' AND 'C31C') OR "d"."製程代碼" = 'C32D' OR "d"."製程代碼" = 'C31H' OR "d"."製程代碼" = 'C31K') AND "c"."文數字4" <> ' ' AND "a"."異動數量" > 0 AND "b"."單據日期" >= "f"."結算日期" UNION ALL /* 前製程日報退庫 */ SELECT CAST("c"."文數字4" AS TEXT) AS "批號", "a"."退庫數量" AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = CAST("c"."文數字4" AS TEXT) WHERE "a"."單據類別" = 'C41' AND "a"."單據序號" < 500 AND ("d"."製程代碼" = 'C31B' OR "d"."製程代碼" = 'C31C' OR "d"."製程代碼" = 'C32D' OR "d"."製程代碼" = 'C31H' OR "d"."製程代碼" = 'C31K') AND "c"."文數字4" <> ' ' AND "a"."退庫數量" > 0 AND "b"."單據日期" >= "f"."結算日期" UNION ALL /* 前製程日報領用退庫 */ SELECT CAST("c"."文數字4" AS TEXT) AS "批號", "a"."退庫數量" AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = CAST("c"."文數字4" AS TEXT) WHERE "a"."單據類別" = 'C41' AND "a"."單據序號" >= 500 AND ("d"."製程代碼" = 'C31B' OR "d"."製程代碼" = 'C31C' OR "d"."製程代碼" = 'C32D' OR "d"."製程代碼" = 'C31H' OR "d"."製程代碼" = 'C31K') AND "c"."文數字4" <> ' ' AND "a"."logical1" = 0 AND "a"."退庫數量" > 0 AND "b"."單據日期" >= "f"."結算日期" UNION ALL /* 前製程日報沿用 */ SELECT CAST("c"."文數字4" AS TEXT) AS "批號", "a"."退庫數量" AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = CAST("c"."文數字4" AS TEXT) WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'C' AND "a"."退庫數量" > 0 AND ("d"."製程代碼" BETWEEN 'C31B' AND 'C31C') AND "c"."文數字4" <> ' ' AND "a"."logical1" = 1 AND "b"."單據日期" >= "f"."結算日期" UNION ALL /* 印刷日報退庫 */ SELECT CAST("c"."文數字4" AS TEXT) AS "批號", "a"."退庫數量" AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = CAST("c"."文數字4" AS TEXT) WHERE "a"."單據類別" = 'C41' AND "d"."製程代碼" = 'C31A' AND CAST("c"."文數字4" AS TEXT) <> ' ' AND "a"."退庫數量" > 0 AND "b"."單據日期" >= "f"."結算日期" UNION ALL /* 製袋主頁領料 */ SELECT "a"."批號", "a"."異動數" * -1 AS "異動數" FROM "viewfilm018a" AS "a" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "a"."批號" WHERE "a"."批號" <> ' ' AND "a"."單據日期" >= "f"."結算日期" UNION ALL /* 退庫 */ SELECT "c"."批號", CASE WHEN "a"."單據類別" = 'D52' THEN "a"."數值4" ELSE ("a"."異動數量" + "a"."贈品數量") END * -1 AS "異動數" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "c"."批號" WHERE "a"."退料註記" = 1 AND "a"."產品編號" <> ' ' AND "c"."批號" <> ' ' AND "a"."異動日期" >= "f"."結算日期" UNION ALL /* 氣閥鐵條領用1 */ SELECT "c"."文數字1" AS "批號", ("c"."數值1") * -1 AS "異動數" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "c"."文數字1" WHERE "a"."單據類別" = 'C41' AND "c"."數值1" > 0 AND "d"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "a"."異動類別" = 'A' AND "c"."文數字1" <> ' ' AND "a"."異動日期" >= "f"."結算日期" UNION ALL /* 裁切材料領用 */ SELECT "a"."廠客單號" AS "批號", "a"."折讓" * -1 AS "異動數" FROM "fil0030" AS "a" /* 特殊欄位 */ INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" LEFT JOIN "viewofobjproperties" AS "d" ON "d"."單據流水號" = "a"."流水編號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "a"."廠客單號" WHERE "a"."單據類別" = 'E13' AND "a"."廠客單號" <> ' ' AND "a"."折讓" > 0 AND COALESCE("d"."簽核狀態", ' ') <> 'A' AND "a"."單據日期" >= "f"."結算日期" UNION ALL /* 裁切材料退庫 */ SELECT "a"."廠客單號" AS "批號", "c"."數值1" AS "異動數" FROM "fil0030" AS "a" /* 特殊欄位 */ INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" LEFT JOIN "viewofobjproperties" AS "d" ON "d"."單據流水號" = "a"."流水編號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "a"."廠客單號" WHERE "a"."單據類別" = 'E13' AND "a"."廠客單號" <> ' ' AND "c"."數值1" > 0 AND COALESCE("d"."簽核狀態", ' ') <> 'A' AND "a"."單據日期" >= "f"."結算日期" UNION ALL /* 氣閥鐵條領用2 */ SELECT "c"."文數字2" AS "批號", ("c"."數值2") * -1 AS "異動數" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "c"."文數字2" WHERE "a"."單據類別" = 'C41' AND "c"."數值2" > 0 AND "d"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "a"."異動類別" = 'A' AND "c"."文數字2" <> ' ' AND "a"."異動日期" >= "f"."結算日期" /* 期初庫存 */ UNION ALL /* 材料領用,報廢,油墨領用 */ SELECT "b"."批號", ("a"."異動數量" - "a"."退庫數量") * -1 FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "c1" ON "a"."單據類別" = "c1"."單據類別" AND "a"."單據編號" = "c1"."單據編號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "b"."批號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" BETWEEN 'C' AND 'E' AND "a"."異動數量" <> 0 AND "b"."批號" <> ' ' AND "c1"."單據日期" >= "f"."結算日期") AS "a" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "a"."批號" INNER JOIN "viewfil1012" AS "e" ON "f"."料號" = "e"."產品編號" GROUP BY "a"."批號");

-- Home #2209 ViewFILM018S.料碼庫存異動
CREATE OR REPLACE VIEW "viewfilm018s" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動類別", "a"."異動日期", "f"."料號" AS "料號", "a"."批號", "a"."最後更新日", COALESCE("a"."異動數", 0) AS "異動數", "a"."來源" FROM (SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."異動類別", "a"."異動日期", "c"."批號", "a"."最後更新日", ("a"."異動數量" + "a"."贈品數量") AS "異動數", '盤點調整' AS "來源" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "c"."批號" WHERE "a"."單據類別" = 'F32' AND "c"."批號" <> ' ' UNION ALL /* 驗收,進料退出,材料入庫,調整,裁切材料入庫 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."異動類別", "a"."異動日期", "c"."批號", "a"."最後更新日", CASE WHEN "a"."單據類別" = 'D21' THEN "a"."數值4" WHEN "a"."單據類別" = 'E12' THEN "a"."數值2" WHEN "a"."單據類別" = 'E13' THEN "a"."數值2" ELSE ("a"."異動數量" + "a"."贈品數量") END AS "異動數", CASE WHEN "a"."單據類別" = 'D41' THEN '原材料.退料' WHEN "a"."單據類別" = 'E12' THEN '材料調整' WHEN "a"."單據類別" = 'E13' THEN '裁切.材料' ELSE '原材料.驗收' END AS "來源" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" LEFT JOIN "viewofobjproperties" AS "d" ON "d"."單據流水號" = "b"."流水編號" WHERE "a"."入料註記" = 1 AND "a"."產品編號" <> ' ' AND "c"."批號" <> ' ' AND COALESCE("d"."簽核狀態", ' ') <> 'A' UNION ALL /* 前製程日報領料 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."異動類別", "b"."單據日期", CAST("c"."文數字4" AS TEXT) AS "批號", "a"."最後更新日", ("a"."異動數量") * -1 AS "異動數", CASE WHEN "d"."製程代碼" = 'C31B' THEN CASE WHEN "a"."異動類別" = 'C' AND "c"."專案代號" <> ' ' THEN '沿用轉入' ELSE '領用' END WHEN "d"."製程代碼" = 'C31C' THEN CASE WHEN "a"."異動類別" = 'C' AND "c"."專案代號" <> ' ' THEN '沿用轉入' ELSE '領用' END ELSE '領用' END AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動數量" > 0 AND (("d"."製程代碼" BETWEEN 'C31A' AND 'C31C') OR "d"."製程代碼" = 'C32D' OR "d"."製程代碼" = 'C31H' OR "d"."製程代碼" = 'C31K') AND "c"."文數字4" <> ' ' UNION ALL /* 印刷日報退回 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."異動類別", "b"."單據日期", CAST("c"."文數字4" AS TEXT) AS "批號", "a"."最後更新日", "a"."退庫數量" AS "異動數", '退庫' AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."退庫數量" > 0 AND "d"."製程代碼" = 'C31A' AND CAST("c"."文數字4" AS TEXT) <> ' ' UNION ALL /* 前製程日報退回 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."異動類別", "b"."單據日期", CAST("c"."文數字4" AS TEXT) AS "批號", "a"."最後更新日", "a"."退庫數量" AS "異動數", '退庫' AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "a"."退庫數量" > 0 AND ("d"."製程代碼" = 'C31B' OR "d"."製程代碼" = 'C31C' OR "d"."製程代碼" = 'C32D' OR "d"."製程代碼" = 'C31H' OR "d"."製程代碼" = 'C31K') AND "c"."文數字4" <> ' ' UNION ALL /* 前製程日報沿用 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."異動類別", "b"."單據日期", CAST("c"."文數字4" AS TEXT) AS "批號", "a"."最後更新日", "a"."退庫數量" AS "異動數", CASE WHEN "a"."logical1" = 1 THEN '退庫沿用' ELSE '退庫' END AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'C' AND "a"."退庫數量" > 0 AND ("d"."製程代碼" BETWEEN 'C31B' AND 'C31C') AND "c"."文數字4" <> ' ' UNION ALL /* 材料領用,報廢,油墨領用 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."異動類別", "b"."單據日期", "c"."批號" AS "批號", "a"."最後更新日", ("a"."異動數量" - "a"."退庫數量") * -1 AS "異動數", '領用' AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動數量" > 0 AND "a"."異動類別" BETWEEN 'C' AND 'E' AND "c"."批號" <> ' ' UNION ALL /* 製袋日報退庫_沿用 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."異動類別", "b"."單據日期", "c"."批號" AS "批號", "a"."最後更新日", "a"."贈品數量" AS "異動數", CASE WHEN "a"."logical1" = 1 THEN '退庫沿用' ELSE '退庫' END AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."贈品數量" > 0 AND "d"."製程代碼" = 'C31E' AND "a"."異動類別" = 'C' AND "c"."批號" <> ' ' UNION ALL /* 製袋裁切領料 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."異動類別", "a"."單據日期", "a"."批號", "a"."最後更新日", "a"."異動數" * -1 AS "異動數", '領用' AS "來源" FROM "viewfilm018a" AS "a" UNION ALL /* 裁切材料領用 */ SELECT "a"."單據類別", "a"."單據編號", 0, ' ', "a"."單據日期", "a"."廠客單號" AS "批號", "a"."最後更新日", "a"."折讓" * -1 AS "異動數", '領用' AS "來源" FROM "fil0030" AS "a" /* 特殊欄位 */ INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" LEFT JOIN "viewofobjproperties" AS "d" ON "d"."單據流水號" = "a"."流水編號" WHERE "a"."單據類別" = 'E13' AND "a"."廠客單號" <> ' ' AND "a"."折讓" > 0 AND COALESCE("d"."簽核狀態", ' ') <> 'A' UNION ALL /* 裁切材料退庫 */ SELECT "a"."單據類別", "a"."單據編號", 0, ' ', "a"."單據日期", "a"."廠客單號" AS "批號", "a"."最後更新日", "c"."數值1" AS "異動數", '退回' AS "來源" FROM "fil0030" AS "a" /* 特殊欄位 */ INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" LEFT JOIN "viewofobjproperties" AS "d" ON "d"."單據流水號" = "a"."流水編號" WHERE "a"."單據類別" = 'E13' AND "a"."廠客單號" <> ' ' AND "c"."數值1" > 0 AND COALESCE("d"."簽核狀態", ' ') <> 'A' UNION ALL /* 氣閥鐵條領用1 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."異動類別", "b"."單據日期", "c"."文數字1" AS "批號", "a"."最後更新日", ("c"."數值1") * -1 AS "異動數", '領用' AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" WHERE "a"."單據類別" = 'C41' AND "c"."數值1" > 0 AND "d"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "a"."異動類別" = 'A' AND "c"."文數字1" <> ' ' /* 盤點調整 */ UNION ALL /* 氣閥鐵條領用2 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."異動類別", "b"."單據日期", "c"."文數字2" AS "批號", "a"."最後更新日", ("c"."數值2") * -1 AS "異動數", '領用' AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" WHERE "a"."單據類別" = 'C41' AND "c"."數值2" > 0 AND "d"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "a"."異動類別" = 'A' AND "c"."文數字2" <> ' ') AS "a" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "a"."批號" INNER JOIN "viewfil1012" AS "e" ON "f"."料號" = "e"."產品編號");

-- Home #2250 ViewFILM021A.製程人工時
CREATE OR REPLACE VIEW "viewfilm021a" AS (SELECT "a"."製程代碼", ORA_SUBSTR("a"."作業日期", 1, 6) AS "年月", SUM("a"."總耗時" * "a"."加工人數") AS "製程日報人工時" FROM "viewfilm201" AS "a" GROUP BY "a"."製程代碼", ORA_SUBSTR("a"."作業日期", 1, 6));

-- Home #2251 ViewFILM022A.總人工時
CREATE OR REPLACE VIEW "viewfilm022a" AS (SELECT ORA_SUBSTR("a"."作業日期", 1, 6) AS "年月", SUM("a"."總耗時" * "a"."加工人數") AS "日報總人工時", MAX(COALESCE("b"."分攤間接人工", 0)) AS "分攤間接人工", MAX(COALESCE("b"."分攤直接人工", 0)) AS "分攤直接人工" FROM "viewfilm201" AS "a" LEFT JOIN (SELECT ORA_SUBSTR("a"."年月", 1, 6) AS "年月", SUM(CASE WHEN "a"."成本類別" = 'B' THEN ("a"."本月應發金額" - "a"."事病假薪點" - "a"."遲到早退扣支" - "a"."調補扣支") ELSE 0 END) AS "分攤間接人工", SUM(CASE WHEN "a"."成本類別" = 'A' THEN ("a"."本月應發金額" - "a"."事病假薪點" - "a"."遲到早退扣支" - "a"."調補扣支") ELSE 0 END) AS "分攤直接人工" FROM "viewfilhs02" AS "a" WHERE "a"."製程代碼" = ' ' AND ORA_SUBSTR("a"."年月", 1, 6) > '2025' GROUP BY ORA_SUBSTR("a"."年月", 1, 6)) AS "b" ON "b"."年月" = ORA_SUBSTR("a"."作業日期", 1, 6) WHERE ORA_SUBSTR("a"."作業日期", 1, 6) > '2025' GROUP BY ORA_SUBSTR("a"."作業日期", 1, 6));

-- Home #2253 ViewFILM101.材料庫存異動明細
CREATE OR REPLACE VIEW "viewfilm101" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動日期", "a"."年月", "a"."料號", "a"."最後更新日", COALESCE("a"."異動數", 0) AS "異動數", COALESCE("a"."異動單價", 0) AS "異動單價", COALESCE("a"."異動金額", 0) AS "異動金額", "a"."來源", "a"."製程代碼" FROM (SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."異動日期", ORA_SUBSTR("a"."異動日期", 1, 6) AS "年月", "a"."產品編號" AS "料號", "a"."最後更新日", "a"."贈品數量" AS "異動數", "a"."異動單價" AS "異動單價", "a"."異動金額" AS "異動金額", '1.期初庫存' AS "來源", "a"."單據類別" AS "製程代碼" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'F35' AND "a"."異動日期" > '2025' UNION ALL /* 進貨發票 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "b"."單據日期", ORA_SUBSTR("b"."單據日期", 1, 6) AS "年月", "a"."產品編號" AS "料號", "a"."最後更新日", "a"."數值4" AS "異動數", "a"."異動單價" AS "異動單價", "a"."異動金額" AS "異動金額", '2.本期進貨' AS "來源", "a"."單據類別" AS "製程代碼" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" LEFT JOIN "viewofobjproperties" AS "c" ON "c"."單據流水號" = "b"."流水編號" WHERE "a"."單據類別" = 'D21' AND "b"."單據日期" > '2025' AND "a"."異動類別" = ' ' AND COALESCE("c"."簽核狀態", ' ') <> 'A' UNION ALL /* 退貨 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "b"."單據日期", ORA_SUBSTR("b"."單據日期", 1, 6) AS "年月", "a"."產品編號" AS "料號", "a"."最後更新日", ("a"."數值4") * -1 AS "異動數", ("a"."異動單價") * -1 AS "異動單價", ("a"."異動金額") * -1 AS "異動金額", '2.本期進貨' AS "來源", "a"."單據類別" AS "製程代碼" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" LEFT JOIN "viewofobjproperties" AS "c" ON "c"."單據流水號" = "b"."流水編號" WHERE "a"."單據類別" = 'D41' AND "b"."單據日期" > '2025' AND "a"."異動類別" = 'S' AND COALESCE("c"."簽核狀態", ' ') <> 'A' UNION ALL /* 日報領料 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "b"."單據日期", ORA_SUBSTR("b"."單據日期", 1, 6) AS "年月", CAST("a"."前製程編號" AS TEXT) AS "料號", "a"."最後更新日", ("a"."異動數量" - "a"."退庫數量") * -1 AS "異動數", COALESCE("e"."平均單價", 0) AS "異動單價", (("a"."異動數量" - "a"."退庫數量") * -1) * COALESCE("e"."平均單價", 0) AS "異動金額", '4.領料' AS "來源", "d"."製程代碼" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN "viewfilm104" AS "e" ON "e"."年月" = ORA_SUBSTR("b"."單據日期", 1, 6) AND "e"."料號" = "a"."前製程編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動數量" > 0 AND (("d"."製程代碼" BETWEEN 'C31A' AND 'C31C') OR "d"."製程代碼" = 'C32D' OR "d"."製程代碼" = 'C31H' OR "d"."製程代碼" = 'C31K') AND "b"."單據日期" > '2025' AND "c"."文數字4" <> ' ' /* 期初庫存 */ UNION ALL /* 製袋裁切領料 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."單據日期", ORA_SUBSTR("a"."單據日期", 1, 6) AS "年月", "f"."料號", "a"."最後更新日", "a"."異動數" * -1 AS "異動數", COALESCE("e"."平均單價", 0) AS "異動單價", ("a"."異動數" * -1 * COALESCE("e"."平均單價", 0)) AS "異動金額", '4.領料' AS "來源", "d"."製程代碼" FROM "viewfilm018a" AS "a" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "a"."批號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" LEFT JOIN "viewfilm104" AS "e" ON "e"."年月" = ORA_SUBSTR("a"."單據日期", 1, 6) AND "e"."料號" = "f"."料號" WHERE "a"."單據日期" > '2025') AS "a" INNER JOIN "viewfil1012" AS "e" ON "a"."料號" = "e"."產品編號");

-- Home #2257 ViewFILM105.材料製程領用月彙總
CREATE OR REPLACE VIEW "viewfilm105" AS (SELECT "a"."年月", "a"."製程代碼", SUM("a"."異動金額") AS "直接材料" FROM "viewfilm101" AS "a" WHERE "a"."來源" = '4.領料' GROUP BY "a"."年月", "a"."製程代碼");

-- Home #2258 ViewFILM106.材料單別領用彙總
CREATE OR REPLACE VIEW "viewfilm106" AS (SELECT "a"."單別" AS "單別", "a"."單號" AS "單號", SUM("a"."異動金額") AS "直接材料" FROM "viewfilm101" AS "a" WHERE "a"."來源" = '4.領料' GROUP BY "a"."單別", "a"."單號");

-- Home #2259 ViewFILM111.客供品庫存異動明細
CREATE OR REPLACE VIEW "viewfilm111" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動日期", "a"."年月", "a"."料號", "a"."最後更新日", COALESCE("a"."異動數", 0) AS "異動數", COALESCE("a"."異動單價", 0) AS "異動單價", COALESCE("a"."異動金額", 0) AS "異動金額", "a"."來源" FROM (SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."異動日期", ORA_SUBSTR("a"."異動日期", 1, 6) AS "年月", "a"."產品編號" AS "料號", "a"."最後更新日", "a"."贈品數量" AS "異動數", "a"."異動單價" AS "異動單價", "a"."異動金額" AS "異動金額", '1.期初庫存' AS "來源" FROM "fil0040" AS "a" INNER JOIN "viewfil1012" AS "e" ON "a"."產品編號" = "e"."產品編號" WHERE "a"."單據類別" = 'F35' AND "e"."物料大類" = 'C10' UNION ALL /* 客供品條碼入庫 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "b"."單據日期", ORA_SUBSTR("b"."單據日期", 1, 6) AS "年月", "a"."產品編號" AS "料號", "a"."最後更新日", ("a"."數值4") AS "異動數", ("a"."異動單價") AS "異動單價", ("a"."異動金額") AS "異動金額", '2.本期進貨' AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" INNER JOIN "viewfil1012" AS "e" ON "a"."產品編號" = "e"."產品編號" WHERE "a"."單據類別" = 'D51' AND "a"."異動類別" = ' ' AND "e"."物料大類" = 'C10' UNION ALL /* 退貨 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "b"."單據日期", ORA_SUBSTR("b"."單據日期", 1, 6) AS "年月", "a"."產品編號" AS "料號", "a"."最後更新日", ("a"."數值4") * -1 AS "異動數", ("a"."異動單價") * -1 AS "異動單價", ("a"."異動金額") * -1 AS "異動金額", '2.本期進貨' AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" INNER JOIN "viewfil1012" AS "e" ON "a"."產品編號" = "e"."產品編號" WHERE "a"."單據類別" = 'D52' AND "a"."異動類別" = 'S' AND "e"."物料大類" = 'C10' UNION ALL /* 領料 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "b"."單據日期", ORA_SUBSTR("b"."單據日期", 1, 6) AS "年月", "a"."產品編號" AS "料號", "a"."最後更新日", ("a"."異動數量" - "a"."退庫數量") * -1 AS "異動數", 0 AS "異動單價", 0 AS "異動金額", '4.領料' FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "viewfil1012" AS "e" ON "a"."產品編號" = "e"."產品編號" WHERE "a"."領料註記" = 1 AND "c"."文數字4" <> ' ' AND "e"."物料大類" = 'C10' /* 期初庫存 */ UNION ALL /* 製袋裁切領料 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."單據日期", ORA_SUBSTR("a"."單據日期", 1, 6) AS "年月", "f"."料號", "a"."最後更新日", "a"."異動數" * -1 AS "異動數", 0 AS "異動單價", 0 AS "異動金額", '4.領料' FROM "viewfilm018a" AS "a" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "a"."批號" INNER JOIN "viewfil1012" AS "e" ON "f"."料號" = "e"."產品編號" WHERE "e"."物料大類" = 'C10') AS "a" INNER JOIN "viewfil4a4l" AS "b" ON "b"."產品編號" = "a"."料號" INNER JOIN "viewfil1012" AS "e" ON "a"."料號" = "e"."產品編號");

-- Home #2265 ViewFILM204.製程人工時費用
CREATE OR REPLACE VIEW "viewfilm204" AS WITH "temp1" AS (SELECT "m"."製程代碼", "m"."年月", CASE WHEN COALESCE("a"."製程日報人工時", 0) = 0 THEN 0 ELSE CAST(COALESCE("c"."分攤直接人工", 0) AS DOUBLE PRECISION) / COALESCE("a"."製程日報人工時", 0) END AS "製程直接人工每人工時", CASE WHEN COALESCE("a"."製程日報人工時", 0) = 0 THEN 0 ELSE CAST((CASE WHEN COALESCE("b"."日報總人工時", 0) = 0 THEN 0 ELSE CAST(COALESCE("b"."分攤間接人工", 0) * COALESCE("a"."製程日報人工時", 0) AS DOUBLE PRECISION) / COALESCE("b"."日報總人工時", 0) END) AS DOUBLE PRECISION) / COALESCE("a"."製程日報人工時", 0) END AS "製程製造費用每人工時" FROM "fil1051" AS "m" /* 製程人工時月彙總 */ LEFT JOIN "viewfilm021a" AS "a" ON "m"."年月" = "a"."年月" AND "m"."製程代碼" = "a"."製程代碼" /* 人工時月彙總 */ LEFT JOIN "viewfilm022a" AS "b" ON "b"."年月" = "m"."年月" /* 製程實際直接人工 */ LEFT JOIN "viewfilm202" AS "c" ON "c"."年月" = "m"."年月" AND "c"."製程代碼" = "m"."製程代碼") SELECT * FROM "temp1";

-- Home #2320 ViewFILR010D.品質異常單明細
CREATE OR REPLACE VIEW "viewfilr010d" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動類別" AS "加工別", "a"."前置單別" AS "製令單別", "a"."前置單號" AS "製令單號", "b"."產品編號", "b"."產品名稱", "a"."備註說明" AS "材質結構", COALESCE("d"."規格", ' ') AS "成品規格", "a"."異動數量" AS "生產總量", "a"."贈品數量" AS "異常數量", "a"."單位代碼", COALESCE("f1"."名稱", ' ') AS "單位名稱", "a"."相關代碼1" AS "異常單位代碼", COALESCE("f2"."名稱", ' ') AS "異常單位名稱", "a"."異動日期" AS "交貨日期", "c"."廠客編號" AS "客戶編號", "a"."數值1" AS "特採數量", "a"."數值2" AS "報廢數量", "a"."logical1" AS "全批", "a"."logical2" AS "生產中", "a"."logical3" AS "異常數量待確認", "a"."logical4" AS "特採數量待確認", "a"."logical5" AS "報廢數量待確認", "a"."領料註記" AS "尚未生產", "a"."預交日" AS "建檔日期", "a"."time1" AS "建檔時間", "a"."流水編號", "m"."流水編號" AS "主檔流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "m" ON "m"."單據類別" = "a"."單據類別" AND "m"."單據編號" = "a"."單據編號" INNER JOIN "fil0032" AS "b" ON "a"."前置單別" = "b"."製令單別" AND "a"."前置單號" = "b"."製令單號" INNER JOIN "fil0030" AS "c" ON "a"."前置單別" = "c"."單據類別" AND "a"."前置單號" = "c"."單據編號" LEFT JOIN "viewfil1012" AS "d" ON REGEXP_SUBSTR("b"."產品編號", '[^/]+', 1, 1) = "d"."產品編號" LEFT JOIN "viewfil3103" AS "f1" ON "a"."單位代碼" = "f1"."代碼" LEFT JOIN "viewfil3103" AS "f2" ON "a"."相關代碼1" = "f2"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."單據類別" = 'R02');

-- Home #2327 ViewFILR020.銷退處理記錄表.R03
CREATE OR REPLACE VIEW "viewfilr020" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期", "a"."廠客編號" AS "客戶編號", COALESCE("g"."全名", ' ') AS "客戶名稱", "a"."公司代碼", COALESCE("z3"."全名", ' ') AS "公司名稱", "a"."簽核系統", COALESCE("z3_2"."簽核狀態", '0') AS "簽核狀態", "a"."簽核系統_結案", "b"."退貨日期", "b"."退貨方式", CASE WHEN "b"."退貨方式" = 'A' THEN '新竹貨運' WHEN "b"."退貨方式" = 'B' THEN '大榮貨運' WHEN "b"."退貨方式" = 'C' THEN '宅配公司' WHEN "b"."退貨方式" = 'D' THEN '司機' WHEN "b"."退貨方式" = 'E' THEN '業務' ELSE '其它' END AS "退貨方式名稱", "b"."退貨件數", "b"."退貨方式說明", "b"."退貨原因", "b"."處理數量_入庫", "b"."處理數量_銷毀", "b"."處理數量_其他", "b"."後續處理", COALESCE("z4"."員工姓名", ' ') AS "品管課負責人姓名", "a"."流水編號", COALESCE("z1"."serial_num", ' ') AS "員工流水編號", COALESCE("z1"."部門編號", ' ') AS "填表人部門編號", "a"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "a"."填表日", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0030" AS "a" INNER JOIN "fil003m1" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0011" AS "g" ON "a"."廠客編號" = "g"."編號" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewfil0011" AS "z3" ON "a"."公司代碼" = "z3"."代碼" LEFT JOIN "fil0010" AS "z4" ON "b"."品管課負責人" = "z4"."員工編號" LEFT JOIN "viewofobjproperties" AS "z3_2" ON "a"."流水編號" = "z3_2"."單據流水號" WHERE "a"."單據類別" = 'R03');

-- Home #2330 ViewFILR030.特採申請單.R04
CREATE OR REPLACE VIEW "viewfilr030" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據日期", "a"."歸屬類別" AS "異常單別", "a"."歸屬編號" AS "異常單號", "a"."歸屬序號" AS "異常明細序號", "a"."廠客編號" AS "廠商編號", COALESCE("g"."全名", ' ') AS "廠商名稱", "a"."公司代碼", COALESCE("z3"."全名", ' ') AS "公司名稱", "a"."簽核系統", COALESCE("z3_2"."簽核狀態", '0') AS "簽核狀態", "a"."簽核系統_結案", "b"."特採類別", "b"."進料批號", "b"."進料數量", "b"."進料單位", COALESCE("c"."名稱", ' ') AS "進料單位名稱", "b"."進料日期", "b"."原物料名稱", "d"."前置單別" AS "製令單別", "d"."前置單號" AS "製令單號", "e"."廠客編號" AS "客戶編號", COALESCE("f"."全名", ' ') AS "客戶名稱", "d"."異動數量" AS "生產數量", "b"."製造日期", "h"."異常單位" AS "責任單位", COALESCE("i"."部門名稱", ' ') AS "責任單位名稱", "b"."作業人員", "b"."作業人員姓名", "b"."特採日期", "b"."特採數量", "b"."特採單位", COALESCE("c1"."名稱", ' ') AS "特採單位名稱", "h"."異常現象_詳述" AS "不良原因", "a"."流水編號", COALESCE("z1"."serial_num", ' ') AS "員工流水編號", COALESCE("z1"."部門編號", ' ') AS "填表人部門編號", "a"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "a"."填表日", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0030" AS "a" INNER JOIN "fil003n1" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "viewfil3103" AS "c" ON "b"."進料單位" = "c"."代碼" LEFT JOIN "viewfil3103" AS "c1" ON "b"."特採單位" = "c1"."代碼" /* 異常明細 */ LEFT JOIN "fil0040" AS "d" ON "a"."歸屬類別" = "d"."單據類別" AND "a"."歸屬編號" = "d"."單據編號" AND "a"."歸屬序號" = "d"."單據序號" /* 異常表頭 */ LEFT JOIN "fil0030" AS "e" ON "a"."歸屬類別" = "e"."單據類別" AND "a"."歸屬編號" = "e"."單據編號" /* 異常單客戶 */ LEFT JOIN "fil0011" AS "f" ON "e"."廠客編號" = "f"."編號" /* 特採單廠商 */ LEFT JOIN "fil0011" AS "g" ON "a"."廠客編號" = "g"."編號" /* 異常單 */ LEFT JOIN "fil003l1" AS "h" ON "a"."歸屬類別" = "h"."單別" AND "a"."歸屬編號" = "h"."單號" /* 異常單位 */ LEFT JOIN "fil0020" AS "i" ON "h"."異常單位" = "i"."部門編號" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewfil0011" AS "z3" ON "a"."公司代碼" = "z3"."代碼" LEFT JOIN "viewofobjproperties" AS "z3_2" ON "a"."流水編號" = "z3_2"."單據流水號" WHERE "a"."單據類別" = 'R04');

-- Home #2325 ViewFILR220.品質異常單主檔.R22
CREATE OR REPLACE VIEW "viewfilr220" AS (SELECT "m"."單據類別" AS "單別", "m"."單據編號" AS "單號", "a"."單據日期", "a"."廠客編號" AS "客戶編號", COALESCE("g"."全名", ' ') AS "客戶名稱", "a"."歸屬類別" AS "客訴單別", "a"."歸屬編號" AS "客訴單號", "a"."公司代碼", COALESCE("z3"."全名", ' ') AS "公司名稱", "a"."簽核系統", COALESCE("z4"."簽核狀態", '0') AS "簽核狀態", "a"."簽核系統_結案", "b"."異常大類", COALESCE("c"."名稱", ' ') AS "異常大類名稱", "b"."異常原因分類", COALESCE("d"."名稱", ' ') AS "異常原因分類名稱", "b"."異常單位", COALESCE("e"."部門名稱", ' ') AS "異常單位名稱", "b"."異常現象_作業者", "b"."異常現象_作業者姓名", "b"."異常現象_摘要", "b"."異常現象_詳述", "b"."異常現象_填表人", "b"."矯正措施_填表人", COALESCE("z5_2"."serial_num", ' ') AS "指定簽核人員", COALESCE("f"."員工姓名", ' ') AS "異常現象_填表人姓名", "m"."流水編號", "m"."填表人", COALESCE("z1"."serial_num", ' ') AS "員工流水編號", COALESCE("z1"."部門編號", ' ') AS "填表人部門編號", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "m"."填表日", "m"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "m"."最後更新日" FROM "fil0030" AS "m" INNER JOIN "fil0030" AS "a" ON "a"."流水編號" = CONCAT('R02', ORA_SUBSTR("m"."流水編號", 4, 60)) INNER JOIN "fil003l1" AS "b" ON "b"."單別" = 'R02' AND "a"."單據編號" = "b"."單號" INNER JOIN "viewofobjproperties" AS "z5" ON "z5"."單據流水號" = CONCAT('R21', ORA_SUBSTR("m"."流水編號", 4, 60)) AND "z5"."簽核狀態" = 'E' LEFT JOIN "viewfil3114" AS "c" ON "b"."異常大類" = "c"."代碼" LEFT JOIN "viewfil3115" AS "d" ON "b"."異常原因分類" = "d"."代碼" LEFT JOIN "fil0020" AS "e" ON "b"."異常單位" = "e"."部門編號" LEFT JOIN "fil0010" AS "f" ON "b"."異常現象_填表人" = "f"."員工編號" LEFT JOIN "fil0011" AS "g" ON "a"."廠客編號" = "g"."編號" LEFT JOIN "fil0010" AS "z1" ON "m"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "m"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewfil0011" AS "z3" ON "a"."公司代碼" = "z3"."代碼" LEFT JOIN "viewofobjproperties" AS "z4" ON "m"."流水編號" = "z4"."單據流水號" LEFT JOIN "fil0010" AS "z5_2" ON "b"."矯正措施_填表人" = "z5_2"."員工編號" WHERE "m"."單據類別" = 'R22');

-- Home #1763 ViewFIL1024.條碼管理檔
CREATE OR REPLACE VIEW "viewfil1024" AS (SELECT "a"."條碼", "a"."單別", "a"."單號", "a"."序號", "a"."qrno", "a"."廠客", COALESCE("k"."全名", ' ') AS "全名", "a"."日期", "a"."料號", COALESCE(CASE WHEN COALESCE("j"."手動品名", ' ') = ' ' THEN "g"."品名" ELSE "j"."手動品名" END, ' ') AS "品名", COALESCE(CASE WHEN COALESCE("j"."手動規格", ' ') = ' ' THEN "g"."規格" ELSE "j"."手動規格" END, ' ') AS "規格", "a"."幅寬", "a"."接頭數", "a"."數量", "a"."單位", "a"."公司代碼", COALESCE("h"."全名", ' ') AS "公司名稱", CONCAT(TRIM("a"."單別"), '-', TRIM("a"."單號"), '-', TRIM(TO_CHAR("a"."序號", '0000'))) AS "採購單號", CASE WHEN "a"."單別" = 'C41' THEN CONCAT(TRIM("a"."單別"), '-', TRIM("a"."單號"), '-', TRIM(TO_CHAR("a"."序號", '0000'))) ELSE CASE WHEN COALESCE("b"."單別", ' ') = ' ' THEN ' ' ELSE CONCAT(COALESCE("b"."單別", ' '), '-', TRIM(COALESCE("b"."單號", ' ')), '-', TRIM(TO_CHAR(COALESCE("b"."序號", 0), '0000'))) END END AS "進料單號", CASE WHEN "a"."單別" = 'C41' THEN COALESCE("i"."倉庫代碼", ' ') ELSE COALESCE("b"."倉庫代碼", ' ') END AS "庫別", COALESCE("f"."名稱", ' ') AS "庫別名稱", CASE WHEN "a"."單別" = 'C41' THEN 1 ELSE CASE WHEN "b"."單號" IS NULL THEN 0 ELSE 1 END END AS "入料", "a"."驗收倉", 'C11' AS "製令單別", ORA_SUBSTR("a"."條碼", 1, POSITION('_' IN "a"."條碼") - 1) AS "製令單號", "a"."廠商批號", "a"."廠商規格", "a"."庫存異動數", CASE WHEN POSITION('_' IN "a"."條碼") = 0 THEN 0 ELSE 1 END AS "類別", CASE WHEN "a"."製造日期" = '00000000' THEN "a"."日期" ELSE "a"."製造日期" END AS "製造日期", "a"."批次匯入", "a"."guid" AS "臨時編號", ORA_SUBSTR("a"."guid", 1, POSITION('_' IN "a"."guid") - 1) AS "總批號", "a"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "a"."填表日", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0043" AS "a" /* 主檔 */ INNER JOIN "fil0030" AS "d" ON CASE WHEN "a"."單別" = 'Q01' THEN ORA_SUBSTR("a"."條碼", 1, 3) ELSE "a"."單別" END = "d"."單據類別" AND "a"."單號" = "d"."單據編號" /* 進料明細 */ LEFT JOIN "viewfil4a21" AS "b" ON "a"."條碼" = "b"."批號" AND "b"."單別" = 'D21' AND "b"."簽核狀態" <> 'A' /* 採購明細 */ LEFT JOIN "fil0040" AS "i" ON "a"."單別" = "i"."單據類別" AND "a"."單號" = "i"."單據編號" AND "a"."序號" = "i"."單據序號" LEFT JOIN "fil0041" AS "j" ON "a"."單別" = "j"."單別" AND "a"."單號" = "j"."單號" AND "a"."序號" = "j"."序號" LEFT JOIN "fil0011" AS "k" ON "a"."廠客" = "k"."編號" LEFT JOIN "viewfil3106" AS "f" ON CASE WHEN "a"."單別" = 'C41' THEN "i"."倉庫代碼" ELSE "b"."倉庫代碼" END = "f"."代碼" LEFT JOIN "fil0012" AS "g" ON "a"."料號" = "g"."產品編號" LEFT JOIN "viewfil0011" AS "h" ON "a"."公司代碼" = "h"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號");

-- Home #1767 ViewFIL1024D.條碼簡檔
CREATE OR REPLACE VIEW "viewfil1024d" AS (SELECT "a"."條碼", "a"."廠客", COALESCE("k"."全名", ' ') AS "廠客全名", "a"."日期", "a"."料號", COALESCE(CASE WHEN "j"."手動品名" = ' ' THEN "g"."品名" ELSE "j"."手動品名" END, ' ') AS "品名", COALESCE(CASE WHEN "j"."手動規格" = ' ' THEN "g"."規格" ELSE "j"."手動規格" END, ' ') AS "規格", "a"."單位", "a"."廠商批號", "a"."廠商規格", CONCAT("a"."料號", '^', REGEXP_SUBSTR("a"."條碼", '[^^]+', 1, 2)) AS "轉換後條碼", CASE WHEN "a"."製造日期" = '00000000' THEN "a"."日期" ELSE "a"."製造日期" END AS "製造日期", "a"."驗收倉", "a"."庫存異動數", "a"."單別", "a"."單號", "a"."序號", 'C11' AS "製令單別", ORA_SUBSTR("a"."條碼", 1, POSITION('_' IN "a"."條碼") - 1) AS "製令單號", CONCAT(TRIM("a"."單別"), '-', TRIM("a"."單號"), '-', TRIM(TO_CHAR("a"."序號", '0000'))) AS "採購單號", CASE WHEN "a"."單別" = 'C41' THEN CONCAT(TRIM("a"."單別"), '-', TRIM("a"."單號"), '-', TRIM(TO_CHAR("a"."序號", '0000'))) ELSE CASE WHEN COALESCE("b"."單別", ' ') = ' ' THEN ' ' ELSE CONCAT(COALESCE("b"."單別", ' '), '-', TRIM(COALESCE("b"."單號", ' ')), '-', TRIM(TO_CHAR(COALESCE("b"."序號", 0), '0000'))) END END AS "進料單號", "a"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "a"."填表日" FROM "fil0043" AS "a" /* 進料明細 */ LEFT JOIN "viewfil4a21" AS "b" ON "a"."條碼" = "b"."批號" AND "b"."單別" = 'D21' AND "b"."簽核狀態" <> 'A' LEFT JOIN "fil0012" AS "g" ON "a"."料號" = "g"."產品編號" LEFT JOIN "fil0041" AS "j" ON "a"."單別" = "j"."單別" AND "a"."單號" = "j"."單號" AND "a"."序號" = "j"."序號" LEFT JOIN "fil0011" AS "k" ON "a"."廠客" = "k"."編號" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號");

-- Home #1774 ViewFIL1024K.條碼收料數量
CREATE OR REPLACE VIEW "viewfil1024k" AS (SELECT "a"."條碼", "a"."單別", "a"."單號", "a"."序號", "a"."料號", "b"."數量", "b"."庫存異動數" FROM "fil0043" AS "a" /* 進料明細 */ INNER JOIN "viewfil4a21" AS "b" ON "a"."條碼" = "b"."批號" AND "b"."單別" = 'D21' AND "b"."簽核狀態" <> 'A' WHERE "a"."條碼" <> ' ');

-- Home #1788 ViewFIL2022.材料異動數
CREATE OR REPLACE VIEW "viewfil2022" AS WITH "temp1" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", CASE WHEN "a"."異動日期" = '00000000' THEN "d"."單據日期" ELSE "a"."異動日期" END AS "異動日期", CASE WHEN "a"."單據類別" = 'D21' THEN "a"."數值4" ELSE "a"."異動數量" END AS "異動數量", "a"."贈品數量", "a"."產品編號" AS "材料編號", "a"."單位代碼", COALESCE("c"."單位代碼", ' ') AS "庫存單位", "a"."倉庫代碼", "b"."材料庫存參數" AS "庫存參數", 1 AS "換算率", CASE WHEN "a"."單據類別" = 'D21' THEN "a"."數值4" ELSE ("a"."異動數量" + "a"."贈品數量") * "b"."材料庫存參數" END AS "異動數", COALESCE("a"."前置單別", ' ') AS "前置單別", COALESCE("a"."前置單號", ' ') AS "前置單號", COALESCE("f"."批號", ' ') AS "批號", REGEXP_SUBSTR(COALESCE("f"."批號", ' '), '[^-]+', 1, 1) AS "採購單別", REGEXP_SUBSTR(COALESCE("f"."批號", ' '), '[^-]+', 1, 2) AS "採購單號", TO_NUMBER(REGEXP_SUBSTR(COALESCE("f"."批號", ' '), '[^-]+', 1, 3), '9999') AS "採購序號", CAST("a"."備註說明" AS TEXT) AS "備註說明", COALESCE("g"."廠商批號", ' ') AS "廠商批號" FROM "fil0040" AS "a" /* 庫存參數 */ INNER JOIN "viewfil0020" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "b"."材料庫存參數" <> 0 /* 主檔 */ INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" /* 品號檔 */ INNER JOIN "viewfil1012" AS "c" ON "a"."產品編號" = "c"."產品編號" AND "c"."產品類別" BETWEEN 'M' AND 'P' /* 單位換算
	LEFT JOIN ViewFIL1017 E ON A.單位代碼 = E.從 AND C.單位代碼 = E.到
	*/ /* 特殊欄位 */ LEFT JOIN "fil0041" AS "f" ON "a"."單據類別" = "f"."單別" AND "a"."單據編號" = "f"."單號" AND "a"."單據序號" = "f"."序號" /* 廠商批號 */ LEFT JOIN "fil0043" AS "g" ON COALESCE("f"."批號", ' ') = "g"."條碼" /* 簽核 */ LEFT JOIN "viewofobjproperties" AS "h" ON "h"."單據流水號" = "d"."流水編號" WHERE "a"."產品編號" <> ' ' AND ("a"."單據類別" = 'D21' AND "a"."異動類別" = 'A' OR "a"."單據類別" <> 'D21') AND COALESCE("h"."簽核狀態", ' ') <> 'A' UNION ALL SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" + 5000 AS "序號", "a"."異動日期", "a"."異動數量", 0 AS "贈品數量", "a"."產品編號" AS "材料編號", "a"."單位代碼", COALESCE("g"."單位代碼", ' ') AS "庫存單位", "f"."庫位代碼" AS "倉庫代碼", 1 AS "庫存參數", 1 AS "換算率", "a"."異動數量" AS "異動數", COALESCE("e"."歸屬類別", ' ') AS "前置單別", COALESCE("e"."歸屬編號", ' ') AS "前置單號", COALESCE("c"."批號", ' ') AS "批號", REGEXP_SUBSTR("c"."批號", '[^-]+', 1, 1) AS "採購單別", REGEXP_SUBSTR("c"."批號", '[^-]+', 1, 2) AS "採購單號", TO_NUMBER(REGEXP_SUBSTR("c"."批號", '[^-]+', 1, 3), '9999') AS "採購序號", CAST("a"."備註說明" AS TEXT) AS "備註說明", COALESCE("g_2"."廠商批號", ' ') AS "廠商批號" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" INNER JOIN "fil0030" AS "e" ON "a"."單據類別" = "e"."單據類別" AND "a"."單據編號" = "e"."單據編號" LEFT JOIN "viewfil310p" AS "f" ON "d"."機台代碼" = "f"."代碼" LEFT JOIN "viewfil1012" AS "g" ON "a"."產品編號" = "g"."產品編號" /* 單位換算
