	*/ /* 廠商批號 */ LEFT JOIN "fil0043" AS "g" ON "b"."批號" = "g"."條碼" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" BETWEEN 'C' AND 'E' AND "a"."異動數量" <> 0 AND "a"."產品編號" <> ' ' UNION ALL SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動日期", "a"."異動數量", 0 AS "贈品數量", CAST("a"."前製程編號" AS TEXT) AS "材料編號", "a"."單位代碼", COALESCE("d"."單位代碼", ' ') AS "庫存單位", "a"."倉庫代碼", -1 AS "庫存參數", 1 AS "換算率", ("a"."異動數量" - "a"."退庫數量") * -1 AS "異動數", COALESCE("c1"."歸屬類別", ' ') AS "前置單別", COALESCE("c1"."歸屬編號", ' ') AS "前置單號", CAST("b"."文數字4" AS TEXT) AS "批號", REGEXP_SUBSTR(CAST("b"."文數字4" AS TEXT), '[^-]+', 1, 1) AS "採購單別", REGEXP_SUBSTR(CAST("b"."文數字4" AS TEXT), '[^-]+', 1, 2) AS "採購單號", TO_NUMBER(REGEXP_SUBSTR(CAST("b"."文數字4" AS TEXT), '[^-]+', 1, 3), '9999') AS "採購序號", CAST('印刷領用' AS TEXT) AS "備註說明", COALESCE("g"."廠商批號", ' ') AS "廠商批號" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "c1" ON "a"."單據類別" = "c1"."單據類別" AND "a"."單據編號" = "c1"."單據編號" INNER JOIN "viewfil1012" AS "d" ON CAST("a"."前製程編號" AS TEXT) = "d"."產品編號" /* 單位換算
