-- Home #1789 ViewFIL2022A.材料異動數(填表)
CREATE OR REPLACE VIEW "viewfil2022a" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動日期", CASE WHEN "a"."單據類別" = 'D21' THEN "a"."數值4" ELSE ("a"."異動數量" + "a"."贈品數量") * "b"."材料庫存參數" END AS "異動數量", "a"."產品編號" AS "材料編號", TO_CHAR("a"."最後更新日", 'YYYYMMDDHH24MISS') AS "更新日時" FROM "fil0040" AS "a" /* 庫存參數 */ INNER JOIN "viewfil0020" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "b"."材料庫存參數" <> 0 /* 主檔 */ INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" /* 品號檔 */ INNER JOIN "fil0012" AS "c" ON "a"."產品編號" = "c"."產品編號" AND "c"."產品類別" BETWEEN 'M' AND 'P' WHERE "a"."產品編號" <> ' ' AND ("a"."單據類別" = 'D21' AND "a"."異動類別" = 'A' OR "a"."單據類別" <> 'D21') UNION ALL /* 領料 */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" + 5000 AS "序號", "a"."異動日期", "a"."異動數量", "a"."產品編號" AS "材料編號", TO_CHAR("a"."最後更新日", 'YYYYMMDDHH24MISS') AS "更新日時" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" INNER JOIN "fil0030" AS "e" ON "a"."單據類別" = "e"."單據類別" AND "a"."單據編號" = "e"."單據編號" WHERE "a"."單據類別" = 'C4M' AND "a"."產品編號" <> ' ' UNION ALL /* 材料領用,報廢,油墨領用 */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動日期", "a"."異動數量" * -1 AS "異動數量", "a"."產品編號" AS "材料編號", TO_CHAR("a"."最後更新日", 'YYYYMMDDHH24MISS') AS "更新日時" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "c1" ON "a"."單據類別" = "c1"."單據類別" AND "a"."單據編號" = "c1"."單據編號" INNER JOIN "fil0012" AS "d" ON "a"."產品編號" = "d"."產品編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" BETWEEN 'C' AND 'E' AND "a"."異動數量" <> 0 AND "a"."產品編號" <> ' ' UNION ALL /* 材料領用.氣閥.鐵條-批號1 */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動日期", "b"."數值1" * -1 AS "異動數量", "d"."料號" AS "材料編號", TO_CHAR("a"."最後更新日", 'YYYYMMDDHH24MISS') AS "更新日時" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "c1" ON "a"."單據類別" = "c1"."單據類別" AND "a"."單據編號" = "c1"."單據編號" INNER JOIN "viewfil1024" AS "d" ON "b"."文數字1" = "d"."條碼" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "b"."文數字1" <> ' ' AND "d"."料號" <> ' ' UNION ALL /* 材料領用.氣閥.鐵條-批號2 */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" + 9000 AS "序號", "a"."異動日期", "b"."數值2" * -1 AS "異動數量", "d"."料號" AS "材料編號", TO_CHAR("a"."最後更新日", 'YYYYMMDDHH24MISS') AS "更新日時" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "c1" ON "a"."單據類別" = "c1"."單據類別" AND "a"."單據編號" = "c1"."單據編號" INNER JOIN "viewfil1024" AS "d" ON "b"."文數字2" = "d"."條碼" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "b"."文數字2" <> ' ' AND "d"."料號" <> ' ' UNION ALL /* 發料回庫(-)
SELECT 
	A.單據類別 單別, 
	A.單據編號 單號,
	A.單據序號 + 5100 序號,
	A.異動日期,
	A.贈品數量*-1 異動數量,
	A.產品編號 材料編號,
	TO_CHAR(A.最後更新日,'YYYYMMDDHH24MISS') 更新日時
FROM 
	FIL0040 A
	INNER JOIN FIL0041 B ON A.單據類別 = B.單別 AND A.單據編號 = B.單號 AND A.單據序號 = B.序號
	INNER JOIN FIL0030 C1 ON A.單據類別 = C1.單據類別 AND A.單據編號 = C1.單據編號
WHERE
	A.單據類別 = 'C41' AND
	A.異動類別 = 'C' AND
	A.贈品數量 != 0 AND
	A.產品編號 != ' '

UNION ALL
*/ /* 發料回庫(+) */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" + 5200 AS "序號", "a"."異動日期", "a"."贈品數量" AS "異動數量", "a"."產品編號" AS "材料編號", TO_CHAR("a"."最後更新日", 'YYYYMMDDHH24MISS') AS "更新日時" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0030" AS "c1" ON "a"."單據類別" = "c1"."單據類別" AND "a"."單據編號" = "c1"."單據編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'C' AND "a"."贈品數量" <> 0 AND "a"."產品編號" <> ' ' /* 廠內盤點調整 */ UNION ALL SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動日期", ("a"."異動數量" + "a"."贈品數量") AS "異動數量", "a"."產品編號" AS "材料編號", TO_CHAR("a"."最後更新日", 'YYYYMMDDHH24MISS') AS "更新日時" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'F32' AND "a"."異動類別" = '2');

-- Home #1790 ViewFIL2022C.紙箱異動數
CREATE OR REPLACE VIEW "viewfil2022c" AS WITH "temp1" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", CASE WHEN "a"."異動日期" = '00000000' THEN "d"."單據日期" ELSE "a"."異動日期" END AS "異動日期", CASE WHEN "a"."單據類別" = 'D21' THEN "a"."數值4" ELSE "a"."異動數量" END AS "異動數量", "a"."贈品數量", "a"."產品編號" AS "材料編號", "a"."單位代碼", COALESCE("c"."單位代碼", ' ') AS "庫存單位", "a"."倉庫代碼", "b"."材料庫存參數" AS "庫存參數", 1 AS "換算率", CASE WHEN "a"."單據類別" = 'D21' THEN "a"."數值4" ELSE ("a"."異動數量" + "a"."贈品數量") * "b"."材料庫存參數" END AS "異動數", COALESCE("a"."前置單別", ' ') AS "前置單別", COALESCE("a"."前置單號", ' ') AS "前置單號", COALESCE("f"."批號", ' ') AS "批號", REGEXP_SUBSTR(COALESCE("f"."批號", ' '), '[^-]+', 1, 1) AS "採購單別", REGEXP_SUBSTR(COALESCE("f"."批號", ' '), '[^-]+', 1, 2) AS "採購單號", TO_NUMBER(REGEXP_SUBSTR(COALESCE("f"."批號", ' '), '[^-]+', 1, 3), '9999') AS "採購序號", CAST("a"."備註說明" AS TEXT) AS "備註說明", COALESCE("g"."廠商批號", ' ') AS "廠商批號" FROM "fil0040" AS "a" /* 庫存參數 */ INNER JOIN "viewfil0020" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "b"."材料庫存參數" <> 0 /* 主檔 */ INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" /* 品號檔 */ INNER JOIN "viewfil1012" AS "c" ON "a"."產品編號" = "c"."產品編號" AND "c"."物料大類" BETWEEN 'B10' AND 'B20' /* 單位換算
	LEFT JOIN ViewFIL1017 E ON A.單位代碼 = E.從 AND C.單位代碼 = E.到
	*/ /* 特殊欄位 */ LEFT JOIN "fil0041" AS "f" ON "a"."單據類別" = "f"."單別" AND "a"."單據編號" = "f"."單號" AND "a"."單據序號" = "f"."序號" /* 廠商批號 */ LEFT JOIN "fil0043" AS "g" ON COALESCE("f"."批號", ' ') = "g"."條碼" /* 簽核 */ LEFT JOIN "viewofobjproperties" AS "h" ON "h"."單據流水號" = "d"."流水編號" WHERE "a"."產品編號" <> ' ' AND ("a"."單據類別" = 'D21' AND "a"."異動類別" = 'A' OR "a"."單據類別" <> 'D21') AND COALESCE("h"."簽核狀態", ' ') <> 'A' UNION ALL SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" + 5000 AS "序號", "a"."異動日期", "a"."異動數量", 0 AS "贈品數量", "a"."產品編號" AS "材料編號", "a"."單位代碼", COALESCE("g"."單位代碼", ' ') AS "庫存單位", "f"."庫位代碼" AS "倉庫代碼", 1 AS "庫存參數", 1 AS "換算率", "a"."異動數量" AS "異動數", COALESCE("e"."歸屬類別", ' ') AS "前置單別", COALESCE("e"."歸屬編號", ' ') AS "前置單號", COALESCE("c"."批號", ' ') AS "批號", REGEXP_SUBSTR("c"."批號", '[^-]+', 1, 1) AS "採購單別", REGEXP_SUBSTR("c"."批號", '[^-]+', 1, 2) AS "採購單號", TO_NUMBER(REGEXP_SUBSTR("c"."批號", '[^-]+', 1, 3), '9999') AS "採購序號", CAST("a"."備註說明" AS TEXT) AS "備註說明", COALESCE("g_2"."廠商批號", ' ') AS "廠商批號" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" INNER JOIN "fil0030" AS "e" ON "a"."單據類別" = "e"."單據類別" AND "a"."單據編號" = "e"."單據編號" LEFT JOIN "viewfil310p" AS "f" ON "d"."機台代碼" = "f"."代碼" INNER JOIN "viewfil1012" AS "g" ON "a"."產品編號" = "g"."產品編號" AND "g"."物料大類" BETWEEN 'B10' AND 'B20' /* 單位換算
	LEFT JOIN ViewFIL1017 H ON A.單位代碼 = H.從 AND G.單位代碼 = H.到
	*/ /* 廠商批號 */ LEFT JOIN "fil0043" AS "g_2" ON "c"."批號" = "g_2"."條碼" WHERE "a"."單據類別" = 'C4M' AND "a"."產品編號" <> ' ' UNION ALL SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動日期", "a"."異動數量", 0 AS "贈品數量", "a"."產品編號" AS "材料編號", "a"."單位代碼", COALESCE("d"."單位代碼", ' ') AS "庫存單位", "a"."倉庫代碼", -1 AS "庫存參數", 1 AS "換算率", "a"."異動數量" * -1 AS "異動數", COALESCE("c1"."歸屬類別", ' ') AS "前置單別", COALESCE("c1"."歸屬編號", ' ') AS "前置單號", COALESCE("b"."批號", ' ') AS "批號", REGEXP_SUBSTR("b"."批號", '[^-]+', 1, 1) AS "採購單別", REGEXP_SUBSTR("b"."批號", '[^-]+', 1, 2) AS "採購單號", TO_NUMBER(REGEXP_SUBSTR("b"."批號", '[^-]+', 1, 3), '9999') AS "採購序號", CAST(CASE WHEN "a"."異動類別" = 'C' THEN '領用' WHEN "a"."異動類別" = 'D' THEN '報廢' WHEN "a"."異動類別" = 'E' THEN '油墨領用' ELSE ' ' END AS TEXT) AS "備註說明", COALESCE("g"."廠商批號", ' ') AS "廠商批號" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "c1" ON "a"."單據類別" = "c1"."單據類別" AND "a"."單據編號" = "c1"."單據編號" INNER JOIN "viewfil1012" AS "d" ON "a"."產品編號" = "d"."產品編號" AND "d"."物料大類" BETWEEN 'B10' AND 'B20' /* 單位換算
	LEFT JOIN ViewFIL1017 E ON A.單位代碼 = E.從 AND D.單位代碼 = E.到
	*/ /* 廠商批號 */ LEFT JOIN "fil0043" AS "g" ON "b"."批號" = "g"."條碼" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" BETWEEN 'C' AND 'E' AND "a"."異動數量" <> 0 AND "a"."產品編號" <> ' ' UNION ALL SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動日期", "a"."異動數量", 0 AS "贈品數量", CAST("a"."前製程編號" AS TEXT) AS "材料編號", "a"."單位代碼", COALESCE("d"."單位代碼", ' ') AS "庫存單位", "a"."倉庫代碼", -1 AS "庫存參數", 1 AS "換算率", ("a"."異動數量" - "a"."退庫數量") * -1 AS "異動數", COALESCE("c1"."歸屬類別", ' ') AS "前置單別", COALESCE("c1"."歸屬編號", ' ') AS "前置單號", CAST("b"."文數字4" AS TEXT) AS "批號", REGEXP_SUBSTR(CAST("b"."文數字4" AS TEXT), '[^-]+', 1, 1) AS "採購單別", REGEXP_SUBSTR(CAST("b"."文數字4" AS TEXT), '[^-]+', 1, 2) AS "採購單號", TO_NUMBER(REGEXP_SUBSTR(CAST("b"."文數字4" AS TEXT), '[^-]+', 1, 3), '9999') AS "採購序號", CAST('印刷領用' AS TEXT) AS "備註說明", COALESCE("g"."廠商批號", ' ') AS "廠商批號" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "c1" ON "a"."單據類別" = "c1"."單據類別" AND "a"."單據編號" = "c1"."單據編號" INNER JOIN "viewfil1012" AS "d" ON CAST("a"."前製程編號" AS TEXT) = "d"."產品編號" AND "d"."物料大類" BETWEEN 'B10' AND 'B20' /* 單位換算
	LEFT JOIN ViewFIL1017 E ON A.單位代碼 = E.從 AND D.單位代碼 = E.到
