ND "c1"."歸屬編號" = "c2"."製令單號" LEFT JOIN "viewfil3103" AS "d" ON "a"."單位代碼" = "d"."代碼" LEFT JOIN "viewfil3106" AS "e" ON "a"."倉庫代碼" = "e"."代碼" LEFT JOIN "viewfil1024" AS "f" ON "b"."批號" = "f"."條碼" LEFT JOIN "fil0012" AS "g" ON "f"."料號" = "g"."產品編號" LEFT JOIN "fil0012" AS "g1" ON "c2"."加工項目_氣閥代碼" = "g1"."產品編號" LEFT JOIN "fil0012" AS "g2" ON "c2"."加工項目_鐵條代碼" = "g2"."產品編號" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" = 'C31E');

-- Home #1961 ViewFIL404F3.氣閥袋重明細
CREATE OR REPLACE VIEW "viewfil404f3" AS (SELECT "c"."歸屬類別" AS "製令單別", "c"."歸屬編號" AS "製令單號", "a"."異動數量" AS "箱號", "a"."贈品數量" AS "繳庫袋數", "b"."數值1" * COALESCE(CAST("e"."單價下限率" AS DOUBLE PRECISION) / 1000, 0) + "b"."數值2" * COALESCE(CAST("g"."單價下限率" AS DOUBLE PRECISION) / 1000, 0) AS "重量", CASE WHEN "a"."贈品數量" = 0 THEN 0 ELSE CAST(("b"."數值1" * COALESCE(CAST("e"."單價下限率" AS DOUBLE PRECISION) / 1000, 0) + "b"."數值2" * COALESCE(CAST("g"."單價下限率" AS DOUBLE PRECISION) / 1000, 0)) AS DOUBLE PRECISION) / "a"."贈品數量" END AS "每袋重量" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" INNER JOIN "fil0031" AS "c1" ON "a"."單據類別" = "c1"."單別" AND "a"."單據編號" = "c1"."單號" LEFT JOIN "viewfil1024" AS "d" ON "b"."文數字1" = "d"."條碼" LEFT JOIN "fil0012" AS "e" ON "d"."料號" = "e"."產品編號" LEFT JOIN "viewfil1024" AS "f" ON "b"."文數字2" = "f"."條碼" LEFT JOIN "fil0012" AS "g" ON "f"."料號" = "g"."產品編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c1"."製程代碼" = 'C31F');

-- Home #1969 ViewFIL404G3.鐵條袋重明細
CREATE OR REPLACE VIEW "viewfil404g3" AS (SELECT "c"."歸屬類別" AS "製令單別", "c"."歸屬編號" AS "製令單號", "a"."異動數量" AS "箱號", SUM("a"."贈品數量") AS "繳庫袋數", SUM("b"."數值1" * COALESCE(CAST("e"."單價下限率" AS DOUBLE PRECISION) / 1000, 0) + "b"."數值2" * COALESCE(CAST("g"."單價下限率" AS DOUBLE PRECISION) / 1000, 0)) AS "重量", CASE WHEN SUM("a"."贈品數量") = 0 THEN 0 ELSE CAST(SUM("b"."數值1" * COALESCE(CAST("e"."單價下限率" AS DOUBLE PRECISION) / 1000, 0) + "b"."數值2" * COALESCE(CAST("g"."單價下限率" AS DOUBLE PRECISION) / 1000, 0)) AS DOUBLE PRECISION) / SUM("a"."贈品數量") END AS "每袋重量" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" INNER JOIN "fil0031" AS "c1" ON "a"."單據類別" = "c1"."單別" AND "a"."單據編號" = "c1"."單號" LEFT JOIN "viewfil1024" AS "d" ON "b"."文數字1" = "d"."條碼" LEFT JOIN "fil0012" AS "e" ON "d"."料號" = "e"."產品編號" LEFT JOIN "viewfil1024" AS "f" ON "b"."文數字2" = "f"."條碼" LEFT JOIN "fil0012" AS "g" ON "f"."料號" = "g"."產品編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c1"."製程代碼" = 'C31G' GROUP BY "c"."歸屬類別", "c"."歸屬編號", "a"."異動數量");

-- Home #2157 ViewFIL4A1D.採購廠商出貨明細
CREATE OR REPLACE VIEW "viewfil4a1d" AS (SELECT "a"."單別", "a"."單號", "a"."序號", "a"."細分", "a"."數字一" AS "出貨支數", "a"."數字二" AS "庫存異動數", "a"."數字三" AS "單價", "a"."數字四" AS "採購數量", CONCAT(TO_CHAR("a"."數字五", '99999.9'), CASE WHEN "a"."文字四" = ' ' THEN "b"."相關代碼1" ELSE "a"."文字四" END) AS "廠商規格", "a"."日期一" AS "製作日期", "a"."日期二" AS "截止日期", "a"."日期三" AS "廠商預交日期", "a"."文字一" AS "製造批號", "a"."文字二" AS "廠商料號", "a"."文字三" AS "廠商發票", "a"."文字五" AS "喜美批號", "a"."邏輯一" AS "平台上傳", "a"."備註", CASE WHEN "a"."文字三" = ' ' THEN 0 ELSE 1 END AS "已開發票", CASE WHEN COALESCE("c"."條碼", ' ') = ' ' THEN 0 ELSE 1 END AS "喜美收貨", "a"."文字六" AS "建檔人員", CASE WHEN "a"."文字七" = ' ' THEN CASE WHEN "a"."文字四" = 'M' THEN '支' WHEN "a"."文字四" = 'MB' THEN '米/箱' ELSE '桶' END ELSE "a"."文字七" END AS "出貨支數單位", "a"."運送方式" AS "運送方式代碼", "d"."名稱" AS "運送方式" FROM "fil00401" AS "a" INNER JOIN "fil0040" AS "b" ON "a"."單別" = "b"."單據類別" AND "a"."單號" = "b"."單據編號" AND "a"."序號" = "b"."單據序號" LEFT JOIN "viewfil1024" AS "c" ON "a"."文字五" = "c"."條碼" LEFT JOIN "viewfil3111" AS "d" ON "d"."代碼" = "a"."運送方式" LEFT JOIN "viewofobjproperties" AS "z3" ON "b"."流水編號" = "z3"."單據流水號" WHERE "a"."單別" = 'D11' AND COALESCE("z3"."簽核狀態", '0') <> 'A');

-- Home #2165 ViewFIL4A2B.採購進料數
CREATE OR REPLACE VIEW "viewfil4a2b" AS (SELECT COALESCE("a"."單別", "b"."單別") AS "單別", COALESCE("a"."單號", "b"."單號") AS "單號", COALESCE("a"."序號", "b"."序號") AS "序號", COALESCE("a"."料號", "b"."料號") AS "料號", COALESCE("a"."採購數量", 0) AS "採購數量", COALESCE("a"."庫存異動數", 0) AS "採購數量_庫存單位", COALESCE(GREATEST(COALESCE("c"."收料數量", 0), COALESCE("b"."進料數量", 0)), 0) AS "進料數量", COALESCE(GREATEST(COALESCE("c"."庫存異動數", 0), COALESCE("b"."庫存異動數", 0)), 0) AS "進料數量_庫存單位", COALESCE("c"."收料數量", 0) AS "收料數量", COALESCE("c"."庫存異動數", 0) AS "收料數量_庫存單位", COALESCE("a"."採購數量", 0) - GREATEST(COALESCE("c"."收料數量", 0), COALESCE("b"."進料數量", 0)) AS "未進料數", COALESCE("a"."庫存異動數", 0) - GREATEST(COALESCE("c"."庫存異動數", 0), COALESCE("b"."庫存異動數", 0)) AS "未進料數_庫存單位", GREATEST(COALESCE("c"."庫存異動數", 0) - COALESCE("b"."庫存異動數", 0), 0) AS "收料未入庫數_庫存單位", COALESCE("a"."採購金額", 0) AS "採購金額", COALESCE("b"."進料金額", 0) AS "進料金額", CASE WHEN COALESCE("a"."採購數量", 0) - GREATEST(COALESCE("c"."收料數量", 0), COALESCE("b"."進料數量", 0)) > 0 THEN 0 ELSE 1 END AS "結案否" FROM (/* 採購單 */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."產品編號" AS "料號", SUM("a"."異動數量") AS "採購數量", SUM("a"."異動金額") AS "採購金額", SUM("a"."數值4") AS "庫存異動數" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'D11' OR "a"."單據類別" = 'D51' GROUP BY "a"."單據類別", "a"."單據編號", "a"."產品編號", "a"."單據序號") AS "a" FULL OUTER JOIN (/* 進料 */ SELECT "a"."採購單別" AS "單別", "a"."採購單號" AS "單號", "a"."採購序號" AS "序號", "a"."料號", SUM("a"."數量") AS "進料數量", SUM("a"."總價") AS "進料金額", SUM("a"."庫存異動數") AS "庫存異動數" FROM "viewfil4a21" AS "a" WHERE "a"."簽核狀態" <> 'A' GROUP BY "a"."採購單別", "a"."採購單號", "a"."採購序號", "a"."料號") AS "b" ON "a"."單別" = "b"."單別" AND "a"."單號" = "b"."單號" AND "a"."序號" = "b"."序號" FULL OUTER JOIN (/* 收料 */ SELECT "a"."單別", "a"."單號", "a"."序號", "a"."料號", SUM("a"."數量") AS "收料數量", SUM("a"."庫存異動數") AS "庫存異動數" FROM "viewfil1024k" AS "a" WHERE "a"."單別" = 'D11' OR "a"."單別" = 'D51' GROUP BY "a"."單別", "a"."單號", "a"."序號", "a"."料號") AS "c" ON "a"."單別" = "c"."單別" AND "a"."單號" = "c"."單號" AND "a"."序號" = "c"."序號");

-- Home #2173 ViewFIL4A4B.採購進退驗數
CREATE OR REPLACE VIEW "viewfil4a4b" AS WITH "tmp1" AS (SELECT "a"."單別", "a"."單號", "a"."料號", "a"."採購數量", "a"."進料數量", "a"."未進料數", "a"."採購數量_庫存單位", "a"."進料數量_庫存單位", "a"."未進料數_庫存單位", "a"."採購金額", "a"."進料金額" FROM "viewfil4a2b" AS "a"), "tmp2" AS (SELECT "c"."歸屬類別" AS "單別", "c"."歸屬編號" AS "單號", "a"."產品編號" AS "料號", SUM("a"."異動數量") AS "退料數量" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" INNER JOIN "fil0030" AS "c" ON "b"."歸屬類別" = "c"."單據類別" AND "b"."歸屬編號" = "c"."單據編號" WHERE "a"."單據類別" = 'D41' OR "a"."單據類別" = 'D52' GROUP BY "c"."歸屬類別", "c"."歸屬編號", "a"."產品編號"), "tmp3" AS (SELECT "c"."歸屬類別" AS "單別", "c"."歸屬編號" AS "單號", "a"."產品編號" AS "料號", SUM("a"."異動數量") AS "檢驗數量" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" INNER JOIN "fil0030" AS "c" ON "b"."歸屬類別" = "c"."單據類別" AND "b"."歸屬編號" = "c"."單據編號" WHERE "a"."單據類別" = 'D31' GROUP BY "c"."歸屬類別", "c"."歸屬編號", "a"."產品編號") SELECT "a"."單別", "a"."單號", "a"."料號", COALESCE("a"."採購數量", 0) AS "採購數量", COALESCE("a"."進料數量", 0) AS "進料數量", COALESCE("a"."未進料數", 0) AS "未進料數", COALESCE("a"."採購數量_庫存單位", 0) AS "採購數量_庫存單位", COALESCE("a"."進料數量_庫存單位", 0) AS "進料數量_庫存單位", COALESCE("a"."未進料數_庫存單位", 0) AS "未進料數_庫存單位", COALESCE("a"."採購金額", 0) AS "採購金額", COALESCE("a"."進料金額", 0) AS "進料金額", COALESCE("b"."退料數量", 0) AS "退料數量", COALESCE("c"."檢驗數量", 0) AS "檢驗數量" FROM "tmp1" AS "a" LEFT JOIN "tmp2" AS "b" ON "a"."單別" = "b"."單別" AND "a"."單號" = "b"."單號" AND "a"."料號" = "b"."料號" LEFT JOIN "tmp3" AS "c" ON "a"."單別" = "c"."單別" AND "a"."單號" = "c"."單號" AND "a"."料號" = "c"."料號";

-- Home #2176 ViewFIL4A4E.批號異動數
CREATE OR REPLACE VIEW "viewfil4a4e" AS (SELECT "材料編號" AS "料號", "批號", SUM("異動數") AS "數量" FROM "viewfil2022" GROUP BY "材料編號", "批號");

-- Home #2092 ViewFILE03D.成品平均重量
CREATE OR REPLACE VIEW "viewfile03d" AS (SELECT CASE WHEN COALESCE("a"."平均袋重", 0) = 0 THEN CAST('C11' AS TEXT) ELSE "a"."製令單別" END AS "製令單別", CASE WHEN COALESCE("a"."平均袋重", 0) = 0 THEN "d"."製令單號" ELSE "a"."製令單號" END AS "製令單號", CASE WHEN COALESCE("a"."平均袋重", 0) = 0 THEN "d"."箱號" ELSE "a"."箱號" END AS "箱號", CASE WHEN COALESCE("a"."平均袋重", 0) = 0 THEN COALESCE("d"."平均袋重", 0) ELSE "a"."平均袋重" + COALESCE("b"."每袋重量", 0) + COALESCE("c"."每袋重量", 0) END AS "每袋重量" FROM "viewfil404e7" AS "a" LEFT JOIN "viewfil404f3" AS "b" ON "a"."製令單別" = "b"."製令單別" AND "a"."製令單號" = "b"."製令單號" AND "a"."箱號" = "b"."箱號" LEFT JOIN "viewfil404g3" AS "c" ON "a"."製令單別" = "c"."製令單別" AND "a"."製令單號" = "c"."製令單號" AND "a"."箱號" = "c"."箱號" FULL OUTER JOIN "viewfile03c" AS "d" ON "a"."製令單號" = "d"."製令單號" AND "a"."箱號" = "d"."箱號" AND COALESCE("d"."平均袋重", 0) <> 0);

-- Home #2115 ViewFILF031.庫存盤點明細
CREATE OR REPLACE VIEW "viewfilf031" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."產品編號" AS "料號", COALESCE("e"."品名", ' ') AS "品名", COALESCE("e"."規格", ' ') AS "規格", "a"."異動類別", CASE WHEN "a"."異動類別" = '1' THEN '半成品' ELSE '材料' END AS "異動說明", "a"."異動日期", COALESCE("f"."製造日期", ' ') AS "製造日期", "a"."異動數量" AS "箱號", COALESCE("a"."贈品數量", 0) AS "數量", "a"."毛重" AS "重量", "a"."數值1" AS "箱數", "c"."批號", "a"."廠客品號" AS "製令單號", COALESCE("a"."異動單價", 0) AS "庫存數", COALESCE("a"."贈品數量", 0) - COALESCE("a"."異動單價", 0) AS "差異數", COALESCE("a"."異動金額", 0) AS "委外庫存數", "a"."logical1" AS "已盤", "a"."備註說明", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", COALESCE("z2"."廠商批號", ' ') AS "廠商批號", "a"."最後更新日" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" /* 製造日期 */ LEFT JOIN "viewfil4036" AS "f" ON "a"."廠客品號" = "f"."製令單號" LEFT JOIN "fil0012" AS "e" ON "a"."產品編號" = "e"."產品編號" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" LEFT JOIN "viewfil1024" AS "z2" ON "z2"."單別" = 'E11' AND "c"."批號" = "z2"."條碼" WHERE "a"."單據類別" = 'F31');

-- Home #2119 ViewFILF041.盤點調整明細
CREATE OR REPLACE VIEW "viewfilf041" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."產品編號" AS "料號", COALESCE("e"."品名", ' ') AS "品名", COALESCE("e"."規格", ' ') AS "規格", "a"."異動類別", CASE WHEN "a"."異動類別" = '1' THEN '半成品' ELSE '材料' END AS "異動說明", "a"."異動日期", COALESCE("f"."製造日期", ' ') AS "製造日期", "a"."異動數量" AS "箱號", "a"."贈品數量" AS "調整數量", "a"."毛重" AS "重量", "a"."數值1" AS "箱數", "c"."批號", COALESCE("z2"."廠商批號", ' ') AS "廠商批號", "a"."廠客品號" AS "製令單號", "a"."異動單價" AS "庫存數", "a"."贈品數量" - "a"."異動單價" AS "差異數", "a"."logical1" AS "已盤", "a"."備註說明", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" /* 製造日期 */ LEFT JOIN "viewfil4036" AS "f" ON "a"."廠客品號" = "f"."製令單號" LEFT JOIN "fil0012" AS "e" ON "a"."產品編號" = "e"."產品編號" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" LEFT JOIN "viewfil1024" AS "z2" ON "z2"."單別" = 'E11' AND "c"."批號" = "z2"."條碼" WHERE "a"."單據類別" = 'F32');

-- Home #2128 ViewFILF062.期初庫存明細
CREATE OR REPLACE VIEW "viewfilf062" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."產品編號" AS "料號", COALESCE("e"."品名", ' ') AS "品名", COALESCE("e"."規格", ' ') AS "規格", "a"."異動類別", CASE WHEN "a"."異動類別" = '1' THEN '半成品' ELSE '材料' END AS "異動說明", "a"."異動日期", COALESCE("f"."製造日期", ' ') AS "製造日期", "a"."異動數量" AS "箱號", "a"."贈品數量" AS "調整數量", "a"."異動金額" AS "金額", "a"."毛重" AS "重量", "a"."數值1" AS "箱數", "c"."批號", COALESCE("z2"."廠商批號", ' ') AS "廠商批號", "a"."廠客品號" AS "製令單號", "a"."異動單價" AS "單價", 0 AS "差異數", "a"."logical1" AS "已盤", "a"."備註說明", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" /* 製造日期 */ LEFT JOIN "viewfil4036" AS "f" ON "a"."廠客品號" = "f"."製令單號" LEFT JOIN "fil0012" AS "e" ON "a"."產品編號" = "e"."產品編號" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" LEFT JOIN "viewfil1024" AS "z2" ON "z2"."單別" = 'E11' AND "c"."批號" = "z2"."條碼" WHERE "a"."單據類別" = 'F35');

-- Home #2132 ViewFILF0W3.委外原物料異動檔
