 BETWEEN 'C31F' AND 'C31G' AND "d"."料號" <> ' ' AND "a"."異動日期" >= "f"."日期" UNION ALL /* 材料耗用.氣閥.鐵條 */ /* 報廢 */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" + 9500 AS "序號", "a"."異動日期", "a"."產品編號" AS "料號", "a"."異動數量" AS "數量", "c"."製程代碼", "c"."工站代碼", "b"."批號", "a"."備註說明", 0 AS "箱數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "g" ON "a"."單據類別" = "g"."單據類別" AND "a"."單據編號" = "g"."單據編號" INNER JOIN "fil1014" AS "f" ON "f"."代碼類別" = '工站代碼' AND "c"."工站代碼" = "f"."系統代碼" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'D' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "a"."產品編號" <> ' ' AND "a"."異動日期" >= "f"."日期" UNION ALL SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動日期", "a"."產品編號" AS "料號", "a"."贈品數量" AS "數量", "b"."製程代碼", "b"."工站代碼", "c"."批號", "a"."備註說明", "a"."數值1" AS "箱數" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" /* 料號 */ INNER JOIN "fil0012" AS "e" ON "a"."產品編號" = "e"."產品編號" AND "e"."產品類別" BETWEEN 'M' AND 'P' /* 簽收 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0037" AS "d" ON "a"."單據類別" = "d"."製令單別" AND "a"."單據編號" = "d"."製令單號" AND "d"."材料序號" = 0 AND ((COALESCE("dbms_lob".getlength("d"."圖檔"), 0) > 0) OR "a"."單據類別" = 'F32') INNER JOIN "fil1014" AS "f" ON "f"."代碼類別" = '工站代碼' AND "b"."工站代碼" = "f"."系統代碼" WHERE "a"."單據類別" BETWEEN 'F11' AND 'F32' AND "a"."單據類別" <> 'F31' AND "a"."異動日期" >= "f"."日期") AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單別" = "b"."單據類別" AND "a"."單號" = "b"."單據編號" LEFT JOIN "viewofobjproperties" AS "d1" ON "b"."流水編號" = "d1"."單據流水號" /* 料號 */ INNER JOIN "fil0012" AS "e" ON "a"."料號" = "e"."產品編號" /* 工站 */ INNER JOIN "viewfil310o" AS "g" ON "a"."工站代碼" = "g"."代碼");

