-- Home #2134 ViewFILF0W3B.委外原物料異動檔
CREATE OR REPLACE VIEW "viewfilf0w3b" AS (SELECT "a"."單別", "a"."單號", "a"."序號", "a"."料號", "a"."批號", "a"."數量", "a"."製程代碼", "a"."工站代碼" FROM (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."產品編號" AS "料號", "c"."批號", "a"."贈品數量" AS "數量", "b"."製程代碼", "b"."工站代碼" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" /* 特殊欄位 */ INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" /* 料號 */ INNER JOIN "fil0012" AS "e" ON "a"."產品編號" = "e"."產品編號" AND "e"."產品類別" BETWEEN 'M' AND 'P' /* 簽收 */ INNER JOIN "fil0037" AS "f" ON "a"."單據類別" = "f"."製令單別" AND "a"."單據編號" = "f"."製令單號" AND "f"."材料序號" = 0 AND ((COALESCE("dbms_lob".getlength("f"."圖檔"), 0) > 0) OR "a"."單據類別" = 'F32') INNER JOIN "fil1014" AS "h" ON "h"."代碼類別" = '工站代碼' AND "b"."工站代碼" = "h"."系統代碼" WHERE "a"."單據類別" BETWEEN 'F11' AND 'F32' AND "a"."單據類別" <> 'F31' AND "a"."異動日期" >= "h"."日期" UNION ALL /* 材料耗用.氣閥.鐵條 */ /* 批號1 */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "d"."料號", "b"."文數字1" AS "批號", "b"."數值1" AS "數量", "c"."製程代碼", "c"."工站代碼" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "viewfil1024" AS "d" ON "b"."文數字1" = "d"."條碼" INNER JOIN "viewfil310p" AS "e" ON "c"."機台代碼" = "e"."代碼" AND "e"."委外" = 1 INNER JOIN "fil1014" AS "h" ON "h"."代碼類別" = '工站代碼' AND "c"."工站代碼" = "h"."系統代碼" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "d"."料號" <> ' ' AND "a"."異動日期" >= "h"."日期" UNION ALL /* 材料耗用.氣閥.鐵條 */ /* 批號2 */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" + 9000 AS "序號", "d"."料號", "b"."文數字2" AS "批號", "b"."數值2" AS "數量", "c"."製程代碼", "c"."工站代碼" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "viewfil1024" AS "d" ON "b"."文數字2" = "d"."條碼" INNER JOIN "viewfil310p" AS "e" ON "c"."機台代碼" = "e"."代碼" AND "e"."委外" = 1 INNER JOIN "fil1014" AS "h" ON "h"."代碼類別" = '工站代碼' AND "c"."工站代碼" = "h"."系統代碼" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "d"."料號" <> ' ' AND "a"."異動日期" >= "h"."日期" UNION ALL /* 材料耗用.氣閥.鐵條 */ /* 報廢 */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" + 9500 AS "序號", "a"."產品編號" AS "料號", "b"."批號", "a"."異動數量" AS "數量", "c"."製程代碼", "c"."工站代碼" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil1014" AS "h" ON "h"."代碼類別" = '工站代碼' AND "c"."工站代碼" = "h"."系統代碼" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'D' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "a"."產品編號" <> ' ' AND "a"."異動日期" >= "h"."日期") AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單別" = "b"."單據類別" AND "a"."單號" = "b"."單據編號" LEFT JOIN "viewofobjproperties" AS "d1" ON "b"."流水編號" = "d1"."單據流水號" INNER JOIN "viewfilf013" AS "f" ON "f"."批號" = "a"."批號" AND CASE WHEN "d1"."送簽日時" IS NULL THEN "b"."填表日" ELSE "d1"."送簽日時" END >= "f"."填表日");

-- Home #2135 ViewFILF0W3C.委外原物料批號檔
CREATE OR REPLACE VIEW "viewfilf0w3c" AS (SELECT DISTINCT "c"."批號", "a"."產品編號" AS "料號", "b"."製程代碼", "b"."工站代碼" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" /* 料號 */ INNER JOIN "fil0012" AS "e" ON "a"."產品編號" = "e"."產品編號" AND "e"."產品類別" BETWEEN 'M' AND 'P' INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" /* 簽收 */ INNER JOIN "fil0037" AS "f" ON "a"."單據類別" = "f"."製令單別" AND "a"."單據編號" = "f"."製令單號" AND "f"."材料序號" = 0 AND ((COALESCE("dbms_lob".getlength("f"."圖檔"), 0) > 0) OR "a"."單據類別" = 'F32') WHERE "a"."單據類別" BETWEEN 'F11' AND 'F32' AND "a"."單據類別" <> 'F31' UNION ALL SELECT DISTINCT "b"."文數字1" AS "批號", "d"."料號", "c"."製程代碼", "c"."工站代碼" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "viewfil1024" AS "d" ON "b"."文數字1" = "d"."條碼" INNER JOIN "viewfil310p" AS "e" ON "c"."機台代碼" = "e"."代碼" AND "e"."委外" = 1 WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "d"."料號" <> ' ' UNION ALL /* 材料耗用.氣閥.鐵條 */ /* 批號2 */ SELECT DISTINCT "b"."文數字2" AS "批號", "d"."料號", "c"."製程代碼", "c"."工站代碼" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "viewfil1024" AS "d" ON "b"."文數字2" = "d"."條碼" INNER JOIN "viewfil310p" AS "e" ON "c"."機台代碼" = "e"."代碼" AND "e"."委外" = 1 WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "d"."料號" <> ' ');

-- Home #2137 ViewFILF0W4.委外原物枓結存檔
CREATE OR REPLACE VIEW "viewfilf0w4" AS (SELECT "a"."料號", "a"."品名", "a"."規格", "a"."製程代碼", "a"."製程名稱", "a"."工站代碼", "a"."工站名稱", "a"."製程工站", SUM(CASE WHEN "a"."單別" = 'F11' THEN "a"."數量" ELSE 0 END) AS "加工數量", SUM(CASE WHEN "a"."單別" = 'F21' THEN "a"."數量" ELSE 0 END) AS "回廠數量", SUM(CASE WHEN "a"."單別" = 'C41' THEN "a"."數量" ELSE 0 END) AS "耗用數量", SUM(CASE WHEN "a"."單別" = 'F32' THEN "a"."數量" ELSE 0 END) AS "調整數量", SUM("a"."數量" * "a"."庫存參數") AS "結存數量" FROM "viewfilf0w3" AS "a" GROUP BY "a"."料號", "a"."品名", "a"."規格", "a"."製程代碼", "a"."製程名稱", "a"."工站代碼", "a"."工站名稱", "a"."製程工站");

-- Home #2138 ViewFILF0W4A.委外原物料結存檔
CREATE OR REPLACE VIEW "viewfilf0w4a" AS (SELECT "a"."料號", "e"."品名", "e"."規格", "a"."製程代碼", "g"."製程名稱", "a"."工站代碼", "g"."名稱" AS "工站名稱", "g"."製程工站", SUM(CASE WHEN "a"."單別" = 'F11' THEN "a"."數量" ELSE 0 END) AS "加工數量", SUM(CASE WHEN "a"."單別" = 'F21' THEN "a"."數量" ELSE 0 END) AS "回廠數量", SUM(CASE WHEN "a"."單別" = 'C41' THEN (CASE WHEN "a"."序號" <= 9500 THEN "a"."數量" ELSE 0 END) ELSE 0 END) AS "耗用數量", SUM(CASE WHEN "a"."單別" = 'C41' THEN (CASE WHEN "a"."序號" > 9500 THEN "a"."數量" ELSE 0 END) ELSE 0 END) AS "報廢數量", SUM(CASE WHEN "a"."單別" = 'F32' THEN "a"."數量" ELSE 0 END) AS "調整數量", SUM("a"."數量" * CASE WHEN "a"."單別" = 'F11' THEN 1 WHEN "a"."單別" = 'F21' THEN -1 WHEN "a"."單別" = 'F32' THEN 1 ELSE -1 END) AS "結存數量" FROM "viewfilf0w3a" AS "a" /* 料號 */ INNER JOIN "fil0012" AS "e" ON "a"."料號" = "e"."產品編號" /* 工站 */ INNER JOIN "viewfil310o" AS "g" ON "a"."工站代碼" = "g"."代碼" GROUP BY "a"."料號", "e"."品名", "e"."規格", "a"."製程代碼", "g"."製程名稱", "a"."工站代碼", "g"."名稱", "g"."製程工站");

-- Home #2139 ViewFILF0W4B.委外原物料結存檔
CREATE OR REPLACE VIEW "viewfilf0w4b" AS (SELECT "a"."料號", "a"."製程代碼", "a"."工站代碼", SUM("a"."加工數量") AS "加工數量", SUM("a"."回廠數量") AS "回廠數量", SUM("a"."耗用數量") AS "耗用數量", SUM("a"."報廢數量") AS "報廢數量", SUM("a"."調整數量") AS "調整數量", SUM("a"."結存數量") AS "結存數量" FROM (SELECT "a"."產品編號" AS "料號", "b"."製程代碼", "b"."工站代碼", SUM(CASE WHEN "a"."單據類別" = 'F11' THEN "a"."贈品數量" ELSE 0 END) AS "加工數量", SUM(CASE WHEN "a"."單據類別" = 'F21' THEN "a"."贈品數量" ELSE 0 END) AS "回廠數量", 0 AS "耗用數量", 0 AS "報廢數量", SUM(CASE WHEN "a"."單據類別" = 'F32' THEN "a"."贈品數量" ELSE 0 END) AS "調整數量", SUM("a"."贈品數量" * CASE WHEN "a"."單據類別" = 'F11' THEN 1 WHEN "a"."單據類別" = 'F21' THEN -1 WHEN "a"."單據類別" = 'F32' THEN 1 ELSE -1 END) AS "結存數量" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" LEFT JOIN "viewofobjproperties" AS "d1" ON "d"."流水編號" = "d1"."單據流水號" /* 料號 */ INNER JOIN "fil0012" AS "e" ON "a"."產品編號" = "e"."產品編號" AND "e"."產品類別" BETWEEN 'M' AND 'P' INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" /* 簽收 */ INNER JOIN "fil0037" AS "f" ON "a"."單據類別" = "f"."製令單別" AND "a"."單據編號" = "f"."製令單號" AND "f"."材料序號" = 0 AND ((COALESCE("dbms_lob".getlength("f"."圖檔"), 0) > 0) OR "a"."單據類別" = 'F32') /* 填單日 */ INNER JOIN "viewfilf013" AS "h" ON "h"."工站代碼" = "b"."工站代碼" AND "h"."批號" = "c"."批號" AND CASE WHEN "d1"."送簽日時" IS NULL THEN "d"."填表日" ELSE "d1"."送簽日時" END >= "h"."填表日" INNER JOIN "fil1014" AS "i" ON "i"."代碼類別" = '工站代碼' AND "b"."工站代碼" = "i"."系統代碼" WHERE "a"."單據類別" BETWEEN 'F11' AND 'F32' AND "a"."單據類別" <> 'F31' AND "a"."異動日期" >= "i"."日期" GROUP BY "a"."產品編號", "b"."製程代碼", "b"."工站代碼" UNION ALL /* 材料耗用.氣閥.鐵條 */ /* 批號1 */ SELECT "d"."料號", "c"."製程代碼", "c"."工站代碼", 0 AS "加工數量", 0 AS "回廠數量", SUM("b"."數值1") AS "耗用數量", 0 AS "報廢數量", 0 AS "調整數量", SUM("b"."數值1" * CASE WHEN "a"."單據類別" = 'F11' THEN 1 WHEN "a"."單據類別" = 'F21' THEN -1 WHEN "a"."單據類別" = 'F32' THEN 1 ELSE -1 END) AS "結存數量" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "g" ON "a"."單據類別" = "g"."單據類別" AND "a"."單據編號" = "g"."單據編號" INNER JOIN "viewfil1024" AS "d" ON "b"."文數字1" = "d"."條碼" /* 填單日 */ INNER JOIN "viewfilf013" AS "h" ON "h"."工站代碼" = "c"."工站代碼" AND "h"."批號" = "b"."文數字1" AND "g"."填表日" >= "h"."填表日" INNER JOIN "fil1014" AS "i" ON "i"."代碼類別" = '工站代碼' AND "c"."工站代碼" = "i"."系統代碼" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "d"."料號" <> ' ' AND "a"."異動日期" >= "i"."日期" GROUP BY "d"."料號", "c"."製程代碼", "c"."工站代碼" UNION ALL /* 材料耗用.氣閥.鐵條 */ /* 批號2 */ SELECT "d"."料號", "c"."製程代碼", "c"."工站代碼", 0 AS "加工數量", 0 AS "回廠數量", SUM("b"."數值2") AS "耗用數量", 0 AS "報廢數量", 0 AS "調整數量", SUM("b"."數值2" * CASE WHEN "a"."單據類別" = 'F11' THEN 1 WHEN "a"."單據類別" = 'F21' THEN -1 WHEN "a"."單據類別" = 'F32' THEN 1 ELSE -1 END) AS "結存數量" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "g" ON "a"."單據類別" = "g"."單據類別" AND "a"."單據編號" = "g"."單據編號" INNER JOIN "viewfil1024" AS "d" ON "b"."文數字2" = "d"."條碼" /* 填單日 */ INNER JOIN "viewfilf013" AS "h" ON "h"."工站代碼" = "c"."工站代碼" AND "h"."批號" = "b"."文數字2" AND "g"."填表日" >= "h"."填表日" INNER JOIN "fil1014" AS "i" ON "i"."代碼類別" = '工站代碼' AND "c"."工站代碼" = "i"."系統代碼" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "d"."料號" <> ' ' AND "a"."異動日期" >= "i"."日期" GROUP BY "d"."料號", "c"."製程代碼", "c"."工站代碼" UNION ALL /* 材料耗用.氣閥.鐵條 */ /* 報廢 */ SELECT "a"."產品編號" AS "料號", "c"."製程代碼", "c"."工站代碼", 0 AS "加工數量", 0 AS "回廠數量", 0 AS "耗用數量", SUM("a"."異動數量") AS "報廢數量", 0 AS "調整數量", SUM("a"."異動數量" * CASE WHEN "a"."單據類別" = 'F11' THEN 1 WHEN "a"."單據類別" = 'F21' THEN -1 WHEN "a"."單據類別" = 'F32' THEN 1 ELSE -1 END) AS "結存數量" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "g" ON "a"."單據類別" = "g"."單據類別" AND "a"."單據編號" = "g"."單據編號" LEFT JOIN "viewofobjproperties" AS "d1" ON "g"."流水編號" = "d1"."單據流水號" /* 填單日 */ INNER JOIN "viewfilf013" AS "h" ON "h"."工站代碼" = "c"."工站代碼" AND "h"."批號" = "b"."批號" AND CASE WHEN "d1"."送簽日時" IS NULL THEN "g"."填表日" ELSE "d1"."送簽日時" END >= "h"."填表日" INNER JOIN "fil1014" AS "i" ON "i"."代碼類別" = '工站代碼' AND "c"."工站代碼" = "i"."系統代碼" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'D' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "a"."產品編號" <> ' ' AND "a"."異動日期" >= "i"."日期" GROUP BY "a"."產品編號", "c"."製程代碼", "c"."工站代碼") AS "a" GROUP BY "a"."料號", "a"."製程代碼", "a"."工站代碼");

-- Home #2141 ViewFILF0W4B2.委外原物料結存檔
CREATE OR REPLACE VIEW "viewfilf0w4b_2" AS (/* 材料耗用.氣閥.鐵條 */ /* 批號1 */ SELECT "d"."料號", "c"."製程代碼", "c"."工站代碼", 0 AS "加工數量", 0 AS "回廠數量", SUM("b"."數值1") AS "耗用數量", 0 AS "報廢數量", 0 AS "調整數量", SUM("b"."數值1" * -1) AS "結存數量" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "g" ON "a"."單據類別" = "g"."單據類別" AND "a"."單據編號" = "g"."單據編號" INNER JOIN "viewfil1024" AS "d" ON "b"."文數字1" = "d"."條碼" /* 填單日 */ INNER JOIN "viewfilf013" AS "h" ON "h"."工站代碼" = "c"."工站代碼" AND "h"."批號" = "b"."文數字1" AND "g"."填表日" >= "h"."填表日" INNER JOIN "fil1014" AS "i" ON "i"."代碼類別" = '工站代碼' AND "c"."工站代碼" = "i"."系統代碼" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "b"."文數字1" <> ' ' AND "a"."異動日期" >= "i"."日期" GROUP BY "d"."料號", "c"."製程代碼", "c"."工站代碼");

-- Home #2142 ViewFILF0W4B3.委外原物料結存檔
CREATE OR REPLACE VIEW "viewfilf0w4b_3" AS (/* 材料耗用.氣閥.鐵條 */ /* 批號2 */ SELECT "d"."料號", "c"."製程代碼", "c"."工站代碼", 0 AS "加工數量", 0 AS "回廠數量", SUM("b"."數值2") AS "耗用數量", 0 AS "報廢數量", 0 AS "調整數量", SUM("b"."數值2" * -1) AS "結存數量" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "g" ON "a"."單據類別" = "g"."單據類別" AND "a"."單據編號" = "g"."單據編號" INNER JOIN "viewfil1024" AS "d" ON "b"."文數字2" = "d"."條碼" /* 填單日 */ INNER JOIN "viewfilf013" AS "h" ON "h"."工站代碼" = "c"."工站代碼" AND "h"."批號" = "b"."文數字2" AND "g"."填表日" >= "h"."填表日" INNER JOIN "fil1014" AS "i" ON "i"."代碼類別" = '工站代碼' AND "c"."工站代碼" = "i"."系統代碼" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "b"."文數字2" <> ' ' AND "a"."異動日期" >= "i"."日期" GROUP BY "d"."料號", "c"."製程代碼", "c"."工站代碼");

-- Home #2144 ViewFILF0W5.委外批號工站結存檔
CREATE OR REPLACE VIEW "viewfilf0w5" AS (SELECT COALESCE("a"."料號", ' ') AS "料號", COALESCE("a"."批號", ' ') AS "批號", "e"."品名", "e"."規格", COALESCE("a"."製程代碼", ' ') AS "製程代碼", "g"."製程名稱", COALESCE("a"."工站代碼", ' ') AS "工站代碼", "g"."名稱" AS "工站名稱", "g"."製程工站", SUM(CASE WHEN "a"."單別" = 'F11' THEN COALESCE("a"."數量", 0) ELSE 0 END) AS "加工數量", SUM(CASE WHEN "a"."單別" = 'F21' THEN COALESCE("a"."數量", 0) ELSE 0 END) AS "回廠數量", SUM(CASE WHEN "a"."單別" = 'C41' THEN (CASE WHEN "a"."序號" <= 9500 THEN "a"."數量" ELSE 0 END) ELSE 0 END) AS "耗用數量", SUM(CASE WHEN "a"."單別" = 'C41' THEN (CASE WHEN "a"."序號" > 9500 THEN "a"."數量" ELSE 0 END) ELSE 0 END) AS "報廢數量", SUM(CASE WHEN "a"."單別" = 'F32' THEN COALESCE("a"."數量", 0) ELSE 0 END) AS "調整數量", SUM("a"."數量" * CASE WHEN "a"."單別" = 'F11' THEN 1 WHEN "a"."單別" = 'F21' THEN -1 WHEN "a"."單別" = 'F32' THEN 1 ELSE -1 END) AS "結存數量" FROM "viewfilf0w3a" AS "a" /* 料號 */ INNER JOIN "fil0012" AS "e" ON "a"."料號" = "e"."產品編號" /* 工站 */ INNER JOIN "viewfil310o" AS "g" ON "a"."工站代碼" = "g"."代碼" GROUP BY "a"."料號", "a"."批號", "e"."品名", "e"."規格", "a"."製程代碼", "g"."製程名稱", "a"."工站代碼", "g"."名稱", "g"."製程工站");

-- Home #2145 ViewFILF0W5A.委外批號工站結存
CREATE OR REPLACE VIEW "viewfilf0w5a" AS (SELECT "a"."料號", "a"."批號", "e"."品名", "e"."規格", "a"."製程代碼", "g"."製程名稱", "a"."工站代碼", "g"."名稱" AS "工站名稱", "g"."製程工站", SUM(CASE WHEN "a"."單別" = 'F11' THEN COALESCE("a"."數量", 0) ELSE 0 END) AS "加工數量", SUM(CASE WHEN "a"."單別" = 'F21' THEN COALESCE("a"."數量", 0) ELSE 0 END) AS "回廠數量", SUM(CASE WHEN "a"."單別" = 'C41' THEN (CASE WHEN "a"."序號" <= 9500 THEN "a"."數量" ELSE 0 END) ELSE 0 END) AS "耗用數量", SUM(CASE WHEN "a"."單別" = 'C41' THEN (CASE WHEN "a"."序號" > 9500 THEN "a"."數量" ELSE 0 END) ELSE 0 END) AS "報廢數量", SUM(CASE WHEN "a"."單別" = 'F32' THEN COALESCE("a"."數量", 0) ELSE 0 END) AS "調整數量", SUM("a"."數量" * CASE WHEN "a"."單別" = 'F11' THEN 1 WHEN "a"."單別" = 'F21' THEN -1 WHEN "a"."單別" = 'F32' THEN 1 ELSE -1 END) AS "結存數量" FROM "viewfilf0w3b" AS "a" /* 料號 */ INNER JOIN "fil0012" AS "e" ON "a"."料號" = "e"."產品編號" /* 工站 */ INNER JOIN "viewfil310o" AS "g" ON "a"."工站代碼" = "g"."代碼" GROUP BY "a"."料號", "a"."批號", "e"."品名", "e"."規格", "a"."製程代碼", "g"."製程名稱", "a"."工站代碼", "g"."名稱", "g"."製程工站");

-- Home #2146 ViewFILF0W6.委外批號彙總結存檔
CREATE OR REPLACE VIEW "viewfilf0w6" AS (SELECT "a"."料號", "a"."批號", "a"."品名", "a"."規格", SUM(CASE WHEN "a"."單別" = 'F11' THEN "a"."數量" ELSE 0 END) AS "加工數量", SUM(CASE WHEN "a"."單別" = 'F21' THEN "a"."數量" ELSE 0 END) AS "回廠數量", SUM(CASE WHEN "a"."單別" = 'C41' THEN "a"."數量" ELSE 0 END) AS "耗用數量", SUM(CASE WHEN "a"."單別" = 'F32' THEN "a"."數量" ELSE 0 END) AS "調整數量", SUM("a"."數量" * "a"."庫存參數") AS "結存數量" FROM "viewfilf0w3" AS "a" GROUP BY "a"."料號", "a"."批號", "a"."品名", "a"."規格");

-- Home #2286 ViewFILH007.出缺勤日結.H04
CREATE OR REPLACE VIEW "viewfilh007" AS (SELECT "a"."員工編號", "b"."員工姓名", "b"."公司別", "b"."部門名稱", "b"."職位名稱", "b"."生產部門禁", "a"."出勤日期", (CASE WHEN COALESCE("f"."休假", 0) <= 1 AND COALESCE("e"."請假時數", 0) = 0 THEN "a"."遲到" ELSE 0 END) AS "遲到", (CASE WHEN COALESCE("f"."休假", 0) <= 1 AND COALESCE("e"."請假時數", 0) = 0 THEN "a"."早退" ELSE 0 END) AS "早退", "c"."假別", "a"."上班刷卡", "a"."下班刷卡", (CASE WHEN ("a"."班別" = '4' OR "a"."班別" = '5' OR "a"."班別" = '7') AND "a"."上班刷卡" <> '000000' AND "a"."下班刷卡" BETWEEN '013000' AND '032959' THEN 1 ELSE 0 END) AS "夜班", (CASE WHEN ("a"."班別" = '4' OR "a"."班別" = '5' OR "a"."班別" = '7') AND "a"."上班刷卡" <> '000000' AND "a"."下班刷卡" BETWEEN '033000' AND "a"."班別時間起" THEN 1 ELSE 0 END) AS "大夜", (CASE WHEN COALESCE("f"."休假", 0) <= 1 AND COALESCE("e"."請假時數", 0) <= 2 THEN CASE WHEN (TO_NUMBER("a"."上班刷卡", '999999') + TO_NUMBER("a"."下班刷卡", '999999')) = 0 THEN 0 ELSE 1 END WHEN COALESCE("f"."休假", 0) <= 1 AND COALESCE("e"."請假時數", 0) BETWEEN 2.01 AND 4 THEN CASE WHEN (TO_NUMBER("a"."上班刷卡", '999999') + TO_NUMBER("a"."下班刷卡", '999999')) = 0 THEN 0 ELSE 0.5 END ELSE 0 END) AS "平日打卡日", (CASE WHEN COALESCE("f"."休假", 0) > 1 AND "d"."加班時數" >= 6 THEN CASE WHEN (TO_NUMBER("a"."上班刷卡", '999999') + TO_NUMBER("a"."下班刷卡", '999999')) = 0 THEN 0 ELSE 1 END WHEN COALESCE("f"."休假", 0) > 1 AND "d"."加班時數" BETWEEN 4 AND 5.99 THEN CASE WHEN (TO_NUMBER("a"."上班刷卡", '999999') + TO_NUMBER("a"."下班刷卡", '999999')) = 0 THEN 0 ELSE 0.5 END ELSE 0 END) AS "假日打卡日", "a"."打卡日調整", CASE WHEN "a"."門禁計薪上班" = '000000' THEN "a"."門禁上班刷卡" ELSE "a"."門禁計薪上班" END AS "門禁上班刷卡", CASE WHEN "a"."門禁計薪下班" = '000000' THEN "a"."門禁下班刷卡" ELSE "a"."門禁計薪下班" END AS "門禁下班刷卡", "a"."修正午晚進" AS "門禁中午進", "a"."修正午晚出" AS "門禁中午出", "a"."門禁午休時間", "a"."班別", "a"."班別時間起", "a"."班別時間迄", COALESCE("d"."平日前2小時", 0) AS "平日前2小時", COALESCE("d"."平日前4小時", 0) AS "平日前4小時", COALESCE("d"."平日大於4小時", 0) AS "平日大於4小時", COALESCE("d"."休息日前2小時", 0) AS "休息日前2小時", COALESCE("d"."休息日前8小時", 0) AS "休息日前8小時", COALESCE("d"."休息日大於8小時", 0) AS "休息日大於8小時", COALESCE("d"."例假日前8小時", 0) AS "例假日前8小時", COALESCE("d"."例假日大於8小時", 0) AS "例假日大於8小時", COALESCE("d"."例假日大於10小時", 0) AS "例假日大於10小時", COALESCE("d"."例假日補休小時", 0) AS "例假日補休小時", COALESCE("d"."國定假日前8小時", 0) AS "國定假日前8小時", COALESCE("d"."國定假日大於8小時", 0) AS "國定假日大於8小時", COALESCE("d"."國定假日大於10小時", 0) AS "國定假日大於10小時", COALESCE("d"."調補時數", 0) AS "調補時數", "a"."已手動修正", "f"."休假" AS "星期代碼", "f"."說明" AS "星期說明", "f"."星期" AS "星期幾", "a"."流水編號", "a"."最後更新者", "a"."最後更新日" FROM "hrfil1007" AS "a" INNER JOIN "viewfil1010" AS "b" ON "b"."員工編號" = "a"."員工編號" AND "b"."國籍" <> '委外' LEFT JOIN (SELECT "a"."申請人", "m"."異動日期" AS "起始日期", "utl_raw".cast_to_nvarchar2(STRING_AGG(CAST(CONCAT("utl_raw".cast_to_raw(CONCAT("a"."假別名稱", ORA_SUBSTR("m"."time1", 1, 2), ':', ORA_SUBSTR("m"."time1", 3, 2), '[')), "utl_raw".cast_to_raw(TO_NCHAR(ROUND("m"."異動數量", 1), '90D9')), "utl_raw".cast_to_raw(N'小時]')) AS TEXT), "utl_raw".cast_to_raw(N' ') ORDER BY "a"."申請人")) AS "假別" FROM "fil0040" AS "m" INNER JOIN "viewfilh001" AS "a" ON "a"."單別" = "m"."單據類別" AND "a"."單號" = "m"."單據編號" WHERE "m"."單據類別" = 'H01' AND "a"."簽核狀態" = 'E' GROUP BY "a"."申請人", "m"."異動日期") AS "c" ON "c"."申請人" = "a"."員工編號" AND "a"."出勤日期" = "c"."起始日期" LEFT JOIN (SELECT "a"."申請人", "a"."加班日期" AS "加班日期", SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) <= 1 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" >= 2 THEN 2 ELSE "a"."小計" END) ELSE 0 END, 0)) AS "平日前2小時" /* 平日、補班 */, SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) <= 1 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 2 AND "a"."小計" < 4 THEN "a"."小計" - 2 WHEN "a"."小計" >= 4 THEN 2 ELSE 0 END) ELSE 0 END, 0)) AS "平日前4小時", SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) <= 1 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 4 THEN "a"."小計" - 4 ELSE 0 END) ELSE 0 END, 0)) AS "平日大於4小時", SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 2 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" >= 2 THEN 2 ELSE "a"."小計" END) ELSE 0 END, 0)) AS "休息日前2小時" /* 休息日 */, SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 2 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 2 AND "a"."小計" < 8 THEN "a"."小計" - 2 WHEN "a"."小計" >= 8 THEN 6 ELSE 0 END) ELSE 0 END, 0)) AS "休息日前8小時", SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 2 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 8 THEN "a"."小計" - 8 ELSE 0 END) ELSE 0 END, 0)) AS "休息日大於8小時", SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 3 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 0 THEN (CASE WHEN "a"."小計" > 8 THEN 8 ELSE "a"."小計" END) ELSE 0 END) ELSE 0 END, 0)) AS "例假日前8小時" /* 例假日 */, SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 3 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 8 AND "a"."小計" < 10 THEN "a"."小計" - 8 WHEN "a"."小計" >= 10 THEN 2 ELSE 0 END) ELSE 0 END, 0)) AS "例假日大於8小時", SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 3 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 10 THEN "a"."小計" - 10 ELSE 0 END) ELSE 0 END, 0)) AS "例假日大於10小時", SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 3 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 8 THEN 8 ELSE "a"."小計" END) ELSE 0 END, 0)) AS "例假日補休小時", SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 4 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 0 THEN (CASE WHEN "a"."小計" > 8 THEN 8 ELSE "a"."小計" END) ELSE 0 END) ELSE 0 END, 0)) AS "國定假日前8小時" /* 國定假日 */, SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 4 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 8 AND "a"."小計" < 10 THEN "a"."小計" - 8 WHEN "a"."小計" >= 10 THEN 2 ELSE 0 END) ELSE 0 END, 0)) AS "國定假日大於8小時", SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 4 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 10 THEN "a"."小計" - 10 ELSE 0 END) ELSE 0 END, 0)) AS "國定假日大於10小時", SUM(COALESCE(CASE WHEN "a"."調補" = 1 THEN "a"."小計" ELSE 0 END, 0)) AS "調補時數" /* 調補 */, SUM(COALESCE("a"."小計", 0)) AS "加班時數" FROM "viewfilh005a" AS "a" LEFT JOIN "viewfil3805" AS "c" ON "a"."加班日期" = "c"."日期" GROUP BY "a"."申請人", "a"."加班日期") AS "d" ON "a"."員工編號" = "d"."申請人" AND "d"."加班日期" = "a"."出勤日期" LEFT JOIN "viewfilh012" AS "e" ON "e"."申請人" = "a"."員工編號" AND "e"."異動日期" = "a"."出勤日期" LEFT JOIN "viewfil3805" AS "f" ON "a"."出勤日期" = "f"."日期");

-- Home #2287 ViewFILH008.出缺勤月結.H04
CREATE OR REPLACE VIEW "viewfilh008" AS (SELECT "a"."員工編號", ORA_SUBSTR("a"."出勤日期", 1, 6) AS "出勤年月", SUM(CASE WHEN COALESCE("f"."休假", 0) <= 1 AND COALESCE("e"."請假時數", 0) = 0 AND "a"."遲到" - 5 > 0 THEN 1 ELSE 0 END) AS "遲到", SUM(CASE WHEN COALESCE("f"."休假", 0) <= 1 AND COALESCE("e"."請假時數", 0) = 0 AND "a"."早退" > 0 THEN 1 ELSE 0 END) AS "早退", SUM((CASE WHEN ("a"."班別" = '4' OR "a"."班別" = '5' OR "a"."班別" = '7') AND "a"."上班刷卡" <> '000000' AND "a"."下班刷卡" BETWEEN '013000' AND '032959' THEN 1 ELSE 0 END)) AS "夜班", SUM((CASE WHEN ("a"."班別" = '4' OR "a"."班別" = '5' OR "a"."班別" = '7') AND "a"."上班刷卡" <> '000000' AND "a"."下班刷卡" BETWEEN '033000' AND "a"."班別時間起" THEN 1 ELSE 0 END)) AS "大夜", SUM(COALESCE("d"."平日前2小時", 0)) AS "平日前2小時", SUM(COALESCE("d"."平日前4小時", 0)) AS "平日前4小時", SUM(COALESCE("d"."平日大於4小時", 0)) AS "平日大於4小時", SUM(COALESCE("d"."休息日前2小時", 0)) AS "休息日前2小時", SUM(COALESCE("d"."休息日前8小時", 0)) AS "休息日前8小時", SUM(COALESCE("d"."休息日大於8小時", 0)) AS "休息日大於8小時", SUM(COALESCE("d"."例假日前8小時", 0)) AS "例假日前8小時", SUM(COALESCE("d"."例假日大於8小時", 0)) AS "例假日大於8小時", SUM(COALESCE("d"."例假日大於10小時", 0)) AS "例假日大於10小時", SUM(COALESCE("d"."例假日補休小時", 0)) AS "例假日補休小時", SUM(COALESCE("d"."國定假日前8小時", 0)) AS "國定假日前8小時", SUM(COALESCE("d"."國定假日大於8小時", 0)) AS "國定假日大於8小時", SUM(COALESCE("d"."國定假日大於10小時", 0)) AS "國定假日大於10小時", SUM((CASE WHEN COALESCE("f"."休假", 0) <= 1 AND COALESCE("e"."請假時數", 0) <= 2 THEN CASE WHEN (TO_NUMBER("a"."上班刷卡", '999999') + TO_NUMBER("a"."下班刷卡", '999999')) = 0 THEN 0 ELSE 1 END WHEN COALESCE("f"."休假", 0) <= 1 AND COALESCE("e"."請假時數", 0) BETWEEN 2.01 AND 4 THEN CASE WHEN (TO_NUMBER("a"."上班刷卡", '999999') + TO_NUMBER("a"."下班刷卡", '999999')) = 0 THEN 0 ELSE 0.5 END ELSE 0 END)) AS "平日打卡日", SUM((CASE WHEN COALESCE("f"."休假", 0) > 1 AND "d"."加班時數" >= 6 THEN CASE WHEN (TO_NUMBER("a"."上班刷卡", '999999') + TO_NUMBER("a"."下班刷卡", '999999')) = 0 THEN 0 ELSE 1 END WHEN COALESCE("f"."休假", 0) > 1 AND "d"."加班時數" BETWEEN 4 AND 5.99 THEN CASE WHEN (TO_NUMBER("a"."上班刷卡", '999999') + TO_NUMBER("a"."下班刷卡", '999999')) = 0 THEN 0 ELSE 0.5 END ELSE 0 END)) AS "假日打卡日", SUM(COALESCE("d"."調補時數", 0)) AS "調補時數", SUM("a"."打卡日調整") AS "打卡日調整" FROM "hrfil1007" AS "a" INNER JOIN "viewfil1010" AS "b" ON "b"."員工編號" = "a"."員工編號" AND "b"."國籍" <> '委外' LEFT JOIN (SELECT "a"."申請人", "a"."起始日期", "a"."截止日期", "utl_raw".cast_to_nvarchar2(STRING_AGG(CAST(CONCAT("utl_raw".cast_to_raw(CONCAT("a"."假別名稱", '[')), "utl_raw".cast_to_raw(TO_NCHAR(ROUND("a"."天數"))), "utl_raw".cast_to_raw(N'天'), "utl_raw".cast_to_raw(TO_NCHAR(ROUND("a"."時數"))), "utl_raw".cast_to_raw(N'小時]')) AS TEXT), "utl_raw".cast_to_raw(N' ') ORDER BY "a"."申請人")) AS "假別" FROM "viewfilh001" AS "a" WHERE "a"."簽核狀態" = 'E' GROUP BY "a"."申請人", "a"."起始日期", "a"."截止日期") AS "c" ON "c"."申請人" = "a"."員工編號" AND "a"."出勤日期" BETWEEN "c"."起始日期" AND "c"."截止日期" LEFT JOIN (SELECT "a"."申請人", "a"."加班日期" AS "加班日期", MAX("c"."休假") AS "休假", SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) <= 1 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" >= 2 THEN 2 ELSE "a"."小計" END) ELSE 0 END, 0)) AS "平日前2小時" /* 平日、補班 */, SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) <= 1 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 2 AND "a"."小計" < 4 THEN "a"."小計" - 2 WHEN "a"."小計" >= 4 THEN 2 ELSE 0 END) ELSE 0 END, 0)) AS "平日前4小時", SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) <= 1 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 4 THEN "a"."小計" - 4 ELSE 0 END) ELSE 0 END, 0)) AS "平日大於4小時", SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 2 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" >= 2 THEN 2 ELSE "a"."小計" END) ELSE 0 END, 0)) AS "休息日前2小時" /* 休息日 */, SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 2 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 2 AND "a"."小計" < 8 THEN "a"."小計" - 2 WHEN "a"."小計" >= 8 THEN 6 ELSE 0 END) ELSE 0 END, 0)) AS "休息日前8小時", SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 2 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 8 THEN "a"."小計" - 8 ELSE 0 END) ELSE 0 END, 0)) AS "休息日大於8小時", SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 3 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 0 THEN (CASE WHEN "a"."小計" > 8 THEN 8 ELSE "a"."小計" END) ELSE 0 END) ELSE 0 END, 0)) AS "例假日前8小時" /* 例假日 */, SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 3 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 8 AND "a"."小計" < 10 THEN "a"."小計" - 8 WHEN "a"."小計" >= 10 THEN 2 ELSE 0 END) ELSE 0 END, 0)) AS "例假日大於8小時", SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 3 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 10 THEN "a"."小計" - 10 ELSE 0 END) ELSE 0 END, 0)) AS "例假日大於10小時", SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 3 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 8 THEN 8 ELSE "a"."小計" END) ELSE 0 END, 0)) AS "例假日補休小時", SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 4 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 0 THEN (CASE WHEN "a"."小計" > 8 THEN 8 ELSE "a"."小計" END) ELSE 0 END) ELSE 0 END, 0)) AS "國定假日前8小時" /* 國定假日 */, SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 4 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 8 AND "a"."小計" < 10 THEN "a"."小計" - 8 WHEN "a"."小計" >= 10 THEN 2 ELSE 0 END) ELSE 0 END, 0)) AS "國定假日大於8小時", SUM(COALESCE(CASE WHEN COALESCE("c"."休假", 0) = 4 AND "a"."調補" = 0 THEN (CASE WHEN "a"."小計" > 10 THEN "a"."小計" - 10 ELSE 0 END) ELSE 0 END, 0)) AS "國定假日大於10小時", SUM(COALESCE("a"."小計", 0)) AS "加班時數" /* 加班總時數 */, SUM(COALESCE(CASE WHEN "a"."調補" = 1 THEN "a"."小計" ELSE 0 END, 0)) AS "調補時數" /* 調補 */ FROM "viewfilh005a" AS "a" LEFT JOIN "viewfil3805" AS "c" ON "a"."加班日期" = "c"."日期" GROUP BY "a"."申請人", "a"."加班日期") AS "d" ON "a"."員工編號" = "d"."申請人" AND "d"."加班日期" = "a"."出勤日期" LEFT JOIN "viewfilh012" AS "e" ON "e"."申請人" = "a"."員工編號" AND "e"."異動日期" = "a"."出勤日期" LEFT JOIN "viewfil3805" AS "f" ON "a"."出勤日期" = "f"."日期" GROUP BY "a"."員工編號", ORA_SUBSTR("a"."出勤日期", 1, 6));

-- Home #2222 ViewFILM001.材料月異動數
CREATE OR REPLACE VIEW "viewfilm001" AS (SELECT ORA_SUBSTR("a"."異動日期", 1, 6) AS "月份", "a"."倉庫代碼", "a"."材料編號", SUM("a"."異動數") AS "異動數量" FROM "viewfil2022" AS "a" GROUP BY ORA_SUBSTR("a"."異動日期", 1, 6), "a"."倉庫代碼", "a"."材料編號");

-- Home #2223 ViewFILM005.材料月庫存數
CREATE OR REPLACE VIEW "viewfilm005" AS (SELECT "a"."月份", "a"."倉庫代碼" AS "庫別代碼", COALESCE("b"."名稱", ' ') AS "庫別名稱", COALESCE("b"."倉別代碼", ' ') AS "倉別代碼", COALESCE("c"."名稱", ' ') AS "倉別名稱", "a"."材料編號", COALESCE("a"."前期庫存", 0) AS "前期庫存", "a"."本期異動", COALESCE("a"."前期庫存", 0) + "a"."本期異動" AS "期末庫存", ROW_NUMBER() OVER (PARTITION BY "a"."材料編號", "a"."倉庫代碼" ORDER BY "a"."月份" DESC) AS "年月序" FROM (SELECT "a"."月份", "a"."倉庫代碼", "a"."材料編號", (SELECT SUM("b"."異動數量") FROM "viewfilm001" AS "b" WHERE "b"."材料編號" = "a"."材料編號" AND "b"."倉庫代碼" = "a"."倉庫代碼" AND "b"."月份" < "a"."月份") AS "前期庫存", "a"."異動數量" AS "本期異動" FROM "viewfilm001" AS "a") AS "a" LEFT JOIN "viewfil3106" AS "b" ON "a"."倉庫代碼" = "b"."代碼" LEFT JOIN "viewfil310r" AS "c" ON "b"."倉別代碼" = "c"."代碼");

-- Home #2224 ViewFILM006.不分倉庫存數(含負)
CREATE OR REPLACE VIEW "viewfilm006" AS (SELECT "a"."材料編號", SUM("a"."異動數") AS "庫存數" FROM "viewfil2022" AS "a" GROUP BY "a"."材料編號");

-- Home #2225 ViewFILM007.不分月庫存數
CREATE OR REPLACE VIEW "viewfilm007" AS (SELECT "a"."材料編號", "a"."庫別代碼", COALESCE("b"."名稱", ' ') AS "庫別名稱", COALESCE("b"."倉別代碼", ' ') AS "倉別代碼", COALESCE("c"."名稱", ' ') AS "倉別名稱", "a"."庫存數" FROM (SELECT "a"."材料編號", "a"."倉庫代碼" AS "庫別代碼", SUM("a"."異動數") AS "庫存數" FROM "viewfil2022" AS "a" GROUP BY "a"."材料編號", "a"."倉庫代碼") AS "a" LEFT JOIN "viewfil3106" AS "b" ON "a"."庫別代碼" = "b"."代碼" LEFT JOIN "viewfil310r" AS "c" ON "b"."倉別代碼" = "c"."代碼");

-- Home #2213 ViewFILM008S.材料庫存數不分倉
CREATE OR REPLACE VIEW "viewfilm008s" AS (SELECT "a"."料號" AS "材料編號", "e"."品名", "e"."規格", "a"."庫存數" FROM (SELECT "f"."料號", SUM(GREATEST(COALESCE("a"."庫存數", 0), 0)) AS "庫存數" FROM "viewfilm017sa" AS "a" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "a"."批號" GROUP BY "f"."料號") AS "a" INNER JOIN "fil0012" AS "e" ON "e"."產品編號" = "a"."料號");

-- Home #2215 ViewFILM008SA.材料庫存數分倉
CREATE OR REPLACE VIEW "viewfilm008sa" AS (SELECT "a"."料號" AS "材料編號", "e"."品名", "e"."規格", "a"."庫位", SUM(COALESCE("a"."異動數", 0)) AS "庫存數" FROM (SELECT "a"."批號", "a"."料號", COALESCE("g"."目前庫位", ' ') AS "庫位", "a"."異動數" FROM "viewfilm018s" AS "a" INNER JOIN "viewfilm000s" AS "g" ON "g"."條碼" = "a"."批號") AS "a" INNER JOIN "viewfil1012" AS "e" ON "a"."料號" = "e"."產品編號" GROUP BY "a"."料號", "e"."品名", "e"."規格", "a"."庫位");

-- Home #2216 ViewFILM008SC.紙箱/管庫存數
CREATE OR REPLACE VIEW "viewfilm008sc" AS WITH "temp1" AS (SELECT "a"."產品編號" AS "材料編號", SUM(CASE WHEN "a"."單據類別" = 'D21' THEN "a"."數值4" ELSE ("a"."異動數量" + "a"."贈品數量") * "b"."材料庫存參數" END) AS "異動數" FROM "fil0040" AS "a" /* 庫存參數 */ INNER JOIN "viewfil0020" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "b"."材料庫存參數" <> 0 /* 主檔 */ INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" /* 品號檔 */ INNER JOIN "fil0012" AS "c" ON "a"."產品編號" = "c"."產品編號" AND "c"."物料大類" BETWEEN 'B10' AND 'B20' AND CASE WHEN "a"."異動日期" = '00000000' THEN "d"."單據日期" ELSE "a"."異動日期" END >= "c"."盤點日期" /* 簽核 */ LEFT JOIN "viewofobjproperties" AS "h" ON "h"."單據流水號" = "d"."流水編號" WHERE "a"."產品編號" <> ' ' AND ("a"."單據類別" = 'D21' AND "a"."異動類別" = 'A' OR "a"."單據類別" <> 'D21') AND COALESCE("h"."簽核狀態", ' ') <> 'A' GROUP BY "a"."產品編號" UNION ALL /* 領料 */ SELECT "a"."產品編號" AS "材料編號", SUM("a"."異動數量") AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" INNER JOIN "fil0030" AS "e" ON "a"."單據類別" = "e"."單據類別" AND "a"."單據編號" = "e"."單據編號" LEFT JOIN "viewfil310p" AS "f" ON "d"."機台代碼" = "f"."代碼" INNER JOIN "fil0012" AS "g" ON "a"."產品編號" = "g"."產品編號" AND "g"."物料大類" BETWEEN 'B10' AND 'B20' AND "a"."異動日期" >= "g"."盤點日期" WHERE "a"."單據類別" = 'C4M' AND "a"."產品編號" <> ' ' GROUP BY "a"."產品編號" UNION ALL /* 材料領用,報廢,油墨領用 */ SELECT "a"."產品編號" AS "材料編號", SUM("a"."異動數量" * -1) AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "c1" ON "a"."單據類別" = "c1"."單據類別" AND "a"."單據編號" = "c1"."單據編號" INNER JOIN "fil0012" AS "d" ON "a"."產品編號" = "d"."產品編號" AND "d"."物料大類" BETWEEN 'B10' AND 'B20' AND "a"."異動日期" >= "d"."盤點日期" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" BETWEEN 'C' AND 'E' AND "a"."異動數量" <> 0 AND "a"."產品編號" <> ' ' GROUP BY "a"."產品編號" UNION ALL /* 印刷日報領用 */ SELECT CAST("a"."前製程編號" AS TEXT) AS "材料編號", SUM(("a"."異動數量" - "a"."退庫數量") * -1) AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "c1" ON "a"."單據類別" = "c1"."單據類別" AND "a"."單據編號" = "c1"."單據編號" INNER JOIN "fil0012" AS "d" ON CAST("a"."前製程編號" AS TEXT) = "d"."產品編號" AND "d"."物料大類" BETWEEN 'B10' AND 'B20' AND "a"."異動日期" >= "d"."盤點日期" WHERE "a"."單據類別" = 'C41' AND "a"."異動數量" > 0 AND "c"."製程代碼" = 'C31A' AND "a"."前製程編號" <> ' ' GROUP BY CAST("a"."前製程編號" AS TEXT) UNION ALL /* 材料領用.氣閥.鐵條-批號1 */ SELECT "d"."料號" AS "材料編號", SUM("b"."數值1" * -1) AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "c1" ON "a"."單據類別" = "c1"."單據類別" AND "a"."單據編號" = "c1"."單據編號" INNER JOIN "viewfil1024" AS "d" ON "b"."文數字1" = "d"."條碼" INNER JOIN "fil0012" AS "e" ON "d"."料號" = "e"."產品編號" AND "e"."物料大類" BETWEEN 'B10' AND 'B20' AND "a"."異動日期" >= "e"."盤點日期" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "b"."文數字1" <> ' ' AND "d"."料號" <> ' ' GROUP BY "d"."料號" UNION ALL /* 材料領用.氣閥.鐵條-批號2 */ SELECT "d"."料號" AS "材料編號", SUM("b"."數值2" * -1) AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "c1" ON "a"."單據類別" = "c1"."單據類別" AND "a"."單據編號" = "c1"."單據編號" INNER JOIN "viewfil1024" AS "d" ON "b"."文數字2" = "d"."條碼" INNER JOIN "fil0012" AS "e" ON "d"."料號" = "e"."產品編號" AND "e"."物料大類" BETWEEN 'B10' AND 'B20' AND "a"."異動日期" >= "e"."盤點日期" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "b"."文數字2" <> ' ' AND "d"."料號" <> ' ' GROUP BY "d"."料號" UNION ALL /* 發料回庫(-)
SELECT 
	A.產品編號 材料編號,
	SUM(A.贈品數量 * -1) 異動數
FROM 
	FIL0040 A
	INNER JOIN FIL0041 B ON A.單據類別 = B.單別 AND A.單據編號 = B.單號 AND A.單據序號 = B.序號
	INNER JOIN FIL0012 C ON A.產品編號 = C.產品編號 AND C.物料大類 between 'B10' and 'B20' AND  A.異動日期 >= C.盤點日期
	LEFT JOIN FIL0043 G ON B.批號 = G.條碼
WHERE
	A.單據類別 = 'C41' AND
	A.異動類別 = 'C' AND
	A.贈品數量 != 0 AND
	A.產品編號 != ' '
GROUP BY
	A.產品編號

UNION ALL
*/ /* 發料回庫(+) */ SELECT "a"."產品編號" AS "材料編號", SUM("a"."贈品數量" * 1) AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0012" AS "c" ON "a"."產品編號" = "c"."產品編號" AND "c"."物料大類" BETWEEN 'B10' AND 'B20' AND "a"."異動日期" >= "c"."盤點日期" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'C' AND "a"."贈品數量" <> 0 AND "a"."產品編號" <> ' ' GROUP BY "a"."產品編號" /* 廠內盤點調整 */ UNION ALL SELECT "a"."產品編號" AS "材料編號", SUM(("a"."異動數量" + "a"."贈品數量")) AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0012" AS "e" ON "a"."產品編號" = "e"."產品編號" AND "e"."物料大類" BETWEEN 'B10' AND 'B20' AND "a"."異動日期" >= "e"."盤點日期" WHERE "a"."單據類別" = 'F32' AND "a"."異動類別" = '2' GROUP BY "a"."產品編號") SELECT "e"."產品編號" AS "材料編號", "e"."品名", "e"."規格", SUM(COALESCE("a"."異動數", 0)) + MAX(COALESCE("e"."盤存數量", 0)) AS "庫存數" FROM "fil0012" AS "e" LEFT JOIN "temp1" AS "a" ON "a"."材料編號" = "e"."產品編號" WHERE "e"."物料大類" BETWEEN 'B10' AND 'B20' GROUP BY "e"."產品編號", "e"."品名", "e"."規格";

-- Home #2228 ViewFILM011.材料月異動數(批號)
CREATE OR REPLACE VIEW "viewfilm011" AS (SELECT ORA_SUBSTR("a"."異動日期", 1, 6) AS "月份", "a"."倉庫代碼", "a"."材料編號", "a"."批號", SUM("a"."異動數") AS "異動數量" FROM "viewfil2022" AS "a" WHERE "a"."批號" <> ' ' GROUP BY ORA_SUBSTR("a"."異動日期", 1, 6), "a"."倉庫代碼", "a"."材料編號", "a"."批號");

-- Home #2229 ViewFILM015.材料月庫存數(批號)
CREATE OR REPLACE VIEW "viewfilm015" AS (SELECT "a"."月份", "a"."倉庫代碼", COALESCE("b"."名稱", ' ') AS "倉庫名稱", COALESCE("b"."倉別代碼", ' ') AS "倉別代碼", COALESCE("b"."倉別名稱", ' ') AS "倉別名稱", "a"."材料編號", "a"."批號", COALESCE("a"."前期庫存", 0) AS "前期庫存", "a"."本期異動", COALESCE("a"."前期庫存", 0) + "a"."本期異動" AS "期末庫存", ROW_NUMBER() OVER (PARTITION BY "a"."材料編號", "a"."批號", "a"."倉庫代碼" ORDER BY "a"."月份" DESC) AS "年月序" FROM (SELECT "a"."月份", "a"."倉庫代碼", "a"."材料編號", "a"."批號", (SELECT SUM("b"."異動數量") FROM "viewfilm011" AS "b" WHERE "b"."材料編號" = "a"."材料編號" AND "b"."批號" = "a"."批號" AND "b"."倉庫代碼" = "a"."倉庫代碼" AND "b"."月份" < "a"."月份") AS "前期庫存", "a"."異動數量" AS "本期異動" FROM "viewfilm011" AS "a") AS "a" LEFT JOIN "viewfil3106" AS "b" ON "a"."倉庫代碼" = "b"."代碼");

-- Home #2247 ViewFILM016A.不分倉庫存(批號)
CREATE OR REPLACE VIEW "viewfilm016a" AS (SELECT "a"."批號", SUM("a"."庫存數量") AS "庫存數" FROM (SELECT "a"."批號", SUM("a"."異動數量") AS "庫存數量" FROM "viewfilm011" AS "a" WHERE "a"."月份" = TO_CHAR(CURRENT_TIMESTAMP, 'yyyymm') GROUP BY "a"."批號" UNION ALL SELECT "a"."批號", SUM("a"."庫存數量") FROM "fil5002" AS "a" WHERE "a"."月份" = TO_CHAR(CURRENT_TIMESTAMP - INTERVAL '1 MONTH', 'yyyymm') GROUP BY "a"."批號") AS "a" GROUP BY "a"."批號");

-- Home #2231 ViewFILM017.不分倉(料號＋批號)
CREATE OR REPLACE VIEW "viewfilm017" AS (SELECT "a"."產品編號" AS "材料編號", "e"."物料大類", "e"."品名", "e"."規格", CASE WHEN "e"."批號管理" = 0 THEN '' ELSE "a"."批號" END AS "批號", SUM(COALESCE("a"."異動數", 0)) AS "庫存數" FROM (SELECT "a"."產品編號", "c"."批號", CASE WHEN "a"."單據類別" = 'D21' THEN "a"."數值4" ELSE ("a"."異動數量" + "a"."贈品數量") END * "b"."材料庫存參數" AS "異動數" FROM "fil0040" AS "a" /* 庫存參數 */ INNER JOIN "viewfil0020" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "b"."材料庫存參數" <> 0 /* 特殊欄位 */ LEFT JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" LEFT JOIN "fil0012" AS "e" ON "a"."產品編號" = "e"."產品編號" /* 單位換算
			LEFT JOIN ViewFIL1017 F ON A.單位代碼 = F.從 AND E.單位代碼 = F.到
			*/ /* 簽核 */ LEFT JOIN "viewofobjproperties" AS "h" ON "h"."單據流水號" = "d"."流水編號" WHERE "a"."產品編號" <> ' ' AND CASE WHEN "e"."批號管理" = 0 THEN '不分批號' ELSE "c"."批號" END <> ' ' AND COALESCE("h"."簽核狀態", ' ') <> 'A' AND CASE WHEN "a"."單據類別" = 'D21' THEN CASE WHEN "a"."異動類別" = 'A' THEN 0 ELSE 1 END ELSE 0 END = 0 UNION ALL /* 發料 */ SELECT "a"."產品編號", "c"."批號", "a"."異動數量" AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN "fil0012" AS "g" ON "a"."產品編號" = "g"."產品編號" /* 單位換算
			LEFT JOIN ViewFIL1017 H ON A.單位代碼 = H.從 AND G.單位代碼 = H.到
			*/ WHERE "a"."單據類別" = 'C4M' AND "a"."產品編號" <> ' ' AND CASE WHEN "g"."批號管理" = 0 THEN '不分批號' ELSE "c"."批號" END <> ' ' UNION ALL /* 材料領用,報廢,油墨領用 */ SELECT "a"."產品編號", "b"."批號", "a"."異動數量" * -1 AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" LEFT JOIN "fil0012" AS "c" ON "a"."產品編號" = "c"."產品編號" /* 單位換算
			LEFT JOIN ViewFIL1017 E ON A.單位代碼 = E.從 AND C.單位代碼 = E.到
			*/ WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" BETWEEN 'C' AND 'E' AND "a"."異動數量" <> 0 AND "a"."產品編號" <> ' ' AND CASE WHEN "c"."批號管理" = 0 THEN '不分批號' ELSE "b"."批號" END <> ' ' UNION ALL /* 材料領用.氣閥.鐵條-批號1 */ SELECT "e"."料號", "b"."文數字1" AS "批號", "b"."數值1" * -1 AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "viewfil1024" AS "e" ON "b"."文數字1" = "e"."條碼" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "b"."文數字1" <> ' ' UNION ALL /* 材料領用.氣閥.鐵條-批號2 */ SELECT "e"."料號", "b"."文數字2" AS "批號", "b"."數值2" * -1 AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "viewfil1024" AS "e" ON "b"."文數字2" = "e"."條碼" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "b"."文數字2" <> ' ' UNION ALL /* 發料回庫(+) */ SELECT "a"."產品編號", "b"."批號", "a"."贈品數量" AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" /* 單位換算
			LEFT JOIN FIL0012 C ON A.產品編號 = C.產品編號
			LEFT JOIN ViewFIL1017 E ON A.單位代碼 = E.從 AND C.單位代碼 = E.到
			*/ WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'C' AND "a"."贈品數量" <> 0 /* 廠內盤點調整 */ UNION ALL SELECT "a"."產品編號", "c"."批號", ("a"."異動數量" + "a"."贈品數量") AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'F32' AND "a"."異動類別" = '2') AS "a" INNER JOIN "fil0012" AS "e" ON "a"."產品編號" = "e"."產品編號" GROUP BY "a"."產品編號", "e"."物料大類", "e"."品名", "e"."規格", CASE WHEN "e"."批號管理" = 0 THEN '' ELSE "a"."批號" END);

-- Home #2243 ViewFILM017A.不分倉(料/批號)
CREATE OR REPLACE VIEW "viewfilm017a" AS (SELECT "a"."材料編號", "e"."物料大類", "e"."品名", "e"."規格", CASE WHEN "e"."批號管理" = 0 THEN '' ELSE "a"."批號" END AS "批號", SUM("a"."庫存數量") AS "庫存數" FROM (SELECT "a"."材料編號", "a"."批號", SUM("a"."異動數量") AS "庫存數量" FROM "viewfilm011" AS "a" WHERE "a"."月份" = TO_CHAR(CURRENT_TIMESTAMP, 'yyyymm') GROUP BY "a"."材料編號", "a"."批號" UNION ALL SELECT "a"."材料編號", "a"."批號", SUM("a"."庫存數量") FROM "fil5002" AS "a" WHERE "a"."月份" = TO_CHAR(CURRENT_TIMESTAMP - INTERVAL '1 MONTH', 'yyyymm') GROUP BY "a"."材料編號", "a"."批號") AS "a" INNER JOIN "viewfil1012" AS "e" ON "a"."材料編號" = "e"."產品編號" GROUP BY "a"."材料編號", "e"."物料大類", "e"."品名", "e"."規格", CASE WHEN "e"."批號管理" = 0 THEN '' ELSE "a"."批號" END);

-- Home #2232 ViewFILM018.不分倉批號異動檔
CREATE OR REPLACE VIEW "viewfilm018" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動日期", "a"."產品編號" AS "料號", COALESCE(CASE WHEN "e"."批號管理" = 0 THEN ' ' ELSE "c"."批號" END, ' ') AS "批號", COALESCE(CASE WHEN "a"."單據類別" = 'D21' THEN "a"."數值4" ELSE ("a"."異動數量" + "a"."贈品數量") END * "b"."材料庫存參數", 0) AS "異動數" FROM "fil0040" AS "a" /* 庫存參數 */ INNER JOIN "viewfil0020" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "b"."材料庫存參數" <> 0 /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN "viewfil1012" AS "e" ON "a"."產品編號" = "e"."產品編號" /* 單位換算
	LEFT JOIN ViewFIL1017 F ON A.單位代碼 = F.從 AND E.單位代碼 = F.到
	*/ WHERE "a"."產品編號" <> ' ' AND "c"."批號" <> ' ' UNION ALL /* 發料 */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動日期", "a"."產品編號", CASE WHEN "g"."批號管理" = 0 THEN ' ' ELSE "c"."批號" END AS "批號", "a"."異動數量" AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN "viewfil1012" AS "g" ON "a"."產品編號" = "g"."產品編號" /* 單位換算
	LEFT JOIN ViewFIL1017 H ON A.單位代碼 = H.從 AND G.單位代碼 = H.到
	*/ WHERE "a"."單據類別" = 'C4M' AND "a"."產品編號" <> ' ' AND "c"."批號" <> ' ' UNION ALL /* 材料領用,報廢,油墨領用 */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."產品編號", "a"."異動日期", CASE WHEN "c"."批號管理" = 0 THEN ' ' ELSE "b"."批號" END AS "批號", "a"."異動數量" * -1 AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" LEFT JOIN "viewfil1012" AS "c" ON "a"."產品編號" = "c"."產品編號" /* 單位換算
	LEFT JOIN ViewFIL1017 E ON A.單位代碼 = E.從 AND C.單位代碼 = E.到
	*/ WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" BETWEEN 'C' AND 'E' AND "a"."異動數量" <> 0 AND "b"."批號" <> ' ' UNION ALL /* 材料領用.氣閥.鐵條-批號1 */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動日期", "e"."料號", CASE WHEN "f"."批號管理" = 0 THEN ' ' ELSE "b"."文數字1" END AS "批號", "b"."數值1" * -1 AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "viewfil1024" AS "e" ON "b"."文數字1" = "e"."條碼" INNER JOIN "viewfil1012" AS "f" ON "e"."料號" = "f"."產品編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "b"."文數字1" <> ' ' UNION ALL /* 材料領用.氣閥.鐵條-批號2 */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動日期", "e"."料號", CASE WHEN "f"."批號管理" = 0 THEN ' ' ELSE "b"."文數字2" END AS "批號", "b"."數值2" * -1 AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "viewfil1024" AS "e" ON "b"."文數字2" = "e"."條碼" INNER JOIN "viewfil1012" AS "f" ON "e"."料號" = "f"."產品編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "b"."文數字2" <> ' ' UNION ALL /* 發料回庫(+) */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" + 5200 AS "序號", "a"."異動日期", "a"."產品編號", CASE WHEN "c"."批號管理" = 0 THEN ' ' ELSE "b"."批號" END AS "批號", "a"."贈品數量" AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" LEFT JOIN "viewfil1012" AS "c" ON "a"."產品編號" = "c"."產品編號" /* 單位換算
	LEFT JOIN ViewFIL1017 E ON A.單位代碼 = E.從 AND C.單位代碼 = E.到
	*/ WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'C' AND "a"."贈品數量" <> 0 /* 廠內盤點調整 */ UNION ALL SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動日期", "a"."產品編號", CASE WHEN "d"."批號管理" = 0 THEN ' ' ELSE "c"."批號" END AS "批號", ("a"."異動數量" + "a"."贈品數量") AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN "viewfil1012" AS "d" ON "a"."產品編號" = "d"."產品編號" WHERE "a"."單據類別" = 'F32' AND "a"."異動類別" = '2');

-- Home #2241 ViewFILM019.分倉批號庫存
CREATE OR REPLACE VIEW "viewfilm019" AS (SELECT "a"."倉庫代碼", COALESCE("b"."名稱", ' ') AS "倉庫名稱", "a"."材料編號", "a"."批號", SUM("a"."異動數量") AS "庫存數" FROM "viewfilm011" AS "a" LEFT JOIN "viewfil3106" AS "b" ON "a"."倉庫代碼" = "b"."代碼" GROUP BY "a"."倉庫代碼", COALESCE("b"."名稱", ' '), "a"."材料編號", "a"."批號");

-- Home #2248 ViewFILM019A.分倉批號庫存
CREATE OR REPLACE VIEW "viewfilm019a" AS (SELECT "a"."倉庫代碼", COALESCE("b"."名稱", ' ') AS "倉庫名稱", "a"."材料編號", "a"."批號", SUM("a"."庫存數量") AS "庫存數" FROM (SELECT "a"."倉庫代碼", "a"."材料編號", "a"."批號", SUM("a"."異動數量") AS "庫存數量" FROM "viewfilm011" AS "a" WHERE "a"."月份" = TO_CHAR(CURRENT_TIMESTAMP, 'yyyymm') GROUP BY "a"."倉庫代碼", "a"."材料編號", "a"."批號" UNION ALL SELECT "a"."倉庫代碼", "a"."材料編號", "a"."批號", "a"."庫存數量" FROM "fil5001" AS "a" WHERE "a"."月份" = TO_CHAR(CURRENT_TIMESTAMP - INTERVAL '1 MONTH', 'yyyymm')) AS "a" LEFT JOIN "viewfil3106" AS "b" ON "a"."倉庫代碼" = "b"."代碼" GROUP BY "a"."倉庫代碼", COALESCE("b"."名稱", ' '), "a"."材料編號", "a"."批號");

-- Home #2249 ViewFILM020A.分倉批號前月庫存
CREATE OR REPLACE VIEW "viewfilm020a" AS (SELECT "a"."產品編號" AS "材料編號", "a"."倉庫代碼", COALESCE(CASE WHEN "c"."批號管理" = 0 THEN ' ' ELSE "f"."批號" END, ' ') AS "批號", SUM(("a"."異動數量" + "a"."贈品數量") * "b"."材料庫存參數") AS "庫存數" FROM "fil0040" AS "a" /* 庫存參數 */ INNER JOIN "viewfil0020" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "b"."材料庫存參數" <> 0 /* 主檔 */ INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" /* 品號檔 */ INNER JOIN "viewfil1012" AS "c" ON "a"."產品編號" = "c"."產品編號" AND "c"."產品類別" BETWEEN 'M' AND 'P' /* 特殊欄位 */ LEFT JOIN "fil0041" AS "f" ON "a"."單據類別" = "f"."單別" AND "a"."單據編號" = "f"."單號" AND "a"."單據序號" = "f"."序號" WHERE "a"."產品編號" <> ' ' AND CASE WHEN "a"."異動日期" = '00000000' THEN "d"."單據日期" ELSE "a"."異動日期" END <= CONCAT(TO_CHAR(CURRENT_TIMESTAMP - INTERVAL '1 MONTH', 'yyyymm'), '99') GROUP BY "a"."產品編號", "a"."倉庫代碼", COALESCE(CASE WHEN "c"."批號管理" = 0 THEN ' ' ELSE "f"."批號" END, ' ') UNION ALL /* 領料 */ SELECT "a"."產品編號" AS "材料編號", "f"."庫位代碼" AS "倉庫代碼", CASE WHEN "g"."批號管理" = 0 THEN ' ' ELSE "c"."批號" END, SUM("a"."異動數量") AS "庫存數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" LEFT JOIN "viewfil310p" AS "f" ON "d"."機台代碼" = "f"."代碼" LEFT JOIN "viewfil1012" AS "g" ON "a"."產品編號" = "g"."產品編號" WHERE "a"."單據類別" = 'C4M' AND "a"."產品編號" <> ' ' AND "a"."異動日期" <= CONCAT(TO_CHAR(CURRENT_TIMESTAMP - INTERVAL '1 MONTH', 'yyyymm'), '99') GROUP BY "a"."產品編號", "f"."庫位代碼", CASE WHEN "g"."批號管理" = 0 THEN ' ' ELSE "c"."批號" END UNION ALL /* 材料領用,報廢,油墨領用 */ SELECT "a"."產品編號" AS "材料編號", "a"."倉庫代碼", CASE WHEN "d"."批號管理" = 0 THEN ' ' ELSE "b"."批號" END AS "批號", SUM("a"."異動數量" * -1) AS "庫存數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" INNER JOIN "viewfil1012" AS "d" ON "a"."產品編號" = "d"."產品編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" BETWEEN 'C' AND 'E' AND "a"."異動數量" <> 0 AND "a"."產品編號" <> ' ' AND "a"."異動日期" <= CONCAT(TO_CHAR(CURRENT_TIMESTAMP - INTERVAL '1 MONTH', 'yyyymm'), '99') GROUP BY "a"."產品編號", "a"."倉庫代碼", CASE WHEN "d"."批號管理" = 0 THEN ' ' ELSE "b"."批號" END UNION ALL /* 材料領用.氣閥.鐵條-批號1 */ SELECT "d"."料號" AS "材料編號", "a"."倉庫代碼", CASE WHEN "e"."批號管理" = 0 THEN ' ' ELSE "b"."文數字1" END AS "批號", SUM("b"."數值1" * -1) AS "庫存數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "viewfil1024" AS "d" ON "b"."文數字1" = "d"."條碼" INNER JOIN "viewfil1012" AS "e" ON "d"."料號" = "e"."產品編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "b"."文數字1" <> ' ' AND "d"."料號" <> ' ' AND "a"."異動日期" <= CONCAT(TO_CHAR(CURRENT_TIMESTAMP - INTERVAL '1 MONTH', 'yyyymm'), '99') GROUP BY "d"."料號", "a"."倉庫代碼", CASE WHEN "e"."批號管理" = 0 THEN ' ' ELSE "b"."文數字1" END UNION ALL /* 材料領用.氣閥.鐵條-批號2 */ SELECT "d"."料號" AS "材料編號", "a"."倉庫代碼", CASE WHEN "e"."批號管理" = 0 THEN ' ' ELSE "b"."文數字2" END AS "批號", SUM("b"."數值2" * -1) AS "庫存數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "viewfil1024" AS "d" ON "b"."文數字2" = "d"."條碼" INNER JOIN "viewfil1012" AS "e" ON "d"."料號" = "e"."產品編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "b"."文數字2" <> ' ' AND "d"."料號" <> ' ' AND "a"."異動日期" <= CONCAT(TO_CHAR(CURRENT_TIMESTAMP - INTERVAL '1 MONTH', 'yyyymm'), '99') GROUP BY "d"."料號", "a"."倉庫代碼", CASE WHEN "e"."批號管理" = 0 THEN ' ' ELSE "b"."文數字2" END UNION ALL /* 發料回庫(-)
SELECT 
	A.產品編號 材料編號,
	A.倉庫代碼,
	decode(C.批號管理,0,' ',B.批號) 批號,
	SUM(A.贈品數量 * -1) 庫存數
FROM 
	FIL0040 A
	INNER JOIN FIL0041 B ON A.單據類別 = B.單別 AND A.單據編號 = B.單號 AND A.單據序號 = B.序號
	INNER JOIN FIL0030 D ON A.單據類別 = D.單據類別 AND A.單據編號 = D.單據編號	
	LEFT JOIN VIEWFIL1012 C ON A.產品編號 = C.產品編號
WHERE
	A.單據類別 = 'C41' AND
	A.異動類別 = 'C' AND
	A.贈品數量 != 0 AND
	A.產品編號 != ' ' AND
	A.異動日期 <= TO_CHAR(SYSDATE - interval '1' month,'yyyymm')||'99'
GROUP BY 
	A.產品編號,
	A.倉庫代碼,
	decode(C.批號管理,0,' ',B.批號)

UNION ALL
*/ /* 發料回庫(+) */ SELECT "a"."產品編號", "a"."前置單別" AS "倉庫代碼", CASE WHEN "c"."批號管理" = 0 THEN ' ' ELSE "b"."批號" END AS "批號", SUM("a"."贈品數量" * 1) AS "庫存數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" LEFT JOIN "viewfil1012" AS "c" ON "a"."產品編號" = "c"."產品編號" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'C' AND "a"."贈品數量" <> 0 AND "a"."產品編號" <> ' ' AND "a"."異動日期" <= CONCAT(TO_CHAR(CURRENT_TIMESTAMP - INTERVAL '1 MONTH', 'yyyymm'), '99') GROUP BY "a"."產品編號", "a"."前置單別", CASE WHEN "c"."批號管理" = 0 THEN ' ' ELSE "b"."批號" END /* 廠內盤點調整 */ UNION ALL SELECT "a"."產品編號", ' ' AS "倉庫代碼", CASE WHEN "e"."批號管理" = 0 THEN ' ' ELSE "c"."批號" END AS "批號", SUM("a"."異動數量" + "a"."贈品數量") AS "庫存數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN "viewfil1012" AS "e" ON "a"."產品編號" = "e"."產品編號" WHERE "a"."單據類別" = 'F32' AND "a"."異動類別" = '2' AND "a"."異動日期" <= CONCAT(TO_CHAR(CURRENT_TIMESTAMP - INTERVAL '1 MONTH', 'yyyymm'), '99') GROUP BY "a"."產品編號", CASE WHEN "e"."批號管理" = 0 THEN ' ' ELSE "c"."批號" END);

-- Home #1082     ..ViewTemp01(臨時)
CREATE OR REPLACE VIEW "viewtemp01" AS (SELECT "a"."產品編號" AS "材料編號", SUM(COALESCE("a"."異動數", 0)) AS "庫存數" FROM (SELECT "a"."產品編號", SUM(("a"."異動數量" + "a"."贈品數量") * "b"."材料庫存參數") AS "異動數" FROM "fil0040" AS "a" /* 庫存參數 */ INNER JOIN "viewfil0020" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "b"."材料庫存參數" <> 0 INNER JOIN "fil0030" AS "c1" ON "a"."單據類別" = "c1"."單據類別" AND "a"."單據編號" = "c1"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN "viewfil1012" AS "e" ON "a"."產品編號" = "e"."產品編號" /* 單位換算
			LEFT JOIN ViewFIL1017 F ON A.單位代碼 = F.從 AND E.單位代碼 = F.到
			*/ WHERE "a"."產品編號" <> ' ' AND CASE WHEN "e"."批號管理" = 0 THEN '不分批號' ELSE "c"."批號" END <> ' ' AND TO_CHAR("c1"."填表日", 'YYYYMMDDHH24MISS') <= ':1' GROUP BY "a"."產品編號" UNION ALL /* 發料 */ SELECT "a"."產品編號", SUM("a"."異動數量") AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0030" AS "c1" ON "a"."單據類別" = "c1"."單據類別" AND "a"."單據編號" = "c1"."單據編號" LEFT JOIN "viewfil1012" AS "g" ON "a"."產品編號" = "g"."產品編號" /* 單位換算
			LEFT JOIN ViewFIL1017 H ON A.單位代碼 = H.從 AND G.單位代碼 = H.到
			*/ WHERE "a"."單據類別" = 'C4M' AND "a"."產品編號" <> ' ' AND CASE WHEN "g"."批號管理" = 0 THEN '不分批號' ELSE "c"."批號" END <> ' ' AND TO_CHAR("c1"."填表日", 'YYYYMMDDHH24MISS') <= ':1' GROUP BY "a"."產品編號" UNION ALL /* 材料領用,報廢,油墨領用 */ SELECT "a"."產品編號", SUM("a"."異動數量" * -1) AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" LEFT JOIN "viewfil1012" AS "c" ON "a"."產品編號" = "c"."產品編號" /* 單位換算
			LEFT JOIN ViewFIL1017 E ON A.單位代碼 = E.從 AND C.單位代碼 = E.到
			*/ WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" BETWEEN 'C' AND 'E' AND "a"."異動數量" <> 0 AND "a"."產品編號" <> ' ' AND CASE WHEN "c"."批號管理" = 0 THEN '不分批號' ELSE "b"."批號" END <> ' ' AND TO_CHAR("a"."最後更新日", 'YYYYMMDDHH24MISS') <= ':1' GROUP BY "a"."產品編號" UNION ALL /* 材料領用.氣閥.鐵條-批號1 */ SELECT "e"."料號" AS "產品編號", SUM("b"."數值1" * -1) AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "viewfil1024" AS "e" ON "b"."文數字1" = "e"."條碼" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "b"."文數字1" <> ' ' AND TO_CHAR("a"."最後更新日", 'YYYYMMDDHH24MISS') <= ':1' GROUP BY "e"."料號" UNION ALL /* 材料領用.氣閥.鐵條-批號2 */ SELECT "e"."料號" AS "產品編號", SUM("b"."數值2" * -1) AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "viewfil1024" AS "e" ON "b"."文數字2" = "e"."條碼" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "b"."文數字2" <> ' ' AND TO_CHAR("a"."最後更新日", 'YYYYMMDDHH24MISS') <= ':1' GROUP BY "e"."料號" UNION ALL /* 發料回庫(+) */ SELECT "a"."產品編號", SUM("a"."贈品數量") AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0030" AS "c1" ON "a"."單據類別" = "c1"."單據類別" AND "a"."單據編號" = "c1"."單據編號" /* 單位換算
			LEFT JOIN VIEWFIL1012 C ON A.產品編號 = C.產品編號
			LEFT JOIN ViewFIL1017 E ON A.單位代碼 = E.從 AND C.單位代碼 = E.到
			*/ WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'C' AND "a"."贈品數量" <> 0 AND TO_CHAR("c1"."填表日", 'YYYYMMDDHH24MISS') <= ':1' GROUP BY "a"."產品編號" /* 廠內盤點調整 */ UNION ALL SELECT "a"."產品編號", SUM("a"."異動數量" + "a"."贈品數量") AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'F32' AND "a"."異動類別" = '2' AND TO_CHAR("b"."填表日", 'YYYYMMDDHH24MISS') <= ':1' GROUP BY "a"."產品編號") AS "a" GROUP BY "a"."產品編號");

-- Home #2044 ViewFIL404E3.成品異動明細
CREATE OR REPLACE VIEW "viewfil404e3" AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動數量" AS "箱號", COALESCE(CASE WHEN "c"."製程代碼" = 'C31E' THEN CASE WHEN "b"."數值14" = 0 THEN "a"."贈品數量" ELSE "b"."數值14" END ELSE "b"."數值5" * -1 END, 0) AS "數量", 0 AS "報廢數量", COALESCE(CASE WHEN "c"."製程代碼" = 'C31E' THEN CASE WHEN "b"."數值14" = 0 THEN "a"."毛重" ELSE "a"."毛重" * (CAST("b"."數值14" AS DOUBLE PRECISION) / "a"."贈品數量") END ELSE "b"."數值5" * -1 * "g"."平均袋重" END, 0) AS "重量", CONCAT("d"."歸屬編號", '-', TRIM(TO_CHAR("a"."異動數量", '0000'))) AS "批號", "d"."歸屬類別" AS "製令類別", "d"."歸屬編號" AS "製令單號", "d"."單據日期" AS "作業日期", "g"."作業人員" AS "作業員一", "g"."作業員二" AS "作業員二", "g"."作業員三" AS "作業員三", "g"."作業人員姓名" AS "作業員一姓名", "g"."作業員二姓名" AS "作業員二姓名", "g"."作業員三姓名" AS "作業員三姓名", "a"."贈品數量" AS "單據數量", "a"."毛重" AS "單據重量", CASE WHEN "c"."製程代碼" = 'C31E' THEN CAST('製袋' AS TEXT) WHEN "c"."製程代碼" = 'C31G' THEN CAST('鐵條' AS TEXT) ELSE CAST('氣閥' AS TEXT) END AS "來源", "b"."標籤類別", 1 AS "製袋", CASE WHEN "c"."製程代碼" = 'C31F' THEN 1 ELSE 0 END AS "氣閥", CASE WHEN "c"."製程代碼" = 'C31G' THEN 1 ELSE 0 END AS "鐵條", 0 AS "異動", 0 AS "重工", 0 AS "品檢", "a"."流水編號", TO_CHAR("a"."最後更新日", 'YYYYMMDDHH24MISS') AS "最後更新日時" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" LEFT JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" LEFT JOIN "viewfil404e7" AS "g" ON "d"."歸屬類別" = "g"."製令單別" AND "d"."歸屬編號" = "g"."製令單號" AND "a"."異動數量" = "g"."箱號" WHERE "a"."異動類別" = 'A' AND ("c"."製程代碼" = 'C31E' OR "c"."製程代碼" = 'C31F' OR "c"."製程代碼" = 'C31G') UNION ALL SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動數量" AS "箱號", COALESCE(CASE WHEN "a"."單據類別" = 'E35' THEN "a"."贈品數量" * -1 WHEN "a"."單據類別" = 'E37' THEN "b"."數值5" * -1 ELSE "a"."贈品數量" END, 0) AS "數量", COALESCE(CASE WHEN "a"."單據類別" = 'E33' THEN "b"."數值5" ELSE 0 END, 0) AS "報廢數量", COALESCE(CASE WHEN "a"."單據類別" = 'E35' THEN ("a"."贈品數量" * -1 * "j"."平均袋重") WHEN "a"."單據類別" = 'E37' THEN ("b"."數值5" * -1 * ("j"."平均袋重" + COALESCE("k"."每袋重量", 0) + COALESCE("l"."每袋重量", 0))) ELSE "a"."毛重" END, 0) AS "重量", "b"."批號" AS "批號", CAST('C11' AS TEXT) AS "製令類別", "a"."廠客品號" AS "製令單號", "d"."單據日期" AS "作業日期", "j"."作業人員" AS "作業員一", "j"."作業員二" AS "作業員二", "j"."作業員三" AS "作業員三", "j"."作業人員姓名" AS "作業員一姓名", "j"."作業員二姓名" AS "作業員二姓名", "j"."作業員三姓名" AS "作業員三姓名", "a"."贈品數量" AS "單據數量", "a"."毛重" AS "單據重量", CASE WHEN "a"."單據類別" = 'E32' THEN CAST('異動' AS TEXT) WHEN "a"."單據類別" = 'E33' THEN CAST('重工' AS TEXT) WHEN "a"."單據類別" = 'E35' THEN CAST('出貨' AS TEXT) ELSE CAST('品檢' AS TEXT) END AS "來源", "b"."標籤類別", 1 AS "製袋", "b"."logical2" AS "氣閥", "b"."logical3" AS "鐵條", CASE WHEN "a"."單據類別" = 'E32' THEN 1 ELSE 0 END AS "異動", CASE WHEN "a"."單據類別" = 'E33' THEN 1 ELSE 0 END AS "重工", CASE WHEN "a"."單據類別" = 'E37' THEN 1 ELSE 0 END AS "品檢", "a"."流水編號", TO_CHAR("a"."最後更新日", 'YYYYMMDDHH24MISS') AS "最後更新日時" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" LEFT JOIN "viewfil404e7" AS "j" ON CAST('C11' AS TEXT) = "j"."製令單別" AND "a"."廠客品號" = "j"."製令單號" AND "a"."異動數量" = "j"."箱號" LEFT JOIN "viewfil404f3" AS "k" ON CAST('C11' AS TEXT) = "k"."製令單別" AND "a"."廠客品號" = "k"."製令單號" AND "a"."異動數量" = "k"."箱號" LEFT JOIN "viewfil404g3" AS "l" ON CAST('C11' AS TEXT) = "l"."製令單別" AND "a"."廠客品號" = "l"."製令單號" AND "a"."異動數量" = "l"."箱號" WHERE "a"."單據類別" = 'E32' OR "a"."單據類別" = 'E33' OR "a"."單據類別" = 'E35' OR "a"."單據類別" = 'E37');

-- Home #2045 ViewFIL404E3_S.成品異動明細
CREATE OR REPLACE VIEW "viewfil404e3_s" AS (SELECT "d"."歸屬編號" AS "製令單號", "a"."異動數量" AS "箱號", COALESCE(CASE WHEN "c"."製程代碼" = 'C31E' THEN CASE WHEN "b"."數值14" = 0 THEN "a"."贈品數量" ELSE "b"."數值14" END ELSE "b"."數值5" * -1 END, 0) AS "數量", 0 AS "報廢數量", COALESCE(CASE WHEN "c"."製程代碼" = 'C31E' THEN CASE WHEN "b"."數值14" = 0 THEN "a"."毛重" ELSE "a"."毛重" * (CAST("b"."數值14" AS DOUBLE PRECISION) / "a"."贈品數量") END ELSE "b"."數值5" * -1 * "g"."平均袋重" END, 0) AS "重量", CONCAT("d"."歸屬編號", '-', TRIM(TO_CHAR("a"."異動數量", '0000'))) AS "批號", 1 AS "製袋", CASE WHEN "c"."製程代碼" = 'C31F' THEN 1 ELSE 0 END AS "氣閥", CASE WHEN "c"."製程代碼" = 'C31G' THEN 1 ELSE 0 END AS "鐵條", 0 AS "異動", 0 AS "重工", 0 AS "出貨", 0 AS "品檢", CASE WHEN "c"."製程代碼" = 'C31E' THEN TO_NCHAR('製袋') WHEN "c"."製程代碼" = 'C31G' THEN TO_NCHAR('鐵條') ELSE TO_NCHAR('氣閥') END AS "來源", "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" LEFT JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" LEFT JOIN "viewfil404e7" AS "g" ON "d"."歸屬類別" = "g"."製令單別" AND "d"."歸屬編號" = "g"."製令單號" AND "a"."異動數量" = "g"."箱號" WHERE "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31E' AND 'C31G' UNION ALL SELECT "a"."廠客品號" AS "製令單號", "a"."異動數量" AS "箱號", COALESCE(CASE WHEN "a"."單據類別" = 'E35' THEN "a"."贈品數量" * -1 WHEN "a"."單據類別" = 'E37' THEN "b"."數值5" * -1 ELSE "a"."贈品數量" END, 0) AS "數量", COALESCE(CASE WHEN "a"."單據類別" = 'E33' THEN "b"."數值5" ELSE 0 END, 0) AS "報廢數量", COALESCE(CASE WHEN "a"."單據類別" = 'E35' THEN ("a"."贈品數量" * -1 * "j"."平均袋重") WHEN "a"."單據類別" = 'E37' THEN ("b"."數值5" * -1 * ("j"."平均袋重" + COALESCE("k"."每袋重量", 0) + COALESCE("l"."每袋重量", 0))) ELSE "a"."毛重" END, 0) AS "重量", "b"."批號" AS "批號", 1 AS "製袋", "b"."logical2" AS "氣閥", "b"."logical3" AS "鐵條", CASE WHEN "a"."單據類別" = 'E32' THEN 1 ELSE 0 END AS "異動", CASE WHEN "a"."單據類別" = 'E33' THEN 1 ELSE 0 END AS "重工", CASE WHEN "a"."單據類別" = 'E35' THEN 1 ELSE 0 END AS "重工", CASE WHEN "a"."單據類別" = 'E37' THEN 1 ELSE 0 END AS "品檢", CASE WHEN "a"."單據類別" = 'E32' THEN TO_NCHAR('異動') WHEN "a"."單據類別" = 'E33' THEN TO_NCHAR('重工') WHEN "a"."單據類別" = 'E35' THEN TO_NCHAR('出貨') ELSE TO_NCHAR('品檢') END AS "來源", "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" LEFT JOIN "viewfil404e7" AS "j" ON CAST('C11' AS TEXT) = "j"."製令單別" AND "a"."廠客品號" = "j"."製令單號" AND "a"."異動數量" = "j"."箱號" LEFT JOIN "viewfil404f3" AS "k" ON CAST('C11' AS TEXT) = "k"."製令單別" AND "a"."廠客品號" = "k"."製令單號" AND "a"."異動數量" = "k"."箱號" LEFT JOIN "viewfil404g3" AS "l" ON CAST('C11' AS TEXT) = "l"."製令單別" AND "a"."廠客品號" = "l"."製令單號" AND "a"."異動數量" = "l"."箱號" WHERE "a"."單據類別" BETWEEN 'E32' AND 'E37');

-- Home #2065 ViewFIL404E4.成品異動合計
CREATE OR REPLACE VIEW "viewfil404e4" AS (SELECT "a"."批號" AS "批號", CASE WHEN SUM("製袋") = 0 THEN 0 ELSE 1 END AS "製袋", CASE WHEN SUM("氣閥") = 0 THEN 0 ELSE 1 END AS "氣閥", CASE WHEN SUM("鐵條") = 0 THEN 0 ELSE 1 END AS "鐵條", CASE WHEN SUM("異動") = 0 THEN 0 ELSE 1 END AS "異動", CASE WHEN SUM("重工") = 0 THEN 0 ELSE 1 END AS "重工", CASE WHEN SUM("出貨") = 0 THEN 0 ELSE 1 END AS "出貨", CASE WHEN SUM("品檢") = 0 THEN 0 ELSE 1 END AS "品檢", MAX("a"."箱號") AS "箱號", SUM("a"."數量") AS "數量", SUM("a"."報廢數量") AS "報廢數量", SUM("a"."數量" * CASE WHEN COALESCE("c"."平均袋重", 0) = 0 THEN COALESCE("b"."平均袋重", 0) ELSE COALESCE("c"."平均袋重", 0) END) AS "重量", CASE WHEN SUM("a"."數量") = 0 THEN 0 ELSE CAST(SUM("a"."數量" * CASE WHEN COALESCE("c"."平均袋重", 0) = 0 THEN COALESCE("b"."平均袋重", 0) ELSE COALESCE("c"."平均袋重", 0) END) AS DOUBLE PRECISION) / SUM("a"."數量") END AS "平均重量" FROM "viewfil404e3_s" AS "a" LEFT JOIN "viewfil404e7" AS "b" ON "a"."製令單號" = "b"."製令單號" AND "a"."箱號" = "b"."箱號" LEFT JOIN "viewfil404e8" AS "c" ON "a"."製令單號" = "c"."製令單號" AND "a"."箱號" = "c"."箱號" GROUP BY "a"."批號");

-- Home #2066 ViewFIL404E5.成品製令合計
CREATE OR REPLACE VIEW "viewfil404e5" AS (SELECT CAST('C11' AS TEXT) AS "製令類別", "a"."製令單號", MAX("a"."箱號") AS "箱號", SUM("a"."數量") AS "數量", SUM("a"."報廢數量") AS "報廢數量", SUM("a"."數量" * CASE WHEN COALESCE("c"."平均袋重", 0) = 0 THEN COALESCE("b"."平均袋重", 0) ELSE COALESCE("c"."平均袋重", 0) END) AS "重量", CASE WHEN SUM("a"."數量") = 0 THEN 0 ELSE CAST(SUM("a"."數量" * CASE WHEN COALESCE("c"."平均袋重", 0) = 0 THEN COALESCE("b"."平均袋重", 0) ELSE COALESCE("c"."平均袋重", 0) END) AS DOUBLE PRECISION) / SUM("a"."數量") END AS "平均重量" FROM "viewfil404e3_s" AS "a" LEFT JOIN "viewfil404e71" AS "b" ON "b"."批號" = CONCAT("a"."製令單號", '-', TRIM(TO_CHAR("a"."箱號", '0009'))) LEFT JOIN "viewfil404e81" AS "c" ON "c"."批號" = CONCAT("a"."製令單號", '-', TRIM(TO_CHAR("a"."箱號", '0009'))) GROUP BY CAST('C11' AS TEXT), "a"."製令單號");

-- Home #2067 ViewFIL404E6.成品製令分項
CREATE OR REPLACE VIEW "viewfil404e6" AS (SELECT CAST('C11' AS TEXT) AS "製令類別", "a"."製令單號", CASE WHEN SUM("製袋") = 0 THEN 0 ELSE 1 END AS "製袋", CASE WHEN SUM("氣閥") = 0 THEN 0 ELSE 1 END AS "氣閥", CASE WHEN SUM("鐵條") = 0 THEN 0 ELSE 1 END AS "鐵條", CASE WHEN SUM("異動") = 0 THEN 0 ELSE 1 END AS "異動", CASE WHEN SUM("重工") = 0 THEN 0 ELSE 1 END AS "重工", CASE WHEN SUM("出貨") = 0 THEN 0 ELSE 1 END AS "出貨", CASE WHEN SUM("品檢") = 0 THEN 0 ELSE 1 END AS "品檢", MAX("a"."箱號") AS "箱號", SUM("a"."數量") AS "數量", SUM("a"."報廢數量") AS "報廢數量", SUM("a"."數量" * CASE WHEN COALESCE("c"."平均袋重", 0) = 0 THEN COALESCE("b"."平均袋重", 0) ELSE COALESCE("c"."平均袋重", 0) END) AS "重量", CASE WHEN SUM("a"."數量") = 0 THEN 0 ELSE CAST(SUM("a"."數量" * CASE WHEN COALESCE("c"."平均袋重", 0) = 0 THEN COALESCE("b"."平均袋重", 0) ELSE COALESCE("c"."平均袋重", 0) END) AS DOUBLE PRECISION) / SUM("a"."數量") END AS "平均重量" FROM "viewfil404e3_s" AS "a" LEFT JOIN "viewfil404e7" AS "b" ON "a"."製令單號" = "b"."製令單號" AND "a"."箱號" = "b"."箱號" LEFT JOIN "viewfil404e8" AS "c" ON "a"."製令單號" = "c"."製令單號" AND "a"."箱號" = "c"."箱號" GROUP BY CAST('C11' AS TEXT), "a"."製令單號");

-- Home #2175 ViewFIL4A4D.批號委外數
CREATE OR REPLACE VIEW "viewfil4a4d" AS (SELECT "a"."料號", "a"."批號", SUM("a"."數量" * "a"."庫存參數") AS "委外數量" FROM "viewfilf0w3" AS "a" GROUP BY "a"."料號", "a"."批號");

-- Home #2244 ViewFILM006A.不分倉庫存(含負)
CREATE OR REPLACE VIEW "viewfilm006a" AS (SELECT "a"."材料編號", SUM("a"."庫存數") AS "庫存數" FROM "viewfilm017a" AS "a" GROUP BY "a"."材料編號");

-- Home #2245 ViewFILM007A.不分月庫存數
CREATE OR REPLACE VIEW "viewfilm007a" AS (SELECT "a"."材料編號", "a"."倉庫代碼" AS "庫別代碼", COALESCE("b"."名稱", ' ') AS "庫別名稱", COALESCE("b"."倉別代碼", ' ') AS "倉別代碼", COALESCE("c"."名稱", ' ') AS "倉別名稱", SUM("a"."庫存數量") AS "庫存數" FROM (SELECT "a"."倉庫代碼", "a"."材料編號", SUM("a"."異動數量") AS "庫存數量" FROM "viewfilm011" AS "a" WHERE "a"."月份" = TO_CHAR(CURRENT_TIMESTAMP, 'yyyymm') GROUP BY "a"."倉庫代碼", "a"."材料編號" UNION ALL SELECT "a"."倉庫代碼", "a"."材料編號", SUM("a"."庫存數量") AS "庫存數量" FROM "fil5001" AS "a" WHERE "a"."月份" = TO_CHAR(CURRENT_TIMESTAMP - INTERVAL '1 MONTH', 'yyyymm') GROUP BY "a"."倉庫代碼", "a"."材料編號") AS "a" LEFT JOIN "viewfil3106" AS "b" ON "a"."倉庫代碼" = "b"."代碼" LEFT JOIN "viewfil310r" AS "c" ON "b"."倉別代碼" = "c"."代碼" GROUP BY "a"."材料編號", "a"."倉庫代碼", COALESCE("b"."名稱", ' '), COALESCE("b"."倉別代碼", ' '), COALESCE("c"."名稱", ' '));

-- Home #2227 ViewFILM008.不分倉庫存數(唯正)
CREATE OR REPLACE VIEW "viewfilm008" AS (SELECT "a"."材料編號", SUM(CASE WHEN "b"."批號管理" = 0 THEN "a"."庫存數" ELSE (CASE WHEN "a"."庫存數" <= 0 THEN 0 ELSE "a"."庫存數" END) END) AS "庫存數" FROM "viewfilm017" AS "a" INNER JOIN "viewfil1012" AS "b" ON "a"."材料編號" = "b"."產品編號" GROUP BY "a"."材料編號");

-- Home #2246 ViewFILM008A.不分倉庫存(唯正)
CREATE OR REPLACE VIEW "viewfilm008a" AS (SELECT "a"."材料編號", SUM(CASE WHEN "b"."批號管理" = 0 THEN "a"."庫存數" ELSE (CASE WHEN "a"."庫存數" <= 0 THEN 0 ELSE "a"."庫存數" END) END) AS "庫存數" FROM "viewfilm017a" AS "a" INNER JOIN "viewfil1012" AS "b" ON "a"."材料編號" = "b"."產品編號" GROUP BY "a"."材料編號");

